    pub(crate) fn connection_attention_detail(&self) -> Option<String> {
        if let Some(error) = self.error.as_deref().filter(|text| !text.is_empty()) {
            return Some(format!("SIFS unavailable: {error}"));
        }
        if self.source == FilesSourceKind::Sifs
            && let Some(error) = self
                .details_error
                .as_deref()
                .filter(|text| !text.is_empty())
        {
            return Some(format!("SIFS metadata unavailable: {error}"));
        }
        self.tasks
            .iter()
            .find(|task| {
                task.source == FilesSourceKind::Sifs && task.state == FilesTaskState::Failed
            })
            .map(|task| format!("{} failed: {}", task.title, task.detail))
    }

    /// Replace endpoint-bound SIFS state after the daemon connection recovers or moves. Local
    /// browsing remains untouched; an already-open SIFS surface immediately retries on the new
    /// worker while a never-opened surface stays lazy.
    pub(crate) fn rebind_backend(
        &mut self,
        backend: &Backend,
        waker: Option<sui::UiHandle>,
    ) -> bool {
        let daemon_address = backend.connection.daemon_address().map(str::to_string);
        let daemon_unavailable_detail = backend.connection_issue_detail();
        let clustered = backend.connection.is_clustered();
        if self.daemon_address == daemon_address
            && self.daemon_unavailable_detail == daemon_unavailable_detail
            && self.clustered == clustered
        {
            return false;
        }

        let reopen_sifs = self.source == FilesSourceKind::Sifs && self.loaded;
        let placement_activity_was_open = self.placement_activity_open;
        let placement_activity_filter = self.placement_activity_filter;
        let placement_activity_loaded_filter = self.placement_activity_loaded_filter;
        let placement_activity_origin = self.placement_activity_origin_daemon_address.clone();
        let preserve_placement_activity =
            placement_activity_origin.as_ref().is_some_and(|origin| {
                daemon_address
                    .as_ref()
                    .is_none_or(|address| address == origin)
            }) || (placement_activity_origin.is_none() && self.daemon_address == daemon_address);
        let placement_activity = if preserve_placement_activity {
            self.placement_activity.clone()
        } else {
            Default::default()
        };
        let placement_activity_head_job_ids = if preserve_placement_activity {
            self.placement_activity_head_job_ids.clone()
        } else {
            Default::default()
        };
        let placement_activity_next_cursor = preserve_placement_activity
            .then(|| self.placement_activity_next_cursor.clone())
            .flatten();
        let placement_activity_partial =
            preserve_placement_activity && self.placement_activity_partial;
        let placement_activity_history_truncated =
            preserve_placement_activity && self.placement_activity_history_truncated;
        let placement_activity_error = preserve_placement_activity
            .then(|| self.placement_activity_error.clone())
            .flatten();
        let placement_activity_refreshed_at_unix_nanos = preserve_placement_activity
            .then_some(self.placement_activity_refreshed_at_unix_nanos)
            .flatten();
        let activity_waker = waker.clone();
        self.daemon_address = daemon_address;
        self.daemon_unavailable_detail = daemon_unavailable_detail;
        self.clustered = clustered;
        self.reset_for_retry();
        self.placement_activity_open = placement_activity_was_open;
        self.placement_activity_filter = placement_activity_filter;
        self.placement_activity_loaded_filter = if preserve_placement_activity {
            placement_activity_loaded_filter
        } else {
            placement_activity_filter
        };
        self.placement_activity = placement_activity;
        self.placement_activity_head_job_ids = placement_activity_head_job_ids;
        self.placement_activity_next_cursor = placement_activity_next_cursor;
        self.placement_activity_partial = placement_activity_partial;
        self.placement_activity_history_truncated = placement_activity_history_truncated;
        self.placement_activity_error = placement_activity_error;
        self.placement_activity_refreshed_at_unix_nanos =
            placement_activity_refreshed_at_unix_nanos;
        self.placement_activity_origin_daemon_address = if preserve_placement_activity {
            placement_activity_origin
        } else {
            self.daemon_address.clone()
        };
        if reopen_sifs {
            self.ensure_loaded(waker.clone());
        }
        if placement_activity_was_open {
            if let Some(waker) = activity_waker {
                self.ensure_worker(waker);
            }
            self.request_placement_activity(false, Duration::ZERO);
        }
        true
    }

    fn ensure_loaded(&mut self, waker: Option<sui::UiHandle>) -> bool {
        if self.loaded {
            return self.pump_load();
        }
        if let Some(waker) = waker {
            self.ensure_worker(waker);
            self.loaded = true;
            self.reload();
            return true;
        }
        self.load_sync();
        true
    }

    fn load_sync(&mut self) {
        self.loaded = true;
        self.loading = false;
        if self.source == FilesSourceKind::Local {
            self.browser = None;
            self.node_id = local_node_label();
            self.error = None;
            self.reload();
            return;
        }
        let result = self
            .daemon_address
            .as_deref()
            .ok_or_else(|| {
                self.daemon_unavailable_detail
                    .clone()
                    .unwrap_or_else(|| "SIFS browsing requires a daemon connection".to_string())
            })
            .and_then(|address| SifsBrowser::open_daemon_on_runtime(address, &self.app_runtime));
        match result {
            Ok(browser) => {
                self.node_id = browser.node_id().to_string();
                self.browser = Some(browser);
                self.error = None;
            }
            Err(error) => {
                self.browser = None;
                self.node_id.clear();
                self.error = Some(error);
            }
        }
        self.reload();
    }

    fn reload(&mut self) {
        if self.worker_tx.is_some() {
            self.reload_async();
            return;
        }
        self.reload_sync();
    }

    fn reload_sync(&mut self) {
        self.begin_thumbnail_listing();
        self.selected = None;
        self.marked_entries.clear();
        self.clear_selected_details();
        self.list_slow_after_secs = None;
        self.completed_request_id = None;
        self.pending_append_request_id = None;
        self.loading = false;
        let path = self.path.clone();
        let listing = match self.source {
            FilesSourceKind::Sifs => self.browser.as_ref().map(|b| {
                b.list_shallow_page(
                    &path,
                    self.sort_mode.sifs_options(0, Some(FILES_LIST_PAGE_SIZE)),
                )
            }),
            FilesSourceKind::Local => Some(list_local_dir_page(
                &path,
                self.sort_mode,
                0,
                Some(FILES_LIST_PAGE_SIZE),
            )),
        };
        match listing {
            Some(Ok(page)) => {
                self.entries_total_count = page.total_count;
                self.entry_metadata = page
                    .metadata
                    .into_iter()
                    .map(|metadata| (metadata.path.clone(), metadata))
                    .collect();
                self.entries = page.entries;
                self.error = None;
                if self.source == FilesSourceKind::Local {
                    self.node_id = local_node_label();
                    self.sifs_health = None;
                    self.sifs_health_error = None;
                } else if let Some(browser) = self.browser.as_ref() {
                    match browser.health_summary() {
                        Ok(health) => {
                            self.sifs_health = health;
                            self.sifs_health_error = None;
                        }
                        Err(error) => {
                            self.sifs_health = None;
                            self.sifs_health_error = Some(error);
                        }
                    }
                }
                if let Some(select_path) = self.pending_select_path.take()
                    && let Some(index) = self
                        .entries
                        .iter()
                        .position(|entry| entry.path == select_path)
                {
                    self.selected = Some(index);
                    self.request_selected_details();
                }
            }
            Some(Err(error)) => {
                self.entries.clear();
                self.entry_metadata.clear();
                self.entries_total_count = 0;
                self.error = Some(error);
            }
            None => {}
        }
        self.list_revision = self.list_revision.wrapping_add(1);
    }

    fn reload_async(&mut self) {
        let Some(tx) = self.worker_tx.clone() else {
            return;
        };
        self.begin_thumbnail_listing();
        let request_id = self.next_request_id;
        self.next_request_id = self.next_request_id.wrapping_add(1);
        self.pending_request_id = Some(request_id);
        self.selected = None;
        self.marked_entries.clear();
        self.clear_selected_details();
        self.list_slow_after_secs = None;
        self.completed_request_id = None;
        self.pending_append_request_id = None;
        self.loading = true;
        self.error = None;
        self.entries.clear();
        self.entry_metadata.clear();
        self.entries_total_count = 0;
        self.list_revision = self.list_revision.wrapping_add(1);
        let command = FilesWorkerCommand::List {
            request_id,
            source: self.source,
            path: self.path.clone(),
            sort_mode: self.sort_mode,
            offset: 0,
            limit: Some(FILES_LIST_PAGE_SIZE),
            append: false,
        };
        if tx.send(command).is_err() {
            self.pending_request_id = None;
            self.completed_request_id = None;
            self.loading = false;
            self.error = Some("SIFS browser worker stopped".to_string());
            self.list_revision = self.list_revision.wrapping_add(1);
            return;
        }
        if let Some(result_tx) = self.worker_result_tx.clone() {
            let path = self.path.clone();
            let source = self.source;
            let waker = self.worker_waker.clone();
            let _ = thread::Builder::new()
                .name("sinomo-app-files-timeout".to_string())
                .spawn(move || {
                    thread::sleep(LOAD_TIMEOUT);
                    let _ = result_tx.send(FilesWorkerResult::List {
                        request_id,
                        source,
                        path,
                        append: false,
                        result: FilesListResult::Slow {
                            elapsed_secs: LOAD_TIMEOUT.as_secs(),
                        },
                    });
                    if let Some(waker) = waker {
                        waker.wake();
                    }
                });
        }
    }

    pub(crate) fn retry(&mut self, waker: Option<sui::UiHandle>) {
        self.reset_for_retry();
        self.ensure_loaded(waker);
    }

    fn refresh(&mut self, waker: Option<sui::UiHandle>) {
        if !self.loaded {
            self.ensure_loaded(waker);
            return;
        }
        if self.loading {
            return;
        }
        if let Some(waker) = waker {
            self.ensure_worker(waker);
        }
        self.reload();
    }

    fn request_more_entries(&mut self, waker: Option<sui::UiHandle>) {
        if self.loading
            || self.pending_request_id.is_some()
            || self.pending_append_request_id.is_some()
            || self.error.is_some()
            || self.entries.len() >= self.entries_total_count
        {
            return;
        }
        if let Some(waker) = waker {
            self.ensure_worker(waker);
        }
        let Some(tx) = self.worker_tx.clone() else {
            return;
        };
        let request_id = self.next_request_id;
        self.next_request_id = self.next_request_id.wrapping_add(1);
        self.pending_append_request_id = Some(request_id);
        let command = FilesWorkerCommand::List {
            request_id,
            source: self.source,
            path: self.path.clone(),
            sort_mode: self.sort_mode,
            offset: self.entries.len(),
            limit: Some(FILES_LIST_PAGE_SIZE),
            append: true,
        };
        if tx.send(command).is_err() {
            self.pending_append_request_id = None;
            self.error = Some("SIFS browser worker stopped".to_string());
            self.list_revision = self.list_revision.wrapping_add(1);
        }
    }

    fn reset_for_retry(&mut self) {
        self.browser = None;
        self.error = None;
        self.entries.clear();
        self.entry_metadata.clear();
        self.entries_total_count = 0;
        self.selected = None;
        self.marked_entries.clear();
        self.clear_selected_details();
        self.node_id.clear();
        self.sifs_health = None;
        self.sifs_health_error = None;
        self.list_slow_after_secs = None;
        self.inspector_details_open = false;
        self.loaded = self.source == FilesSourceKind::Local;
        self.loading = false;
        self.pending_request_id = None;
        self.pending_append_request_id = None;
        self.completed_request_id = None;
        self.pending_details_request_id = None;
        self.pending_preview_request_id = None;
        self.pending_document_request_id = None;
        self.pending_document_save_request_id = None;
        self.pending_document_saved_text = None;
        self.pending_attachment_request_id = None;
        self.pending_attachment_source_path = None;
        self.pending_import_request_ids.clear();
        self.history_open = false;
        self.clear_history_content();
        self.storage_center_open = false;
        self.storage_center_loading = false;
        self.storage_overview = None;
        self.storage_center_error = None;
        self.pending_storage_center_request_id = None;
        self.storage_center_revision = self.storage_center_revision.wrapping_add(1);
        self.placement_draft = None;
        self.placement_advanced_open = false;
        self.placement_preview_revision = None;
        self.pending_placement_preview_revision = None;
        self.placement_preview = None;
        self.placement_reconciliation = None;
        self.placement_loading = false;
        self.placement_applying = false;
        self.placement_error = None;
        self.placement_error_from_reconciliation = false;
        self.pending_placement_request_id = None;
        self.placement_activity_open = false;
        self.placement_activity_loaded_filter = PlacementActivityFilter::All;
        self.placement_activity.clear();
        self.placement_activity_head_job_ids.clear();
        self.placement_activity_next_cursor = None;
        self.placement_activity_loading = false;
        self.placement_activity_error = None;
        self.placement_activity_partial = false;
        self.placement_activity_history_truncated = false;
        self.placement_activity_refreshed_at_unix_nanos = None;
        self.placement_activity_origin_daemon_address = None;
        self.pending_placement_activity_request_id = None;
        self.pending_placement_activity_append = false;
        self.placement_activity_poll_generation
            .fetch_add(1, Ordering::AcqRel);
        self.placement_activity_in_flight_generation
            .store(0, Ordering::Release);
        self.placement_activity_refresh_dirty = false;
        self.attachment_loading = false;
        if let Some(document) = self.document.as_mut()
            && document.saving
        {
            document.saving = false;
            document.save_error = Some(
                "The connection changed before the save completed. Your edits are still open."
                    .to_string(),
            );
        }
        self.worker_tx = None;
        self.operations_tx = None;
        self.worker_rx = None;
        self.worker_result_tx = None;
        self.worker_waker = None;
        self.ui_preview_catalog_refresh_pending = false;
        self.thumbnail_tx = None;
        self.thumbnail_rx = None;
        self.thumbnail_inflight.clear();
        if let Some(abort) = self.live_event_abort.take() {
            abort.abort();
        }
        self.live_updates_connected = false;
        self.live_updates_error = None;
        self.live_refresh_pending = false;
        clear_all_cancelled_operations(&self.worker_cancellations);
        self.list_revision = self.list_revision.wrapping_add(1);
    }

    fn ensure_worker(&mut self, waker: sui::UiHandle) {
        if self.worker_tx.is_some() {
            return;
        }
        let (command_tx, command_rx) = mpsc::channel();
        let (result_tx, result_rx) = mpsc::channel();
        let data_dir = self.data_dir.clone();
        let daemon_address = self.daemon_address.clone();
        let daemon_unavailable_detail = self.daemon_unavailable_detail.clone();
        let app_runtime = self.app_runtime.clone();
        let cancellations = self.worker_cancellations.clone();
        let timeout_tx = result_tx.clone();
        let timeout_waker = waker.clone();
        let live_data_dir = self.data_dir.as_ref().clone();
        let live_address = self.daemon_address.clone();
        let live_runtime = self.app_runtime.clone();
        let live_result_tx = result_tx.clone();
        let operations_tx = spawn_files_operations_lane(
            self.data_dir.clone(),
            self.daemon_address.clone(),
            self.daemon_unavailable_detail.clone(),
            self.app_runtime.clone(),
            result_tx.clone(),
            self.worker_cancellations.clone(),
            waker.clone(),
        );
        match thread::Builder::new()
            .name("sinomo-app-files".to_string())
            .spawn(move || {
                files_worker_loop(
                    data_dir,
                    daemon_address,
                    daemon_unavailable_detail,
                    app_runtime,
                    command_rx,
                    result_tx,
                    cancellations,
                    waker,
                )
            }) {
            Ok(_) => {
                self.worker_tx = Some(command_tx);
                self.operations_tx = operations_tx;
                self.worker_rx = Some(result_rx);
                self.worker_result_tx = Some(timeout_tx);
                self.worker_waker = Some(timeout_waker.clone());
                if let Some(address) = live_address {
                    self.live_event_abort = Some(spawn_files_dfs_event_subscription(
                        &live_runtime,
                        live_data_dir,
                        address,
                        live_result_tx,
                        Some(timeout_waker),
                    ));
                }
            }
            Err(error) => {
                self.loaded = true;
                self.loading = false;
                self.error = Some(format!("cannot start SIFS browser worker: {error}"));
                self.list_revision = self.list_revision.wrapping_add(1);
            }
        }
    }

    fn operations_sender(&self) -> Option<Sender<FilesWorkerCommand>> {
        self.operations_tx
            .clone()
            .or_else(|| self.worker_tx.clone())
    }

    fn ensure_thumbnail_worker(&mut self, waker: sui::UiHandle) {
        if self.thumbnail_tx.is_some() {
            return;
        }
        let (command_tx, command_rx) = mpsc::channel();
        let (result_tx, result_rx) = mpsc::channel();
        let daemon_address = self.daemon_address.clone();
        let daemon_unavailable_detail = self.daemon_unavailable_detail.clone();
        let app_runtime = self.app_runtime.clone();
        if thread::Builder::new()
            .name("sinomo-app-thumbnails".to_string())
            .spawn(move || {
                thumbnail_worker_loop(
                    daemon_address,
                    daemon_unavailable_detail,
                    app_runtime,
                    command_rx,
                    result_tx,
                    waker,
                )
            })
            .is_ok()
        {
            self.thumbnail_tx = Some(command_tx);
            self.thumbnail_rx = Some(result_rx);
        }
    }

    fn begin_thumbnail_listing(&mut self) {
        self.thumbnail_listing_epoch = self.thumbnail_listing_epoch.wrapping_add(1);
        self.thumbnail_inflight.clear();
        self.thumbnail_cache.remove_unavailable();
        if let Some(tx) = &self.thumbnail_tx {
            let _ = tx.send(ThumbnailWorkerCommand {
                requests: Vec::new(),
            });
        }
    }

    fn thumbnail_request_for_entry(
        &self,
        entry: &SifsEntry,
        bucket: ThumbnailBucket,
    ) -> Option<ThumbnailRequest> {
        if entry.is_dir || entry.is_link {
            return None;
        }
        let identity = if self.source == FilesSourceKind::Sifs {
            // Stored thumbnails may be supplied for any file type by another
            // producer. Require the listing's immutable identity before fetching.
            let metadata = self.entry_metadata.get(&entry.path)?;
            ThumbnailIdentity::Sifs {
                object_id: metadata.object_id.clone(),
                version: metadata.version.clone(),
            }
        } else {
            if !thumbnail_candidate(&entry.name) {
                return None;
            }
            ThumbnailIdentity::Listing(self.thumbnail_listing_epoch)
        };
        Some(ThumbnailRequest {
            key: ThumbnailRequestKey {
                source: self.source,
                path: entry.path.clone(),
                identity,
                bucket,
            },
        })
    }

    fn request_visible_thumbnails(
        &mut self,
        entries: &[SifsEntry],
        range: std::ops::Range<usize>,
        bucket: ThumbnailBucket,
        waker: Option<sui::UiHandle>,
    ) {
        if self.thumbnail_tx.is_none()
            && let Some(waker) = waker
        {
            self.ensure_thumbnail_worker(waker);
        }
        let mut requests = Vec::new();
        for entry in entries.get(range).into_iter().flatten() {
            let Some(request) = self.thumbnail_request_for_entry(entry, bucket) else {
                continue;
            };
            if self.thumbnail_cache.contains(&request.key) {
                self.thumbnail_cache.touch(&request.key);
                continue;
            }
            self.thumbnail_inflight.insert(request.key.clone());
            requests.push(request);
        }
        let Some(tx) = &self.thumbnail_tx else {
            for request in requests {
                self.thumbnail_inflight.remove(&request.key);
            }
            return;
        };
        if let Err(error) = tx.send(ThumbnailWorkerCommand { requests }) {
            for request in error.0.requests {
                self.thumbnail_inflight.remove(&request.key);
            }
            self.thumbnail_tx = None;
            self.thumbnail_rx = None;
        }
    }

    fn cancel_thumbnail_requests(&mut self) {
        self.thumbnail_inflight.clear();
        if let Some(tx) = &self.thumbnail_tx {
            let _ = tx.send(ThumbnailWorkerCommand {
                requests: Vec::new(),
            });
        }
    }

    fn thumbnail_result_is_current(&self, key: &ThumbnailRequestKey) -> bool {
        if key.source != self.source {
            return false;
        }
        self.entries
            .iter()
            .find(|entry| entry.path == key.path)
            .and_then(|entry| self.thumbnail_request_for_entry(entry, key.bucket))
            .is_some_and(|request| request.key == *key)
    }

    fn pump_thumbnail_results(&mut self) -> bool {
        let mut changed = false;
        loop {
            let result = match self.thumbnail_rx.as_ref().map(|rx| rx.try_recv()) {
                Some(Ok(result)) => result,
                Some(Err(TryRecvError::Empty)) | None => break,
                Some(Err(TryRecvError::Disconnected)) => {
                    self.thumbnail_tx = None;
                    self.thumbnail_rx = None;
                    self.thumbnail_inflight.clear();
                    break;
                }
            };
            self.thumbnail_inflight.remove(&result.key);
            if !self.thumbnail_result_is_current(&result.key) {
                continue;
            }
            let entry = match result.result {
                Ok(bitmap) => ThumbnailCacheEntry::Ready(bitmap),
                Err(_) => {
                    // Files without previews keep their existing generic icon.
                    // Negative results need no repaint or full Flow relayout,
                    // and must not replace a successful duplicate result.
                    if !self.thumbnail_cache.contains(&result.key) {
                        self.thumbnail_cache
                            .insert(result.key, ThumbnailCacheEntry::Unavailable);
                    }
                    continue;
                }
            };
            self.thumbnail_cache.insert(result.key, entry);
            self.thumbnail_revision = self.thumbnail_revision.wrapping_add(1);
            changed = true;
        }
        changed
    }

    pub(crate) const fn thumbnail_revision(&self) -> u64 {
        self.thumbnail_revision
    }

    pub fn pump_load(&mut self) -> bool {
        self.schedule_ui_extension_catalog_refresh();
        let mut changed = self.poll_native_picker() | self.pump_thumbnail_results();
        loop {
            let result = match self.worker_rx.as_ref().map(|rx| rx.try_recv()) {
                Some(Ok(result)) => result,
                Some(Err(TryRecvError::Empty)) | None => break,
                Some(Err(TryRecvError::Disconnected)) => {
                    if self.loading {
                        self.loading = false;
                        self.pending_request_id = None;
                        self.completed_request_id = None;
                        self.error = Some("SIFS browser worker stopped".to_string());
                        self.list_revision = self.list_revision.wrapping_add(1);
                        changed = true;
                    }
                    if self.details_loading {
                        self.details_loading = false;
                        self.pending_details_request_id = None;
                        self.selected_details = None;
                        self.details_error = Some("SIFS browser worker stopped".to_string());
                        changed = true;
                    }
                    if self.preview_loading {
                        self.preview_loading = false;
                        self.pending_preview_request_id = None;
                        self.selected_preview = None;
                        self.custom_preview = None;
                        self.preview_error = Some("SIFS browser worker stopped".to_string());
                        changed = true;
                    }
                    if self.pending_document_request_id.take().is_some() {
                        if let Some(document) = self.document.as_mut() {
                            document.loading = false;
                            document.load_error = Some(
                                "The Files background worker stopped while reading the document."
                                    .to_string(),
                            );
                        }
                        self.document_revision = self.document_revision.wrapping_add(1);
                        changed = true;
                    }
                    if self.pending_document_save_request_id.take().is_some() {
                        self.pending_document_saved_text = None;
                        if let Some(document) = self.document.as_mut() {
                            document.saving = false;
                            document.save_error = Some(
                                "The Files background worker stopped while saving. Your edits are still open."
                                    .to_string(),
                            );
                        }
                        changed = true;
                    }
                    if self.pending_attachment_request_id.take().is_some() {
                        self.pending_attachment_source_path = None;
                        self.attachment_loading = false;
                        self.attachment_error = Some(
                            "The Files background worker stopped while reading the attachment."
                                .to_string(),
                        );
                        changed = true;
                    }
                    let history_more = self.pending_history_more_request_id.take().is_some();
                    let history_preview = self.pending_history_preview_request_id.take();
                    if self.pending_history_request_id.take().is_some() || history_more {
                        self.history_loading = false;
                        self.history_error = Some(
                            "The Files background worker stopped while reading file history."
                                .to_string(),
                        );
                        self.history_revision = self.history_revision.wrapping_add(1);
                        changed = true;
                    }
                    if history_preview.is_some() {
                        if let Some(preview) = self.history_preview.as_mut() {
                            preview.result = Some(Err(
                                "The Files background worker stopped while reading this version."
                                    .to_string(),
                            ));
                        }
                        self.history_revision = self.history_revision.wrapping_add(1);
                        changed = true;
                    }
                    if self.pending_storage_center_request_id.take().is_some() {
                        self.storage_center_loading = false;
                        self.storage_center_error = Some(
                            "The Files background worker stopped while reading storage health."
                                .to_string(),
                        );
                        self.storage_center_revision = self.storage_center_revision.wrapping_add(1);
                        changed = true;
                    }
                    if self.pending_placement_request_id.take().is_some() {
                        self.placement_loading = false;
                        self.placement_applying = false;
                        self.placement_error = Some(
                            "The Files background worker stopped while managing placement."
                                .to_string(),
                        );
                        self.placement_error_from_reconciliation = false;
                        changed = true;
                    }
                    if self.pending_placement_activity_request_id.take().is_some() {
                        self.placement_activity_loading = false;
                        self.placement_activity_in_flight_generation
                            .store(0, Ordering::Release);
                        self.placement_activity_refresh_dirty = false;
                        self.placement_activity_error = Some(
                            "The Files background worker stopped while reading reconciliation activity."
                                .to_string(),
                        );
                        changed = true;
                    }
                    self.worker_rx = None;
                    self.worker_tx = None;
                    self.operations_tx = None;
                    self.worker_result_tx = None;
                    self.worker_waker = None;
                    self.ui_preview_catalog_refresh_pending = false;
                    if let Some(abort) = self.live_event_abort.take() {
                        abort.abort();
                    }
                    self.live_updates_connected = false;
                    break;
                }
            };
            if self.apply_worker_result(result) {
                changed = true;
            }
        }
        if self.flush_live_refresh() {
            changed = true;
        }
        changed
    }

    fn apply_worker_result(&mut self, result: FilesWorkerResult) -> bool {
        match result {
            FilesWorkerResult::UiExtensionCatalog(result) => {
                self.ui_preview_catalog_refresh_pending = false;
                let Ok(catalog) = result else {
                    return false;
                };
                for warning in &catalog.warnings {
                    tracing::warn!(%warning, "UI extension catalog refresh warning");
                }
                if catalog.registry_generation == self.ui_preview_catalog_generation {
                    return false;
                }
                self.ui_preview_catalog_generation = catalog.registry_generation;
                self.ui_preview_entries = catalog.entries;
                // Dropping the session disconnects its isolated worker. Keep
                // the built-in preview until the current file is selected
                // again under the new catalog generation.
                self.custom_preview = None;
                true
            }
            FilesWorkerResult::LiveUpdate(update) => self.apply_live_update(update),
            FilesWorkerResult::List {
                request_id,
                source,
                path,
                append,
                result,
            } => {
                if append {
                    if self.pending_append_request_id != Some(request_id) {
                        return false;
                    }
                } else if self.pending_request_id != Some(request_id) {
                    return false;
                }
                if self.source != source {
                    return false;
                }
                match result {
                    FilesListResult::Ok(listing) => {
                        if append {
                            self.pending_append_request_id = None;
                        } else {
                            self.pending_request_id = None;
                            self.completed_request_id = Some(request_id);
                            self.loading = false;
                        }
                        self.list_slow_after_secs = None;
                        self.path = path;
                        self.store_active_path();
                        self.node_id = listing.node_id;
                        self.sifs_health = listing.health;
                        self.sifs_health_error = listing.health_error;
                        self.entries_total_count = listing.total_count;
                        if append {
                            self.entry_metadata.extend(
                                listing
                                    .entry_metadata
                                    .into_iter()
                                    .map(|metadata| (metadata.path.clone(), metadata)),
                            );
                            self.entries.extend(listing.entries);
                        } else {
                            self.entry_metadata = listing
                                .entry_metadata
                                .into_iter()
                                .map(|metadata| (metadata.path.clone(), metadata))
                                .collect();
                            self.entries = listing.entries;
                        }
                        self.error = None;
                        if !append
                            && let Some(select_path) = self.pending_select_path.take()
                            && let Some(index) = self
                                .entries
                                .iter()
                                .position(|entry| entry.path == select_path)
                        {
                            self.selected = Some(index);
                            self.request_selected_details();
                        }
                    }
                    FilesListResult::Err(error) => {
                        if append {
                            self.pending_append_request_id = None;
                        } else {
                            self.pending_request_id = None;
                            self.completed_request_id = None;
                            self.loading = false;
                        }
                        self.list_slow_after_secs = None;
                        self.path = path;
                        self.store_active_path();
                        if !append {
                            self.entries.clear();
                            self.entry_metadata.clear();
                            self.entries_total_count = 0;
                            self.sifs_health = None;
                            self.sifs_health_error = None;
                        }
                        self.error = Some(error);
                    }
                    FilesListResult::Slow { elapsed_secs } => {
                        self.list_slow_after_secs = Some(elapsed_secs);
                    }
                }
                self.list_revision = self.list_revision.wrapping_add(1);
                true
            }
            FilesWorkerResult::Health {
                request_id,
                source,
                health,
                health_error,
            } => {
                if self.source != source {
                    return false;
                }
                if self.pending_request_id.is_some()
                    || self.completed_request_id != Some(request_id)
                {
                    return false;
                }
                self.sifs_health = health;
                self.sifs_health_error = health_error;
                self.list_revision = self.list_revision.wrapping_add(1);
                true
            }
            FilesWorkerResult::Details {
                request_id,
                source,
                path,
                result,
            } => {
                if self.pending_details_request_id != Some(request_id) {
                    return false;
                }
                if self.source != source {
                    return false;
                }
                self.pending_details_request_id = None;
                self.details_loading = false;
                let selected_path = self.selected_entry().map(|entry| entry.path.as_str());
                if selected_path != Some(path.as_str()) {
                    return false;
                }
                match result {
                    Ok(FilesObjectDetails::Sifs(details)) => {
                        self.selected_details = Some(details);
                        self.selected_local_details = None;
                        self.details_error = None;
                    }
                    Ok(FilesObjectDetails::Local(details)) => {
                        self.selected_details = None;
                        self.selected_local_details = Some(details);
                        self.details_error = None;
                    }
                    Err(error) => {
                        self.selected_details = None;
                        self.selected_local_details = None;
                        self.details_error = Some(error);
                    }
                }
                true
            }
            FilesWorkerResult::Preview {
                request_id,
                source,
                path,
                result,
            } => {
                if self.pending_preview_request_id != Some(request_id) {
                    return false;
                }
                if self.source != source {
                    return false;
                }
                self.pending_preview_request_id = None;
                self.preview_loading = false;
                let selected_path = self.selected_entry().map(|entry| entry.path.as_str());
                if selected_path != Some(path.as_str()) {
                    return false;
                }
                match result {
                    Ok(preview) => {
                        self.custom_preview = self.start_custom_preview(&path, &preview);
                        self.selected_preview = Some(preview);
                        self.preview_error = None;
                    }
                    Err(error) => {
                        self.selected_preview = None;
                        self.custom_preview = None;
                        self.preview_error = Some(error);
                    }
                }
                true
            }
            FilesWorkerResult::Document {
                request_id,
                source,
                path,
                result,
            } => {
                if self.pending_document_request_id != Some(request_id) {
                    return false;
                }
                let matches_open = self
                    .document
                    .as_ref()
                    .is_some_and(|document| document.source == source && document.path == path);
                if !matches_open {
                    return false;
                }
                self.pending_document_request_id = None;
                match result {
                    Ok(load) => {
                        self.document = Some(FilesDocument {
                            source: load.source,
                            path: load.path,
                            title: load.title,
                            saved_text: load.text.clone(),
                            text: load.text,
                            local_fingerprint: load.local_fingerprint,
                            sifs_fingerprint: load.sifs_fingerprint,
                            read_only_reason: load.read_only_reason,
                            loading: false,
                            load_error: None,
                            saving: false,
                            save_error: None,
                            save_warning: None,
                        });
                    }
                    Err(error) => {
                        if let Some(document) = self.document.as_mut() {
                            document.loading = false;
                            document.load_error = Some(error);
                        }
                    }
                }
                self.document_revision = self.document_revision.wrapping_add(1);
                true
            }
            FilesWorkerResult::DocumentSaved {
                request_id,
                source,
                path,
                result,
            } => {
                if self.pending_document_save_request_id != Some(request_id) {
                    return false;
                }
                let Some(document) = self.document.as_mut() else {
                    return false;
                };
                if document.source != source || document.path != path {
                    return false;
                }
                self.pending_document_save_request_id = None;
                let saved_text = self.pending_document_saved_text.take();
                document.saving = false;
                match result {
                    Ok(FilesDocumentSave::Local {
                        fingerprint,
                        maintenance_warning,
                        requires_reload,
                    }) => {
                        document.local_fingerprint = Some(fingerprint);
                        if let Some(saved_text) = saved_text.clone() {
                            document.saved_text = saved_text;
                        }
                        document.save_error = None;
                        document.save_warning = maintenance_warning;
                        document.read_only_reason = requires_reload.then(|| {
                            "The content was saved, but the host did not return a complete post-save metadata receipt. Reload before editing again."
                                .to_string()
                        });
                    }
                    Ok(FilesDocumentSave::Sifs {
                        fingerprint,
                        maintenance_warning,
                    }) => {
                        document.sifs_fingerprint = Some(fingerprint);
                        if let Some(saved_text) = saved_text {
                            document.saved_text = saved_text;
                        }
                        document.save_error = None;
                        document.save_warning = maintenance_warning;
                        self.pending_select_path = Some(path);
                        self.refresh(None);
                    }
                    Err(error) => {
                        document.save_error = Some(error);
                        document.save_warning = None;
                    }
                }
                true
            }
            FilesWorkerResult::Attachment {
                request_id,
                source,
                path,
                result,
            } => {
                if self.pending_attachment_request_id != Some(request_id) {
                    return false;
                }
                let still_requested =
                    self.pending_attachment_source_path.as_ref() == Some(&(source, path.clone()));
                self.pending_attachment_request_id = None;
                self.pending_attachment_source_path = None;
                self.attachment_loading = false;
                if !still_requested {
                    return false;
                }
                match result {
                    Ok(intent) => {
                        self.ready_attachment_intent = Some(intent);
                        self.attachment_error = None;
                    }
                    Err(error) => {
                        self.ready_attachment_intent = None;
                        self.attachment_error = Some(error);
                    }
                }
                true
            }
            FilesWorkerResult::ImportPrepared {
                request_id,
                destination_source,
                destination_path,
                result,
            } => {
                if !self.pending_import_request_ids.remove(&request_id) {
                    return false;
                }
                if self.source != destination_source || self.path != destination_path {
                    self.picker_error = Some(
                        "The destination changed before the import started. Nothing was copied."
                            .to_string(),
                    );
                    return true;
                }
                match result {
                    Ok(operations) => {
                        let waker = self.worker_waker.clone();
                        for (source, queued) in operations {
                            self.start_operation_for_source(
                                source,
                                queued.operation,
                                queued.title,
                                queued.detail,
                                waker.clone(),
                            );
                        }
                        self.picker_error = None;
                    }
                    Err(error) => self.picker_error = Some(error),
                }
                true
            }
            FilesWorkerResult::TaskProgress {
                request_id,
                detail,
                progress,
            } => self.update_task_progress(request_id, detail, progress),
            FilesWorkerResult::Operation { request_id, result } => {
                self.apply_operation_result(request_id, result)
            }
            FilesWorkerResult::History { request_id, result } => {
                if self.pending_history_request_id != Some(request_id) || !self.history_open {
                    return false;
                }
                self.pending_history_request_id = None;
                self.history_loading = false;
                match result {
                    Ok(snapshot) => {
                        if let Err(error) = self.apply_history_snapshot(snapshot) {
                            self.clear_history_snapshot();
                            self.history_error = Some(error);
                        } else {
                            self.history_error = None;
                        }
                    }
                    Err(error) => {
                        self.clear_history_snapshot();
                        self.history_error = Some(error);
                    }
                }
                self.history_revision = self.history_revision.wrapping_add(1);
                true
            }
            FilesWorkerResult::HistoryMore { request_id, result } => {
                if self.pending_history_more_request_id != Some(request_id) || !self.history_open {
                    return false;
                }
                self.pending_history_more_request_id = None;
                match result {
                    Ok((entries, next_cursor)) => {
                        for entry in entries {
                            if !self
                                .history_entries
                                .iter()
                                .any(|known| known.identity == entry.identity)
                            {
                                self.history_entries.push(entry);
                            }
                        }
                        sort_history_entries(&mut self.history_entries);
                        self.history_next_cursor = next_cursor;
                        self.history_list_error = None;
                    }
                    Err(error) => {
                        self.history_list_error = Some(format!(
                            "Older versions could not be searched: {}. Refresh to start again.",
                            history_error_message(&error)
                        ));
                    }
                }
                self.history_revision = self.history_revision.wrapping_add(1);
                true
            }
            FilesWorkerResult::HistoryAction { request_id, result } => {
                if self.pending_history_request_id != Some(request_id) || !self.history_open {
                    return false;
                }
                self.pending_history_request_id = None;
                self.history_loading = false;
                match result {
                    Ok(outcome) => {
                        self.history_notice = Some(outcome.notice);
                        self.history_error = None;
                        self.history_decision = None;
                        self.history_capture_name.clear();
                        match outcome.snapshot {
                            Ok(snapshot) => {
                                if let Err(error) = self.apply_history_snapshot(snapshot) {
                                    self.history_error = Some(error);
                                }
                            }
                            Err(error) => {
                                self.history_error = Some(format!(
                                    "The change was applied, but history could not refresh: {error}"
                                ));
                            }
                        }
                        if let Some(path) = outcome.reveal_path {
                            self.pending_select_path = Some(path);
                            self.refresh(None);
                        }
                    }
                    Err(error) => {
                        self.history_error = Some(error);
                    }
                }
                self.history_revision = self.history_revision.wrapping_add(1);
                true
            }
            FilesWorkerResult::HistoryPreview {
                request_id,
                identity,
                result,
            } => {
                if self.pending_history_preview_request_id != Some(request_id) || !self.history_open
                {
                    return false;
                }
                self.pending_history_preview_request_id = None;
                match self.history_preview.as_mut() {
                    Some(preview) if preview.identity == identity => {
                        preview.result = Some(result);
                    }
                    _ => return false,
                }
                self.history_revision = self.history_revision.wrapping_add(1);
                true
            }
            FilesWorkerResult::StorageOverview { request_id, result } => {
                if self.pending_storage_center_request_id != Some(request_id)
                    || !self.storage_center_open
                {
                    return false;
                }
                self.pending_storage_center_request_id = None;
                self.storage_center_loading = false;
                match result {
                    Ok(overview) => {
                        self.storage_overview = Some(overview);
                        self.storage_center_error = None;
                    }
                    Err(error) => {
                        self.storage_center_error = Some(error);
                    }
                }
                self.storage_center_revision = self.storage_center_revision.wrapping_add(1);
                true
            }
            FilesWorkerResult::PlacementPreview {
                request_id,
                path,
                result,
            } => {
                if self.pending_placement_request_id != Some(request_id) {
                    return false;
                }
                self.pending_placement_request_id = None;
                let preview_revision = self.pending_placement_preview_revision.take();
                self.placement_loading = false;
                if preview_revision != Some(self.placement_edit_revision) {
                    self.resume_placement_progress_poll();
                    return false;
                }
                if self
                    .action_prompt
                    .as_ref()
                    .and_then(|prompt| prompt.target_path.as_deref())
                    != Some(path.as_str())
                {
                    self.resume_placement_progress_poll();
                    return false;
                }
                match result {
                    Ok(preview) => {
                        self.placement_preview = Some(preview);
                        self.placement_preview_revision = preview_revision;
                        self.placement_error = None;
                        self.placement_error_from_reconciliation = false;
                    }
                    Err(error) => {
                        self.placement_preview_revision = None;
                        self.placement_error = Some(error);
                        self.placement_error_from_reconciliation = false;
                    }
                }
                // Previewing a replacement temporarily owns the placement
                // request slot. Resume observation of the accepted job once
                // that bounded request finishes so its progress never becomes
                // stale while the operator considers a superseding policy.
                self.resume_placement_progress_poll();
                true
            }
            FilesWorkerResult::PlacementUpdate {
                request_id,
                path,
                result,
            } => {
                if self.pending_placement_request_id != Some(request_id) {
                    return false;
                }
                self.pending_placement_request_id = None;
                self.pending_placement_preview_revision = None;
                self.placement_loading = false;
                self.placement_applying = false;
                match result {
                    Ok(outcome) => {
                        let accepted_resolved = outcome.preview.resolved.clone();
                        if let Some(draft) = self.placement_draft.as_mut() {
                            draft.rebase_accepted_scope(
                                outcome.reconciliation.scope,
                                &accepted_resolved,
                            );
                        }
                        // Keep the selected-object cache aligned with the policy that was
                        // atomically accepted alongside this reconciliation job. Otherwise,
                        // closing and reopening the editor before reconciliation finishes would
                        // rebuild from the pre-Apply details and misclassify an exact reversion as
                        // an unchanged policy. The resolved projection includes both exact scopes,
                        // so a subtree update does not erase a coexisting self-only rule (or vice
                        // versa).
                        if let Some(details) = self
                            .selected_details
                            .as_mut()
                            .filter(|details| details.path == path)
                        {
                            details.placement = Some(accepted_resolved);
                        }
                        let terminal = outcome.reconciliation.state.is_terminal();
                        let job_id = outcome.reconciliation.job_id.clone();
                        self.placement_preview = Some(outcome.preview);
                        self.placement_preview_revision = Some(self.placement_edit_revision);
                        self.placement_reconciliation = Some(outcome.reconciliation);
                        self.placement_error = None;
                        self.placement_error_from_reconciliation = false;
                        self.pending_select_path = Some(path);
                        if terminal {
                            self.refresh(None);
                        } else {
                            self.schedule_placement_progress_poll(job_id);
                        }
                    }
                    Err(error) => {
                        self.placement_error = Some(error);
                        self.placement_error_from_reconciliation = false;
                    }
                }
                self.resume_placement_progress_poll();
                true
            }
            FilesWorkerResult::PlacementProgress { request_id, result } => {
                if self.pending_placement_request_id != Some(request_id) {
                    return false;
                }
                self.pending_placement_request_id = None;
                self.pending_placement_preview_revision = None;
                match result {
                    Ok(job) => {
                        let terminal = job.state.is_terminal();
                        let job_id = job.job_id.clone();
                        self.placement_reconciliation = Some(job);
                        if self.placement_error_from_reconciliation {
                            self.placement_error = None;
                            self.placement_error_from_reconciliation = false;
                        }
                        if terminal {
                            self.refresh(None);
                        } else {
                            self.schedule_placement_progress_poll(job_id);
                        }
                    }
                    Err(error) => {
                        if self.placement_error.is_none()
                            || self.placement_error_from_reconciliation
                        {
                            self.placement_error = Some(error);
                            self.placement_error_from_reconciliation = true;
                        }
                        if let Some(job_id) = self
                            .placement_reconciliation
                            .as_ref()
                            .filter(|job| !job.state.is_terminal())
                            .map(|job| job.job_id.clone())
                        {
                            self.schedule_placement_progress_poll(job_id);
                        }
                    }
                }
                true
            }
            FilesWorkerResult::PlacementActivity {
                request_id,
                filter,
                append,
                result,
            } => {
                if self.pending_placement_activity_request_id != Some(request_id)
                    || self.pending_placement_activity_append != append
                    || self.placement_activity_filter != filter
                {
                    return false;
                }
                self.pending_placement_activity_request_id = None;
                self.pending_placement_activity_append = false;
                self.placement_activity_loading = false;
                self.placement_activity_in_flight_generation
                    .store(0, Ordering::Release);
                let refresh_dirty = std::mem::take(&mut self.placement_activity_refresh_dirty);
                match result {
                    Ok(page) => {
                        let page_has_more = page.next_cursor.is_some();
                        let page_partial = page.partial;
                        let page_history_truncated = page.history_truncated;
                        let next_cursor = page.next_cursor;
                        let activities = page.activities;
                        let activity_ids = activities
                            .iter()
                            .map(|activity| activity.job_id.clone())
                            .collect::<BTreeSet<_>>();
                        let prior_next_cursor = self.placement_activity_next_cursor.clone();
                        let had_known_head = !self.placement_activity_head_job_ids.is_empty();
                        let query_changed = self.placement_activity_loaded_filter != filter;
                        if append {
                            for activity in activities {
                                match self
                                    .placement_activity
                                    .iter()
                                    .position(|current| current.job_id == activity.job_id)
                                {
                                    Some(index)
                                        if activity.revision
                                            >= self.placement_activity[index].revision =>
                                    {
                                        self.placement_activity[index] = activity;
                                    }
                                    Some(_) => {}
                                    None => self.placement_activity.push(activity),
                                }
                            }
                            self.placement_activity_next_cursor = next_cursor;
                        } else if query_changed
                            || filter == PlacementActivityFilter::Active
                            || !page_has_more
                            || self.placement_activity.is_empty()
                        {
                            // A complete successful query is authoritative. Replacing the rows
                            // evicts jobs that left Active/Failed after a state transition; stale
                            // rows are retained only when the read itself fails.
                            self.placement_activity = activities;
                            self.placement_activity_next_cursor = next_cursor;
                        } else {
                            // Preserve the loaded terminal window while merging the refreshed
                            // head. Removing prior head IDs would create a pagination hole whenever
                            // new jobs push old head rows behind the retained tail cursor.
                            //
                            // The All view is different only for active rows: its separately
                            // queried active head is bounded, so an absent older Running/Retrying
                            // row cannot be retained as truth. Resetting to the refreshed cursor
                            // after dropping one lets pagination rediscover its terminal state.
                            let dropped_stale_active =
                                filter == PlacementActivityFilter::All
                                    && self.placement_activity.iter().any(|activity| {
                                        matches!(
                                            activity.status,
                                            sinomo_runtime::dfs::DfsPlacementReconciliationActivityStatus::Running
                                                | sinomo_runtime::dfs::DfsPlacementReconciliationActivityStatus::Retrying
                                        ) && !activity_ids.contains(&activity.job_id)
                                    });
                            if filter == PlacementActivityFilter::All {
                                self.placement_activity.retain(|activity| {
                                    !matches!(
                                        activity.status,
                                        sinomo_runtime::dfs::DfsPlacementReconciliationActivityStatus::Running
                                            | sinomo_runtime::dfs::DfsPlacementReconciliationActivityStatus::Retrying
                                    )
                                });
                            }
                            for activity in activities {
                                match self
                                    .placement_activity
                                    .iter()
                                    .position(|current| current.job_id == activity.job_id)
                                {
                                    Some(index)
                                        if activity.revision
                                            >= self.placement_activity[index].revision =>
                                    {
                                        self.placement_activity[index] = activity;
                                    }
                                    Some(_) => {}
                                    None => self.placement_activity.push(activity),
                                }
                            }
                            self.placement_activity_next_cursor = if dropped_stale_active {
                                next_cursor
                            } else if had_known_head {
                                prior_next_cursor
                            } else {
                                next_cursor
                            };
                        }
                        if !append {
                            self.placement_activity_head_job_ids = activity_ids;
                            self.placement_activity_loaded_filter = filter;
                        }
                        self.placement_activity.sort_by(|left, right| {
                            right
                                .created_at_unix_nanos
                                .cmp(&left.created_at_unix_nanos)
                                .then_with(|| right.job_id.cmp(&left.job_id))
                        });
                        self.placement_activity_error = None;
                        if query_changed {
                            self.placement_activity_partial = page_partial;
                            self.placement_activity_history_truncated = page_history_truncated;
                        } else {
                            self.placement_activity_partial |= page_partial;
                            self.placement_activity_history_truncated |= page_history_truncated;
                        }
                        if self.placement_activity_origin_daemon_address.is_none() {
                            self.placement_activity_origin_daemon_address =
                                self.daemon_address.clone();
                        }
                        self.placement_activity_refreshed_at_unix_nanos =
                            time::OffsetDateTime::now_utc()
                                .unix_timestamp_nanos()
                                .try_into()
                                .ok();
                        if refresh_dirty && self.placement_activity_open {
                            self.request_placement_activity(false, Duration::ZERO);
                        } else {
                            let poll_interval = if self.placement_activity_has_active_jobs() {
                                PLACEMENT_ACTIVITY_POLL_INTERVAL
                            } else {
                                PLACEMENT_ACTIVITY_IDLE_POLL_INTERVAL
                            };
                            self.schedule_placement_activity_poll(poll_interval);
                        }
                    }
                    Err(error) => {
                        self.placement_activity_error = Some(error);
                        if refresh_dirty && self.placement_activity_open {
                            self.request_placement_activity(false, Duration::ZERO);
                        } else {
                            self.schedule_placement_activity_poll(Duration::from_secs(5));
                        }
                    }
                }
                true
            }
        }
    }

    fn schedule_ui_extension_catalog_refresh(&mut self) {
        if self.ui_preview_catalog_refresh_pending
            || Instant::now() < self.ui_preview_catalog_refresh_after
        {
            return;
        }
        self.ui_preview_catalog_refresh_after =
            Instant::now() + UI_EXTENSION_CATALOG_REFRESH_INTERVAL;
        let (Some(address), Some(result_tx), Some(waker)) = (
            self.daemon_address.clone(),
            self.worker_result_tx.clone(),
            self.worker_waker.clone(),
        ) else {
            return;
        };
        self.ui_preview_catalog_refresh_pending = true;
        self.app_runtime.spawn_blocking(move || {
            let result = crate::backend::ui_extensions::ui_extension_catalog_at_address(
                &address,
                Some(FILE_PREVIEW_EXTENSION_POINT_ID),
            );
            let _ = result_tx.send(FilesWorkerResult::UiExtensionCatalog(result));
            waker.wake();
        });
    }

    fn apply_live_update(&mut self, update: FilesLiveUpdate) -> bool {
        match update {
            FilesLiveUpdate::Item(DaemonEventStreamItem::Ready { .. }) => {
                let changed = !self.live_updates_connected || self.live_updates_error.is_some();
                let activity_open = self.placement_activity_open;
                self.live_updates_connected = true;
                self.live_updates_error = None;
                // The stream is live now. Reload the durable snapshot once so changes made between
                // the initial list and subscription readiness cannot be missed.
                self.live_refresh_pending |= self.source == FilesSourceKind::Sifs;
                if self.placement_activity_open {
                    self.refresh_placement_activity();
                }
                changed || self.source == FilesSourceKind::Sifs || activity_open
            }
            FilesLiveUpdate::Item(DaemonEventStreamItem::Event { event }) => {
                let status_changed =
                    !self.live_updates_connected || self.live_updates_error.is_some();
                self.live_updates_connected = true;
                self.live_updates_error = None;
                let selected_path = self.selected_entry().map(|entry| entry.path.as_str());
                let touches_location = self.source == FilesSourceKind::Sifs
                    && dfs_event_touches_location(&event.payload, &self.path, selected_path);
                if touches_location {
                    self.live_refresh_pending = true;
                }
                let placement_changed = event.kind.as_str().starts_with("dfs.placement.");
                if placement_changed && self.placement_activity_open {
                    self.refresh_placement_activity();
                }
                status_changed || touches_location || placement_changed
            }
            FilesLiveUpdate::Item(DaemonEventStreamItem::Lagged { .. }) => {
                let status_changed =
                    !self.live_updates_connected || self.live_updates_error.is_some();
                let activity_open = self.placement_activity_open;
                self.live_updates_connected = true;
                self.live_updates_error = None;
                self.live_refresh_pending |= self.source == FilesSourceKind::Sifs;
                if self.placement_activity_open {
                    self.refresh_placement_activity();
                }
                status_changed || self.source == FilesSourceKind::Sifs || activity_open
            }
            FilesLiveUpdate::Disconnected(detail) => {
                let changed = self.live_updates_connected
                    || self.live_updates_error.as_deref() != Some(detail.as_str());
                self.live_updates_connected = false;
                self.live_updates_error = Some(detail);
                changed
            }
        }
    }

    fn flush_live_refresh(&mut self) -> bool {
        if !self.live_refresh_pending
            || self.source != FilesSourceKind::Sifs
            || !self.loaded
            || self.loading
            || self.pending_request_id.is_some()
            || self.pending_append_request_id.is_some()
        {
            return false;
        }
        self.live_refresh_pending = false;
        self.pending_select_path = self.selected_entry().map(|entry| entry.path.clone());
        self.reload();
        true
    }

    fn current_location(&self) -> FilesLocation {
        FilesLocation {
            source: self.source,
            path: self.path.clone(),
        }
    }

    fn can_go_back(&self) -> bool {
        !self.history_back.is_empty()
    }

    fn can_go_forward(&self) -> bool {
        !self.history_forward.is_empty()
    }

    fn can_modify_current_location(&self) -> bool {
        self.loaded && !self.loading && self.error.is_none()
    }

    fn push_history(stack: &mut Vec<FilesLocation>, location: FilesLocation) {
        if stack.last() == Some(&location) {
            return;
        }
        stack.push(location);
        if stack.len() > MAX_NAV_HISTORY {
            stack.remove(0);
        }
    }

    fn record_navigation_origin(&mut self) {
        let location = self.current_location();
        Self::push_history(&mut self.history_back, location);
        self.history_forward.clear();
    }

    fn normalize_location_path(
        &self,
        source: FilesSourceKind,
        path: &str,
    ) -> Result<String, String> {
        match source {
            FilesSourceKind::Sifs => Ok(self
                .browser
                .as_ref()
                .map(|b| b.normalize(path))
                .unwrap_or_else(|| normalize_path(path))),
            FilesSourceKind::Local => {
                let path = Path::new(path);
                let candidate = if path.is_absolute() {
                    path.to_path_buf()
                } else {
                    Path::new(&self.path).join(path)
                };
                normalize_local_path(&candidate.to_string_lossy())
            }
        }
    }

    fn apply_location(
        &mut self,
        source: FilesSourceKind,
        path: String,
        waker: Option<sui::UiHandle>,
    ) {
        let location_changed = self.source != source || self.path != path;
        if self.source != source {
            self.store_active_path();
            self.source = source;
            self.error = None;
            self.entries.clear();
            self.entry_metadata.clear();
            self.entries_total_count = 0;
            self.selected = None;
            self.clear_selected_details();
            self.loading = false;
            self.pending_request_id = None;
            self.pending_append_request_id = None;
            self.completed_request_id = None;
            self.pending_details_request_id = None;
            self.pending_preview_request_id = None;
            self.list_revision = self.list_revision.wrapping_add(1);
            if let Some(waker) = waker {
                self.ensure_worker(waker);
            }
            self.loaded = true;
        }
        self.path = path;
        if location_changed {
            self.picker_context_generation = self.picker_context_generation.wrapping_add(1);
        }
        self.store_active_path();
        self.reload();
    }

    pub(crate) fn open_location(
        &mut self,
        source: FilesSourceKind,
        path: String,
        waker: Option<sui::UiHandle>,
    ) {
        let normalized = match self.normalize_location_path(source, &path) {
            Ok(path) => path,
            Err(error) => {
                self.error = Some(error);
                self.list_revision = self.list_revision.wrapping_add(1);
                return;
            }
        };
        if self.source == source && self.path == normalized {
            self.reload();
            return;
        }
        self.record_navigation_origin();
        self.apply_location(source, normalized, waker);
    }

    pub(crate) fn open_sifs_path(&mut self, path: impl Into<String>, waker: Option<sui::UiHandle>) {
        self.open_location(FilesSourceKind::Sifs, path.into(), waker);
    }

    fn navigate(&mut self, path: String) {
        self.open_location(self.source, path, None);
    }

    fn go_up(&mut self) {
        let parent = match self.source {
            FilesSourceKind::Sifs => self
                .browser
                .as_ref()
                .and_then(|b| b.parent(&self.path))
                .or_else(|| parent_path(&self.path)),
            FilesSourceKind::Local => parent_local_path(&self.path),
        };
        if let Some(parent) = parent {
            self.navigate(parent);
        }
    }

    fn go_back(&mut self, waker: Option<sui::UiHandle>) {
        let Some(location) = self.history_back.pop() else {
            return;
        };
        let current = self.current_location();
        if current != location {
            Self::push_history(&mut self.history_forward, current);
        }
        self.apply_location(location.source, location.path, waker);
    }

    /// Follow the same history stack as the Files header's back button.
    pub(crate) fn navigate_back(&mut self, waker: Option<sui::UiHandle>) -> bool {
        if !self.can_go_back() {
            return false;
        }
        self.go_back(waker);
        true
    }

    fn go_forward(&mut self, waker: Option<sui::UiHandle>) {
        let Some(location) = self.history_forward.pop() else {
            return;
        };
        let current = self.current_location();
        if current != location {
            Self::push_history(&mut self.history_back, current);
        }
        self.apply_location(location.source, location.path, waker);
    }

    fn switch_source(&mut self, source: FilesSourceKind, waker: Option<sui::UiHandle>) {
        if self.source == source {
            return;
        }
        let path = match source {
            FilesSourceKind::Sifs => self.sifs_path.clone(),
            FilesSourceKind::Local => self.local_path.clone(),
        };
        self.open_location(source, path, waker);
    }

    fn store_active_path(&mut self) {
        match self.source {
            FilesSourceKind::Sifs => self.sifs_path = self.path.clone(),
            FilesSourceKind::Local => self.local_path = self.path.clone(),
        }
    }

    fn clear_selected_details(&mut self) {
        self.selected_details = None;
        self.selected_local_details = None;
        self.details_loading = false;
        self.details_error = None;
        self.pending_details_request_id = None;
        self.selected_preview = None;
        self.custom_preview = None;
        self.preview_loading = false;
        self.preview_error = None;
        self.pending_preview_request_id = None;
        if !self.history_open {
            self.clear_history_content();
        }
    }

    fn selected_entry(&self) -> Option<&SifsEntry> {
        self.selected.and_then(|i| self.entries.get(i))
    }

    fn entry_marked(&self, index: usize) -> bool {
        self.marked_entries.contains(&index)
    }

    fn marked_count(&self) -> usize {
        self.marked_entries.len()
    }

    fn marked_targets(&self) -> Vec<FileActionTarget> {
        self.marked_entries
            .iter()
            .filter_map(|index| self.entries.get(*index))
            .map(|entry| FileActionTarget {
                path: entry.path.clone(),
                is_dir: entry.is_dir,
            })
            .collect()
    }

    fn toggle_marked_entry(&mut self, index: usize) -> bool {
        if index >= self.entries.len() {
            return false;
        }
        if !self.marked_entries.insert(index) {
            self.marked_entries.remove(&index);
        }
        true
    }

    fn clear_marked_entries(&mut self) {
        self.marked_entries.clear();
    }

    fn request_selected_details(&mut self) {
        let Some(entry) = self.selected_entry().cloned() else {
            self.clear_selected_details();
            return;
        };
        let path = entry.path.clone();
        self.selected_details = None;
        self.details_error = None;
        if let Some(tx) = self.worker_tx.clone() {
            let request_id = self.next_request_id;
            self.next_request_id = self.next_request_id.wrapping_add(1);
            self.pending_details_request_id = Some(request_id);
            self.details_loading = true;
            if tx
                .send(FilesWorkerCommand::Details {
                    request_id,
                    source: self.source,
                    path,
                })
                .is_err()
            {
                self.pending_details_request_id = None;
                self.details_loading = false;
                self.details_error = Some("SIFS browser worker stopped".to_string());
            }
            self.request_selected_preview(entry);
            return;
        }

        self.pending_details_request_id = None;
        self.details_loading = false;
        match self.source {
            FilesSourceKind::Sifs => match self.browser.as_ref().map(|browser| browser.stat(&path))
            {
                Some(Ok(details)) => self.selected_details = Some(details),
                Some(Err(error)) => self.details_error = Some(error),
                None => {}
            },
            FilesSourceKind::Local => match local_details(&path) {
                Ok(details) => self.selected_local_details = Some(details),
                Err(error) => self.details_error = Some(error),
            },
        }
        self.request_selected_preview(entry);
    }

    fn request_selected_preview(&mut self, entry: SifsEntry) {
        self.selected_preview = None;
        self.custom_preview = None;
        self.preview_error = None;
        self.pending_preview_request_id = None;
        if entry.is_dir {
            self.preview_loading = false;
            return;
        }
        if let Some(tx) = self.worker_tx.clone() {
            let max_bytes = if self.ui_preview_entries.is_empty() {
                FILE_PREVIEW_MAX_BYTES
            } else {
                CUSTOM_FILE_PREVIEW_MAX_BYTES
            };
            let request_id = self.next_request_id;
            self.next_request_id = self.next_request_id.wrapping_add(1);
            self.pending_preview_request_id = Some(request_id);
            self.preview_loading = true;
            if tx
                .send(FilesWorkerCommand::Preview {
                    request_id,
                    source: self.source,
                    path: entry.path,
                    max_bytes,
                })
                .is_err()
            {
                self.pending_preview_request_id = None;
                self.preview_loading = false;
                self.preview_error = Some("SIFS browser worker stopped".to_string());
            }
            return;
        }

        self.preview_loading = false;
        let max_bytes = if self.ui_preview_entries.is_empty() {
            FILE_PREVIEW_MAX_BYTES
        } else {
            CUSTOM_FILE_PREVIEW_MAX_BYTES
        };
        let result = match self.source {
            FilesSourceKind::Sifs => self
                .browser
                .as_ref()
                .ok_or_else(|| "SIFS browser is not open".to_string())
                .and_then(|browser| {
                    browser
                        .read_file_prefix(&entry.path, max_bytes)
                        .map(|read| preview_from_read(&entry.name, read))
                }),
            FilesSourceKind::Local => local_read_file_prefix(&entry.path, max_bytes)
                .map(|read| preview_from_read(&entry.name, read)),
        };
        match result {
            Ok(preview) => {
                self.custom_preview = self.start_custom_preview(&entry.path, &preview);
                self.selected_preview = Some(preview);
            }
            Err(error) => {
                self.custom_preview = None;
                self.preview_error = Some(error);
            }
        }
    }

    fn start_custom_preview(
        &self,
        path: &str,
        preview: &FilesPreview,
    ) -> Option<CustomFilesPreview> {
        if cfg!(target_os = "android") {
            // Android needs a platform isolated-service host rather than the
            // desktop sibling-executable lifecycle. Preserve the built-in
            // preview until that backend exists.
            return None;
        }
        let name = Path::new(path)
            .file_name()
            .and_then(|name| name.to_str())
            .unwrap_or(path);
        let matches = self
            .ui_preview_entries
            .iter()
            .filter(|entry| ui_preview_entry_matches(entry, name, &preview.bytes))
            .cloned()
            .collect::<Vec<_>>();
        if matches.len() > 1 {
            tracing::warn!(
                file_name = name,
                providers = matches.len(),
                "custom file preview is ambiguous; preserving the built-in preview until the user selects a provider"
            );
            return None;
        }
        let entry = matches.into_iter().next()?;
        let UiContributionPayload::CustomWidget { widget } = &entry.contribution.payload else {
            return None;
        };
        entry.component_path.as_ref()?;
        let content = UiContentGrant {
            grant_id: format!(
                "files.preview.{}.{}",
                self.ui_preview_catalog_generation, self.list_revision
            ),
            display_name: name.to_string(),
            content_version: format!("{}:{}", self.list_revision, path),
            size_bytes: self
                .selected_entry()
                .and_then(|selected| selected.size)
                .unwrap_or_else(|| {
                    (preview.bytes.len() as u64).saturating_add(u64::from(preview.truncated))
                }),
            media_type: None,
            initial_bytes: preview.bytes.clone(),
        };
        match ModuleWidgetSession::start(
            entry.clone(),
            content,
            DefaultTheme::default(),
            self.worker_waker.clone(),
        ) {
            Ok(session) => Some(CustomFilesPreview {
                contribution_id: entry.contribution.contribution_id,
                label: widget.label.clone(),
                sizing: widget.sizing,
                session,
            }),
            Err(error) => {
                tracing::warn!(
                    contribution_id = %entry.contribution.contribution_id,
                    %error,
                    "custom file preview did not start"
                );
                None
            }
        }
    }

    fn open_selected_document(&mut self, waker: Option<sui::UiHandle>) {
        let Some(entry) = self.selected_entry().cloned() else {
            return;
        };
        if entry.is_dir {
            return;
        }
        self.open_document(self.source, entry.path, entry.name, waker);
    }

    fn open_document(
        &mut self,
        source: FilesSourceKind,
        path: String,
        title: String,
        waker: Option<sui::UiHandle>,
    ) {
        self.pending_tab_open = Some((source, path, title));
        if let Some(waker) = waker {
            waker.wake();
        }
    }

    pub(crate) fn begin_document_load(
        &mut self,
        source: FilesSourceKind,
        path: String,
        title: String,
        waker: Option<sui::UiHandle>,
    ) {
        if let Some(waker) = waker {
            self.ensure_worker(waker);
        }
        self.compact_overlay = None;
        self.action_prompt = None;
        self.document_close_confirmation = false;
        self.pending_document_open = None;
        self.pending_document_save_request_id = None;
        self.pending_document_saved_text = None;
        self.document = Some(FilesDocument::loading(source, path.clone(), title));
        self.document_revision = self.document_revision.wrapping_add(1);
        let Some(tx) = self.worker_tx.clone() else {
            if let Some(document) = self.document.as_mut() {
                document.loading = false;
                document.load_error = Some("The Files background worker is not ready. Retry after the folder finishes loading.".to_string());
            }
            self.document_revision = self.document_revision.wrapping_add(1);
            return;
        };
        let request_id = self.next_request_id;
        self.next_request_id = self.next_request_id.wrapping_add(1);
        self.pending_document_request_id = Some(request_id);
        if tx
            .send(FilesWorkerCommand::ReadDocument {
                request_id,
                source,
                path,
            })
            .is_err()
        {
            self.pending_document_request_id = None;
            if let Some(document) = self.document.as_mut() {
                document.loading = false;
                document.load_error =
                    Some("The Files background worker stopped. Retry the document.".to_string());
            }
            self.document_revision = self.document_revision.wrapping_add(1);
        }
    }

    fn retry_document(&mut self, waker: Option<sui::UiHandle>) {
        let Some(document) = self.document.as_ref() else {
            return;
        };
        let request = (
            document.source,
            document.path.clone(),
            document.title.clone(),
        );
        self.begin_document_load(request.0, request.1, request.2, waker);
    }

    fn set_document_text(&mut self, value: String) {
        let Some(document) = self.document.as_mut() else {
            return;
        };
        if !document.editable() {
            return;
        }
        document.text = value;
        document.save_error = None;
    }

    fn save_document(&mut self, waker: Option<sui::UiHandle>) {
        if let Some(waker) = waker {
            self.ensure_worker(waker);
        }
        let Some(document) = self.document.as_mut() else {
            return;
        };
        if !document.editable() || !document.dirty() || document.saving {
            return;
        }
        let Some(tx) = self.worker_tx.clone() else {
            document.save_error = Some("The Files background worker is not available.".to_string());
            return;
        };
        let request_id = self.next_request_id;
        self.next_request_id = self.next_request_id.wrapping_add(1);
        document.saving = true;
        document.save_error = None;
        document.save_warning = None;
        self.pending_document_saved_text = Some(document.text.clone());
        self.pending_document_save_request_id = Some(request_id);
        let command = match document.source {
            FilesSourceKind::Local => {
                let Some(expected) = document.local_fingerprint.clone() else {
                    document.saving = false;
                    self.pending_document_save_request_id = None;
                    self.pending_document_saved_text = None;
                    document.save_error = Some(
                        "The local file fingerprint is missing. Reload before saving.".to_string(),
                    );
                    return;
                };
                FilesWorkerCommand::SaveLocalDocument {
                    request_id,
                    path: document.path.clone(),
                    expected,
                    text: document.text.clone(),
                }
            }
            FilesSourceKind::Sifs => {
                let Some(expected) = document.sifs_fingerprint.clone() else {
                    document.saving = false;
                    self.pending_document_save_request_id = None;
                    self.pending_document_saved_text = None;
                    document.save_error = Some(
                        "The SIFS object version is missing. Reload before saving.".to_string(),
                    );
                    return;
                };
                FilesWorkerCommand::SaveSifsDocument {
                    request_id,
                    path: document.path.clone(),
                    expected,
                    text: document.text.clone(),
                }
            }
        };
        if tx.send(command).is_err() {
            self.pending_document_save_request_id = None;
            self.pending_document_saved_text = None;
            document.saving = false;
            document.save_error =
                Some("The Files background worker stopped before saving.".to_string());
        }
    }

    pub(crate) fn request_close_document(&mut self) {
        if self.document.as_ref().is_some_and(FilesDocument::dirty) {
            self.document_close_confirmation = true;
            return;
        }
        self.close_document_now();
    }

    fn close_document_now(&mut self) {
        self.document = None;
        self.document_close_confirmation = false;
        self.pending_document_open = None;
        self.pending_document_request_id = None;
        self.pending_document_save_request_id = None;
        self.pending_document_saved_text = None;
        self.document_revision = self.document_revision.wrapping_add(1);
    }

    fn cancel_document_close(&mut self) {
        self.document_close_confirmation = false;
        self.pending_document_open = None;
    }

    fn discard_document_and_continue(&mut self, waker: Option<sui::UiHandle>) {
        let pending = self.pending_document_open.take();
        self.document = None;
        self.document_close_confirmation = false;
        self.pending_document_request_id = None;
        self.pending_document_save_request_id = None;
        self.pending_document_saved_text = None;
        self.document_revision = self.document_revision.wrapping_add(1);
        if let Some((source, path, title)) = pending {
            self.begin_document_load(source, path, title, waker);
        }
    }

    fn start_attach_selected(&mut self, waker: Option<sui::UiHandle>) {
        let Some(entry) = self.selected_entry().cloned() else {
            return;
        };
        if entry.is_dir {
            self.attachment_error =
                Some("Folders cannot be attached directly. Choose a file.".to_string());
            return;
        }
        self.start_attach_path(self.source, entry.path, entry.name, waker);
    }

    fn start_attach_document(&mut self, waker: Option<sui::UiHandle>) {
        let Some(document) = self.document.as_ref() else {
            return;
        };
        let provenance = match document.source {
            FilesSourceKind::Local => {
                let Some(fingerprint) = document.local_fingerprint.as_ref() else {
                    self.attachment_error = Some(
                        "The document has no local snapshot fingerprint. Reload before attaching."
                            .to_string(),
                    );
                    return;
                };
                FilesAttachmentProvenance::Local {
                    path: document.path.clone(),
                    canonical_path: fingerprint.canonical_path.to_string_lossy().into_owned(),
                    modified_at_unix_nanos: fingerprint.modified_at_unix_nanos,
                }
            }
            FilesSourceKind::Sifs => {
                let Some(fingerprint) = document.sifs_fingerprint.as_ref() else {
                    self.attachment_error = Some(
                        "The document has no SIFS object version. Reload before attaching."
                            .to_string(),
                    );
                    return;
                };
                FilesAttachmentProvenance::Sifs {
                    path: document.path.clone(),
                    object_id: fingerprint.object_id.clone(),
                    version: fingerprint.version.clone(),
                    content_hash: fingerprint.content_hash.clone(),
                    policy: fingerprint.policy.clone(),
                }
            }
        };
        self.ready_attachment_intent = Some(FilesAttachmentIntent {
            file_name: document.title.clone(),
            bytes: document.text.as_bytes().to_vec(),
            provenance,
            is_unsaved_editor_buffer: document.dirty(),
        });
        self.attachment_error = None;
        if let Some(waker) = waker {
            waker.wake();
        }
    }

    fn start_attach_path(
        &mut self,
        source: FilesSourceKind,
        path: String,
        file_name: String,
        waker: Option<sui::UiHandle>,
    ) {
        if let Some(waker) = waker {
            self.ensure_worker(waker);
        }
        let Some(tx) = self.worker_tx.clone() else {
            self.attachment_error =
                Some("The Files background worker is not available.".to_string());
            return;
        };
        let request_id = self.next_request_id;
        self.next_request_id = self.next_request_id.wrapping_add(1);
        self.pending_attachment_request_id = Some(request_id);
        self.pending_attachment_source_path = Some((source, path.clone()));
        self.attachment_loading = true;
        self.attachment_error = None;
        self.ready_attachment_intent = None;
        if tx
            .send(FilesWorkerCommand::ReadAttachment {
                request_id,
                source,
                path,
                file_name,
            })
            .is_err()
        {
            self.pending_attachment_request_id = None;
            self.pending_attachment_source_path = None;
            self.attachment_loading = false;
            self.attachment_error = Some(
                "The Files background worker stopped before reading the attachment.".to_string(),
            );
        }
    }

    pub(crate) fn take_ready_attachment_intent(&mut self) -> Option<FilesAttachmentIntent> {
        self.ready_attachment_intent.take()
    }

    fn request_native_picker(&mut self, action: FilesPickerAction, waker: Option<sui::UiHandle>) {
        let (kind, title) = match action {
            FilesPickerAction::OpenFile => (NativePickerKind::OneFile, "Open a local file"),
            FilesPickerAction::OpenFolder => (NativePickerKind::OneFolder, "Open a local folder"),
            FilesPickerAction::ImportFiles => (
                NativePickerKind::MultipleFiles,
                "Import files into this folder",
            ),
            FilesPickerAction::ImportFolder => (
                NativePickerKind::OneFolder,
                "Import a folder into this folder",
            ),
            FilesPickerAction::ChooseDestination => {
                (NativePickerKind::OneFolder, "Choose a destination folder")
            }
        };
        self.picker_error = None;
        match self
            .picker_lane
            .request(kind, title, self.picker_context_generation, waker)
        {
            Ok(_) => self.picker_action = Some(action),
            Err(error) => self.picker_error = Some(error),
        }
    }

    fn poll_native_picker(&mut self) -> bool {
        let Some(result) = self.picker_lane.poll() else {
            return false;
        };
        let action = self.picker_action.take();
        if result.context_generation != self.picker_context_generation
            && matches!(
                action,
                Some(
                    FilesPickerAction::ImportFiles
                        | FilesPickerAction::ImportFolder
                        | FilesPickerAction::ChooseDestination
                )
            )
        {
            self.picker_error = Some(
                "The destination changed while the picker was open. Nothing was imported."
                    .to_string(),
            );
            return true;
        }
        match (action, result.outcome) {
            (_, NativePickerOutcome::Cancelled) => {}
            (_, NativePickerOutcome::Failed(error)) => self.picker_error = Some(error),
            (Some(FilesPickerAction::OpenFile), NativePickerOutcome::Selected(mut paths)) => {
                if let Some(path) = paths.pop() {
                    self.open_picked_local_file(path);
                }
            }
            (Some(FilesPickerAction::OpenFolder), NativePickerOutcome::Selected(mut paths)) => {
                if let Some(path) = paths.pop() {
                    match normalize_local_path(&path.to_string_lossy()) {
                        Ok(path) => self.open_location(
                            FilesSourceKind::Local,
                            path,
                            self.worker_waker.clone(),
                        ),
                        Err(error) => self.picker_error = Some(error),
                    }
                }
            }
            (
                Some(FilesPickerAction::ImportFiles | FilesPickerAction::ImportFolder),
                NativePickerOutcome::Selected(paths),
            ) => {
                if let Err(error) = self.import_external_paths(paths, self.worker_waker.clone()) {
                    self.picker_error = Some(error);
                }
            }
            (
                Some(FilesPickerAction::ChooseDestination),
                NativePickerOutcome::Selected(mut paths),
            ) => {
                if let Some(path) = paths.pop() {
                    self.apply_picked_destination(path);
                }
            }
            (None, NativePickerOutcome::Selected(_)) => {
                self.picker_error = Some("The picker result no longer has an owner.".to_string())
            }
        }
        true
    }

    fn apply_picked_destination(&mut self, folder: PathBuf) {
        let folder = match normalize_local_path(&folder.to_string_lossy()) {
            Ok(folder) => folder,
            Err(error) => {
                self.picker_error = Some(error);
                return;
            }
        };
        let Some(prompt) = self.action_prompt.as_mut() else {
            self.picker_error = Some("The destination dialog is no longer open.".to_string());
            return;
        };
        let destination = match prompt.kind {
            FileActionPromptKind::Copy
            | FileActionPromptKind::Move
            | FileActionPromptKind::CopyToLocal => {
                join_local_child(&folder, &prompt.target_name).unwrap_or(folder)
            }
            FileActionPromptKind::CopySelected
            | FileActionPromptKind::MoveSelected
            | FileActionPromptKind::TransferSelected => folder,
            _ => {
                self.picker_error =
                    Some("This action does not accept a local destination folder.".to_string());
                return;
            }
        };
        prompt.input = destination;
        prompt.error = None;
        self.picker_error = None;
        self.action_prompt_revision = self.action_prompt_revision.wrapping_add(1);
    }

    fn choose_sifs_destination(&mut self, folder: &str) {
        let Some(prompt) = self.action_prompt.as_mut() else {
            return;
        };
        let destination = match prompt.kind {
            FileActionPromptKind::Copy
            | FileActionPromptKind::Move
            | FileActionPromptKind::CopyToSifs => {
                join_sifs_child(folder, &prompt.target_name).unwrap_or_else(|_| folder.to_string())
            }
            FileActionPromptKind::CopySelected
            | FileActionPromptKind::MoveSelected
            | FileActionPromptKind::TransferSelected => folder.to_string(),
            _ => return,
        };
        prompt.input = destination;
        prompt.error = None;
        self.picker_error = None;
        self.action_prompt_revision = self.action_prompt_revision.wrapping_add(1);
    }

    fn open_picked_local_file(&mut self, path: PathBuf) {
        let path_string = path.to_string_lossy().into_owned();
        let title = path
            .file_name()
            .map(|name| name.to_string_lossy().into_owned())
            .unwrap_or_else(|| path_string.clone());
        if let Some(parent) = path.parent() {
            let parent = parent.to_string_lossy().into_owned();
            self.pending_select_path = Some(path_string.clone());
            self.open_location(FilesSourceKind::Local, parent, self.worker_waker.clone());
        }
        self.open_document(
            FilesSourceKind::Local,
            path_string,
            title,
            self.worker_waker.clone(),
        );
    }

    fn import_external_paths(
        &mut self,
        paths: Vec<PathBuf>,
        waker: Option<sui::UiHandle>,
    ) -> Result<(), String> {
        if paths.is_empty() {
            return Ok(());
        }
        if !self.can_modify_current_location() {
            return Err(
                "Wait for the destination folder to become available before importing.".to_string(),
            );
        }
        if let Some(waker) = waker {
            self.ensure_worker(waker);
        }
        let Some(tx) = self.operations_sender() else {
            return Err("The Files background worker is not available.".to_string());
        };
        let request_id = self.next_request_id;
        self.next_request_id = self.next_request_id.wrapping_add(1);
        self.pending_import_request_ids.insert(request_id);
        if tx
            .send(FilesWorkerCommand::PrepareImport {
                request_id,
                destination_source: self.source,
                destination_path: self.path.clone(),
                paths,
            })
            .is_err()
        {
            self.pending_import_request_ids.remove(&request_id);
            return Err(
                "The Files background worker stopped before preparing the import.".to_string(),
            );
        }
        Ok(())
    }

    pub(crate) fn begin_external_file_hover(&mut self, _path: PathBuf) -> bool {
        let changed = !self.external_file_hovered;
        self.external_file_hovered = true;
        changed
    }

    pub(crate) fn cancel_external_file_hover(&mut self) -> bool {
        let changed = self.external_file_hovered;
        self.external_file_hovered = false;
        changed
    }

    pub(crate) fn accept_external_file_drop(
        &mut self,
        path: PathBuf,
        waker: Option<sui::UiHandle>,
    ) -> bool {
        self.external_file_hovered = false;
        if let Err(error) = self.import_external_paths(vec![path], waker) {
            self.picker_error = Some(error);
        }
        true
    }

    fn select_entry(&mut self, index: usize) -> bool {
        if index >= self.entries.len() {
            return false;
        }
        let changed = self.selected != Some(index);
        self.selected = Some(index);
        if changed || self.selected_details.is_none() {
            self.request_selected_details();
        }
        changed
    }

    /// Select the row targeted by a context click. A click outside the marked set starts a new
    /// single-item context, while clicking a marked row preserves the batch operation target.
    fn select_context_entry(&mut self, index: usize) -> bool {
        if index >= self.entries.len() {
            return false;
        }
        let cleared_marks = !self.entry_marked(index) && !self.marked_entries.is_empty();
        if cleared_marks {
            self.clear_marked_entries();
        }
        self.select_entry(index) || cleared_marks
    }

    fn open_action_prompt(&mut self, kind: FileActionPromptKind) {
        self.compact_overlay = None;
        let targets = if file_prompt_uses_marked_targets(kind) {
            self.marked_targets()
        } else {
            Vec::new()
        };
        let selected = self.selected_entry().cloned();
        let (target_path, target_name, target_is_dir) = match selected {
            Some(entry) => (Some(entry.path), entry.name, entry.is_dir),
            None => (None, String::new(), false),
        };
        let placement_draft = if kind == FileActionPromptKind::Placement {
            self.selected_details
                .as_ref()
                .filter(|details| {
                    Some(details.path.as_str()) == target_path.as_deref()
                        && details.placement.is_some()
                })
                .map(|details| PlacementEditorDraft::for_details(Some(details), target_is_dir))
        } else {
            None
        };
        let continuing_reconciliation_job = (kind == FileActionPromptKind::Placement)
            .then(|| {
                self.placement_reconciliation
                    .as_ref()
                    .filter(|job| {
                        !job.state.is_terminal()
                            && Some(job.path.as_str()) == target_path.as_deref()
                    })
                    .map(|job| job.job_id.clone())
            })
            .flatten();
        let input = match kind {
            FileActionPromptKind::GoTo => self.path.clone(),
            FileActionPromptKind::NewFile => "untitled.txt".to_string(),
            FileActionPromptKind::NewFolder => "New folder".to_string(),
            FileActionPromptKind::Copy => {
                if target_name.is_empty() {
                    String::new()
                } else {
                    suggested_copy_name(&target_name)
                }
            }
            FileActionPromptKind::CopySelected | FileActionPromptKind::MoveSelected => {
                self.path.clone()
            }
            FileActionPromptKind::CopyToSifs => {
                default_sifs_transfer_destination(&self.sifs_path, &target_name)
            }
            FileActionPromptKind::CopyToLocal => {
                default_local_transfer_destination(&self.local_path, &target_name)
            }
            FileActionPromptKind::TransferSelected => match self.source {
                FilesSourceKind::Sifs => self.local_path.clone(),
                FilesSourceKind::Local => self.sifs_path.clone(),
            },
            FileActionPromptKind::Move => target_name.clone(),
            FileActionPromptKind::Rename => target_name.clone(),
            FileActionPromptKind::Delete | FileActionPromptKind::DeleteSelected => String::new(),
            FileActionPromptKind::Placement => String::new(),
        };
        let error = match kind {
            FileActionPromptKind::Copy
            | FileActionPromptKind::CopyToSifs
            | FileActionPromptKind::CopyToLocal
            | FileActionPromptKind::Move
            | FileActionPromptKind::Rename
            | FileActionPromptKind::Delete
                if target_path.is_none() =>
            {
                Some("select an item first".to_string())
            }
            FileActionPromptKind::CopySelected
            | FileActionPromptKind::TransferSelected
            | FileActionPromptKind::MoveSelected
            | FileActionPromptKind::DeleteSelected
                if targets.is_empty() =>
            {
                Some("select one or more entries first".to_string())
            }
            FileActionPromptKind::Placement
                if self.source != FilesSourceKind::Sifs || target_path.is_none() =>
            {
                Some("select a SIFS file or folder first".to_string())
            }
            FileActionPromptKind::Placement if placement_draft.is_none() => Some(
                "Wait for this object's resolved placement metadata, then reopen the editor"
                    .to_string(),
            ),
            _ => None,
        };
        if kind == FileActionPromptKind::Placement {
            self.placement_draft = placement_draft;
            self.placement_advanced_open = false;
            self.placement_edit_revision = self.placement_edit_revision.wrapping_add(1);
            self.placement_preview_revision = None;
            self.pending_placement_preview_revision = None;
            if continuing_reconciliation_job.is_none() {
                self.pending_placement_request_id = None;
            }
            self.placement_preview = None;
            self.placement_error = None;
            self.placement_error_from_reconciliation = false;
            self.placement_loading = false;
            self.placement_applying = false;
            if self
                .placement_reconciliation
                .as_ref()
                .is_some_and(|job| Some(job.path.as_str()) != target_path.as_deref())
            {
                self.placement_reconciliation = None;
            }
        }
        self.action_prompt = Some(FileActionPrompt {
            kind,
            input,
            target_name,
            target_path,
            target_is_dir,
            targets,
            error,
        });
        self.action_prompt_revision = self.action_prompt_revision.wrapping_add(1);
        if let Some(job_id) = continuing_reconciliation_job
            && self.pending_placement_request_id.is_none()
        {
            self.schedule_placement_progress_poll(job_id);
        }
    }

    fn close_action_prompt(&mut self) {
        if self.placement_applying {
            return;
        }
        let reconciliation_in_flight = self.placement_reconciliation_in_flight();
        self.action_prompt = None;
        self.placement_draft = None;
        self.placement_advanced_open = false;
        self.placement_preview_revision = None;
        self.pending_placement_preview_revision = None;
        if !reconciliation_in_flight {
            self.pending_placement_request_id = None;
        }
        self.placement_preview = None;
        self.placement_error = None;
        self.placement_error_from_reconciliation = false;
        self.placement_loading = false;
        self.placement_applying = false;
    }

    fn open_compact_overlay(&mut self, overlay: CompactFilesOverlay) {
        self.action_prompt = None;
        self.compact_overlay = Some(overlay);
    }

    fn close_compact_overlay(&mut self) {
        self.compact_overlay = None;
    }

    fn open_placement_activity(&mut self, waker: Option<sui::UiHandle>) {
        if let Some(waker) = waker {
            self.ensure_worker(waker);
        }
        self.compact_overlay = None;
        self.placement_activity_open = true;
        if self.placement_activity_origin_daemon_address.is_none() {
            self.placement_activity_origin_daemon_address = self.daemon_address.clone();
        }
        self.request_placement_activity(false, Duration::ZERO);
    }

    fn close_placement_activity(&mut self) {
        self.placement_activity_open = false;
        self.placement_activity_loading = false;
        // Invalidates a scheduled or in-flight response. The worker operation
        // is read-only and may finish, but a closed center must not restart its
        // polling loop when that stale response arrives.
        self.pending_placement_activity_request_id = None;
        self.pending_placement_activity_append = false;
        self.placement_activity_poll_generation
            .fetch_add(1, Ordering::AcqRel);
        self.placement_activity_in_flight_generation
            .store(0, Ordering::Release);
        self.placement_activity_refresh_dirty = false;
    }

    fn selected_operator_identity(&self) -> Result<(DfsFileSystemId, DfsObjectId, String), String> {
        if self.source != FilesSourceKind::Sifs {
            return Err("History and DFS issues are available for Sinomo files.".to_string());
        }
        let entry = self
            .selected_entry()
            .ok_or_else(|| "Select a file or folder first.".to_string())?;
        let details = self
            .selected_details
            .as_ref()
            .filter(|details| details.path == entry.path)
            .ok_or_else(|| {
                if self.details_loading {
                    "File details are still loading. Try again in a moment.".to_string()
                } else {
                    "Refresh this item's details before opening history.".to_string()
                }
            })?;
        let file_system_id = DfsFileSystemId::new(details.file_system_id.clone())
            .map_err(|error| format!("The file-system identity is invalid: {error}"))?;
        let object_id = DfsObjectId::new(details.object_id.clone())
            .map_err(|error| format!("The object identity is invalid: {error}"))?;
        Ok((file_system_id, object_id, details.path.clone()))
    }

    /// A selected file shows its object's versions; a selected folder, or no
    /// selection, searches the folder so deleted files remain recoverable.
    fn selected_history_target(&self) -> Result<HistoryTarget, String> {
        if self.source != FilesSourceKind::Sifs {
            return Err("History and DFS issues are available for Sinomo files.".to_string());
        }
        let Some(entry) = self.selected_entry() else {
            return Ok(self.current_folder_history_target());
        };
        let is_dir = entry.is_dir;
        let (file_system_id, object_id, path) = self.selected_operator_identity()?;
        Ok(if is_dir {
            HistoryTarget::Folder {
                file_system_id,
                path,
            }
        } else {
            HistoryTarget::File {
                file_system_id,
                object_id,
                path,
            }
        })
    }

    fn current_folder_history_target(&self) -> HistoryTarget {
        HistoryTarget::Folder {
            file_system_id: sinomo_runtime::dfs::sifs_file_system_id(),
            path: normalize_path(&self.path),
        }
    }

    fn open_history(&mut self, waker: Option<sui::UiHandle>) {
        let target = self.selected_history_target();
        self.open_history_for(target, waker);
    }

    fn open_folder_history(&mut self, waker: Option<sui::UiHandle>) {
        let target = if self.source == FilesSourceKind::Sifs {
            Ok(self.current_folder_history_target())
        } else {
            Err("Saved versions are available for Sinomo files.".to_string())
        };
        self.open_history_for(target, waker);
    }

    fn open_history_for(
        &mut self,
        target: Result<HistoryTarget, String>,
        waker: Option<sui::UiHandle>,
    ) {
        self.history_open = true;
        self.compact_overlay = None;
        self.action_prompt = None;
        self.clear_history_content();
        match target {
            Ok(target) => {
                self.history_target = Some(target);
                self.request_history(waker);
            }
            Err(error) => {
                self.history_error = Some(error);
                self.history_revision = self.history_revision.wrapping_add(1);
            }
        }
    }

    fn clear_history_content(&mut self) {
        self.history_loading = false;
        self.history_target = None;
        self.clear_history_snapshot();
        self.history_capture_name.clear();
        self.history_preview = None;
        self.history_error = None;
        self.history_notice = None;
        self.history_decision = None;
        self.pending_history_request_id = None;
        self.pending_history_more_request_id = None;
        self.pending_history_preview_request_id = None;
        self.history_revision = self.history_revision.wrapping_add(1);
    }

    fn clear_history_snapshot(&mut self) {
        self.history_loaded = false;
        self.history_object = None;
        self.history_entries.clear();
        self.history_next_cursor = None;
        self.history_list_error = None;
        self.history_retention = None;
    }

    fn apply_history_snapshot(&mut self, snapshot: FilesHistorySnapshot) -> Result<(), String> {
        if let Some(HistoryTarget::File { object_id, .. }) = &self.history_target {
            match snapshot.object.as_ref() {
                None => {
                    return Err("No authoritative DFS history was found for this path.".to_string());
                }
                Some(object) if &object.object.object_id != object_id => {
                    return Err(
                        "The object at this path changed while its history was loading. Refresh and try again."
                            .to_string(),
                    );
                }
                Some(_) => {}
            }
        }
        let mut entries = snapshot.entries;
        sort_history_entries(&mut entries);
        self.history_object = snapshot.object;
        self.history_entries = entries;
        self.history_next_cursor = snapshot.next_cursor;
        self.history_list_error = snapshot
            .list_error
            .map(|error| history_error_message(&error));
        self.history_retention = snapshot.retention;
        self.history_loaded = true;
        if self.history_preview.as_ref().is_some_and(|preview| {
            !self
                .history_entries
                .iter()
                .any(|entry| entry.identity == preview.identity)
        }) {
            self.history_preview = None;
            self.pending_history_preview_request_id = None;
        }
        Ok(())
    }

    fn request_history(&mut self, waker: Option<sui::UiHandle>) {
        if let Some(waker) = waker {
            self.ensure_worker(waker);
        }
        self.history_error = None;
        let Some(target) = self.history_target.clone() else {
            self.history_loading = false;
            self.history_error = Some("Select a Sinomo file or folder first.".to_string());
            self.history_revision = self.history_revision.wrapping_add(1);
            return;
        };
        let Some(tx) = self.worker_tx.clone() else {
            self.history_loading = false;
            self.history_error = Some("The Files background worker is not available.".to_string());
            self.history_revision = self.history_revision.wrapping_add(1);
            return;
        };
        let request_id = self.next_request_id;
        self.next_request_id = self.next_request_id.wrapping_add(1);
        self.pending_history_request_id = Some(request_id);
        // A refreshed first page supersedes any continuation of the old listing.
        self.pending_history_more_request_id = None;
        self.history_loading = true;
        self.history_revision = self.history_revision.wrapping_add(1);
        if tx
            .send(FilesWorkerCommand::History { request_id, target })
            .is_err()
        {
            self.pending_history_request_id = None;
            self.history_loading = false;
            self.history_error =
                Some("The Files background worker stopped before reading history.".to_string());
            self.history_revision = self.history_revision.wrapping_add(1);
        }
    }

    fn history_more_loading(&self) -> bool {
        self.pending_history_more_request_id.is_some()
    }

    fn request_more_history(&mut self, waker: Option<sui::UiHandle>) {
        if self.history_loading || self.history_more_loading() {
            return;
        }
        let (Some(target), Some(cursor)) = (
            self.history_target.clone(),
            self.history_next_cursor.clone(),
        ) else {
            return;
        };
        if let Some(waker) = waker {
            self.ensure_worker(waker);
        }
        let Some(tx) = self.worker_tx.clone() else {
            self.history_list_error =
                Some("The Files background worker is not available.".to_string());
            self.history_revision = self.history_revision.wrapping_add(1);
            return;
        };
        let request_id = self.next_request_id;
        self.next_request_id = self.next_request_id.wrapping_add(1);
        self.pending_history_more_request_id = Some(request_id);
        self.history_list_error = None;
        self.history_revision = self.history_revision.wrapping_add(1);
        if tx
            .send(FilesWorkerCommand::HistoryMore {
                request_id,
                target,
                cursor,
            })
            .is_err()
        {
            self.pending_history_more_request_id = None;
            self.history_list_error = Some(
                "The Files background worker stopped before searching older versions.".to_string(),
            );
            self.history_revision = self.history_revision.wrapping_add(1);
        }
    }

    fn toggle_history_preview(
        &mut self,
        identity: DfsFileVersionIdentity,
        waker: Option<sui::UiHandle>,
    ) {
        if self
            .history_preview
            .as_ref()
            .is_some_and(|preview| preview.identity == identity)
        {
            self.history_preview = None;
            self.pending_history_preview_request_id = None;
            self.history_revision = self.history_revision.wrapping_add(1);
            return;
        }
        let Some(entry) = self
            .history_entries
            .iter()
            .find(|entry| entry.identity == identity)
        else {
            return;
        };
        let name = history_entry_file_name(entry);
        if let Some(waker) = waker {
            self.ensure_worker(waker);
        }
        self.history_preview = Some(FilesHistoryPreview {
            identity: identity.clone(),
            result: None,
        });
        self.history_revision = self.history_revision.wrapping_add(1);
        let Some(tx) = self.worker_tx.clone() else {
            self.history_preview = Some(FilesHistoryPreview {
                identity,
                result: Some(Err(
                    "The Files background worker is not available.".to_string()
                )),
            });
            return;
        };
        let request_id = self.next_request_id;
        self.next_request_id = self.next_request_id.wrapping_add(1);
        self.pending_history_preview_request_id = Some(request_id);
        if tx
            .send(FilesWorkerCommand::HistoryPreview {
                request_id,
                identity: identity.clone(),
                name,
            })
            .is_err()
        {
            self.pending_history_preview_request_id = None;
            self.history_preview = Some(FilesHistoryPreview {
                identity,
                result: Some(Err(
                    "The Files background worker stopped before reading this version.".to_string(),
                )),
            });
        }
    }

    fn close_history(&mut self) {
        self.history_open = false;
        self.pending_history_request_id = None;
        self.pending_history_more_request_id = None;
        self.pending_history_preview_request_id = None;
        self.history_loading = false;
        self.history_decision = None;
        self.history_preview = None;
        self.history_revision = self.history_revision.wrapping_add(1);
    }

    fn open_storage_center(&mut self, waker: Option<sui::UiHandle>) {
        self.history_open = false;
        self.compact_overlay = None;
        self.action_prompt = None;
        self.storage_center_open = true;
        self.request_storage_overview(waker);
    }

    fn request_storage_overview(&mut self, waker: Option<sui::UiHandle>) {
        if let Some(waker) = waker {
            self.ensure_worker(waker);
        }
        let Some(tx) = self.worker_tx.clone() else {
            self.storage_center_loading = false;
            self.storage_center_error =
                Some("Storage health requires a daemon connection.".to_string());
            self.storage_center_revision = self.storage_center_revision.wrapping_add(1);
            return;
        };
        let request_id = self.next_request_id;
        self.next_request_id = self.next_request_id.wrapping_add(1);
        self.pending_storage_center_request_id = Some(request_id);
        self.storage_center_loading = true;
        self.storage_center_error = None;
        self.storage_center_revision = self.storage_center_revision.wrapping_add(1);
        if tx
            .send(FilesWorkerCommand::StorageOverview { request_id })
            .is_err()
        {
            self.pending_storage_center_request_id = None;
            self.storage_center_loading = false;
            self.storage_center_error = Some(
                "The Files background worker stopped before reading storage health.".to_string(),
            );
            self.storage_center_revision = self.storage_center_revision.wrapping_add(1);
        }
    }

    fn close_storage_center(&mut self) {
        self.storage_center_open = false;
        self.storage_center_loading = false;
        self.pending_storage_center_request_id = None;
        self.storage_center_revision = self.storage_center_revision.wrapping_add(1);
    }

    fn stage_history_decision(&mut self, decision: HistoryDecision) {
        if self.history_loading {
            return;
        }
        self.history_decision = Some(decision);
        self.history_error = None;
        self.history_revision = self.history_revision.wrapping_add(1);
    }

    fn cancel_history_decision(&mut self) {
        self.history_decision = None;
        self.history_revision = self.history_revision.wrapping_add(1);
    }

    fn history_entry(&self, identity: &DfsFileVersionIdentity) -> Option<&DfsFileHistoryEntry> {
        self.history_entries
            .iter()
            .find(|entry| &entry.identity == identity)
    }

    fn reject_history_choice(&mut self, error: impl Into<String>) {
        self.history_decision = None;
        self.history_error = Some(error.into());
        self.history_revision = self.history_revision.wrapping_add(1);
    }

    /// Replace the current file with a saved version, but only while the file
    /// still has the generation shown in this view.
    fn stage_history_restore(&mut self, identity: DfsFileVersionIdentity) {
        if self.history_loading {
            return;
        }
        let Some(object) = self.history_object.as_ref() else {
            return;
        };
        let Some(entry) = self.history_entry(&identity) else {
            self.reject_history_choice("This version is not kept in file history.");
            return;
        };
        if entry.is_current
            || entry.deleted
            || self
                .history_target
                .as_ref()
                .is_none_or(HistoryTarget::is_folder)
            || object.object.kind == sinomo_runtime::dfs::DfsObjectKind::Tombstone
            || object.object.object_id != identity.object_id
        {
            self.reject_history_choice(
                "Only an older saved version of this file can replace its current content.",
            );
            return;
        }
        let request = DfsFileHistoryRestoreRequest {
            source: identity,
            destination_path: object.object.path.clone(),
            expected_destination: Some(DfsFileVersionIdentity {
                file_system_id: object.object.file_system_id.clone(),
                object_id: object.object.object_id.clone(),
                version: object.object.version.clone(),
            }),
            operation_id: sinomo_runtime::core::Id::generate().to_string(),
        };
        self.stage_history_decision(HistoryDecision::Restore(Box::new(request)));
    }

    /// Stage recovery into a new file. Deleted files default to their former path.
    fn stage_history_recover(&mut self, identity: DfsFileVersionIdentity) {
        if self.history_loading {
            return;
        }
        let Some(entry) = self.history_entry(&identity) else {
            self.reject_history_choice("This version is not kept in file history.");
            return;
        };
        let draft = HistoryRecoverDraft {
            source: identity,
            source_label: history_entry_label(entry),
            anchor_path: entry.current_path.clone(),
            destination: history_recover_destination(entry),
            confirmed: None,
        };
        self.stage_history_decision(HistoryDecision::Recover(Box::new(draft)));
    }

    fn stage_history_add_pin(&mut self, identity: DfsFileVersionIdentity) {
        if self.history_loading {
            return;
        }
        let Some(entry) = self.history_entry(&identity) else {
            self.reject_history_choice("This version is not kept in file history.");
            return;
        };
        let draft = HistoryPinDraft {
            identity,
            path: entry.current_path.clone(),
            source_label: history_entry_label(entry),
            name: String::new(),
        };
        self.stage_history_decision(HistoryDecision::AddPin(Box::new(draft)));
    }

    fn stage_history_unpin(&mut self, identity: DfsFileVersionIdentity, pin_id: String) {
        if self.history_loading {
            return;
        }
        let Some(entry) = self.history_entry(&identity) else {
            self.reject_history_choice("This version is not kept in file history.");
            return;
        };
        if !entry.pins.contains(&pin_id) {
            self.reject_history_choice("That name no longer keeps this version. Refresh history.");
            return;
        }
        let request = DfsFileHistoryPinRequest {
            path: entry.current_path.clone(),
            identity,
            operation: DfsFileHistoryPinOperation::Unpin { pin_id },
            operation_id: sinomo_runtime::core::Id::generate().to_string(),
        };
        self.stage_history_decision(HistoryDecision::Unpin(Box::new(request)));
    }

    /// Text edits in a staged decision do not rebuild the sheet.
    fn set_history_decision_input(&mut self, value: String) {
        match self.history_decision.as_mut() {
            Some(HistoryDecision::Recover(draft)) => draft.destination = value,
            Some(HistoryDecision::AddPin(draft)) => draft.name = value,
            _ => {}
        }
    }

    fn set_history_capture_name(&mut self, name: String) {
        self.history_capture_name = name;
    }

    /// Capture the exact generation shown in this view under a named pin.
    fn capture_history_version(&mut self, waker: Option<sui::UiHandle>) {
        if self.history_loading {
            return;
        }
        let Some(target) = self
            .history_target
            .clone()
            .filter(|target| !target.is_folder())
        else {
            return;
        };
        let Some(object) = self.history_object.as_ref() else {
            self.reject_history_choice("Refresh history before saving a version.");
            return;
        };
        if !history_object_can_capture(&object.object) {
            self.reject_history_choice("Only file content can be saved as a version.");
            return;
        }
        let name = if self.history_capture_name.trim().is_empty() {
            default_history_pin_name(time::OffsetDateTime::now_utc())
        } else {
            match history_pin_name(&self.history_capture_name) {
                Ok(name) => name,
                Err(error) => {
                    self.reject_history_choice(error);
                    return;
                }
            }
        };
        let request = DfsFileHistoryPinRequest {
            path: object.object.path.clone(),
            identity: DfsFileVersionIdentity {
                file_system_id: object.object.file_system_id.clone(),
                object_id: object.object.object_id.clone(),
                version: object.object.version.clone(),
            },
            operation: DfsFileHistoryPinOperation::Capture { pin_id: name },
            operation_id: sinomo_runtime::core::Id::generate().to_string(),
        };
        if let Some(waker) = waker {
            self.ensure_worker(waker);
        }
        self.history_decision = None;
        self.send_history_action(
            target,
            HistoryWorkerAction::Pin(request),
            "Saving the current version...",
        );
    }

    fn confirm_history_decision(&mut self, waker: Option<sui::UiHandle>) {
        if self.history_loading {
            return;
        }
        let Some(decision) = self.history_decision.clone() else {
            return;
        };
        let Some(target) = self.history_target.clone() else {
            return;
        };
        if let Some(waker) = waker {
            self.ensure_worker(waker);
        }
        match decision {
            // The confirmed request retains the observation and operation identity
            // across an error, so another confirmation is an exact retry.
            HistoryDecision::Restore(request) => self.send_history_action(
                target,
                HistoryWorkerAction::Restore(*request),
                "Restoring the saved version...",
            ),
            HistoryDecision::Recover(mut draft) => {
                let parent = parent_path(&draft.anchor_path).unwrap_or_else(|| "/".to_string());
                let destination = match resolve_sifs_destination_path(&parent, &draft.destination) {
                    Ok(destination) => destination,
                    Err(error) => {
                        self.history_error = Some(format!("Choose a destination: {error}."));
                        self.history_revision = self.history_revision.wrapping_add(1);
                        return;
                    }
                };
                let request = match draft.confirmed.take() {
                    Some(request) if request.destination_path == destination => request,
                    _ => DfsFileHistoryRestoreRequest {
                        source: draft.source.clone(),
                        destination_path: destination,
                        expected_destination: None,
                        operation_id: sinomo_runtime::core::Id::generate().to_string(),
                    },
                };
                draft.destination = request.destination_path.clone();
                draft.confirmed = Some(request.clone());
                self.history_decision = Some(HistoryDecision::Recover(draft));
                self.send_history_action(
                    target,
                    HistoryWorkerAction::Restore(request),
                    "Recovering the saved version...",
                );
            }
            HistoryDecision::AddPin(draft) => {
                let name = match history_pin_name(&draft.name) {
                    Ok(name) => name,
                    Err(error) => {
                        self.history_error = Some(error);
                        self.history_revision = self.history_revision.wrapping_add(1);
                        return;
                    }
                };
                let request = DfsFileHistoryPinRequest {
                    path: draft.path,
                    identity: draft.identity,
                    operation: DfsFileHistoryPinOperation::Pin { pin_id: name },
                    operation_id: sinomo_runtime::core::Id::generate().to_string(),
                };
                self.send_history_action(
                    target,
                    HistoryWorkerAction::Pin(request),
                    "Adding the name...",
                );
            }
            HistoryDecision::Unpin(request) => self.send_history_action(
                target,
                HistoryWorkerAction::Pin(*request),
                "Releasing the name...",
            ),
        }
    }

    fn send_history_action(
        &mut self,
        target: HistoryTarget,
        action: HistoryWorkerAction,
        notice: &str,
    ) {
        let Some(tx) = self.worker_tx.clone() else {
            self.history_error = Some("The Files background worker is not available.".to_string());
            self.history_revision = self.history_revision.wrapping_add(1);
            return;
        };
        let request_id = self.next_request_id;
        self.next_request_id = self.next_request_id.wrapping_add(1);
        self.pending_history_request_id = Some(request_id);
        self.pending_history_more_request_id = None;
        self.history_loading = true;
        self.history_error = None;
        self.history_notice = Some(notice.to_string());
        self.history_revision = self.history_revision.wrapping_add(1);
        if tx
            .send(FilesWorkerCommand::HistoryAction {
                request_id,
                target,
                action,
            })
            .is_err()
        {
            self.pending_history_request_id = None;
            self.history_loading = false;
            self.history_error =
                Some("The Files background worker stopped before applying the choice.".to_string());
            self.history_revision = self.history_revision.wrapping_add(1);
        }
    }

    /// Select a history path in the listing, leaving the sheet so the user can
    /// continue from the file itself.
    fn reveal_history_path(&mut self, path: String, waker: Option<sui::UiHandle>) {
        self.close_history();
        let path = normalize_path(&path);
        let parent = parent_path(&path).unwrap_or_else(|| "/".to_string());
        self.pending_select_path = Some(path);
        self.open_location(FilesSourceKind::Sifs, parent, waker);
    }

    fn set_placement_activity_filter(&mut self, filter: PlacementActivityFilter) -> bool {
        if self.placement_activity_filter == filter {
            return false;
        }
        self.placement_activity_filter = filter;
        self.placement_activity_head_job_ids.clear();
        self.placement_activity_next_cursor = None;
        self.pending_placement_activity_request_id = None;
        self.pending_placement_activity_append = false;
        self.placement_activity_poll_generation
            .fetch_add(1, Ordering::AcqRel);
        self.placement_activity_in_flight_generation
            .store(0, Ordering::Release);
        self.placement_activity_refresh_dirty = false;
        true
    }

    fn placement_activity_has_active_jobs(&self) -> bool {
        use sinomo_runtime::dfs::DfsPlacementReconciliationActivityStatus as Status;
        self.placement_activity
            .iter()
            .any(|activity| matches!(activity.status, Status::Running | Status::Retrying))
    }

    fn request_placement_activity(&mut self, append: bool, delay: Duration) {
        if delay.is_zero()
            && self
                .placement_activity_in_flight_generation
                .load(Ordering::Acquire)
                != 0
        {
            if append {
                // An explicit Load older action wins over a background head poll. The worker is
                // serial, so the already-sent read can finish harmlessly; replacing the pending
                // id makes its response stale and queues the requested page immediately behind it.
                self.pending_placement_activity_request_id = None;
                self.pending_placement_activity_append = false;
                self.placement_activity_in_flight_generation
                    .store(0, Ordering::Release);
            } else {
                self.placement_activity_refresh_dirty = true;
                return;
            }
        }
        let poll_generation = self
            .placement_activity_poll_generation
            .fetch_add(1, Ordering::AcqRel)
            .wrapping_add(1);
        let Some(tx) = self.worker_tx.clone() else {
            self.placement_activity_loading = false;
            self.placement_activity_error.get_or_insert_with(|| {
                "Reconciliation activity requires a daemon connection.".to_string()
            });
            return;
        };
        let cursor = append
            .then(|| self.placement_activity_next_cursor.clone())
            .flatten();
        if append && cursor.is_none() {
            return;
        }
        let request_id = self.next_request_id;
        self.next_request_id = self.next_request_id.wrapping_add(1);
        self.pending_placement_activity_request_id = Some(request_id);
        self.pending_placement_activity_append = append;
        self.placement_activity_loading = delay.is_zero();
        let filter = self.placement_activity_filter;
        let command = FilesWorkerCommand::PlacementActivity {
            request_id,
            filter,
            cursor,
            append,
        };
        if delay.is_zero() {
            self.placement_activity_in_flight_generation
                .store(poll_generation, Ordering::Release);
            if tx.send(command).is_err() {
                self.pending_placement_activity_request_id = None;
                self.placement_activity_loading = false;
                self.placement_activity_in_flight_generation
                    .store(0, Ordering::Release);
                self.placement_activity_error =
                    Some("The Files background worker stopped.".to_string());
            }
            return;
        }

        let delay = crate::mobile_runtime::passive_network_interval(
            delay,
            crate::mobile_runtime::MobilePassiveNetworkClass::Observability,
        );
        let result_tx = self.worker_result_tx.clone();
        let waker = self.worker_waker.clone();
        let active_poll_generation = Arc::clone(&self.placement_activity_poll_generation);
        let in_flight_generation = Arc::clone(&self.placement_activity_in_flight_generation);
        self.app_runtime.spawn(async move {
            crate::mobile_runtime::wait_for_interactive().await;
            let paused = tokio::select! {
                _ = tokio::time::sleep(delay) => false,
                _ = crate::mobile_runtime::wait_for_background() => true,
            };
            if paused {
                // A foreground transition is a useful reason to refresh the
                // open activity center immediately; its durable cursor removes
                // the need to spend radio time polling while hidden.
                crate::mobile_runtime::wait_for_interactive().await;
            }
            if active_poll_generation.load(Ordering::Acquire) != poll_generation {
                return;
            }
            if in_flight_generation
                .compare_exchange(0, poll_generation, Ordering::AcqRel, Ordering::Acquire)
                .is_err()
            {
                return;
            }
            if tx.send(command).is_err() {
                in_flight_generation.store(0, Ordering::Release);
                if let Some(result_tx) = result_tx {
                    let _ = result_tx.send(FilesWorkerResult::PlacementActivity {
                        request_id,
                        filter,
                        append,
                        result: Err("The Files background worker stopped.".to_string()),
                    });
                }
            }
            if let Some(waker) = waker {
                waker.wake();
            }
        });
    }

    fn refresh_placement_activity(&mut self) {
        self.request_placement_activity(false, Duration::ZERO);
    }

    fn load_older_placement_activity(&mut self) {
        self.request_placement_activity(true, Duration::ZERO);
    }

    fn schedule_placement_activity_poll(&mut self, delay: Duration) {
        if !self.placement_activity_open {
            return;
        }
        self.request_placement_activity(false, delay);
    }

    fn reveal_placement_activity_path(&mut self, path: String, waker: Option<sui::UiHandle>) {
        self.close_placement_activity();
        let parent = parent_path(&path).unwrap_or_else(|| "/".to_string());
        self.pending_select_path = (path != "/").then_some(path);
        self.open_location(FilesSourceKind::Sifs, parent, waker);
    }

    fn set_action_prompt_input(&mut self, input: String) {
        if let Some(prompt) = &mut self.action_prompt {
            prompt.input = input;
            prompt.error = None;
        }
    }

    fn mutate_placement_draft(&mut self, mutate: impl FnOnce(&mut PlacementEditorDraft)) -> bool {
        if self.placement_editor_locked() {
            return false;
        }
        let Some(draft) = self.placement_draft.as_mut() else {
            return false;
        };
        let before = draft.clone();
        mutate(draft);
        draft.normalize();
        if *draft == before {
            return false;
        }
        let preserves_reconciliation_poll = self.pending_placement_request_id.is_some()
            && self.pending_placement_preview_revision.is_none()
            && !self.placement_loading
            && self.placement_reconciliation_in_flight();
        self.placement_edit_revision = self.placement_edit_revision.wrapping_add(1);
        if !preserves_reconciliation_poll {
            self.pending_placement_request_id = None;
        }
        self.pending_placement_preview_revision = None;
        self.placement_loading = false;
        self.placement_error = None;
        self.placement_error_from_reconciliation = false;
        if let Some(prompt) = self.action_prompt.as_mut() {
            prompt.error = None;
        }
        self.resume_placement_progress_poll();
        true
    }

    fn mutate_placement_policy(
        &mut self,
        mutate: impl FnOnce(&mut PlacementEditorPolicyDraft),
    ) -> bool {
        if !self
            .placement_draft
            .as_ref()
            .and_then(PlacementEditorDraft::active_policy)
            .is_some_and(|policy| policy.consistency.is_editable())
        {
            return false;
        }
        self.mutate_placement_draft(|draft| {
            if let Some(policy) = draft.active_policy_mut() {
                mutate(policy);
            }
        })
    }

    fn set_placement_consistency(&mut self, consistency: PlacementEditorConsistency) -> bool {
        if self
            .placement_draft
            .as_ref()
            .and_then(PlacementEditorDraft::active_policy)
            .is_some_and(|draft| !draft.consistency.is_editable())
        {
            if let Some(prompt) = self.action_prompt.as_mut() {
                prompt.error = Some(
                    "Local-only placement cannot be converted in the visual editor".to_string(),
                );
            }
            return false;
        }
        self.mutate_placement_policy(|policy| {
            policy.inherit = false;
            policy.consistency = consistency;
        })
    }

    fn set_placement_goal(&mut self, goal: usize) -> bool {
        if self
            .placement_draft
            .as_ref()
            .and_then(PlacementEditorDraft::active_policy)
            .is_some_and(|draft| !draft.consistency.is_editable())
        {
            return false;
        }
        self.mutate_placement_draft(|draft| {
            let Some(policy) = draft.active_policy_mut() else {
                return;
            };
            match goal {
                0 => policy.inherit = true,
                2 => {
                    policy.inherit = false;
                    policy.consistency = PlacementEditorConsistency::Confirmed;
                }
                _ => {
                    policy.inherit = false;
                    policy.consistency = PlacementEditorConsistency::Eventual;
                }
            }
        })
    }

    fn toggle_placement_advanced(&mut self) {
        self.placement_advanced_open = !self.placement_advanced_open;
    }

    fn set_placement_min_commit_replicas(&mut self, replicas: usize) -> bool {
        self.mutate_placement_policy(|policy| {
            policy.inherit = false;
            if policy.consistency == PlacementEditorConsistency::Eventual {
                policy.min_commit_replicas = replicas.clamp(1, policy.desired_replicas);
            }
        })
    }

    fn set_placement_desired_replicas(&mut self, replicas: usize) -> bool {
        self.mutate_placement_policy(|policy| {
            policy.inherit = false;
            policy.desired_replicas = replicas.max(1);
        })
    }

    fn set_placement_min_distinct_zones(&mut self, zones: usize) -> bool {
        self.mutate_placement_policy(|policy| {
            policy.inherit = false;
            policy.min_distinct_zones = zones.min(policy.desired_replicas);
        })
    }

    fn set_placement_scope(&mut self, scope: SifsPlacementScope) -> bool {
        let target_is_dir = self
            .action_prompt
            .as_ref()
            .is_some_and(|prompt| prompt.target_is_dir);
        let scope = if target_is_dir {
            scope
        } else {
            SifsPlacementScope::SelfOnly
        };
        if self
            .placement_draft
            .as_ref()
            .is_some_and(|draft| !draft.scope_is_known(scope))
        {
            if let Some(prompt) = self.action_prompt.as_mut() {
                prompt.error = Some(
                    "This daemon did not return the exact policy for that scope. Refresh after upgrading the daemon before switching scopes."
                        .to_string(),
                );
            }
            return false;
        }
        self.mutate_placement_draft(|draft| draft.scope = scope)
    }

    #[cfg(test)]
    fn set_placement_inherit(&mut self, inherit: bool) -> bool {
        self.mutate_placement_draft(|draft| {
            if let Some(policy) = draft.active_policy_mut() {
                policy.inherit = inherit;
            }
        })
    }

    fn set_placement_node_required(
        &mut self,
        node_id: sinomo_runtime::node::NodeId,
        required: bool,
    ) -> bool {
        self.mutate_placement_policy(|policy| {
            policy.inherit = false;
            if required {
                policy.forbidden_node_ids.remove(&node_id);
                policy.required_node_ids.insert(node_id);
            } else {
                policy.required_node_ids.remove(&node_id);
            }
        })
    }

    fn set_placement_node_forbidden(
        &mut self,
        node_id: sinomo_runtime::node::NodeId,
        forbidden: bool,
    ) -> bool {
        self.mutate_placement_policy(|policy| {
            policy.inherit = false;
            if forbidden {
                policy.required_node_ids.remove(&node_id);
                policy.forbidden_node_ids.insert(node_id);
            } else {
                policy.forbidden_node_ids.remove(&node_id);
            }
        })
    }

    fn placement_preview_is_current(&self) -> bool {
        self.placement_preview.is_some()
            && self.placement_preview_revision == Some(self.placement_edit_revision)
    }

    fn placement_reconciliation_in_flight(&self) -> bool {
        self.placement_reconciliation
            .as_ref()
            .is_some_and(|job| !job.state.is_terminal())
    }

    fn placement_editor_locked(&self) -> bool {
        // An accepted reconciliation keeps its immutable policy/candidate
        // snapshot, but it must not trap the editor if one of those candidates
        // later becomes unavailable. A freshly previewed, explicit edit can
        // atomically supersede the old job; only the short Apply request itself
        // is non-detachable.
        self.placement_applying
    }

    fn placement_apply_allowed(&self) -> bool {
        self.placement_preview_is_current()
            && !self.placement_loading
            && !self.placement_editor_locked()
            && self.placement_error.is_none()
            && self.placement_draft.as_ref().is_some_and(|draft| {
                draft.has_actionable_change()
                    && draft
                        .active_policy()
                        .is_some_and(|policy| policy.consistency.is_editable())
            })
            && self
                .placement_preview
                .as_ref()
                .is_some_and(SifsPlacementPreview::is_satisfiable)
    }

    fn placement_candidate_limit(&self) -> usize {
        let draft_count = self
            .placement_draft
            .as_ref()
            .and_then(PlacementEditorDraft::active_policy)
            .map_or(1, |draft| draft.desired_replicas);
        self.placement_preview
            .as_ref()
            .map_or(draft_count, |preview| {
                preview
                    .nodes
                    .iter()
                    .filter(|node| node.accepts_content)
                    .count()
                    .max(draft_count)
            })
            .max(1)
    }

    fn set_sort_mode(&mut self, mode: FileSortMode) {
        if self.sort_mode == mode {
            return;
        }
        self.sort_mode = mode;
        self.reload();
    }

    fn toggle_sort_column(&mut self, column: FilesSortColumn) {
        let mode = self.sort_mode.next_for_column(column);
        self.set_sort_mode(mode);
    }

    fn set_view_mode(&mut self, mode: FilesViewMode) {
        if self.view_mode != mode {
            self.cancel_thumbnail_requests();
        }
        self.view_mode = mode;
    }

    fn submit_action_prompt(&mut self, waker: Option<sui::UiHandle>) {
        let Some(prompt) = self.action_prompt.clone() else {
            return;
        };
        if prompt.kind == FileActionPromptKind::GoTo {
            match normalize_jump_path(self.source, &self.path, &prompt.input) {
                Ok(path) => {
                    self.action_prompt = None;
                    if let Some(waker) = waker {
                        self.ensure_worker(waker);
                    }
                    self.navigate(path);
                }
                Err(error) => {
                    if let Some(current) = &mut self.action_prompt {
                        current.error = Some(error);
                    }
                }
            }
            return;
        }
        if prompt.kind == FileActionPromptKind::Placement {
            self.start_placement_update(&prompt, waker);
            return;
        }
        if prompt.kind == FileActionPromptKind::DeleteSelected {
            if prompt.targets.is_empty() {
                if let Some(current) = &mut self.action_prompt {
                    current.error = Some("select one or more entries first".to_string());
                }
                return;
            }
            self.action_prompt = None;
            self.start_delete_targets(prompt.targets, waker);
            return;
        }
        if matches!(
            prompt.kind,
            FileActionPromptKind::CopySelected
                | FileActionPromptKind::TransferSelected
                | FileActionPromptKind::MoveSelected
        ) {
            match self.operations_from_marked_prompt(&prompt) {
                Ok(operations) => {
                    self.action_prompt = None;
                    self.start_marked_operations(operations, waker);
                }
                Err(error) => {
                    if let Some(current) = &mut self.action_prompt {
                        current.error = Some(error);
                    }
                }
            }
            return;
        }
        match self.operation_from_prompt(&prompt) {
            Ok((operation, title, detail)) => {
                self.action_prompt = None;
                self.start_operation(operation, title, detail, waker);
            }
            Err(error) => {
                if let Some(current) = &mut self.action_prompt {
                    current.error = Some(error);
                }
            }
        }
    }

    fn start_placement_preview(&mut self, waker: Option<sui::UiHandle>) {
        if self.placement_editor_locked() {
            return;
        }
        let Some(prompt) = self.action_prompt.clone() else {
            return;
        };
        if prompt.kind != FileActionPromptKind::Placement {
            return;
        }
        let Some(path) = prompt.target_path.clone() else {
            if let Some(current) = self.action_prompt.as_mut() {
                current.error = Some("select a SIFS file or folder first".to_string());
            }
            return;
        };
        let (policy, scope) = match self
            .placement_draft
            .as_ref()
            .ok_or_else(|| "placement editor is unavailable".to_string())
            .and_then(PlacementEditorDraft::policy_and_scope)
        {
            Ok(parsed) => parsed,
            Err(error) => {
                if let Some(current) = self.action_prompt.as_mut() {
                    current.error = Some(error);
                }
                return;
            }
        };
        if let Some(waker) = waker {
            self.ensure_worker(waker);
        }
        let Some(tx) = self.worker_tx.clone() else {
            return;
        };
        let request_id = self.next_request_id;
        self.next_request_id = self.next_request_id.wrapping_add(1);
        self.pending_placement_request_id = Some(request_id);
        self.pending_placement_preview_revision = Some(self.placement_edit_revision);
        self.placement_loading = true;
        self.placement_error = None;
        self.placement_error_from_reconciliation = false;
        if tx
            .send(FilesWorkerCommand::PlacementPreview {
                request_id,
                path,
                policy,
                scope,
            })
            .is_err()
        {
            self.pending_placement_request_id = None;
            self.pending_placement_preview_revision = None;
            self.placement_loading = false;
            self.placement_error = Some("SIFS browser worker stopped".to_string());
            self.placement_error_from_reconciliation = false;
            self.resume_placement_progress_poll();
        }
    }

    fn start_placement_update(&mut self, prompt: &FileActionPrompt, waker: Option<sui::UiHandle>) {
        if !self.placement_apply_allowed() {
            if let Some(current) = self.action_prompt.as_mut() {
                current.error = Some(
                    "Preview the current policy and resolve blocking warnings before applying"
                        .to_string(),
                );
            }
            return;
        }
        let Some(path) = prompt.target_path.clone() else {
            if let Some(current) = self.action_prompt.as_mut() {
                current.error = Some("select a SIFS file or folder first".to_string());
            }
            return;
        };
        let (policy, scope) = match self
            .placement_draft
            .as_ref()
            .ok_or_else(|| "placement editor is unavailable".to_string())
            .and_then(PlacementEditorDraft::policy_and_scope)
        {
            Ok(parsed) => parsed,
            Err(error) => {
                if let Some(current) = self.action_prompt.as_mut() {
                    current.error = Some(error);
                }
                return;
            }
        };
        let Some(expected_preview_token) = self
            .placement_preview
            .as_ref()
            .map(|preview| preview.preview_token.clone())
        else {
            if let Some(current) = self.action_prompt.as_mut() {
                current.error = Some("Preview the current placement before applying".to_string());
            }
            return;
        };
        if let Some(waker) = waker {
            self.ensure_worker(waker);
        }
        let Some(tx) = self.worker_tx.clone() else {
            return;
        };
        let request_id = self.next_request_id;
        self.next_request_id = self.next_request_id.wrapping_add(1);
        self.pending_placement_request_id = Some(request_id);
        self.pending_placement_preview_revision = None;
        self.placement_loading = true;
        self.placement_applying = true;
        self.placement_error = None;
        self.placement_error_from_reconciliation = false;
        if tx
            .send(FilesWorkerCommand::PlacementUpdate {
                request_id,
                path,
                policy,
                scope,
                expected_preview_token,
            })
            .is_err()
        {
            self.pending_placement_request_id = None;
            self.pending_placement_preview_revision = None;
            self.placement_loading = false;
            self.placement_applying = false;
            self.placement_error = Some("SIFS browser worker stopped".to_string());
            self.placement_error_from_reconciliation = false;
            self.resume_placement_progress_poll();
        }
    }

    fn schedule_placement_progress_poll(&mut self, job_id: String) {
        let Some(tx) = self.worker_tx.clone() else {
            return;
        };
        let request_id = self.next_request_id;
        self.next_request_id = self.next_request_id.wrapping_add(1);
        self.pending_placement_request_id = Some(request_id);
        self.pending_placement_preview_revision = None;
        let waker = self.worker_waker.clone();
        let _ = thread::Builder::new()
            .name("sinomo-app-files-placement-progress".to_string())
            .spawn(move || {
                crate::mobile_runtime::wait_for_interactive_delay(
                    crate::mobile_runtime::passive_network_interval(
                        Duration::from_millis(500),
                        crate::mobile_runtime::MobilePassiveNetworkClass::Essential,
                    ),
                );
                let _ = tx.send(FilesWorkerCommand::PlacementProgress { request_id, job_id });
                if let Some(waker) = waker {
                    waker.wake();
                }
            });
    }

    fn resume_placement_progress_poll(&mut self) {
        if self.pending_placement_request_id.is_some() {
            return;
        }
        let Some(job_id) = self
            .placement_reconciliation
            .as_ref()
            .filter(|job| !job.state.is_terminal())
            .map(|job| job.job_id.clone())
        else {
            return;
        };
        self.schedule_placement_progress_poll(job_id);
    }

    fn operation_from_prompt(
        &self,
        prompt: &FileActionPrompt,
    ) -> Result<(FilesOperation, String, String), String> {
        match prompt.kind {
            FileActionPromptKind::GoTo => unreachable!("Go to path is handled before operations"),
            FileActionPromptKind::Placement => {
                unreachable!("placement is handled through the typed placement API")
            }
            FileActionPromptKind::DeleteSelected => {
                unreachable!("Delete selected queues individual delete operations")
            }
            FileActionPromptKind::CopySelected
            | FileActionPromptKind::TransferSelected
            | FileActionPromptKind::MoveSelected => {
                unreachable!("selected-entry prompts queue individual operations")
            }
            FileActionPromptKind::NewFile => {
                let path = self.join_child(&prompt.input)?;
                Ok((
                    FilesOperation {
                        kind: FilesOperationKind::CreateFile,
                        path: path.clone(),
                        target: None,
                        directory: false,
                    },
                    "Create file".to_string(),
                    path,
                ))
            }
            FileActionPromptKind::NewFolder => {
                let path = self.join_child(&prompt.input)?;
                Ok((
                    FilesOperation {
                        kind: FilesOperationKind::CreateFolder,
                        path: path.clone(),
                        target: None,
                        directory: true,
                    },
                    "Create folder".to_string(),
                    path,
                ))
            }
            FileActionPromptKind::Copy => {
                let from = prompt
                    .target_path
                    .clone()
                    .ok_or_else(|| "select an item first".to_string())?;
                let to = self.resolve_destination_path(&prompt.input)?;
                if from == to {
                    return Err("copy destination matches the source path".to_string());
                }
                if prompt.target_is_dir && destination_inside_source(self.source, &from, &to) {
                    return Err("copy destination cannot be inside the source folder".to_string());
                }
                Ok((
                    FilesOperation {
                        kind: FilesOperationKind::Copy,
                        path: from.clone(),
                        target: Some(to.clone()),
                        directory: prompt.target_is_dir,
                    },
                    "Copy".to_string(),
                    format!("{from} -> {to}"),
                ))
            }
            FileActionPromptKind::CopyToSifs => {
                if self.source != FilesSourceKind::Local {
                    return Err("select a local file or folder first".to_string());
                }
                let from = prompt
                    .target_path
                    .clone()
                    .ok_or_else(|| "select an item first".to_string())?;
                let to = resolve_sifs_destination_path(&self.sifs_path, &prompt.input)?;
                Ok((
                    FilesOperation {
                        kind: FilesOperationKind::CopyToSifs,
                        path: from.clone(),
                        target: Some(to.clone()),
                        directory: prompt.target_is_dir,
                    },
                    "Copy to SIFS".to_string(),
                    format!("{from} -> {to}"),
                ))
            }
            FileActionPromptKind::CopyToLocal => {
                if self.source != FilesSourceKind::Sifs {
                    return Err("select a SIFS file or folder first".to_string());
                }
                let from = prompt
                    .target_path
                    .clone()
                    .ok_or_else(|| "select an item first".to_string())?;
                let to = resolve_local_destination_path(&self.local_path, &prompt.input)?;
                Ok((
                    FilesOperation {
                        kind: FilesOperationKind::CopyToLocal,
                        path: from.clone(),
                        target: Some(to.clone()),
                        directory: prompt.target_is_dir,
                    },
                    "Download".to_string(),
                    format!("{from} -> {to}"),
                ))
            }
            FileActionPromptKind::Move => {
                let from = prompt
                    .target_path
                    .clone()
                    .ok_or_else(|| "select an item first".to_string())?;
                let to = self.resolve_destination_path(&prompt.input)?;
                if from == to {
                    return Err("move destination matches the source path".to_string());
                }
                Ok((
                    FilesOperation {
                        kind: FilesOperationKind::Move,
                        path: from.clone(),
                        target: Some(to.clone()),
                        directory: prompt.target_is_dir,
                    },
                    "Move".to_string(),
                    format!("{from} -> {to}"),
                ))
            }
            FileActionPromptKind::Rename => {
                let from = prompt
                    .target_path
                    .clone()
                    .ok_or_else(|| "select an item first".to_string())?;
                let to = self.join_child(&prompt.input)?;
                if from == to {
                    return Err("new name matches the current name".to_string());
                }
                Ok((
                    FilesOperation {
                        kind: FilesOperationKind::Rename,
                        path: from.clone(),
                        target: Some(to.clone()),
                        directory: prompt.target_is_dir,
                    },
                    "Rename".to_string(),
                    format!("{from} -> {to}"),
                ))
            }
            FileActionPromptKind::Delete => {
                let path = prompt
                    .target_path
                    .clone()
                    .ok_or_else(|| "select an item first".to_string())?;
                Ok((
                    FilesOperation {
                        kind: FilesOperationKind::Delete,
                        path: path.clone(),
                        target: None,
                        directory: prompt.target_is_dir,
                    },
                    "Delete".to_string(),
                    path,
                ))
            }
        }
    }

    fn operations_from_marked_prompt(
        &self,
        prompt: &FileActionPrompt,
    ) -> Result<Vec<FilesQueuedOperation>, String> {
        if prompt.targets.is_empty() {
            return Err("select one or more entries first".to_string());
        }
        let (operation_kind, destination_source, title) = match prompt.kind {
            FileActionPromptKind::CopySelected => {
                (FilesOperationKind::Copy, self.source, "Copy selected")
            }
            FileActionPromptKind::MoveSelected => {
                (FilesOperationKind::Move, self.source, "Move selected")
            }
            FileActionPromptKind::TransferSelected => match self.source {
                FilesSourceKind::Sifs => (
                    FilesOperationKind::CopyToLocal,
                    FilesSourceKind::Local,
                    "Download selected",
                ),
                FilesSourceKind::Local => (
                    FilesOperationKind::CopyToSifs,
                    FilesSourceKind::Sifs,
                    "Copy selected to SIFS",
                ),
            },
            _ => return Err("prompt does not support selected entries".to_string()),
        };
        let destination_root =
            self.resolve_destination_folder(destination_source, &prompt.input)?;
        prompt
            .targets
            .iter()
            .map(|target| {
                let name = file_action_target_name(self.source, &target.path)?;
                let destination =
                    join_destination_child(destination_source, &destination_root, &name)?;
                if self.source == destination_source && target.path == destination {
                    return Err(format!("destination matches {}", target.path));
                }
                if self.source == destination_source
                    && target.is_dir
                    && destination_inside_source(self.source, &target.path, &destination)
                {
                    return Err(format!(
                        "destination cannot be inside the selected folder {}",
                        target.path
                    ));
                }
                Ok(FilesQueuedOperation {
                    operation: FilesOperation {
                        kind: operation_kind,
                        path: target.path.clone(),
                        target: Some(destination.clone()),
                        directory: target.is_dir,
                    },
                    title: title.to_string(),
                    detail: format!("{} -> {destination}", target.path),
                })
            })
            .collect()
    }

    fn resolve_destination_folder(
        &self,
        source: FilesSourceKind,
        input: &str,
    ) -> Result<String, String> {
        match source {
            FilesSourceKind::Sifs => {
                let base = if self.source == FilesSourceKind::Sifs {
                    &self.path
                } else {
                    &self.sifs_path
                };
                resolve_sifs_destination_folder(base, input)
            }
            FilesSourceKind::Local => {
                let base = if self.source == FilesSourceKind::Local {
                    &self.path
                } else {
                    &self.local_path
                };
                resolve_local_destination_path(base, input)
            }
        }
    }

    fn start_operation(
        &mut self,
        operation: FilesOperation,
        title: String,
        detail: String,
        waker: Option<sui::UiHandle>,
    ) {
        self.start_operation_for_source(self.source, operation, title, detail, waker);
    }

    fn start_operation_for_source(
        &mut self,
        source: FilesSourceKind,
        operation: FilesOperation,
        title: String,
        detail: String,
        waker: Option<sui::UiHandle>,
    ) {
        if let Some(waker) = waker {
            self.ensure_worker(waker);
        }
        let request_id = self.next_request_id;
        self.next_request_id = self.next_request_id.wrapping_add(1);
        clear_cancelled_operation(&self.worker_cancellations, request_id);
        self.tasks.insert(
            0,
            FilesTask {
                id: request_id,
                source,
                title,
                detail,
                state: FilesTaskState::Running,
                progress: Some(0.02),
            },
        );
        self.trim_tasks();

        if let Some(tx) = self.operations_sender() {
            if tx
                .send(FilesWorkerCommand::Operation {
                    request_id,
                    source,
                    operation,
                })
                .is_err()
            {
                self.finish_task(
                    request_id,
                    FilesTaskState::Failed,
                    "worker stopped".to_string(),
                );
            }
            return;
        }

        let result = self
            .execute_operation_for_source(source, operation, &self.path)
            .map_err(FilesOperationFailure::Error);
        self.apply_operation_result(request_id, result);
    }

    fn start_marked_operations(
        &mut self,
        operations: Vec<FilesQueuedOperation>,
        waker: Option<sui::UiHandle>,
    ) {
        self.clear_marked_entries();
        for queued in operations {
            self.start_operation(queued.operation, queued.title, queued.detail, waker.clone());
        }
    }

    fn start_delete_targets(
        &mut self,
        targets: Vec<FileActionTarget>,
        waker: Option<sui::UiHandle>,
    ) {
        self.clear_marked_entries();
        for target in targets {
            self.start_operation(
                FilesOperation {
                    kind: FilesOperationKind::Delete,
                    path: target.path.clone(),
                    target: None,
                    directory: target.is_dir,
                },
                "Delete".to_string(),
                target.path,
                waker.clone(),
            );
        }
    }

