/// Narrow file-manager chrome keeps the essential navigation controls visible
/// and moves the remaining commands plus the hidden wide inspector into
/// explicit, keyboard-focusable overlays.
fn compact_header(shared: &Shared, reader: &ThemeReader) -> impl Widget + use<> {
    let back = {
        let s = shared.clone();
        IconButton::new(IconGlyph::ChevronLeft, "Back")
            .size(30.0)
            .theme_when(clone_reader(reader))
            .enabled_when({
                let s = s.clone();
                move || s.files().can_go_back()
            })
            .on_press(move || {
                let waker = { s.borrow().waker.clone() };
                s.files_mut().go_back(waker);
            })
    };
    let up = {
        let s = shared.clone();
        IconButton::new(IconGlyph::ChevronUp, "Up")
            .size(30.0)
            .theme_when(clone_reader(reader))
            .on_press(move || s.files_mut().go_up())
    };
    let location = {
        let files = shared.files();
        let theme = shared.theme();
        let pal = palette(shared);
        let source_label = match files.source {
            FilesSourceKind::Sifs => "SIFS",
            FilesSourceKind::Local => "Local",
        };
        let leaf = match files.source {
            FilesSourceKind::Sifs => files
                .path
                .rsplit('/')
                .find(|segment| !segment.is_empty())
                .unwrap_or("/"),
            FilesSourceKind::Local => Path::new(&files.path)
                .file_name()
                .and_then(|name| name.to_str())
                .unwrap_or(files.path.as_str()),
        };
        Label::new(format!("{source_label} · {}", middle_short(leaf, 18)))
            .semantic_name(format!(
                "Current {} path {}",
                files.source.label(),
                files.path
            ))
            .text_style(pal.text_style(&theme, 12.0, FontWeight::MEDIUM, pal.text))
    };
    let commands = {
        let s = shared.clone();
        IconButton::new(IconGlyph::Folder, "More file commands")
            .size(30.0)
            .theme_when(clone_reader(reader))
            .selected_when({
                let s = s.clone();
                move || s.files().compact_overlay == Some(CompactFilesOverlay::Commands)
            })
            .on_press_with_ctx(move |ctx| {
                s.files_mut()
                    .open_compact_overlay(CompactFilesOverlay::Commands);
                request_files_overlay_rebuild(ctx);
            })
    };
    let selection_actions = {
        let enabled = shared.clone();
        let action = shared.clone();
        IconButton::new(IconGlyph::MoreHorizontal, "Selected item actions")
            .size(30.0)
            .theme_when(clone_reader(reader))
            .enabled_when(move || {
                let files = enabled.files();
                files.marked_count() > 0 || files.selected_entry().is_some()
            })
            .selected_when({
                let action = action.clone();
                move || {
                    action.files().compact_overlay == Some(CompactFilesOverlay::SelectionActions)
                }
            })
            .on_press_with_ctx(move |ctx| {
                action
                    .files_mut()
                    .open_compact_overlay(CompactFilesOverlay::SelectionActions);
                request_files_overlay_rebuild(ctx);
            })
    };
    let placement_activity = {
        let s = shared.clone();
        IconButton::new(IconGlyph::History, "Reconciliation activity")
            .size(30.0)
            .theme_when(clone_reader(reader))
            .selected_when({
                let s = s.clone();
                move || s.files().placement_activity_open
            })
            .on_press_with_ctx(move |ctx| {
                let waker = { s.borrow().waker.clone() };
                s.files_mut().open_placement_activity(waker);
                request_files_overlay_rebuild(ctx);
            })
    };
    let inspector = {
        let s = shared.clone();
        IconButton::new(IconGlyph::FileText, "Open selection info")
            .size(30.0)
            .theme_when(clone_reader(reader))
            .selected_when({
                let s = s.clone();
                move || s.files().compact_overlay == Some(CompactFilesOverlay::Inspector)
            })
            .on_press_with_ctx(move |ctx| {
                s.files_mut()
                    .open_compact_overlay(CompactFilesOverlay::Inspector);
                request_files_overlay_rebuild(ctx);
            })
    };

    Flex::horizontal()
        .main_gap(4.0)
        .align_items(Alignment::Center)
        .with_item(back, FlexItem::new().no_shrink())
        .with_item(up, FlexItem::new().no_shrink())
        .with_item(location, FlexItem::fill().min_width(72.0))
        .with_item(placement_activity, FlexItem::new().no_shrink())
        .with_item(commands, FlexItem::new().no_shrink())
        .with_item(selection_actions, FlexItem::new().no_shrink())
        .with_item(inspector, FlexItem::new().no_shrink())
}

fn files_action_bar_content(
    shared: &Shared,
    reader: &ThemeReader,
    contextual_selection: bool,
) -> WidgetPod {
    let (marked_count, selected_entry, source, current_view_mode) = {
        let files = shared.files();
        (
            files.marked_count(),
            files.selected_entry().cloned(),
            files.source,
            files.view_mode,
        )
    };

    let controls = if contextual_selection && (marked_count > 0 || selected_entry.is_some()) {
        let mut row = Flex::horizontal().gap(6.0).align_items(Alignment::Center);
        if marked_count == 0 {
            let entry = selected_entry.as_ref().expect("selected entry");
            row = row.with_child(file_action_button(
                shared,
                reader,
                FileContextAction::Open,
                if entry.is_dir { "Open folder" } else { "Open" },
                if entry.is_dir {
                    IconGlyph::Folder
                } else {
                    IconGlyph::FileText
                },
                ButtonAppearance::Tonal,
            ));
        }

        let transfer_action = if marked_count > 0 {
            FileContextAction::TransferSelected
        } else {
            FileContextAction::Transfer
        };
        let transfer_label = match source {
            FilesSourceKind::Sifs => "Download",
            FilesSourceKind::Local => "Copy to Sinomo",
        };
        row = row.with_child(file_action_button(
            shared,
            reader,
            transfer_action,
            transfer_label,
            if source == FilesSourceKind::Sifs {
                IconGlyph::Download
            } else {
                IconGlyph::Storage
            },
            ButtonAppearance::Ghost,
        ));

        let trigger = sui::Button::new("Actions")
            .icon(IconGlyph::MoreHorizontal)
            .min_height(32.0)
            .appearance(ButtonAppearance::Ghost)
            .theme_when(clone_reader(reader));
        row = row.with_child(files_primary_menu(
            "visible-selection-actions",
            shared,
            reader,
            FileContextMenuTarget::Selection,
            trigger,
        ));
        row
    } else {
        let new = files_primary_menu(
            "visible-create-menu",
            shared,
            reader,
            FileContextMenuTarget::Create,
            IconButton::new(IconGlyph::Add, "New")
                .size(32.0)
                .appearance(ButtonAppearance::Tonal)
                .tone(SemanticTone::Accent)
                .theme_when(clone_reader(reader)),
        );
        let import = files_primary_menu(
            "visible-import-menu",
            shared,
            reader,
            FileContextMenuTarget::Import,
            IconButton::new(IconGlyph::Download, "Import")
                .size(32.0)
                .appearance(ButtonAppearance::Ghost)
                .theme_when(clone_reader(reader)),
        );
        let more = files_primary_menu(
            "visible-location-actions",
            shared,
            reader,
            FileContextMenuTarget::LocationMore,
            IconButton::new(IconGlyph::MoreHorizontal, "More folder actions")
                .size(32.0)
                .theme_when(clone_reader(reader)),
        );
        Flex::horizontal()
            .gap(6.0)
            .align_items(Alignment::Center)
            .with_child(toolbar_tooltip("New", new, reader))
            .with_child(toolbar_tooltip("Import", import, reader))
            .with_child(toolbar_tooltip("More folder actions", more, reader))
    };

    let s = shared.clone();
    let view_control = ContextMenu::new(
        "files-view-menu",
        IconButton::new(IconGlyph::Monitor, "File view")
            .size(32.0)
            .theme_when(clone_reader(reader)),
    )
    .items(
        FilesViewMode::OPTIONS
            .iter()
            .enumerate()
            .map(|(index, label)| {
                MenuItem::new(if index == current_view_mode.selected_index() {
                    format!("✓ {label}")
                } else {
                    label.to_string()
                })
            }),
    )
    .theme_when(clone_reader(reader))
    .activation_button(PointerButton::Primary)
    .on_activate(move |index, _item| {
        s.files_mut()
            .set_view_mode(FilesViewMode::from_selected_index(index));
    });
    let mut view_commands = Flex::horizontal().gap(6.0).align_items(Alignment::Center);
    if current_view_mode != FilesViewMode::Details {
        view_commands = view_commands.with_child(toolbar_tooltip(
            "Sort",
            files_sort_menu(shared, reader),
            reader,
        ));
    }
    view_commands = view_commands.with_child(toolbar_tooltip(
        format!(
            "File view: {}",
            FilesViewMode::OPTIONS[current_view_mode.selected_index()]
        ),
        view_control,
        reader,
    ));
    if !contextual_selection {
        return WidgetPod::new(
            Flex::horizontal()
                .gap(6.0)
                .align_items(Alignment::Center)
                .with_item(controls, FlexItem::new().no_shrink())
                .with_item(view_commands, FlexItem::new().no_shrink()),
        );
    }
    let view_commands_width = if current_view_mode == FilesViewMode::Details {
        32.0
    } else {
        70.0
    };

    WidgetPod::new(
        Stack::vertical()
            .alignment(Alignment::Stretch)
            .with_child(
                SizedBox::new().height(FILE_ACTION_BAR_H - 1.0).child(
                    WidgetPadding::horizontal(
                        10.0,
                        Flex::horizontal()
                            .justify(sui::FlexJustify::SpaceBetween)
                            .align_items(Alignment::Center)
                            .with_item(controls, FlexItem::new().no_shrink())
                            .with_item(
                                SizedBox::new()
                                    .width(view_commands_width)
                                    .child(view_commands),
                                FlexItem::fixed(view_commands_width),
                            ),
                    )
                    .fill_child_width(true)
                    .fill_child_height(true),
                ),
            )
            .with_child(Separator::horizontal().theme_when(clone_reader(reader))),
    )
}

fn files_sort_menu(shared: &Shared, reader: &ThemeReader) -> ContextMenu {
    let current = shared.files().sort_mode;
    let options = [
        (FileSortMode::NameAsc, "Name (A to Z)"),
        (FileSortMode::NameDesc, "Name (Z to A)"),
        (FileSortMode::Kind, "Kind"),
        (FileSortMode::SizeDesc, "Size (largest first)"),
        (FileSortMode::SizeAsc, "Size (smallest first)"),
    ];
    let items = options.map(|(mode, label)| {
        MenuItem::new(if mode == current {
            format!("✓ {label}")
        } else {
            label.to_string()
        })
    });
    let trigger = IconButton::new(IconGlyph::ChevronDown, "Sort file view")
        .size(32.0)
        .appearance(ButtonAppearance::Ghost)
        .theme_when(clone_reader(reader));
    let s = shared.clone();
    ContextMenu::new("files-sort-menu", trigger)
        .items(items)
        .theme_when(clone_reader(reader))
        .activation_button(PointerButton::Primary)
        .on_activate(move |index, _item| {
            let mode = match index {
                1 => FileSortMode::NameDesc,
                2 => FileSortMode::Kind,
                3 => FileSortMode::SizeDesc,
                4 => FileSortMode::SizeAsc,
                _ => FileSortMode::NameAsc,
            };
            s.files_mut().set_sort_mode(mode);
        })
}

fn files_action_bar(
    shared: &Shared,
    reader: &ThemeReader,
    contextual_selection: bool,
) -> impl Widget + use<> {
    let source = shared
        .signals()
        .files_structure
        .select_named("files visible action bar", |key| {
            (key.header.clone(), key.list.entries_total_count)
        });
    let s = shared.clone();
    let r = Rc::clone(reader);
    RebuildOnChange::key_from(source, move |_key| {
        files_action_bar_content(&s, &r, contextual_selection)
    })
}

// ---------------------------------------------------------------------------
// File listing — rebuilt on navigation by `RebuildOnChange`.
// ---------------------------------------------------------------------------

/// Build the file-list body for the current location: an error/empty placeholder, or a virtual
/// table whose pinned header owns sorting and whose rows support select/open interactions.
fn listing(shared: &Shared, reader: &ThemeReader, scroll_state: &ScrollState) -> WidgetPod {
    let (loading, error, is_empty): (bool, Option<String>, bool) = {
        let files = shared.files();
        (files.loading, files.error.clone(), files.entries.is_empty())
    };
    let source = shared.files().source;

    if sifs_daemon_offline(shared) {
        return WidgetPod::new(sifs_offline_panel(shared, reader));
    }

    if loading {
        let body = centered_note(
            reader,
            IconGlyph::Storage,
            format!("Loading {}", source.label()),
            match source {
                FilesSourceKind::Sifs => "Opening the distributed filesystem...",
                FilesSourceKind::Local => "Reading the local directory...",
            },
        );
        return WidgetPod::new(body);
    }
    if let Some(error) = error {
        let retry = {
            let s = shared.clone();
            sui::Button::new(format!("Retry {}", source.label()))
                .icon(IconGlyph::Redo)
                .theme_when(clone_reader(reader))
                .on_press(move || {
                    let waker = { s.borrow().waker.clone() };
                    s.files_mut().retry(waker);
                })
        };
        let mut actions = Flex::horizontal()
            .wrap(FlexWrap::Wrap)
            .gap(8.0)
            .justify(sui::FlexJustify::Center)
            .align_items(Alignment::Center)
            .with_child(retry);
        if source == FilesSourceKind::Sifs {
            let settings = {
                let s = shared.clone();
                sui::Button::new("Connection settings")
                    .theme_when(clone_reader(reader))
                    .appearance(sui::ButtonAppearance::Tonal)
                    .tone(SemanticTone::Neutral)
                    .on_press(move || open_settings_section(&s, SettingsSection::System))
            };
            let browse_local = {
                let s = shared.clone();
                sui::Button::new(BROWSE_LOCAL_FILES_LABEL)
                    .icon(IconGlyph::Folder)
                    .theme_when(clone_reader(reader))
                    .appearance(sui::ButtonAppearance::Tonal)
                    .tone(SemanticTone::Neutral)
                    .on_press(move || {
                        let waker = { s.borrow().waker.clone() };
                        s.files_mut().switch_source(FilesSourceKind::Local, waker);
                    })
            };
            actions = actions.with_child(settings).with_child(browse_local);
        }
        let body = centered_note(
            reader,
            IconGlyph::Storage,
            format!("{} unavailable", source.label()),
            source_unavailable_summary(source, &error),
        )
        .action(actions)
        .action_max_width(480.0);
        return WidgetPod::new(body);
    }
    if is_empty {
        let create_file = {
            let s = shared.clone();
            sui::Button::new("Create file")
                .icon(IconGlyph::File)
                .min_width(130.0)
                .theme_when(clone_reader(reader))
                .on_press_with_ctx(move |ctx| {
                    s.files_mut()
                        .open_action_prompt(FileActionPromptKind::NewFile);
                    request_files_overlay_rebuild(ctx);
                })
        };
        let create_folder = {
            let s = shared.clone();
            sui::Button::new("Create folder")
                .icon(IconGlyph::Folder)
                .min_width(150.0)
                .theme_when(clone_reader(reader))
                .on_press_with_ctx(move |ctx| {
                    s.files_mut()
                        .open_action_prompt(FileActionPromptKind::NewFolder);
                    request_files_overlay_rebuild(ctx);
                })
        };
        let actions = Flex::horizontal()
            .wrap(FlexWrap::Wrap)
            .gap(8.0)
            .align_items(Alignment::Center)
            .with_child(create_file)
            .with_child(create_folder);
        let body = centered_note(
            reader,
            IconGlyph::Folder,
            "Empty directory",
            "Nothing here yet.",
        )
        .action(actions)
        .action_height(72.0);
        return WidgetPod::new(body);
    }

    WidgetPod::new(files_list_body_rebuild(shared, reader, scroll_state))
}

fn files_list_body_rebuild(
    shared: &Shared,
    reader: &ThemeReader,
    scroll_state: &ScrollState,
) -> impl Widget + use<> {
    let source = shared
        .signals()
        .files_structure
        .select_named("files list structure", |key| key.list.clone());
    let s = shared.clone();
    let r = Rc::clone(reader);
    let ss = scroll_state.clone();
    let table_state = VirtualTableState::new();
    let thumbnail_registration = Rc::new(RefCell::new(ThumbnailRegistrationPool::default()));
    RebuildOnChange::key_from(source, move |_key| {
        files_list_body(&s, &r, &ss, &table_state, &thumbnail_registration)
    })
}

/// Transparent event target around the virtual table. The table owns primary-click selection;
/// this wrapper handles the secondary-click counterpart before the parent [`ContextMenu`] opens.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum FileContextMenuTarget {
    Selection,
    CurrentLocation,
    Create,
    Import,
    LocationMore,
    Availability,
}

struct FileListContextTarget {
    shared: Shared,
    table_state: VirtualTableState,
    context_target: Rc<Cell<FileContextMenuTarget>>,
    child: WidgetPod,
    last_thumbnail_keys: Vec<ThumbnailRequestKey>,
}

impl FileListContextTarget {
    fn new<W>(
        shared: Shared,
        table_state: VirtualTableState,
        context_target: Rc<Cell<FileContextMenuTarget>>,
        child: W,
    ) -> Self
    where
        W: Widget + 'static,
    {
        Self {
            shared,
            table_state,
            context_target,
            child: WidgetPod::new(child),
            last_thumbnail_keys: Vec::new(),
        }
    }

    fn body_rect(&self, bounds: Rect) -> Rect {
        let theme = self.shared.theme();
        let padding = theme.metrics.data_viewport_padding;
        let header_height = theme.metrics.table_header_height;
        let header_gap = theme.metrics.select_menu_gap;
        Rect::new(
            bounds.x() + padding.left,
            bounds.y() + padding.top + header_height + header_gap,
            (bounds.width() - padding.left - padding.right).max(0.0),
            (bounds.height() - padding.top - padding.bottom - header_height - header_gap).max(0.0),
        )
    }

    fn row_at_position(&self, bounds: Rect, position: Point) -> Option<usize> {
        let body = self.body_rect(bounds);
        if !body.contains(position) {
            return None;
        }
        let theme = self.shared.theme();
        let row_height = theme.metrics.table_row_height.max(1.0);
        let scroll_y = self.table_state.scroll_state().current_offset().y;
        let index = ((position.y - body.y() + scroll_y) / row_height).floor() as usize;
        (index < self.shared.files().entries.len()).then_some(index)
    }

    fn schedule_visible_thumbnails(&mut self, bounds: Rect) {
        let body = self.body_rect(bounds);
        if body.height() <= 0.0 {
            return;
        }
        let row_height = self.shared.theme().metrics.table_row_height.max(1.0);
        let offset = self.table_state.scroll_state().current_offset().y.max(0.0);
        let start = ((offset / row_height).floor() as usize).saturating_sub(1);
        let end = ((offset + body.height()) / row_height).ceil() as usize + 1;
        let (entries, keys) = {
            let files = self.shared.files();
            let start = start.min(files.entries.len());
            let end = end.min(files.entries.len()).max(start);
            let entries = files.entries[start..end].to_vec();
            let keys = entries
                .iter()
                .filter_map(|entry| {
                    files.thumbnail_request_for_entry(entry, ThumbnailBucket::Medium)
                })
                .map(|request| request.key)
                .collect::<Vec<_>>();
            (entries, keys)
        };
        if keys == self.last_thumbnail_keys {
            return;
        }
        self.last_thumbnail_keys = keys;
        let waker = self.shared.borrow().waker.clone();
        self.shared
            .files_mut_unpublished()
            .request_visible_thumbnails(&entries, 0..entries.len(), ThumbnailBucket::Medium, waker);
    }
}

impl Widget for FileListContextTarget {
    fn event(&mut self, ctx: &mut EventCtx, event: &Event) {
        if ctx.phase() != EventPhase::Capture
            && let Event::Pointer(pointer) = event
            && pointer.kind == PointerEventKind::Down
            && pointer.button == Some(PointerButton::Secondary)
        {
            if let Some(index) = self.row_at_position(ctx.bounds(), pointer.position) {
                self.context_target.set(FileContextMenuTarget::Selection);
                self.shared.files_mut().select_context_entry(index);
                ctx.request_paint();
                ctx.request_semantics();
            } else if self.body_rect(ctx.bounds()).contains(pointer.position) {
                self.context_target
                    .set(FileContextMenuTarget::CurrentLocation);
            } else {
                // Do not let the parent menu open over the table header or outside the listing.
                ctx.set_handled();
            }
        }
    }

    fn measure(&mut self, ctx: &mut MeasureCtx, constraints: Constraints) -> Size {
        // The table handles wheel/key/accessibility events itself. Observe its
        // published viewport so even handled scrolls schedule newly visible rows.
        let _ = ctx.observe(&self.table_state.viewport_signal());
        self.child.measure(ctx, constraints)
    }

    fn arrange(&mut self, ctx: &mut ArrangeCtx, bounds: Rect) {
        self.child.arrange(ctx, bounds);
        self.schedule_visible_thumbnails(bounds);
    }

    fn paint(&self, ctx: &mut PaintCtx) {
        self.child.paint(ctx);
    }

    fn semantics(&self, ctx: &mut SemanticsCtx) {
        self.child.semantics(ctx);
    }

    fn visit_children(&self, visitor: &mut dyn WidgetPodVisitor) {
        visitor.visit(&self.child);
    }

    fn visit_children_mut(&mut self, visitor: &mut dyn WidgetPodMutVisitor) {
        visitor.visit(&mut self.child);
    }
}

#[cfg(test)]
fn files_context_menu_items(files: &FilesState) -> Vec<MenuItem> {
    file_context_menu_entries(files, FileContextMenuTarget::Selection)
        .into_iter()
        .map(|entry| entry.item)
        .collect()
}

fn file_context_menu<W>(
    name: &'static str,
    shared: &Shared,
    reader: &ThemeReader,
    context_target: Rc<Cell<FileContextMenuTarget>>,
    activation_button: PointerButton,
    anchor_to_pointer: bool,
    trigger: W,
) -> ContextMenu
where
    W: Widget + 'static,
{
    let items_shared = shared.clone();
    let items_target = Rc::clone(&context_target);
    let action_shared = shared.clone();
    let action_target = Rc::clone(&context_target);
    ContextMenu::new(name, trigger)
        .theme_when(clone_reader(reader))
        .items_when(move || {
            file_context_menu_entries(&items_shared.files(), items_target.get())
                .into_iter()
                .map(|entry| entry.item)
                .collect()
        })
        .on_activate_path_with_ctx(move |ctx, path, _item| {
            let action = file_context_action_at_path(
                &file_context_menu_entries(&action_shared.files(), action_target.get()),
                &path,
            );
            if let Some(action) = action {
                activate_file_context_action(&action_shared, action, ctx);
            }
        })
        .activation_button(activation_button)
        .anchor_to_pointer(anchor_to_pointer)
}

fn files_table_with_context_menu<W>(
    shared: &Shared,
    reader: &ThemeReader,
    table_state: &VirtualTableState,
    table: W,
) -> ContextMenu
where
    W: Widget + 'static,
{
    let context_target = Rc::new(Cell::new(FileContextMenuTarget::Selection));
    let trigger = FileListContextTarget::new(
        shared.clone(),
        table_state.clone(),
        Rc::clone(&context_target),
        table,
    );
    file_context_menu(
        "files-list-context-menu",
        shared,
        reader,
        context_target,
        PointerButton::Secondary,
        true,
        trigger,
    )
}

fn files_primary_menu<W>(
    name: &'static str,
    shared: &Shared,
    reader: &ThemeReader,
    target: FileContextMenuTarget,
    trigger: W,
) -> ContextMenu
where
    W: Widget + 'static,
{
    file_context_menu(
        name,
        shared,
        reader,
        Rc::new(Cell::new(target)),
        PointerButton::Primary,
        false,
        trigger,
    )
}

fn file_action_button(
    shared: &Shared,
    reader: &ThemeReader,
    action: FileContextAction,
    label: impl Into<String>,
    icon: IconGlyph,
    appearance: ButtonAppearance,
) -> sui::Button {
    let enabled = action.enabled(&shared.files());
    let action_shared = shared.clone();
    sui::Button::new(label)
        .icon(icon)
        .min_height(32.0)
        .appearance(appearance)
        .tone(if action.destructive() {
            SemanticTone::Warning
        } else {
            SemanticTone::Neutral
        })
        .theme_when(clone_reader(reader))
        .enabled(enabled)
        .on_press_with_ctx(move |ctx| {
            activate_file_context_action(&action_shared, action, ctx);
        })
}

fn files_list_body(
    shared: &Shared,
    reader: &ThemeReader,
    scroll_state: &ScrollState,
    table_state: &VirtualTableState,
    thumbnail_registration: &Rc<RefCell<ThumbnailRegistrationPool>>,
) -> WidgetPod {
    match shared.files().view_mode {
        FilesViewMode::Details => files_list_body_table(
            shared,
            reader,
            scroll_state,
            table_state,
            thumbnail_registration,
        ),
        icon_mode => files_list_body_icons(
            shared,
            reader,
            scroll_state,
            icon_mode,
            thumbnail_registration,
        ),
    }
}

fn files_list_body_table(
    shared: &Shared,
    reader: &ThemeReader,
    scroll_state: &ScrollState,
    table_state: &VirtualTableState,
    thumbnail_registration: &Rc<RefCell<ThumbnailRegistrationPool>>,
) -> WidgetPod {
    let _ = scroll_state;
    let (entries, source, sort_mode, total_count) = {
        let files = shared.files();
        (
            files.entries.clone(),
            files.source,
            files.sort_mode,
            files.entries_total_count,
        )
    };
    if entries.is_empty() {
        return WidgetPod::new(centered_note(
            reader,
            IconGlyph::Folder,
            "Empty directory",
            format!("No {} entries to show.", source.label()),
        ));
    }

    let build_table = |show_details: bool| {
        let row_entries = entries.clone();
        let paint_shared = shared.clone();
        let name_entries = entries.clone();
        let description_entries = entries.clone();
        let s = shared.clone();
        let cell_s = shared.clone();
        let header_s = shared.clone();
        let page_s = shared.clone();
        let description_s = shared.clone();
        let registration = Rc::clone(thumbnail_registration);
        let thumbnail_table_state = table_state.clone();
        let mut columns = vec![
            VirtualTableColumn::new("").key(1).width(36.0),
            VirtualTableColumn::new("Name")
                .key(2)
                .min_width(if show_details {
                    180.0
                } else {
                    COMPACT_FILE_NAME_MIN_W
                })
                .sort_direction(sort_mode.name_sort_direction()),
            VirtualTableColumn::new("Availability")
                .key(3)
                .min_width(COMPACT_FILE_PLACEMENT_W)
                .width(if show_details {
                    156.0
                } else {
                    COMPACT_FILE_PLACEMENT_W
                }),
        ];
        if show_details {
            columns.push(
                VirtualTableColumn::new("Details")
                    .key(4)
                    .width(156.0)
                    .sort_direction(sort_mode.meta_sort_direction()),
            );
        }
        let table = VirtualTable::new("files-listing")
            .state(table_state.clone())
            .columns(columns)
            .collection_window(CollectionWindow::loaded(
                0..entries.len(),
                Some(total_count),
                false,
                entries.len() < total_count,
            ))
            .row_count(entries.len())
            .row_key({
                let entries = entries.clone();
                move |index| entries.get(index).map(file_entry_key).unwrap_or_default()
            })
            .theme_when(clone_gray_data_scrollbar_reader(reader))
            .selected_when({
                let s = s.clone();
                move || {
                    s.files()
                        .selected
                        .filter(|index| *index < s.files().entries.len())
                }
            })
            .row_name(move |index| {
                name_entries
                    .get(index)
                    .map(|entry| entry.name.clone())
                    .unwrap_or_default()
            })
            .row_description(move |index| {
                let Some(entry) = description_entries.get(index) else {
                    return String::new();
                };
                let files = description_s.files();
                let kind = if entry.is_dir {
                    "Folder"
                } else if entry.is_link {
                    "Link"
                } else {
                    "File"
                };
                let mut description =
                    format!("{kind}, {} {}", files.source.path_label(), entry.path);
                if entry.is_dir {
                    description.push_str(". Single click selects; double click opens the folder");
                }
                if files.source == FilesSourceKind::Sifs {
                    let placement = file_row_placement_badge(entry, &files);
                    description.push_str(". Placement: ");
                    description.push_str(&placement.label);
                    if let Some((current, desired)) = placement.replicas {
                        description.push_str(&format!("; {current}/{desired} replicas"));
                    }
                    description.push_str(". Details: ");
                    description.push_str(&entry_row_meta(
                        entry,
                        &files,
                        files.selected == Some(index),
                    ));
                }
                description
            })
            .row_painter(move |ctx, row| {
                paint_file_table_row(
                    ctx,
                    &paint_shared,
                    &row_entries,
                    row,
                    &registration,
                    &thumbnail_table_state,
                );
            })
            .on_cell_activate(move |row_index, column_index, activation| {
                if column_index == 0 && activation == VirtualTableRowActivationKind::Single {
                    cell_s.files_mut().toggle_marked_entry(row_index);
                    true
                } else {
                    false
                }
            })
            .on_row_activate(move |index, activation| {
                s.files_mut().click_row(index, activation);
            })
            .on_header_activate(move |column| {
                let sort_column = match column {
                    1 => FilesSortColumn::Name,
                    3 => FilesSortColumn::KindSize,
                    _ => return,
                };
                header_s.files_mut().toggle_sort_column(sort_column);
            })
            .on_near_end(move || {
                if page_s.files().entries.len() < total_count {
                    let waker = { page_s.borrow().waker.clone() };
                    page_s.files_mut().request_more_entries(waker);
                }
            });
        files_table_with_context_menu(shared, reader, table_state, table)
    };

    let compact_table = build_table(false);
    let complete_table = build_table(true);
    WidgetPod::new(ConstraintView::new(compact_table).when(
        ConstraintQuery::new().min_width(COMPLETE_FILE_TABLE_MIN_W),
        complete_table,
    ))
}

fn file_entry_key(entry: &SifsEntry) -> u64 {
    let mut key = 0xcbf2_9ce4_8422_2325_u64;
    for byte in entry.path.bytes() {
        key ^= u64::from(byte);
        key = key.wrapping_mul(0x0000_0100_0000_01b3);
    }
    key.max(1)
}

fn paint_file_table_row(
    ctx: &mut PaintCtx,
    shared: &Shared,
    entries: &[SifsEntry],
    row: &VirtualTableRowContext<'_>,
    registration: &Rc<RefCell<ThumbnailRegistrationPool>>,
    table_state: &VirtualTableState,
) {
    let _ = ctx.observe(&shared.signals().files_thumbnail_revision);
    let Some(entry) = entries.get(row.row_index) else {
        return;
    };
    let theme = shared.theme();
    let pal = palette(shared);
    let files = shared.files();
    let active = files.selected == Some(row.row_index);
    let selected = files.entry_marked(row.row_index);
    let label_color = if active { pal.text } else { pal.text_muted };
    let icon_color = if active { pal.accent } else { pal.text_faint };

    let select_cell = row.column_rects.first().copied().unwrap_or(row.row_rect);
    let select_side = theme
        .metrics
        .checkbox_indicator_size
        .min(select_cell.height() - 6.0)
        .max(0.0);
    let select_rect = Rect::new(
        select_cell.x() + ((select_cell.width() - select_side) * 0.5).max(0.0),
        select_cell.y() + ((select_cell.height() - select_side) * 0.5).max(0.0),
        select_side,
        select_side,
    );
    paint_checkbox_indicator(
        ctx,
        &theme,
        select_rect,
        CheckboxIndicatorState::new(selected).hovered(row.hovered),
    );

    if let Some(name_cell) = row.column_rects.get(1).copied() {
        let side = ROW_THUMBNAIL_SIDE.min((name_cell.height() - 6.0).max(0.0));
        let frame = Rect::new(
            name_cell.x() + 6.0,
            name_cell.y() + (name_cell.height() - side) * 0.5,
            side,
            side,
        );
        let row_height = theme.metrics.table_row_height.max(1.0);
        let first_row =
            (table_state.scroll_state().current_offset().y.max(0.0) / row_height).floor() as usize;
        let slot = 100_000 + row.row_index.saturating_sub(first_row) as u64;
        let painted = file_cached_thumbnail_buckets(FilesViewMode::Details)
            .into_iter()
            .flatten()
            .find_map(|bucket| {
                let request = files.thumbnail_request_for_entry(entry, bucket)?;
                let bitmap = files.thumbnail_cache.ready(&request.key)?;
                Some(paint_file_thumbnail(
                    ctx,
                    registration,
                    slot,
                    &request.key,
                    frame,
                    &bitmap,
                    &theme,
                ))
            })
            .unwrap_or(false);
        let style = LeadingLabelCellPaint::new()
            .icon_color(icon_color)
            .label_color(label_color)
            .label_weight(FontWeight::MEDIUM)
            .icon_slot_side(ROW_THUMBNAIL_SIDE)
            .icon_inset(2.0)
            .gap(8.0);
        let style = if painted {
            style.padding(6.0 + side + 8.0, 8.0)
        } else {
            style.icon(entry_icon(entry)).padding(6.0, 8.0)
        };
        let label_width = (name_cell.width() - ROW_THUMBNAIL_SIDE - 22.0).max(0.0);
        let display_name = display_name_for_width(&entry.name, label_width, 7.1);
        paint_leading_label_cell(ctx, &theme, name_cell, &display_name, style);
    }

    if let Some(placement_cell) = row.column_rects.get(2).copied() {
        let placement = file_row_placement_badge(entry, &files);
        // The compact badge has a fixed maximum width. Keep the full local-placement label
        // visible by yielding its redundant storage icon instead of truncating "this device".
        let placement_icon = (!matches!(
            placement.label.as_str(),
            "this device" | "unknown" | "local"
        ))
        .then_some(placement.icon);
        paint_placement_badge_with(
            ctx,
            &theme,
            placement_cell,
            &placement.label,
            placement_icon,
            placement.tone,
            placement.replicas,
            PlacementBadgePaint::new().padding(8.0, 5.0, 8.0, 5.0),
        );
    }

    if let Some(meta_cell) = row.column_rects.get(3).copied() {
        let meta_text = entry_row_meta(entry, &files, active);
        let display = display_name_for_width(&meta_text, (meta_cell.width() - 12.0).max(0.0), 6.2);
        paint_text_cell(
            ctx,
            &theme,
            meta_cell,
            &display,
            TextCellPaint::new()
                .text_token(theme.text.xs)
                .color(pal.text_faint)
                .padding(8.0, 8.0),
        );
    }
}

#[derive(Clone, Copy, Debug, PartialEq)]
struct FileIconGridMetrics {
    icon_side: f32,
    tile_width: f32,
    tile_height: f32,
    gap: f32,
    padding: f32,
    label_height: f32,
}

fn file_icon_grid_metrics(mode: FilesViewMode) -> FileIconGridMetrics {
    match mode {
        FilesViewMode::SmallIcons => FileIconGridMetrics {
            icon_side: 24.0,
            tile_width: 92.0,
            tile_height: 70.0,
            gap: 6.0,
            padding: 10.0,
            label_height: 30.0,
        },
        FilesViewMode::MediumIcons => FileIconGridMetrics {
            icon_side: 48.0,
            tile_width: 116.0,
            tile_height: 108.0,
            gap: 8.0,
            padding: 12.0,
            label_height: 38.0,
        },
        FilesViewMode::LargeIcons => FileIconGridMetrics {
            icon_side: 72.0,
            tile_width: 148.0,
            tile_height: 142.0,
            gap: 10.0,
            padding: 14.0,
            label_height: 44.0,
        },
        FilesViewMode::Flow => FileIconGridMetrics {
            icon_side: 56.0,
            tile_width: 196.0,
            tile_height: 240.0,
            gap: 12.0,
            padding: 12.0,
            label_height: 44.0,
        },
        FilesViewMode::Details => file_icon_grid_metrics(FilesViewMode::MediumIcons),
    }
}

fn file_thumbnail_bucket(mode: FilesViewMode) -> Option<ThumbnailBucket> {
    match mode {
        FilesViewMode::SmallIcons | FilesViewMode::MediumIcons | FilesViewMode::Details => {
            Some(ThumbnailBucket::Medium)
        }
        FilesViewMode::LargeIcons | FilesViewMode::Flow => Some(ThumbnailBucket::Large),
    }
}

fn file_cached_thumbnail_buckets(mode: FilesViewMode) -> [Option<ThumbnailBucket>; 2] {
    match mode {
        FilesViewMode::SmallIcons | FilesViewMode::MediumIcons | FilesViewMode::Details => {
            [Some(ThumbnailBucket::Medium), Some(ThumbnailBucket::Large)]
        }
        FilesViewMode::LargeIcons | FilesViewMode::Flow => {
            [Some(ThumbnailBucket::Large), Some(ThumbnailBucket::Medium)]
        }
    }
}

fn files_list_body_icons(
    shared: &Shared,
    reader: &ThemeReader,
    scroll_state: &ScrollState,
    mode: FilesViewMode,
    thumbnail_registration: &Rc<RefCell<ThumbnailRegistrationPool>>,
) -> WidgetPod {
    let (entries, total_count) = {
        let files = shared.files();
        (files.entries.clone(), files.entries_total_count)
    };
    let context_target = Rc::new(Cell::new(FileContextMenuTarget::Selection));
    let grid = FileIconGrid::new(
        shared.clone(),
        entries,
        total_count,
        mode,
        scroll_state.clone(),
        Rc::clone(&context_target),
        Rc::clone(thumbnail_registration),
    );
    let scroll = ScrollView::vertical(grid)
        .state(scroll_state.clone())
        .name(if mode == FilesViewMode::Flow {
            "File flow view".to_string()
        } else {
            format!("{} file icons", mode.icon_label().unwrap_or("Medium"))
        })
        .theme_when(clone_gray_data_scrollbar_reader(reader))
        .viewport_width_hint(true);
    let trigger = FileIconGridContextTarget::new(
        shared.clone(),
        scroll_state.clone(),
        file_icon_grid_metrics(mode).tile_height,
        Rc::clone(&context_target),
        scroll,
    );
    WidgetPod::new(file_context_menu(
        "files-icons-context-menu",
        shared,
        reader,
        context_target,
        PointerButton::Secondary,
        true,
        trigger,
    ))
}

/// Resets blank-space context clicks to the current folder before the nested grid gets a chance to
/// refine a tile hit to `Selection` during target/bubble routing.
struct FileIconGridContextTarget {
    shared: Shared,
    scroll_state: ScrollState,
    tile_height: f32,
    context_target: Rc<Cell<FileContextMenuTarget>>,
    child: WidgetPod,
}

impl FileIconGridContextTarget {
    fn new<W>(
        shared: Shared,
        scroll_state: ScrollState,
        tile_height: f32,
        context_target: Rc<Cell<FileContextMenuTarget>>,
        child: W,
    ) -> Self
    where
        W: Widget + 'static,
    {
        Self {
            shared,
            scroll_state,
            tile_height,
            context_target,
            child: WidgetPod::new(child),
        }
    }

    fn maybe_request_more(&self) {
        let should_request = {
            let files = self.shared.files();
            if files.entries.len() >= files.entries_total_count {
                false
            } else {
                let offset = self.scroll_state.current_offset().y;
                let viewport_height = self.scroll_state.viewport_size().height;
                let remaining =
                    (self.scroll_state.content_size().height - viewport_height - offset).max(0.0);
                remaining <= self.tile_height * 3.0
            }
        };
        if should_request {
            let waker = { self.shared.borrow().waker.clone() };
            self.shared.files_mut().request_more_entries(waker);
        }
    }
}

impl Widget for FileIconGridContextTarget {
    fn event(&mut self, ctx: &mut EventCtx, event: &Event) {
        if ctx.phase() == EventPhase::Capture
            && let Event::Pointer(pointer) = event
            && pointer.kind == PointerEventKind::Down
            && pointer.button == Some(PointerButton::Secondary)
            && ctx.bounds().contains(pointer.position)
        {
            self.context_target
                .set(FileContextMenuTarget::CurrentLocation);
        }
        if ctx.phase() != EventPhase::Capture
            && (matches!(
                event,
                Event::Pointer(pointer)
                    if matches!(
                        pointer.kind,
                        PointerEventKind::Move
                            | PointerEventKind::Up
                            | PointerEventKind::Scroll
                    )
            ) || matches!(event, Event::Keyboard(_)))
        {
            self.maybe_request_more();
        }
    }

    fn measure(&mut self, ctx: &mut MeasureCtx, constraints: Constraints) -> Size {
        self.child.measure(ctx, constraints)
    }

    fn arrange(&mut self, ctx: &mut ArrangeCtx, bounds: Rect) {
        self.child.arrange(ctx, bounds);
    }

    fn paint(&self, ctx: &mut PaintCtx) {
        self.child.paint(ctx);
    }

    fn semantics(&self, ctx: &mut SemanticsCtx) {
        self.child.semantics(ctx);
    }

    fn visit_children(&self, visitor: &mut dyn WidgetPodVisitor) {
        visitor.visit(&self.child);
    }

    fn visit_children_mut(&mut self, visitor: &mut dyn WidgetPodMutVisitor) {
        visitor.visit(&mut self.child);
    }
}

/// Responsive icon layout for Files. Scrolling stays in SUI's stock [`ScrollView`], while this
/// content widget paints only visible tiles and maps pointer/keyboard actions back to the same
/// [`FilesState`] operations used by the details table.
struct FileIconGrid {
    shared: Shared,
    thumbnail_revision: sui::Signal<u64>,
    entries: Vec<SifsEntry>,
    total_count: usize,
    mode: FilesViewMode,
    metrics: FileIconGridMetrics,
    scroll_state: ScrollState,
    context_target: Rc<Cell<FileContextMenuTarget>>,
    columns: usize,
    tile_width: f32,
    grid_start_x: f32,
    content_height: f32,
    flow_tiles: Vec<Rect>,
    max_flow_tile_height: f32,
    pending_reveal: Option<usize>,
    hovered: Option<usize>,
    pressed: Option<(usize, bool)>,
    last_click: Option<(usize, Instant)>,
    last_thumbnail_keys: Vec<ThumbnailRequestKey>,
    thumbnail_registration: Rc<RefCell<ThumbnailRegistrationPool>>,
}

#[derive(Default)]
struct ThumbnailRegistrationPool {
    handles: BTreeMap<u64, ImageHandle>,
    bindings: BTreeMap<u64, ThumbnailRequestKey>,
    /// Retain only current-listing dimensions across pagination/rebuilds and bitmap eviction.
    /// These contain no pixels and use the same source/version identity as thumbnail requests.
    flow_aspect_ratios: BTreeMap<ThumbnailRequestKey, f32>,
}

impl FileIconGrid {
    fn new(
        shared: Shared,
        entries: Vec<SifsEntry>,
        total_count: usize,
        mode: FilesViewMode,
        scroll_state: ScrollState,
        context_target: Rc<Cell<FileContextMenuTarget>>,
        thumbnail_registration: Rc<RefCell<ThumbnailRegistrationPool>>,
    ) -> Self {
        let thumbnail_revision = shared.signals().files_thumbnail_revision.clone();
        Self {
            shared,
            thumbnail_revision,
            entries,
            total_count,
            mode,
            metrics: file_icon_grid_metrics(mode),
            scroll_state,
            context_target,
            columns: 1,
            tile_width: 1.0,
            grid_start_x: 0.0,
            content_height: 0.0,
            flow_tiles: Vec::new(),
            max_flow_tile_height: 0.0,
            pending_reveal: None,
            hovered: None,
            pressed: None,
            last_click: None,
            last_thumbnail_keys: Vec::new(),
            thumbnail_registration,
        }
    }

    fn update_layout(&mut self, width: f32) {
        let usable = (width - self.metrics.padding * 2.0).max(1.0);
        self.tile_width = self.metrics.tile_width.min(usable);
        self.columns =
            (((usable + self.metrics.gap) / (self.tile_width + self.metrics.gap)).floor() as usize)
                .max(1);
        if !self.entries.is_empty() {
            self.columns = self.columns.min(self.entries.len());
        }
        if self.mode == FilesViewMode::Flow {
            self.tile_width = ((usable - self.columns.saturating_sub(1) as f32 * self.metrics.gap)
                / self.columns as f32)
                .min(256.0);
        }
        let grid_width = self.columns as f32 * self.tile_width
            + self.columns.saturating_sub(1) as f32 * self.metrics.gap;
        self.grid_start_x = ((width - grid_width) * 0.5).max(self.metrics.padding);
        if self.mode == FilesViewMode::Flow {
            self.update_flow_layout();
            return;
        }
        let rows = self.entries.len().div_ceil(self.columns);
        self.content_height = self.metrics.padding * 2.0
            + rows as f32 * self.metrics.tile_height
            + rows.saturating_sub(1) as f32 * self.metrics.gap;
    }

    fn update_flow_layout(&mut self) {
        let files = self.shared.files();
        let mut registration = self.thumbnail_registration.borrow_mut();
        let mut current_keys = BTreeSet::new();
        let mut column_bottoms = vec![self.metrics.padding; self.columns];
        self.flow_tiles.clear();
        self.max_flow_tile_height = 0.0;
        for entry in &self.entries {
            let preview_height = if let Some(request) =
                files.thumbnail_request_for_entry(entry, ThumbnailBucket::Large)
            {
                let key = request.key;
                current_keys.insert(key.clone());
                if !registration.flow_aspect_ratios.contains_key(&key) {
                    let bitmap = files.thumbnail_cache.ready(&key).or_else(|| {
                        let mut fallback = key.clone();
                        fallback.bucket = ThumbnailBucket::Medium;
                        files.thumbnail_cache.ready(&fallback)
                    });
                    if let Some(bitmap) = bitmap
                        && bitmap.width > 0
                        && bitmap.height > 0
                    {
                        registration
                            .flow_aspect_ratios
                            .insert(key.clone(), bitmap.height as f32 / bitmap.width as f32);
                    }
                }
                let ratio = registration
                    .flow_aspect_ratios
                    .get(&key)
                    .copied()
                    .unwrap_or(1.0);
                // Extreme panoramas/portraits stay bounded; the image itself is fitted without cropping.
                (self.tile_width - 16.0).max(1.0) * ratio.clamp(0.5, 1.75)
            } else {
                80.0
            };
            let height = preview_height + self.metrics.label_height + 20.0;
            let column = column_bottoms
                .iter()
                .enumerate()
                .min_by(|(_, left), (_, right)| left.total_cmp(right))
                .map(|(column, _)| column)
                .unwrap_or(0);
            self.flow_tiles.push(Rect::new(
                self.grid_start_x + column as f32 * (self.tile_width + self.metrics.gap),
                column_bottoms[column],
                self.tile_width,
                height,
            ));
            column_bottoms[column] += height + self.metrics.gap;
            self.max_flow_tile_height = self.max_flow_tile_height.max(height);
        }
        registration
            .flow_aspect_ratios
            .retain(|key, _| current_keys.contains(key));
        self.content_height = if self.entries.is_empty() {
            self.metrics.padding * 2.0
        } else {
            column_bottoms.into_iter().fold(0.0_f32, f32::max) - self.metrics.gap
                + self.metrics.padding
        };
    }

    /// Shortest-column placement produces monotonic tile tops. Binary-search a bounded span,
    /// including tall cards which start above the viewport, instead of scanning the folder.
    fn flow_range(&self, top: f32, bottom: f32) -> std::ops::Range<usize> {
        let start = self
            .flow_tiles
            .partition_point(|tile| tile.y() < top - self.max_flow_tile_height);
        let end = self.flow_tiles.partition_point(|tile| tile.y() <= bottom);
        start..end
    }

    fn flow_tile_visible(&self, index: usize) -> bool {
        let viewport = self.scroll_state.viewport_size();
        let offset = self.scroll_state.current_offset().y;
        let tile = self.flow_tiles[index];
        viewport.height <= 0.0 || (tile.max_y() >= offset && tile.y() <= offset + viewport.height)
    }

    fn flow_keyboard_target(&self, current: usize, key: &str) -> usize {
        let tile = self.flow_tiles[current];
        let center_y = tile.y() + tile.height() * 0.5;
        let column_step = self.tile_width + self.metrics.gap;
        let target_x = match key {
            "ArrowLeft" => tile.x() - column_step,
            "ArrowRight" => tile.x() + column_step,
            _ => tile.x(),
        };
        let target_y = match key {
            "PageUp" => center_y - self.scroll_state.viewport_size().height,
            "PageDown" => center_y + self.scroll_state.viewport_size().height,
            _ => center_y,
        };
        self.flow_tiles
            .iter()
            .enumerate()
            .filter(|(index, candidate)| {
                *index != current
                    && (candidate.x() - target_x).abs() < 0.5
                    && match key {
                        "ArrowUp" | "PageUp" => candidate.y() < tile.y(),
                        "ArrowDown" | "PageDown" => candidate.y() > tile.y(),
                        _ => true,
                    }
            })
            .min_by(|(_, left), (_, right)| {
                let distance = |rect: &Rect| (rect.y() + rect.height() * 0.5 - target_y).abs();
                distance(left).total_cmp(&distance(right))
            })
            .map(|(index, _)| index)
            .unwrap_or(current)
    }

    fn tile_rect(&self, bounds: Rect, index: usize) -> Rect {
        if self.mode == FilesViewMode::Flow {
            let tile = self.flow_tiles[index];
            return Rect::new(
                bounds.x() + tile.x(),
                bounds.y() + tile.y(),
                tile.width(),
                tile.height(),
            );
        }
        let row = index / self.columns;
        let column = index % self.columns;
        Rect::new(
            bounds.x() + self.grid_start_x + column as f32 * (self.tile_width + self.metrics.gap),
            bounds.y()
                + self.metrics.padding
                + row as f32 * (self.metrics.tile_height + self.metrics.gap),
            self.tile_width,
            self.metrics.tile_height,
        )
    }

    fn icon_rect(&self, tile: Rect) -> Rect {
        if self.mode == FilesViewMode::Flow {
            let frame = self.thumbnail_rect(tile);
            let side = self
                .metrics
                .icon_side
                .min(frame.width())
                .min(frame.height());
            return Rect::new(
                frame.x() + (frame.width() - side) * 0.5,
                frame.y() + (frame.height() - side) * 0.5,
                side,
                side,
            );
        }
        Rect::new(
            tile.x() + (tile.width() - self.metrics.icon_side) * 0.5,
            tile.y() + 7.0,
            self.metrics.icon_side,
            self.metrics.icon_side,
        )
    }

    fn thumbnail_rect(&self, tile: Rect) -> Rect {
        if self.mode == FilesViewMode::Flow {
            Rect::new(
                tile.x() + 8.0,
                tile.y() + 8.0,
                (tile.width() - 16.0).max(1.0),
                (tile.height() - self.metrics.label_height - 20.0).max(1.0),
            )
        } else {
            self.icon_rect(tile)
        }
    }

    fn label_rect(&self, tile: Rect) -> Rect {
        Rect::new(
            tile.x() + 4.0,
            tile.max_y() - self.metrics.label_height - 4.0,
            (tile.width() - 8.0).max(0.0),
            self.metrics.label_height,
        )
    }

    fn checkbox_rect(&self, tile: Rect, theme: &DefaultTheme) -> Rect {
        let side = theme.metrics.checkbox_indicator_size.min(18.0);
        Rect::new(tile.x() + 5.0, tile.y() + 5.0, side, side)
    }

    fn index_at_position(&self, bounds: Rect, position: Point) -> Option<usize> {
        if self.mode == FilesViewMode::Flow {
            return self
                .flow_range(position.y - bounds.y(), position.y - bounds.y())
                .find(|&index| self.tile_rect(bounds, index).contains(position));
        }
        let x = position.x - bounds.x() - self.grid_start_x;
        let y = position.y - bounds.y() - self.metrics.padding;
        if x < 0.0 || y < 0.0 {
            return None;
        }
        let column = (x / (self.tile_width + self.metrics.gap)).floor() as usize;
        let row = (y / (self.metrics.tile_height + self.metrics.gap)).floor() as usize;
        if column >= self.columns
            || x - column as f32 * (self.tile_width + self.metrics.gap) > self.tile_width
            || y - row as f32 * (self.metrics.tile_height + self.metrics.gap)
                > self.metrics.tile_height
        {
            return None;
        }
        let index = row.saturating_mul(self.columns).saturating_add(column);
        (index < self.entries.len()).then_some(index)
    }

    fn visible_indices(&self) -> std::ops::Range<usize> {
        if self.entries.is_empty() {
            return 0..0;
        }
        let viewport = self.scroll_state.viewport_size();
        if viewport.height <= 0.0 {
            return 0..self.entries.len();
        }
        let offset = self.scroll_state.current_offset().y;
        if self.mode == FilesViewMode::Flow {
            return self.flow_range(offset, offset + viewport.height);
        }
        let row_step = self.metrics.tile_height + self.metrics.gap;
        let first_row = ((offset - self.metrics.padding).max(0.0) / row_step).floor() as usize;
        let last_row = (((offset + viewport.height - self.metrics.padding).max(0.0) / row_step)
            .ceil() as usize)
            .saturating_add(1);
        let start = first_row
            .saturating_mul(self.columns)
            .min(self.entries.len());
        let end = last_row
            .saturating_mul(self.columns)
            .min(self.entries.len());
        start..end
    }

    fn thumbnail_request_range(&self) -> std::ops::Range<usize> {
        let visible = self.visible_indices();
        visible.start.saturating_sub(self.columns)
            ..visible
                .end
                .saturating_add(self.columns)
                .min(self.entries.len())
    }

    fn schedule_visible_thumbnails(&mut self) {
        let Some(bucket) = file_thumbnail_bucket(self.mode) else {
            self.last_thumbnail_keys.clear();
            return;
        };
        let range = self.thumbnail_request_range();
        let keys = {
            let files = self.shared.files();
            self.entries
                .get(range.clone())
                .into_iter()
                .flatten()
                .filter_map(|entry| files.thumbnail_request_for_entry(entry, bucket))
                .map(|request| request.key)
                .collect::<Vec<_>>()
        };
        if keys == self.last_thumbnail_keys {
            return;
        }
        self.last_thumbnail_keys = keys;
        let waker = { self.shared.borrow().waker.clone() };
        self.shared
            .files_mut_unpublished()
            .request_visible_thumbnails(&self.entries, range, bucket, waker);
    }

    fn row_activation_kind(&mut self, index: usize) -> VirtualTableRowActivationKind {
        let now = Instant::now();
        let double_click = self.last_click.take().is_some_and(|(previous, instant)| {
            previous == index && now.duration_since(instant) <= FILE_ICON_GRID_DOUBLE_CLICK_WINDOW
        });
        if double_click {
            VirtualTableRowActivationKind::Double
        } else {
            self.last_click = Some((index, now));
            VirtualTableRowActivationKind::Single
        }
    }

    fn offset_to_reveal(&self, index: usize) -> f32 {
        let tile = self.tile_rect(Rect::new(0.0, 0.0, 0.0, 0.0), index);
        let top = tile.y();
        let bottom = tile.max_y();
        let viewport = self.scroll_state.viewport_size();
        let current = self.scroll_state.current_offset().y;
        if top < current {
            top
        } else if bottom > current + viewport.height {
            (bottom - viewport.height).max(0.0)
        } else {
            current
        }
    }

    fn maybe_request_more(&self, predicted_scroll_delta: f32) {
        if self.entries.len() >= self.total_count {
            return;
        }
        let viewport = self.scroll_state.viewport_size();
        let offset = (self.scroll_state.current_offset().y + predicted_scroll_delta).max(0.0);
        let remaining = (self.content_height - viewport.height - offset).max(0.0);
        if remaining <= (self.metrics.tile_height + self.metrics.gap) * 3.0 {
            let waker = { self.shared.borrow().waker.clone() };
            self.shared.files_mut().request_more_entries(waker);
        }
    }

    fn select_from_keyboard(&mut self, index: usize, ctx: &mut EventCtx) {
        self.shared.files_mut().select_entry(index);
        // Split panes probe several widths during measure. Resolve scrolling during arrange,
        // after the final viewport metrics, so a temporary wide probe cannot clamp it back to zero.
        self.pending_reveal = Some(index);
        ctx.request_arrange();
        ctx.request_hit_test();
        ctx.request_paint();
        ctx.request_semantics();
    }

    fn entry_description(&self, index: usize) -> String {
        let Some(entry) = self.entries.get(index) else {
            return String::new();
        };
        let files = self.shared.files();
        let kind = if entry.is_dir {
            "Folder"
        } else if entry.is_link {
            "Link"
        } else {
            "File"
        };
        let mut description = format!(
            "{kind}, {} {}. Item {} of {}",
            files.source.path_label(),
            entry.path,
            index + 1,
            self.total_count
        );
        if entry.is_dir {
            description.push_str(". Single click selects; double click opens the folder");
        }
        if files.entry_marked(index) {
            description.push_str(". Marked for a batch action");
        }
        if files.source == FilesSourceKind::Sifs {
            let placement = file_row_placement_badge(entry, &files);
            description.push_str(". Placement: ");
            description.push_str(&placement.label);
            if let Some((current, desired)) = placement.replicas {
                description.push_str(&format!("; {current}/{desired} replicas"));
            }
        }
        description
    }

    fn paint_thumbnail(
        &self,
        ctx: &mut PaintCtx,
        visible_slot: u64,
        key: &ThumbnailRequestKey,
        tile: Rect,
        bitmap: &ThumbnailBitmap,
        theme: &DefaultTheme,
    ) -> bool {
        let frame = self.thumbnail_rect(tile);
        paint_file_thumbnail(
            ctx,
            &self.thumbnail_registration,
            visible_slot,
            key,
            frame,
            bitmap,
            theme,
        )
    }
}

fn paint_file_thumbnail(
    ctx: &mut PaintCtx,
    registration_pool: &Rc<RefCell<ThumbnailRegistrationPool>>,
    visible_slot: u64,
    key: &ThumbnailRequestKey,
    frame: Rect,
    bitmap: &ThumbnailBitmap,
    theme: &DefaultTheme,
) -> bool {
    let (handle, binding_changed) = {
        let mut registration = registration_pool.borrow_mut();
        let handle = *registration
            .handles
            .entry(visible_slot)
            .or_insert_with(|| ctx.widget_image_handle(10_000_u64.saturating_add(visible_slot)));
        let binding_changed = registration.bindings.get(&visible_slot) != Some(key);
        (handle, binding_changed)
    };
    if binding_changed || !ctx.image_registered(handle) {
        let Ok(image) =
            RegisteredImage::from_rgba8(bitmap.width, bitmap.height, bitmap.rgba.as_ref().to_vec())
        else {
            return false;
        };
        ctx.register_image(handle, image);
        registration_pool
            .borrow_mut()
            .bindings
            .insert(visible_slot, key.clone());
    }
    if !ctx.image_registered(handle) || bitmap.width == 0 || bitmap.height == 0 {
        return false;
    }
    widgets::fill_round_rect(ctx, frame, theme.palette.control, 5.0);
    let source = Size::new(bitmap.width as f32, bitmap.height as f32);
    let scale = (frame.width() / source.width)
        .min(frame.height() / source.height)
        .max(0.0);
    let image_size = Size::new(source.width * scale, source.height * scale);
    let image_rect = Rect::new(
        frame.x() + (frame.width() - image_size.width) * 0.5,
        frame.y() + (frame.height() - image_size.height) * 0.5,
        image_size.width,
        image_size.height,
    );
    ctx.push_clip(sui::Path::rounded_rect(frame, 5.0));
    ctx.draw_image_source(image_rect, ImageSource::new(handle));
    ctx.pop_clip();
    true
}

impl Widget for FileIconGrid {
    fn event(&mut self, ctx: &mut EventCtx, event: &Event) {
        if ctx.phase() == EventPhase::Capture {
            return;
        }
        let bounds = ctx.bounds();
        match event {
            Event::Pointer(pointer) if pointer.kind == PointerEventKind::Move => {
                let hovered = self.index_at_position(bounds, pointer.position);
                if self.hovered != hovered {
                    self.hovered = hovered;
                    ctx.request_paint();
                    ctx.request_semantics();
                }
                self.maybe_request_more(0.0);
            }
            Event::Pointer(pointer) if pointer.kind == PointerEventKind::Scroll => {
                let delta = match pointer.scroll_delta {
                    Some(ScrollDelta::Lines(delta)) => -delta.y * 40.0,
                    Some(ScrollDelta::Pixels(delta)) => -delta.y,
                    None => -pointer.delta.y,
                };
                self.maybe_request_more(delta);
            }
            Event::Pointer(pointer)
                if pointer.kind == PointerEventKind::Down
                    && pointer.button == Some(PointerButton::Primary) =>
            {
                if let Some(index) = self.index_at_position(bounds, pointer.position) {
                    let mark = self
                        .checkbox_rect(self.tile_rect(bounds, index), &self.shared.theme())
                        .contains(pointer.position);
                    self.pressed = Some((index, mark));
                    self.hovered = Some(index);
                    ctx.request_focus();
                    ctx.request_pointer_capture(pointer.pointer_id);
                    ctx.request_paint();
                    ctx.set_handled();
                }
            }
            Event::Pointer(pointer)
                if pointer.kind == PointerEventKind::Up
                    && pointer.button == Some(PointerButton::Primary) =>
            {
                let hovered = self.index_at_position(bounds, pointer.position);
                if let Some((index, mark)) = self.pressed.take() {
                    if hovered == Some(index) {
                        if mark
                            && self
                                .checkbox_rect(self.tile_rect(bounds, index), &self.shared.theme())
                                .contains(pointer.position)
                        {
                            self.shared.files_mut().toggle_marked_entry(index);
                            self.last_click = None;
                        } else {
                            let activation = self.row_activation_kind(index);
                            self.shared.files_mut().click_row(index, activation);
                        }
                    }
                    self.hovered = hovered;
                    ctx.release_pointer_capture(pointer.pointer_id);
                    ctx.request_paint();
                    ctx.request_semantics();
                    ctx.set_handled();
                }
            }
            Event::Pointer(pointer)
                if pointer.kind == PointerEventKind::Down
                    && pointer.button == Some(PointerButton::Secondary) =>
            {
                if let Some(index) = self.index_at_position(bounds, pointer.position) {
                    self.context_target.set(FileContextMenuTarget::Selection);
                    self.shared.files_mut().select_context_entry(index);
                } else if bounds.contains(pointer.position) {
                    self.context_target
                        .set(FileContextMenuTarget::CurrentLocation);
                }
                ctx.request_paint();
                ctx.request_semantics();
            }
            Event::Pointer(pointer) if pointer.kind == PointerEventKind::Leave => {
                if self.hovered.take().is_some() {
                    ctx.request_paint();
                    ctx.request_semantics();
                }
            }
            Event::Pointer(pointer) if pointer.kind == PointerEventKind::Cancel => {
                if self.pressed.take().is_some() {
                    ctx.release_pointer_capture(pointer.pointer_id);
                    ctx.request_paint();
                    ctx.set_handled();
                }
            }
            Event::Keyboard(key) if ctx.is_focused() && key.state == KeyState::Pressed => {
                if self.entries.is_empty() {
                    return;
                }
                let current = self
                    .shared
                    .files()
                    .selected
                    .filter(|index| *index < self.entries.len())
                    .unwrap_or(0);
                let next = match key.key.as_str() {
                    direction @ ("ArrowLeft" | "ArrowRight" | "ArrowUp" | "ArrowDown"
                    | "PageUp" | "PageDown")
                        if self.mode == FilesViewMode::Flow =>
                    {
                        Some(self.flow_keyboard_target(current, direction))
                    }
                    "ArrowLeft" => Some(current.saturating_sub(1)),
                    "ArrowRight" => Some((current + 1).min(self.entries.len() - 1)),
                    "ArrowUp" => Some(current.saturating_sub(self.columns)),
                    "ArrowDown" => Some((current + self.columns).min(self.entries.len() - 1)),
                    "PageUp" => Some(
                        current.saturating_sub(
                            self.columns
                                * (self.scroll_state.viewport_size().height
                                    / (self.metrics.tile_height + self.metrics.gap))
                                    .floor()
                                    .max(1.0) as usize,
                        ),
                    ),
                    "PageDown" => Some(
                        (current
                            + self.columns
                                * (self.scroll_state.viewport_size().height
                                    / (self.metrics.tile_height + self.metrics.gap))
                                    .floor()
                                    .max(1.0) as usize)
                            .min(self.entries.len() - 1),
                    ),
                    "Home" => Some(0),
                    "End" => Some(self.entries.len() - 1),
                    "Enter" => {
                        self.shared.files_mut().activate_row(current);
                        ctx.request_measure();
                        ctx.request_paint();
                        ctx.request_semantics();
                        ctx.set_handled();
                        return;
                    }
                    " " => {
                        self.shared.files_mut().toggle_marked_entry(current);
                        ctx.request_paint();
                        ctx.request_semantics();
                        ctx.set_handled();
                        return;
                    }
                    _ => None,
                };
                if let Some(next) = next {
                    self.select_from_keyboard(next, ctx);
                    self.maybe_request_more(0.0);
                    ctx.set_handled();
                }
            }
            Event::Semantics(semantics) => {
                let target = self.entries.iter().enumerate().find_map(|(index, entry)| {
                    (file_icon_semantics_id(ctx.widget_id(), file_entry_key(entry))
                        == semantics.target)
                        .then_some(index)
                });
                if let Some(index) = target {
                    match semantics.action {
                        SemanticsActionRequest::Activate => {
                            self.shared.files_mut().activate_row(index);
                            ctx.request_measure();
                            ctx.request_paint();
                            ctx.request_semantics();
                            ctx.set_handled();
                        }
                        SemanticsActionRequest::Focus => {
                            self.select_from_keyboard(index, ctx);
                            ctx.request_focus();
                            ctx.set_handled();
                        }
                        _ => {}
                    }
                }
            }
            _ => {}
        }
    }

    fn measure(&mut self, ctx: &mut MeasureCtx, constraints: Constraints) -> Size {
        let _ = ctx.observe(&self.thumbnail_revision);
        let desired_width = if constraints.max.width.is_finite() {
            constraints.max.width
        } else {
            self.metrics.tile_width * 4.0 + self.metrics.gap * 3.0 + self.metrics.padding * 2.0
        };
        let width = constraints.clamp(Size::new(desired_width, 0.0)).width;
        self.update_layout(width);
        constraints.clamp(Size::new(width, self.content_height.max(1.0)))
    }

    fn arrange(&mut self, ctx: &mut ArrangeCtx, _bounds: Rect) {
        if let Some(index) = self
            .pending_reveal
            .take()
            .filter(|index| *index < self.entries.len())
        {
            let next = self.offset_to_reveal(index);
            if self.scroll_state.set_offset(Vector::new(0.0, next)) {
                ctx.request_arrange();
                ctx.request_paint();
                ctx.request_semantics();
            }
            self.maybe_request_more(0.0);
        }
        self.schedule_visible_thumbnails();
    }

    fn paint(&self, ctx: &mut PaintCtx) {
        let theme = self.shared.theme();
        let pal = palette(&self.shared);
        let files = self.shared.files();
        let bounds = ctx.bounds();
        let visible = self.visible_indices();
        for (visible_slot, index) in visible.clone().enumerate() {
            if self.mode == FilesViewMode::Flow && !self.flow_tile_visible(index) {
                continue;
            }
            let Some(entry) = self.entries.get(index) else {
                continue;
            };
            let tile = self.tile_rect(bounds, index);
            let active = files.selected == Some(index);
            let marked = files.entry_marked(index);
            let hovered = self.hovered == Some(index);
            let pressed = self.pressed.is_some_and(|(pressed, _)| pressed == index);
            if active || marked {
                widgets::fill_round_rect(
                    ctx,
                    tile.inflate(-2.0, -2.0),
                    theme.palette.selection,
                    6.0,
                );
            } else if hovered || pressed {
                widgets::fill_round_rect(
                    ctx,
                    tile.inflate(-2.0, -2.0),
                    theme.palette.control_hover,
                    6.0,
                );
            } else if self.mode == FilesViewMode::Flow {
                widgets::fill_round_rect(ctx, tile.inflate(-2.0, -2.0), theme.palette.control, 8.0);
            }

            let thumbnail = file_cached_thumbnail_buckets(self.mode)
                .into_iter()
                .flatten()
                .find_map(|bucket| {
                    let request = files.thumbnail_request_for_entry(entry, bucket)?;
                    let bitmap = files.thumbnail_cache.ready(&request.key)?;
                    Some((request.key, bitmap))
                });
            let painted_thumbnail = thumbnail.is_some_and(|(key, thumbnail)| {
                self.paint_thumbnail(ctx, visible_slot as u64, &key, tile, &thumbnail, &theme)
            });
            if !painted_thumbnail {
                if self.mode == FilesViewMode::Flow {
                    widgets::fill_round_rect(
                        ctx,
                        self.thumbnail_rect(tile),
                        theme.palette.control,
                        5.0,
                    );
                }
                let icon_color = if entry.is_dir || entry.is_link || active {
                    pal.accent
                } else {
                    pal.text_faint
                };
                draw_glyph(ctx, entry_icon(entry), self.icon_rect(tile), icon_color);
            }

            let label_rect = self.label_rect(tile);
            let average_char_width = (theme.text.sm.size * 0.55).max(5.0);
            let display =
                display_name_for_width(&entry.name, label_rect.width() * 1.8, average_char_width);
            let text_token = if self.mode == FilesViewMode::SmallIcons {
                theme.text.xs
            } else {
                theme.text.sm
            };
            paint_text_block(
                ctx,
                &theme,
                label_rect,
                &display,
                TextBlockPaint::new()
                    .text_token(text_token)
                    .color(if active { pal.text } else { pal.text_muted })
                    .weight(FontWeight::MEDIUM)
                    .wrap(TextWrap::Character)
                    .alignment(TextAlign::Center)
                    .padding(Insets {
                        left: 0.0,
                        top: 1.0,
                        right: 0.0,
                        bottom: 1.0,
                    }),
            );

            if marked || hovered {
                paint_checkbox_indicator(
                    ctx,
                    &theme,
                    self.checkbox_rect(tile, &theme),
                    CheckboxIndicatorState::new(marked).hovered(hovered),
                );
            }
        }
    }

    fn semantics(&self, ctx: &mut SemanticsCtx) {
        let mut root = SemanticsNode::new(ctx.widget_id(), SemanticsRole::List, ctx.bounds());
        root.name = Some(
            if self.mode == FilesViewMode::Flow {
                "files-flow"
            } else {
                "files-icons"
            }
            .to_string(),
        );
        root.description = Some(format!(
            "{} view; {} loaded of {} items",
            FilesViewMode::OPTIONS[self.mode.selected_index()],
            self.entries.len(),
            self.total_count
        ));
        root.value = Some(SemanticsValue::Text(format!("{} items", self.total_count)));
        root.state.focused = ctx.is_focused();
        root.actions = vec![SemanticsAction::Focus];
        ctx.push(root);

        let files = self.shared.files();
        for index in self.visible_indices() {
            if self.mode == FilesViewMode::Flow && !self.flow_tile_visible(index) {
                continue;
            }
            let Some(entry) = self.entries.get(index) else {
                continue;
            };
            let mut node = SemanticsNode::new(
                file_icon_semantics_id(ctx.widget_id(), file_entry_key(entry)),
                SemanticsRole::ListItem,
                self.tile_rect(ctx.bounds(), index),
            );
            node.parent = Some(ctx.widget_id());
            node.name = Some(entry.name.clone());
            node.description = Some(self.entry_description(index));
            node.state.selected = files.selected == Some(index);
            node.state.checked = files
                .entry_marked(index)
                .then_some(ToggleState::Checked)
                .or(Some(ToggleState::Unchecked));
            node.state.hovered = self.hovered == Some(index);
            node.actions = vec![SemanticsAction::Focus, SemanticsAction::Activate];
            ctx.push(node);
        }
    }

    fn accepts_focus(&self) -> bool {
        true
    }

    fn focus_changed(&mut self, ctx: &mut EventCtx, _focused: bool) {
        ctx.request_paint();
        ctx.request_semantics();
    }
}

fn file_icon_semantics_id(parent: WidgetId, entry_key: u64) -> WidgetId {
    const TAG: u64 = 9_u64 << 50;
    const LOW_MASK: u64 = (1_u64 << 50) - 1;
    let mixed = entry_key
        .wrapping_add(0x9e37_79b9_7f4a_7c15)
        .wrapping_add(parent.get().rotate_left(19));
    let mixed = (mixed ^ (mixed >> 30)).wrapping_mul(0xbf58_476d_1ce4_e5b9);
    let mixed = (mixed ^ (mixed >> 27)).wrapping_mul(0x94d0_49bb_1331_11eb);
    WidgetId::new(TAG | ((mixed ^ (mixed >> 31)) & LOW_MASK))
}

/// A centered empty/error placeholder themed off the chrome palette.
/// What Files needs the daemon for, shown on the offline panel.
pub(crate) const FILES_OFFLINE_SUMMARY: &str =
    "SIFS browsing runs through the daemon. Local files stay available.";
pub(crate) const BROWSE_LOCAL_FILES_LABEL: &str = "Browse local files";
pub(crate) const SIFS_OFFLINE_STATUS: &str = "SIFS offline";
pub(crate) const SIFS_OFFLINE_INSPECTOR_NOTE: &str = "Details appear here once SIFS is connected.";

/// SIFS is selected but the daemon that serves it is unreachable.
fn sifs_daemon_offline(shared: &Shared) -> bool {
    shared.files().source == FilesSourceKind::Sifs && !shared.daemon_availability().is_available()
}

fn sifs_offline_panel(shared: &Shared, reader: &ThemeReader) -> impl Widget + use<> {
    let browse = shared.clone();
    DaemonOfflinePanel::new(shared, reader, "Files offline", FILES_OFFLINE_SUMMARY)
        .action(move || {
            let shared = browse.clone();
            sui::Button::new(BROWSE_LOCAL_FILES_LABEL)
                .icon(IconGlyph::Folder)
                .appearance(sui::ButtonAppearance::Tonal)
                .tone(SemanticTone::Neutral)
                .on_press(move || {
                    let waker = { shared.borrow().waker.clone() };
                    shared
                        .files_mut()
                        .switch_source(FilesSourceKind::Local, waker);
                })
        })
        .build()
}

fn centered_note(
    reader: &ThemeReader,
    icon: IconGlyph,
    title: impl Into<String>,
    subtitle: impl Into<String>,
) -> EmptyState {
    EmptyState::new(title, subtitle)
        .icon(icon)
        .theme_when(clone_reader(reader))
}

fn request_files_overlay_rebuild(ctx: &mut EventCtx) {
    ctx.request_measure();
    ctx.request_paint();
    ctx.request_semantics();
    ctx.request_hit_test();
}

fn open_settings_section(shared: &Shared, section: SettingsSection) {
    if shared.is_ready() {
        shared.settings_mut().open(section);
    }
    shared.set_active_tab(Tab::Settings);
}

fn sifs_health_has_attention(health: &SifsHealthSummary) -> bool {
    health.pending_repair_count > 0 || health.failed_namespace_job_count > 0
}

fn sifs_health_has_activity(health: &SifsHealthSummary) -> bool {
    health.pending_write_count > 0 || health.pending_namespace_job_count > 0
}

fn sifs_health_status_detail(health: &SifsHealthSummary) -> String {
    let mut parts = Vec::new();

    if health.pending_repair_count > 0 {
        parts.push(format!(
            "{} {}",
            health.pending_repair_count,
            if health.pending_repair_count == 1 {
                "repair"
            } else {
                "repairs"
            }
        ));
    }
    if health.failed_namespace_job_count > 0 {
        parts.push(format!(
            "{} failed namespace {}",
            health.failed_namespace_job_count,
            if health.failed_namespace_job_count == 1 {
                "job"
            } else {
                "jobs"
            }
        ));
    }
    if health.pending_write_count > 0 {
        parts.push(format!(
            "{} pending {}",
            health.pending_write_count,
            if health.pending_write_count == 1 {
                "write"
            } else {
                "writes"
            }
        ));
    }
    if health.pending_namespace_job_count > 0 {
        parts.push(format!(
            "{} namespace {}",
            health.pending_namespace_job_count,
            if health.pending_namespace_job_count == 1 {
                "job"
            } else {
                "jobs"
            }
        ));
    }
    if parts.is_empty() {
        format!(
            "DFS healthy; {} objects, {} shards",
            health.object_count, health.metadata_shard_count
        )
    } else {
        format!("DFS {}", parts.join(", "))
    }
}

fn sifs_health_error_status_detail(error: &str) -> String {
    let detail = error.split_whitespace().collect::<Vec<_>>().join(" ");
    if detail.is_empty() {
        "DFS health unavailable".to_string()
    } else {
        format!("DFS health unavailable: {detail}")
    }
}

#[cfg(test)]
fn sifs_health_status_summary(health: &SifsHealthSummary) -> String {
    if sifs_health_has_attention(health) {
        return "Needs attention".to_string();
    }
    if sifs_health_has_activity(health) {
        return "Syncing".to_string();
    }
    "Healthy".to_string()
}

#[cfg(test)]
fn sifs_health_error_status_summary(_error: &str) -> String {
    "Health unavailable; open Connection or Cluster".to_string()
}

fn files_source_status(files: &FilesState) -> &'static str {
    match files.source {
        FilesSourceKind::Sifs if files.error.is_some() => "SIFS unavailable",
        FilesSourceKind::Sifs if files.loading => "Loading SIFS",
        FilesSourceKind::Sifs if files.sifs_health_error.is_some() => "SIFS unknown",
        FilesSourceKind::Sifs
            if files
                .sifs_health
                .as_ref()
                .is_some_and(sifs_health_has_attention) =>
        {
            "SIFS degraded"
        }
        FilesSourceKind::Sifs
            if files
                .sifs_health
                .as_ref()
                .is_some_and(sifs_health_has_activity) =>
        {
            "SIFS syncing"
        }
        FilesSourceKind::Sifs if files_sifs_daemon_is_remote(files) => "Remote SIFS",
        FilesSourceKind::Sifs if files.clustered => "SIFS online",
        FilesSourceKind::Sifs => "Local SIFS",
        FilesSourceKind::Local if files.error.is_some() => "Local unavailable",
        FilesSourceKind::Local if files.loading => "Loading local",
        FilesSourceKind::Local => "Local files",
    }
}

fn files_source_tone(files: &FilesState) -> SemanticTone {
    match files.source {
        FilesSourceKind::Sifs if files.error.is_some() => SemanticTone::Warning,
        FilesSourceKind::Sifs if files.loading => SemanticTone::Accent,
        FilesSourceKind::Sifs if files.sifs_health_error.is_some() => SemanticTone::Warning,
        FilesSourceKind::Sifs
            if files
                .sifs_health
                .as_ref()
                .is_some_and(sifs_health_has_attention) =>
        {
            SemanticTone::Warning
        }
        FilesSourceKind::Sifs
            if files
                .sifs_health
                .as_ref()
                .is_some_and(sifs_health_has_activity) =>
        {
            SemanticTone::Accent
        }
        FilesSourceKind::Sifs if files.clustered || files_sifs_daemon_is_remote(files) => {
            SemanticTone::Success
        }
        FilesSourceKind::Local if files.error.is_some() => SemanticTone::Warning,
        FilesSourceKind::Local if files.loading => SemanticTone::Accent,
        FilesSourceKind::Local => SemanticTone::Success,
        FilesSourceKind::Sifs => SemanticTone::Neutral,
    }
}

fn files_sifs_connection_detail(files: &FilesState) -> Option<String> {
    if files.source != FilesSourceKind::Sifs {
        return None;
    }
    files.daemon_address.as_deref().map(|address| {
        let label = if daemon_address_is_remote(address) {
            "remote daemon"
        } else {
            "daemon"
        };
        format!("{label} {}", middle_short(address, 44))
    })
}

fn files_sifs_daemon_is_remote(files: &FilesState) -> bool {
    files
        .daemon_address
        .as_deref()
        .is_some_and(daemon_address_is_remote)
}

fn daemon_address_is_remote(address: &str) -> bool {
    let host = daemon_address_host(address);
    !matches!(host, "" | "localhost" | "::1") && !host.starts_with("127.") && host != "0.0.0.0"
}

fn daemon_address_host(address: &str) -> &str {
    let trimmed = address.trim();
    if let Some(rest) = trimmed.strip_prefix('[')
        && let Some((host, _)) = rest.split_once(']')
    {
        return host;
    }
    trimmed
        .rsplit_once(':')
        .map(|(host, _)| host.trim_matches(['[', ']']))
        .unwrap_or(trimmed)
}

fn files_entry_count_status(files: &FilesState) -> String {
    if files.loading {
        "loading directory".to_string()
    } else if files.error.is_some() {
        "listing unavailable".to_string()
    } else if files.entries_total_count > files.entries.len() {
        format!(
            "{}/{} entries loaded",
            files.entries.len(),
            files.entries_total_count
        )
    } else {
        plural(files.entries.len(), "entry")
    }
}

fn files_selection_status(files: &FilesState) -> String {
    let marked = files.marked_count();
    if marked > 0 {
        return if marked == 1 {
            "1 entry selected".to_string()
        } else {
            format!("{marked} entries selected")
        };
    }
    files
        .selected_entry()
        .map(|entry| format!("selected {}", entry.path))
        .unwrap_or_else(|| "no selection".to_string())
}

fn files_status_bar_selection(files: &FilesState) -> String {
    let marked = files.marked_count();
    if marked > 0 {
        return if marked == 1 {
            "1 selected".to_string()
        } else {
            format!("{marked} selected")
        };
    }
    files
        .selected_entry()
        .map(|entry| middle_short(&entry.name, 34))
        .unwrap_or_else(|| "no selection".to_string())
}

fn files_task_status(files: &FilesState) -> String {
    if files.external_file_hovered {
        return "drop to import".to_string();
    }
    if files.picker_lane.is_pending() {
        return "picker open".to_string();
    }
    if !files.pending_import_request_ids.is_empty() {
        return "preparing import".to_string();
    }
    if files.picker_error.is_some() {
        return "import needs attention".to_string();
    }
    let running = files
        .tasks
        .iter()
        .filter(|task| task.state == FilesTaskState::Running)
        .count();
    let cancelling = files
        .tasks
        .iter()
        .filter(|task| task.state == FilesTaskState::CancelRequested)
        .count();
    let failed = files
        .tasks
        .iter()
        .filter(|task| task.state == FilesTaskState::Failed)
        .count();
    let cancelled = files
        .tasks
        .iter()
        .filter(|task| task.state == FilesTaskState::Cancelled)
        .count();
    let completed = files
        .tasks
        .iter()
        .filter(|task| task.state == FilesTaskState::Completed)
        .count();
    if running > 0 {
        if running == 1 {
            "1 task running".to_string()
        } else {
            format!("{running} tasks running")
        }
    } else if cancelling > 0 {
        if cancelling == 1 {
            "1 task cancelling".to_string()
        } else {
            format!("{cancelling} tasks cancelling")
        }
    } else if failed > 0 {
        if failed == 1 {
            "1 task failed".to_string()
        } else {
            format!("{failed} tasks failed")
        }
    } else if cancelled > 0 {
        if cancelled == 1 {
            "1 task cancelled".to_string()
        } else {
            format!("{cancelled} tasks cancelled")
        }
    } else if completed > 0 {
        if completed == 1 {
            "1 task done".to_string()
        } else {
            format!("{completed} tasks done")
        }
    } else {
        "idle".to_string()
    }
}

fn files_active_task_progress(files: &FilesState) -> Option<(usize, u8)> {
    let active = files
        .tasks
        .iter()
        .filter(|task| {
            matches!(
                task.state,
                FilesTaskState::Running | FilesTaskState::CancelRequested
            )
        })
        .collect::<Vec<_>>();
    if active.is_empty() {
        return None;
    }
    let progress = active
        .iter()
        .map(|task| task_progress_fraction(task))
        .sum::<f32>()
        / active.len() as f32;
    Some((
        active.len(),
        (progress.clamp(0.0, 1.0) * 100.0).round() as u8,
    ))
}

fn files_task_badge_label(files: &FilesState) -> String {
    let source = files_source_status(files);
    if let Some((active, progress)) = files_active_task_progress(files) {
        let task_label = if active == 1 { "task" } else { "tasks" };
        return format!("{source} - {active} {task_label} {progress}%");
    }
    let task_status = files_task_status(files);
    if task_status == "idle" {
        source.to_string()
    } else {
        format!("{source} - {task_status}")
    }
}

fn files_task_badge_tone(files: &FilesState) -> SemanticTone {
    let source_tone = files_source_tone(files);
    if source_tone == SemanticTone::Warning
        || files.picker_error.is_some()
        || files
            .tasks
            .iter()
            .any(|task| task.state == FilesTaskState::Failed)
    {
        return SemanticTone::Warning;
    }
    if files.external_file_hovered
        || files.picker_lane.is_pending()
        || !files.pending_import_request_ids.is_empty()
        || files_active_task_progress(files).is_some()
    {
        return SemanticTone::Accent;
    }
    source_tone
}

fn files_tasks_have_finished(tasks: &[FilesTask]) -> bool {
    tasks.iter().any(|task| {
        matches!(
            task.state,
            FilesTaskState::Cancelled | FilesTaskState::Completed | FilesTaskState::Failed
        )
    })
}

fn files_task_queue_summary(tasks: &[FilesTask]) -> String {
    let running = tasks
        .iter()
        .filter(|task| task.state == FilesTaskState::Running)
        .count();
    let cancelling = tasks
        .iter()
        .filter(|task| task.state == FilesTaskState::CancelRequested)
        .count();
    let failed = tasks
        .iter()
        .filter(|task| task.state == FilesTaskState::Failed)
        .count();
    if running > 0 || cancelling > 0 {
        let active = running + cancelling;
        if active == 1 {
            "1 active".to_string()
        } else {
            format!("{active} active")
        }
    } else if failed > 0 {
        if failed == 1 {
            "1 failed".to_string()
        } else {
            format!("{failed} failed")
        }
    } else if tasks.is_empty() {
        "idle".to_string()
    } else if tasks.len() == 1 {
        "1 finished".to_string()
    } else {
        format!("{} finished", tasks.len())
    }
}

fn files_status_summary(files: &FilesState) -> String {
    let mut summary = files_source_status(files).to_string();
    summary.push_str(&format!(
        " | Path {} | {} | {} | {}",
        files.path,
        files_entry_count_status(files),
        files_selection_status(files),
        files_task_status(files),
    ));
    summary
}

fn push_unique_place(
    places: &mut Vec<FilePlace>,
    label: impl Into<String>,
    detail: impl Into<String>,
    source: FilesSourceKind,
    path: impl Into<String>,
    glyph: IconGlyph,
) {
    push_unique_place_with_action(
        places,
        label,
        detail,
        source,
        path,
        glyph,
        FilePlaceAction::OpenPath,
    );
}

fn push_unique_place_with_action(
    places: &mut Vec<FilePlace>,
    label: impl Into<String>,
    detail: impl Into<String>,
    source: FilesSourceKind,
    path: impl Into<String>,
    glyph: IconGlyph,
    action: FilePlaceAction,
) {
    let path = path.into();
    if places
        .iter()
        .any(|place| place.source == source && place.path == path && place.action == action)
    {
        return;
    }
    places.push(FilePlace {
        label: label.into(),
        detail: detail.into(),
        source,
        path,
        glyph,
        action,
    });
}

fn local_home_path() -> Option<String> {
    std::env::var_os("USERPROFILE")
        .or_else(|| std::env::var_os("HOME"))
        .map(PathBuf::from)
        .map(|path| path.to_string_lossy().into_owned())
}

fn compact_local_place_path(path: &str) -> String {
    let display = local_home_path()
        .and_then(|home| {
            let relative = Path::new(path).strip_prefix(&home).ok()?;
            if relative.as_os_str().is_empty() {
                Some("~".to_string())
            } else {
                Some(format!(
                    "~{}{}",
                    std::path::MAIN_SEPARATOR,
                    relative.to_string_lossy()
                ))
            }
        })
        .unwrap_or_else(|| path.to_string());
    middle_short(&display, 30)
}

fn local_root_path(path: &str) -> Option<String> {
    let mut root = PathBuf::new();
    let mut saw_prefix = false;
    for component in Path::new(path).components() {
        match component {
            std::path::Component::Prefix(prefix) => {
                root.push(prefix.as_os_str());
                saw_prefix = true;
            }
            std::path::Component::RootDir => {
                root.push(std::path::MAIN_SEPARATOR.to_string());
                let label = root.to_string_lossy().into_owned();
                return (!label.is_empty()).then_some(display_local_path(label));
            }
            _ => break,
        }
    }
    if saw_prefix {
        let label = root.to_string_lossy().into_owned();
        (!label.is_empty()).then_some(display_local_path(label))
    } else {
        None
    }
}

fn display_local_path(path: String) -> String {
    #[cfg(windows)]
    {
        if let Some(rest) = path.strip_prefix(r"\\?\UNC\") {
            return format!(r"\\{rest}");
        }
        if let Some(rest) = path.strip_prefix(r"\\?\") {
            return rest.to_string();
        }
    }
    path
}

fn local_root_label(path: &str) -> String {
    let trimmed = path.trim_end_matches(['\\', '/']);
    if trimmed.ends_with(':') {
        return trimmed.to_string();
    }
    if path == "/" {
        return "Filesystem".to_string();
    }
    Path::new(trimmed)
        .file_name()
        .map(|name| name.to_string_lossy().into_owned())
        .filter(|label| !label.is_empty())
        .unwrap_or_else(|| trimmed.to_string())
}

fn system_drive_path() -> Option<String> {
    #[cfg(windows)]
    {
        std::env::var_os("SystemDrive").map(|drive| {
            let mut path = drive.to_string_lossy().into_owned();
            if !path.ends_with('\\') && !path.ends_with('/') {
                path.push('\\');
            }
            path
        })
    }
    #[cfg(not(windows))]
    {
        None
    }
}

fn files_places(files: &FilesState) -> Vec<FilePlace> {
    let mut places = Vec::new();
    push_unique_place(
        &mut places,
        "Root",
        "Distributed namespace",
        FilesSourceKind::Sifs,
        "/",
        IconGlyph::Storage,
    );
    push_unique_place(
        &mut places,
        "Services",
        "/services",
        FilesSourceKind::Sifs,
        "/services",
        IconGlyph::Storage,
    );
    push_unique_place(
        &mut places,
        "Users",
        "/users",
        FilesSourceKind::Sifs,
        "/users",
        IconGlyph::Folder,
    );
    if !files.node_id.trim().is_empty() {
        push_unique_place(
            &mut places,
            "This node",
            "Node-local SIFS files",
            FilesSourceKind::Sifs,
            format!("/sinomo/nodes/{}/files", files.node_id),
            IconGlyph::Folder,
        );
    }
    push_unique_place_with_action(
        &mut places,
        "Go to path…",
        "Enter a SIFS path",
        FilesSourceKind::Sifs,
        files.sifs_path.clone(),
        IconGlyph::Search,
        FilePlaceAction::OpenPathPrompt,
    );
    push_unique_place(
        &mut places,
        if files.source == FilesSourceKind::Local {
            "Current folder"
        } else {
            "Last local folder"
        },
        compact_local_place_path(&files.local_path),
        FilesSourceKind::Local,
        files.local_path.clone(),
        IconGlyph::Folder,
    );
    if let Some(home) = local_home_path() {
        push_unique_place(
            &mut places,
            "Home",
            compact_local_place_path(&home),
            FilesSourceKind::Local,
            home,
            IconGlyph::Folder,
        );
    }
    let data_dir = files.data_dir.root().to_string_lossy().into_owned();
    push_unique_place(
        &mut places,
        "Sinomo data",
        compact_local_place_path(&data_dir),
        FilesSourceKind::Local,
        data_dir,
        IconGlyph::Folder,
    );
    if let Some(root) = local_root_path(&files.local_path) {
        push_unique_place(
            &mut places,
            local_root_label(&root),
            root.clone(),
            FilesSourceKind::Local,
            root,
            IconGlyph::Storage,
        );
    }
    if let Some(system_drive) = system_drive_path() {
        push_unique_place(
            &mut places,
            local_root_label(&system_drive),
            system_drive.clone(),
            FilesSourceKind::Local,
            system_drive,
            IconGlyph::Storage,
        );
    }
    push_unique_place_with_action(
        &mut places,
        "Browse…",
        "Drive, share, or mount",
        FilesSourceKind::Local,
        files.local_path.clone(),
        IconGlyph::Search,
        FilePlaceAction::OpenPathPrompt,
    );
    places
}

fn file_place_active_index(files: &FilesState, places: &[FilePlace]) -> Option<usize> {
    places
        .iter()
        .enumerate()
        .filter(|(_, place)| {
            place.action == FilePlaceAction::OpenPath
                && files.source == place.source
                && match place.source {
                    FilesSourceKind::Sifs => dfs_path_contains(&place.path, &files.path),
                    FilesSourceKind::Local => {
                        Path::new(&files.path).starts_with(Path::new(&place.path))
                    }
                }
        })
        .max_by_key(|(_, place)| place.path.len())
        .map(|(index, _)| index)
}

fn open_file_place(shared: &Shared, place: FilePlace, ctx: &mut EventCtx) {
    let waker = { shared.borrow().waker.clone() };
    {
        let mut files = shared.files_mut();
        match place.action {
            FilePlaceAction::OpenPath => files.open_location(place.source, place.path, waker),
            FilePlaceAction::OpenPathPrompt => {
                if files.source != place.source {
                    files.switch_source(place.source, waker);
                }
                files.open_action_prompt(FileActionPromptKind::GoTo);
            }
        }
    }
    request_files_overlay_rebuild(ctx);
}

fn plural(count: usize, singular: &str) -> String {
    if count == 1 {
        format!("1 {singular}")
    } else if singular == "entry" {
        format!("{count} entries")
    } else if singular == "copy" {
        format!("{count} copies")
    } else {
        format!("{count} {singular}s")
    }
}

fn marked_entries_label(count: usize) -> String {
    if count == 1 {
        "1 selected entry".to_string()
    } else {
        format!("{count} selected entries")
    }
}

fn files_task_popover(shared: &Shared, reader: &ThemeReader) -> impl Widget + use<> {
    let source = shared
        .signals()
        .files_structure
        .select_named("files task popover theme", |key| key.theme);
    let s = shared.clone();
    let r = Rc::clone(reader);
    RebuildOnChange::key_from(source, move |_theme| {
        let badge_label = {
            let s = s.clone();
            move || {
                if sifs_daemon_offline(&s) {
                    SIFS_OFFLINE_STATUS.to_string()
                } else {
                    files_task_badge_label(&s.files())
                }
            }
        };
        let badge_tone = {
            let s = s.clone();
            move || {
                if sifs_daemon_offline(&s) {
                    SemanticTone::Neutral
                } else {
                    files_task_badge_tone(&s.files())
                }
            }
        };
        WidgetPod::new(
            Popover::new(
                "File tasks",
                SizedBox::new().width(FILES_TASK_BADGE_W).child(
                    StatusBadge::new("SIFS unknown")
                        .label_when(badge_label)
                        .tone_when(badge_tone)
                        .icon(IconGlyph::Storage)
                        .theme_when(clone_reader(&r)),
                ),
                SizedBox::new()
                    .width(FILES_TASK_POPOVER_W)
                    .child(FilesTaskQueue::new(s.clone(), &r)),
            )
            .alignment(PopoverAlignment::Start)
            .theme(r()),
        )
    })
}

fn files_status_bar(shared: &Shared, reader: &ThemeReader) -> impl Widget + use<> {
    let path_summary = {
        let s = shared.clone();
        move || {
            let files = s.files();
            let selected = files_status_bar_selection(&files);
            format!(
                "{} | {} | {}",
                middle_short(&files.path, 64),
                files_entry_count_status(&files),
                selected
            )
        }
    };
    let accessibility_summary = {
        let s = shared.clone();
        move || files_status_summary(&s.files())
    };
    let task_popover = files_task_popover(shared, reader);
    let status_theme = clone_reader(reader);
    let body = Background::new(
        Color::TRANSPARENT,
        Stack::vertical()
            .alignment(Alignment::Stretch)
            .with_child(Separator::horizontal().theme_when(clone_reader(reader)))
            .with_child(
                SizedBox::new().height(FILES_STATUS_H - 1.0).child(
                    Flex::horizontal()
                        .gap(8.0)
                        .align_items(Alignment::Center)
                        .with_child(task_popover)
                        .with_item(
                            StatusBar::new()
                                .name("Files status")
                                .description_when(accessibility_summary)
                                .height(FILES_STATUS_H - 1.0)
                                .theme_when(status_theme)
                                .segment(
                                    StatusBarSegment::new("Path /")
                                        .text_when(path_summary)
                                        .expand(true),
                                ),
                            FlexItem::flex(1.0).min_width(0.0),
                        ),
                ),
            ),
    )
    .brush_when({
        let s = shared.clone();
        move || palette(&s).sidebar
    });

    SizedBox::new().height(FILES_STATUS_H).child(body)
}

fn files_places_content_height(sifs_count: usize, local_count: usize) -> f32 {
    PLACES_HEADER_H
        + PLACE_SECTION_HEADER_H * 2.0
        + (sifs_count + local_count) as f32 * PLACE_ROW_H
        + PLACE_SECTION_GAP
        + PLACE_RAIL_BOTTOM_PAD
}

fn files_places_rail(shared: &Shared, reader: &ThemeReader) -> impl Widget + use<> {
    let source = shared
        .signals()
        .files_structure
        .select_named("files places structure", |key| {
            (key.theme, key.places.clone())
        });
    let s = shared.clone();
    let r = Rc::clone(reader);
    RebuildOnChange::key_from(source, move |_key| files_places_rail_rebuild(&s, &r))
}

fn files_places_rail_rebuild(shared: &Shared, reader: &ThemeReader) -> WidgetPod {
    let places = {
        let files = shared.files();
        files_places(&files)
    };
    let sifs_places = places
        .iter()
        .filter(|place| place.source == FilesSourceKind::Sifs)
        .cloned()
        .collect::<Vec<_>>();
    let local_places = places
        .iter()
        .filter(|place| place.source == FilesSourceKind::Local)
        .cloned()
        .collect::<Vec<_>>();
    let content_height = files_places_content_height(sifs_places.len(), local_places.len());
    let sifs_list = files_place_list(shared, reader, "SIFS locations", sifs_places);
    let local_list = files_place_list(shared, reader, "Device locations", local_places);

    let heading = SizedBox::new().height(PLACES_HEADER_H).child(
        WidgetPadding::horizontal(
            14.0,
            Flex::horizontal()
                .align_items(Alignment::Center)
                .with_child(SectionLabel::new("Locations").theme_when(clone_reader(reader))),
        )
        .fill_child_height(true),
    );
    let sifs_heading = files_place_section_heading("SIFS", reader);
    let local_heading = files_place_section_heading("This device", reader);

    let content = Stack::vertical()
        .alignment(Alignment::Stretch)
        .with_child(heading)
        .with_child(sifs_heading)
        .with_child(WidgetPadding::horizontal(8.0, sifs_list).fill_child_width(true))
        .with_child(SizedBox::new().height(PLACE_SECTION_GAP))
        .with_child(local_heading)
        .with_child(WidgetPadding::horizontal(8.0, local_list).fill_child_width(true))
        .with_child(SizedBox::new().height(PLACE_RAIL_BOTTOM_PAD));

    WidgetPod::new(
        SizedBox::new().height(content_height).child(
            Surface::new(SurfaceRole::Sidebar, content)
                .theme_when(clone_reader(reader))
                .fill(),
        ),
    )
}

fn files_place_section_heading(label: &'static str, reader: &ThemeReader) -> impl Widget + use<> {
    SizedBox::new().height(PLACE_SECTION_HEADER_H).child(
        WidgetPadding::horizontal(
            14.0,
            Flex::horizontal()
                .align_items(Alignment::Center)
                .with_child(SectionLabel::new(label).theme_when(clone_reader(reader))),
        )
        .fill_child_height(true),
    )
}

fn files_place_list(
    shared: &Shared,
    reader: &ThemeReader,
    name: &'static str,
    places: Vec<FilePlace>,
) -> impl Widget + use<> {
    let selection_places = places.clone();
    let action_places = places.clone();
    let selection_shared = shared.clone();
    let action_shared = shared.clone();
    let items = places
        .iter()
        .map(|place| {
            let semantic_description =
                if place.action == FilePlaceAction::OpenPath && place.detail != place.path {
                    format!("{}; path {}", place.detail, place.path)
                } else {
                    place.detail.clone()
                };
            ListItem::new(place.label.clone())
                .detail(place.detail.clone())
                .description(semantic_description)
                .leading_icon(place.glyph)
        })
        .collect::<Vec<_>>();

    let list_reader: ThemeReader = {
        let reader = Rc::clone(reader);
        Rc::new(move || reader().with_size(ControlSize::Small))
    };
    ListView::new(name)
        .items(items)
        .row_height(PLACE_ROW_H)
        .theme_when(clone_reader(&list_reader))
        .selected_when(move || {
            let files = selection_shared.files();
            file_place_active_index(&files, &selection_places)
        })
        .on_change_with_ctx(move |ctx, index, _label| {
            if let Some(place) = action_places.get(index).cloned() {
                open_file_place(&action_shared, place, ctx);
            }
        })
}

fn file_task_has_recovery(task: &FilesTask) -> bool {
    task.source == FilesSourceKind::Sifs && task.state == FilesTaskState::Failed
}

fn file_task_detail_display(task: &FilesTask) -> String {
    let detail = files_task_detail_display(task);
    if file_task_has_recovery(task) {
        detail
            .strip_suffix(" in Connection")
            .unwrap_or(detail.as_str())
            .to_string()
    } else {
        detail
    }
}

fn file_task_button_padding() -> sui::Insets {
    sui::Insets {
        left: 8.0,
        right: 8.0,
        top: 2.0,
        bottom: 2.0,
    }
}

fn file_task_clear_button(shared: &Shared, reader: &ThemeReader) -> sui::Button {
    let s = shared.clone();
    sui::Button::new("Clear finished")
        .semantic_name("Clear finished file tasks")
        .description("Dismiss completed, failed, and cancelled file operations")
        .min_width(108.0)
        .min_height(22.0)
        .padding(file_task_button_padding())
        .theme_when(clone_reader(reader))
        .appearance(sui::ButtonAppearance::Tonal)
        .tone(SemanticTone::Neutral)
        .on_press_with_ctx(move |ctx| {
            s.files_mut().clear_finished_tasks();
            ctx.request_measure();
            ctx.request_arrange();
            ctx.request_paint();
            ctx.request_semantics();
        })
}

fn file_task_cancel_button(shared: &Shared, reader: &ThemeReader, task: &FilesTask) -> sui::Button {
    let s = shared.clone();
    let task_id = task.id;
    sui::Button::new("Cancel")
        .semantic_name(format!("Cancel {}", task.title))
        .description(task.detail.clone())
        .min_width(58.0)
        .min_height(22.0)
        .padding(file_task_button_padding())
        .theme_when(clone_reader(reader))
        .appearance(sui::ButtonAppearance::Tonal)
        .tone(SemanticTone::Neutral)
        .on_press_with_ctx(move |ctx| {
            s.files_mut().cancel_task(task_id);
            ctx.request_paint();
            ctx.request_semantics();
        })
}

fn file_task_recovery_button(
    shared: &Shared,
    reader: &ThemeReader,
    task: &FilesTask,
) -> sui::Button {
    let s = shared.clone();
    sui::Button::new("Connection")
        .icon(IconGlyph::Alert)
        .icon_size(12.0)
        .semantic_name(format!("Open Connection settings for {}", task.title))
        .description(format!("{}: {}", task.title, task.detail))
        .min_width(92.0)
        .min_height(22.0)
        .padding(file_task_button_padding())
        .theme_when(clone_reader(reader))
        .appearance(sui::ButtonAppearance::Tonal)
        .tone(SemanticTone::Neutral)
        .on_press_with_ctx(move |ctx| {
            open_settings_section(&s, SettingsSection::System);
            ctx.request_measure();
            ctx.request_arrange();
            ctx.request_paint();
            ctx.request_semantics();
        })
}

fn file_task_action_slot(
    shared: &Shared,
    reader: &ThemeReader,
    task: &FilesTask,
) -> (SwitchView, f32) {
    let action_index = if task.state.can_cancel() {
        1
    } else if file_task_has_recovery(task) {
        2
    } else {
        0
    };
    let width = match action_index {
        1 => 58.0,
        2 => 92.0,
        _ => 0.0,
    };
    let slot = SwitchView::new()
        .selected(action_index)
        .with_child(SizedBox::new())
        .with_child(file_task_cancel_button(shared, reader, task))
        .with_child(file_task_recovery_button(shared, reader, task));
    (slot, width)
}

fn file_task_progress_indicator(reader: &ThemeReader, task: &FilesTask) -> impl Widget + use<> {
    const INDICATOR_H: f32 = 32.0;
    const INDICATOR_W: f32 = 3.0;
    let fill_h = (INDICATOR_H * task_progress_fraction(task)).clamp(0.0, INDICATOR_H);
    let tone = task_progress_tone(task);
    let track_reader = clone_reader(reader);
    let fill_reader = clone_reader(reader);
    let track = Background::new(
        Color::TRANSPARENT,
        SizedBox::new()
            .width(INDICATOR_W)
            .height(INDICATOR_H - fill_h),
    )
    .brush_when(move || track_reader().semantic_tone_soft_colors(tone).0);
    let fill = Background::new(
        Color::TRANSPARENT,
        SizedBox::new().width(INDICATOR_W).height(fill_h),
    )
    .brush_when(move || fill_reader().semantic_tone_colors(tone).0);
    SizedBox::new()
        .width(INDICATOR_W)
        .height(INDICATOR_H)
        .child(Dock::new(track).bottom(fill_h, fill))
}

fn file_task_row(shared: &Shared, reader: &ThemeReader, task: &FilesTask) -> impl Widget + use<> {
    let theme = reader();
    let pal = Palette::from_theme(&theme, widgets::theme_is_dark(shared));
    let title_style = pal.text_style(&theme, 12.0, FontWeight::MEDIUM, pal.text);
    let detail_style = pal.text_style(&theme, 11.0, FontWeight::NORMAL, pal.text_faint);
    let progress = task_progress_fraction(task);
    let progress_label = if matches!(
        task.state,
        FilesTaskState::Running | FilesTaskState::CancelRequested
    ) {
        format!(" - {}%", (progress * 100.0).round() as u8)
    } else {
        String::new()
    };
    let title = format!("{} - {}{progress_label}", task.title, task.state.label());
    let detail = file_task_detail_display(task);
    let (action, action_w) = file_task_action_slot(shared, reader, task);

    let text = Flex::vertical()
        .main_gap(1.0)
        .align_items(Alignment::Stretch)
        .with_child(Label::new(title).text_style(title_style))
        .with_child(Label::new(detail).text_style(detail_style));
    let body = Flex::horizontal()
        .main_gap(8.0)
        .align_items(Alignment::Center)
        .with_child(file_task_progress_indicator(reader, task))
        .with_item(text, FlexItem::flex(1.0).min_width(0.0));

    TrailingSlotRow::new(body, action)
        .trailing_width(action_w)
        .trailing_height(22.0)
        .gap(8.0)
}

