#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum FileContextAction {
    Open,
    OpenInNewTab,
    AttachToChat,
    Copy,
    CopySelected,
    CopyPath,
    CopyPaths,
    CopyIdentifiers,
    HistoryIssues,
    FolderHistory,
    Transfer,
    TransferSelected,
    Move,
    MoveSelected,
    Rename,
    Delete,
    DeleteSelected,
    EditPlacement,
    RefreshPlacement,
    RepairReplicas,
    MakeMetadataPrimary,
    PinMetadata,
    UnpinMetadata,
    PinContent,
    UnpinContent,
    ConnectionSettings,
    NewFile,
    NewFolder,
    ImportFiles,
    ImportFolder,
    GoToPath,
    OpenLocalFile,
    OpenLocalFolder,
    RefreshFolder,
    OpenStorageCenter,
    OpenPlacementActivity,
    RepairCurrentLocation,
    OpenCluster,
}

impl FileContextAction {
    fn label(self, source: FilesSourceKind) -> String {
        match self {
            Self::Open => "Open",
            Self::OpenInNewTab => "Open in new tab",
            Self::AttachToChat => "Attach to current chat",
            Self::Copy => "Copy to",
            Self::CopySelected => "Copy selected to",
            Self::CopyPath => "Copy path",
            Self::CopyPaths => "Copy paths",
            Self::CopyIdentifiers => "Copy DFS identifiers",
            Self::HistoryIssues => "History & issues",
            Self::FolderHistory => "Saved versions & deleted files",
            Self::Transfer => match source {
                FilesSourceKind::Local => "Copy to SIFS",
                FilesSourceKind::Sifs => "Download",
            },
            Self::TransferSelected => match source {
                FilesSourceKind::Local => "Copy selected to SIFS",
                FilesSourceKind::Sifs => "Download selected",
            },
            Self::Move => "Move to",
            Self::MoveSelected => "Move selected to",
            Self::Rename => "Rename",
            Self::Delete => "Delete",
            Self::DeleteSelected => "Delete selected",
            Self::EditPlacement => "Manage availability",
            Self::RefreshPlacement => "Refresh availability",
            Self::RepairReplicas => "Run maintenance and refresh",
            Self::MakeMetadataPrimary => "Move metadata authority here",
            Self::PinMetadata => "Keep metadata on this device",
            Self::UnpinMetadata => "Stop keeping metadata here",
            Self::PinContent => "Keep content on this device",
            Self::UnpinContent => "Stop keeping content here",
            Self::ConnectionSettings => "Connection settings",
            Self::NewFile => "New file",
            Self::NewFolder => "New folder",
            Self::ImportFiles => "Import files",
            Self::ImportFolder => "Import folder",
            Self::GoToPath => "Go to path",
            Self::OpenLocalFile => "Open local file",
            Self::OpenLocalFolder => "Choose local folder",
            Self::RefreshFolder => "Refresh current folder",
            Self::OpenStorageCenter => "Storage health",
            Self::OpenPlacementActivity => "View reconciliation activity",
            Self::RepairCurrentLocation => "Run folder maintenance",
            Self::OpenCluster => "Open Cluster",
        }
        .to_string()
    }

    fn group(self) -> u8 {
        match self {
            Self::Open | Self::OpenInNewTab | Self::AttachToChat => 0,
            Self::Copy
            | Self::CopySelected
            | Self::Transfer
            | Self::TransferSelected
            | Self::Move
            | Self::MoveSelected
            | Self::Rename
            | Self::NewFile
            | Self::NewFolder
            | Self::ImportFiles
            | Self::ImportFolder => 1,
            Self::CopyPath
            | Self::CopyPaths
            | Self::HistoryIssues
            | Self::FolderHistory
            | Self::EditPlacement
            | Self::RefreshPlacement
            | Self::RepairReplicas
            | Self::MakeMetadataPrimary
            | Self::PinMetadata
            | Self::UnpinMetadata
            | Self::PinContent
            | Self::UnpinContent
            | Self::CopyIdentifiers
            | Self::RefreshFolder
            | Self::OpenStorageCenter
            | Self::OpenPlacementActivity
            | Self::RepairCurrentLocation
            | Self::OpenCluster
            | Self::ConnectionSettings
            | Self::GoToPath
            | Self::OpenLocalFile
            | Self::OpenLocalFolder => 2,
            Self::Delete | Self::DeleteSelected => 3,
        }
    }

    fn enabled(self, files: &FilesState) -> bool {
        let can_read = files.loaded && !files.loading && files.error.is_none();
        let can_modify = files.can_modify_current_location();
        match self {
            Self::Move
            | Self::MoveSelected
            | Self::Rename
            | Self::Delete
            | Self::DeleteSelected
            | Self::NewFile
            | Self::NewFolder => can_modify,
            Self::ImportFiles | Self::ImportFolder => can_modify && !files.picker_lane.is_pending(),
            Self::RefreshFolder => !files.loading,
            Self::AttachToChat => can_read && !files.attachment_loading,
            Self::OpenLocalFile | Self::OpenLocalFolder => !files.picker_lane.is_pending(),
            Self::GoToPath => !files.loading,
            Self::Open
            | Self::OpenInNewTab
            | Self::CopyPath
            | Self::CopyPaths
            | Self::CopyIdentifiers
            | Self::EditPlacement
            | Self::RefreshPlacement
            | Self::RepairReplicas
            | Self::MakeMetadataPrimary
            | Self::PinMetadata
            | Self::UnpinMetadata
            | Self::PinContent
            | Self::UnpinContent
            | Self::ConnectionSettings
            | Self::OpenStorageCenter
            | Self::OpenPlacementActivity
            | Self::RepairCurrentLocation
            | Self::OpenCluster => true,
            Self::HistoryIssues => {
                files.source == FilesSourceKind::Sifs
                    && files.selected_entry().is_some()
                    && !files.details_loading
                    && files.selected_details.is_some()
            }
            Self::FolderHistory => files.source == FilesSourceKind::Sifs && !files.loading,
            Self::Copy | Self::CopySelected | Self::Transfer | Self::TransferSelected => can_read,
        }
    }

    fn destructive(self) -> bool {
        matches!(self, Self::Delete | Self::DeleteSelected)
    }
}

struct FileContextMenuEntry {
    action: Option<FileContextAction>,
    item: MenuItem,
    children: Vec<FileContextMenuEntry>,
}

impl FileContextMenuEntry {
    fn action(
        action: FileContextAction,
        files: &FilesState,
        separator_before: bool,
    ) -> FileContextMenuEntry {
        let mut item = MenuItem::new(action.label(files.source));
        if separator_before {
            item = item.separator_before(true);
        }
        if !action.enabled(files) {
            item = item.enabled(false);
        }
        if action.destructive() {
            item = item.destructive(true);
        }
        FileContextMenuEntry {
            action: Some(action),
            item,
            children: Vec::new(),
        }
    }

    fn submenu(
        label: impl Into<String>,
        children: Vec<FileContextMenuEntry>,
        separator_before: bool,
    ) -> FileContextMenuEntry {
        let mut item = MenuItem::new(label).submenu(
            children
                .iter()
                .map(|entry| entry.item.clone())
                .collect::<Vec<_>>(),
        );
        if separator_before {
            item = item.separator_before(true);
        }
        FileContextMenuEntry {
            action: None,
            item,
            children,
        }
    }
}

fn selection_context_actions(files: &FilesState) -> Vec<FileContextAction> {
    if files.marked_count() > 0 {
        return vec![
            FileContextAction::CopySelected,
            FileContextAction::MoveSelected,
            FileContextAction::TransferSelected,
            FileContextAction::CopyPaths,
            FileContextAction::DeleteSelected,
        ];
    }

    let Some(entry) = files.selected_entry() else {
        return Vec::new();
    };
    let mut actions = Vec::with_capacity(18);
    actions.push(FileContextAction::Open);
    actions.push(FileContextAction::OpenInNewTab);
    if !entry.is_dir {
        actions.push(FileContextAction::AttachToChat);
    }
    actions.push(FileContextAction::Copy);
    actions.push(FileContextAction::Move);
    actions.push(FileContextAction::Transfer);
    actions.push(FileContextAction::Rename);
    actions.push(FileContextAction::CopyPath);
    if files.source == FilesSourceKind::Sifs {
        let metadata_needs_connection = files
            .details_error
            .as_deref()
            .is_some_and(sifs_metadata_error_needs_connection);
        if metadata_needs_connection {
            actions.push(FileContextAction::ConnectionSettings);
        }
        let details = files
            .selected_details
            .as_ref()
            .filter(|details| details.path == entry.path);
        if details.is_some_and(|details| details.placement.is_some()) {
            actions.push(FileContextAction::EditPlacement);
        }
        actions.push(FileContextAction::RefreshPlacement);
        actions.push(FileContextAction::HistoryIssues);
        if !metadata_needs_connection
            && !files.details_loading
            && let Some(details) = details
        {
            if sifs_needs_replica_repair(details) {
                actions.push(FileContextAction::RepairReplicas);
            }
            if sifs_can_make_metadata_primary(details) {
                actions.push(FileContextAction::MakeMetadataPrimary);
            }
            if sifs_has_local_pin(details, "metadata") {
                actions.push(FileContextAction::UnpinMetadata);
            } else {
                actions.push(FileContextAction::PinMetadata);
            }
            if !entry.is_dir && !entry.is_link {
                if sifs_has_local_pin(details, "content") {
                    actions.push(FileContextAction::UnpinContent);
                } else {
                    actions.push(FileContextAction::PinContent);
                }
            }
            actions.push(FileContextAction::CopyIdentifiers);
        }
    }
    actions.push(FileContextAction::Delete);
    actions
}

fn sifs_needs_replica_repair(details: &SifsObjectDetails) -> bool {
    details.health.as_ref().is_some_and(|health| {
        health.pending_repair_count > 0 || !health.missing_replica_nodes.is_empty()
    })
}

fn file_context_menu_entries(
    files: &FilesState,
    target: FileContextMenuTarget,
) -> Vec<FileContextMenuEntry> {
    match target {
        FileContextMenuTarget::Selection => selection_context_menu_entries(files),
        FileContextMenuTarget::CurrentLocation => current_location_context_menu_entries(files),
        FileContextMenuTarget::Create => create_context_menu_entries(files),
        FileContextMenuTarget::Import => import_context_menu_entries(files),
        FileContextMenuTarget::LocationMore => location_more_context_menu_entries(files),
        FileContextMenuTarget::Availability => availability_context_menu_entries(files),
    }
}

fn action_entry(
    action: FileContextAction,
    files: &FilesState,
    separator_before: bool,
) -> FileContextMenuEntry {
    FileContextMenuEntry::action(action, files, separator_before)
}

fn selection_context_menu_entries(files: &FilesState) -> Vec<FileContextMenuEntry> {
    if files.marked_count() > 0 {
        return vec![
            action_entry(FileContextAction::CopySelected, files, false),
            action_entry(FileContextAction::MoveSelected, files, false),
            action_entry(FileContextAction::TransferSelected, files, false),
            action_entry(FileContextAction::CopyPaths, files, true),
            action_entry(FileContextAction::DeleteSelected, files, true),
        ];
    }

    let Some(entry) = files.selected_entry() else {
        return Vec::new();
    };
    let mut entries = vec![action_entry(FileContextAction::Open, files, false)];
    entries.push(action_entry(FileContextAction::OpenInNewTab, files, false));
    if !entry.is_dir {
        entries.push(action_entry(FileContextAction::AttachToChat, files, false));
    }
    entries.extend([
        action_entry(FileContextAction::Copy, files, true),
        action_entry(FileContextAction::Move, files, false),
        action_entry(FileContextAction::Transfer, files, false),
        action_entry(FileContextAction::Rename, files, false),
        action_entry(FileContextAction::CopyPath, files, true),
    ]);

    if files.source == FilesSourceKind::Sifs {
        let details = files
            .selected_details
            .as_ref()
            .filter(|details| details.path == entry.path);
        let metadata_needs_connection = files
            .details_error
            .as_deref()
            .is_some_and(sifs_metadata_error_needs_connection);
        let mut placement = Vec::new();
        if details.is_some_and(|details| details.placement.is_some()) {
            placement.push(action_entry(FileContextAction::EditPlacement, files, false));
        }
        placement.push(action_entry(
            FileContextAction::RefreshPlacement,
            files,
            false,
        ));
        if details.is_some_and(sifs_needs_replica_repair) {
            placement.push(action_entry(
                FileContextAction::RepairReplicas,
                files,
                false,
            ));
        }

        let mut device = Vec::new();
        if let Some(details) = details.filter(|_| !metadata_needs_connection) {
            device.push(action_entry(
                if sifs_has_local_pin(details, "metadata") {
                    FileContextAction::UnpinMetadata
                } else {
                    FileContextAction::PinMetadata
                },
                files,
                false,
            ));
            if !entry.is_dir && !entry.is_link {
                device.push(action_entry(
                    if sifs_has_local_pin(details, "content") {
                        FileContextAction::UnpinContent
                    } else {
                        FileContextAction::PinContent
                    },
                    files,
                    false,
                ));
            }
            if sifs_can_make_metadata_primary(details) {
                device.push(action_entry(
                    FileContextAction::MakeMetadataPrimary,
                    files,
                    false,
                ));
            }
        }

        let mut sifs = vec![FileContextMenuEntry::submenu(
            "Availability",
            placement,
            false,
        )];
        if !device.is_empty() {
            sifs.push(FileContextMenuEntry::submenu("This device", device, false));
        }
        if details.is_some() && !metadata_needs_connection {
            sifs.push(action_entry(
                FileContextAction::CopyIdentifiers,
                files,
                true,
            ));
        }
        if metadata_needs_connection {
            sifs.push(action_entry(
                FileContextAction::ConnectionSettings,
                files,
                true,
            ));
        }
        entries.push(FileContextMenuEntry::submenu("SIFS", sifs, false));
        entries.push(action_entry(FileContextAction::HistoryIssues, files, false));
    }
    entries.push(action_entry(FileContextAction::Delete, files, true));
    entries
}

fn current_location_context_menu_entries(files: &FilesState) -> Vec<FileContextMenuEntry> {
    let mut entries = vec![
        FileContextMenuEntry::submenu(
            "New",
            vec![
                action_entry(FileContextAction::NewFile, files, false),
                action_entry(FileContextAction::NewFolder, files, false),
            ],
            false,
        ),
        FileContextMenuEntry::submenu(
            "Import",
            vec![
                action_entry(FileContextAction::ImportFiles, files, false),
                action_entry(FileContextAction::ImportFolder, files, false),
            ],
            false,
        ),
        FileContextMenuEntry::submenu(
            "Open local",
            vec![
                action_entry(FileContextAction::OpenLocalFile, files, false),
                action_entry(FileContextAction::OpenLocalFolder, files, false),
            ],
            false,
        ),
        action_entry(FileContextAction::GoToPath, files, true),
        action_entry(FileContextAction::RefreshFolder, files, false),
    ];

    if files.source == FilesSourceKind::Sifs {
        let mut sifs = vec![
            action_entry(FileContextAction::FolderHistory, files, false),
            action_entry(FileContextAction::OpenStorageCenter, files, false),
            action_entry(FileContextAction::OpenPlacementActivity, files, false),
        ];
        if files
            .sifs_health
            .as_ref()
            .is_some_and(|health| health.pending_repair_count > 0)
        {
            sifs.push(action_entry(
                FileContextAction::RepairCurrentLocation,
                files,
                false,
            ));
        }
        if files.sifs_health.as_ref().is_some_and(|health| {
            sifs_health_has_attention(health) || sifs_health_has_activity(health)
        }) {
            sifs.push(action_entry(FileContextAction::OpenCluster, files, false));
        }
        if files.sifs_health_error.is_some() || files.error.is_some() {
            sifs.push(action_entry(
                FileContextAction::ConnectionSettings,
                files,
                true,
            ));
        }
        entries.push(FileContextMenuEntry::submenu("SIFS", sifs, true));
    }
    entries
}

/// Visible toolbar menus deliberately expose a small task vocabulary. The complete combined menu
/// remains available on the directory background for pointer users, but nobody has to discover a
/// right click before they can create, import, or troubleshoot a location.
fn create_context_menu_entries(files: &FilesState) -> Vec<FileContextMenuEntry> {
    vec![
        action_entry(FileContextAction::NewFile, files, false),
        action_entry(FileContextAction::NewFolder, files, false),
    ]
}

fn import_context_menu_entries(files: &FilesState) -> Vec<FileContextMenuEntry> {
    vec![
        action_entry(FileContextAction::ImportFiles, files, false),
        action_entry(FileContextAction::ImportFolder, files, false),
    ]
}

fn location_more_context_menu_entries(files: &FilesState) -> Vec<FileContextMenuEntry> {
    let mut entries = vec![
        action_entry(FileContextAction::GoToPath, files, false),
        FileContextMenuEntry::submenu(
            "Open from this device",
            vec![
                action_entry(FileContextAction::OpenLocalFile, files, false),
                action_entry(FileContextAction::OpenLocalFolder, files, false),
            ],
            false,
        ),
        action_entry(FileContextAction::RefreshFolder, files, true),
    ];

    if files.source == FilesSourceKind::Sifs {
        entries.push(action_entry(FileContextAction::FolderHistory, files, true));
        let mut storage = vec![
            action_entry(FileContextAction::OpenStorageCenter, files, false),
            action_entry(FileContextAction::OpenPlacementActivity, files, false),
        ];
        if files
            .sifs_health
            .as_ref()
            .is_some_and(|health| health.pending_repair_count > 0)
        {
            storage.push(action_entry(
                FileContextAction::RepairCurrentLocation,
                files,
                false,
            ));
        }
        storage.push(action_entry(FileContextAction::OpenCluster, files, false));
        if files.sifs_health_error.is_some() || files.error.is_some() {
            storage.push(action_entry(
                FileContextAction::ConnectionSettings,
                files,
                true,
            ));
        }
        entries.push(FileContextMenuEntry::submenu(
            "Storage and activity",
            storage,
            true,
        ));
    }
    entries
}

fn availability_context_menu_entries(files: &FilesState) -> Vec<FileContextMenuEntry> {
    if files.source != FilesSourceKind::Sifs {
        return Vec::new();
    }
    let Some(entry) = files.selected_entry() else {
        return Vec::new();
    };
    let details = files
        .selected_details
        .as_ref()
        .filter(|details| details.path == entry.path);
    let metadata_needs_connection = files
        .details_error
        .as_deref()
        .is_some_and(sifs_metadata_error_needs_connection);

    let mut entries = Vec::new();
    if details.is_some_and(|details| details.placement.is_some()) {
        entries.push(action_entry(FileContextAction::EditPlacement, files, false));
    }
    entries.push(action_entry(
        FileContextAction::RefreshPlacement,
        files,
        false,
    ));
    if details.is_some_and(sifs_needs_replica_repair) {
        entries.push(action_entry(
            FileContextAction::RepairReplicas,
            files,
            false,
        ));
    }

    if let Some(details) = details.filter(|_| !metadata_needs_connection) {
        let mut device = vec![action_entry(
            if sifs_has_local_pin(details, "metadata") {
                FileContextAction::UnpinMetadata
            } else {
                FileContextAction::PinMetadata
            },
            files,
            false,
        )];
        if !entry.is_dir && !entry.is_link {
            device.push(action_entry(
                if sifs_has_local_pin(details, "content") {
                    FileContextAction::UnpinContent
                } else {
                    FileContextAction::PinContent
                },
                files,
                false,
            ));
        }
        if sifs_can_make_metadata_primary(details) {
            device.push(action_entry(
                FileContextAction::MakeMetadataPrimary,
                files,
                false,
            ));
        }
        entries.push(FileContextMenuEntry::submenu("This device", device, true));
        entries.push(action_entry(
            FileContextAction::CopyIdentifiers,
            files,
            true,
        ));
    }
    if metadata_needs_connection {
        entries.push(action_entry(
            FileContextAction::ConnectionSettings,
            files,
            true,
        ));
    }
    entries
}

fn file_context_action_at_path(
    entries: &[FileContextMenuEntry],
    path: &[usize],
) -> Option<FileContextAction> {
    let (index, rest) = path.split_first()?;
    let entry = entries.get(*index)?;
    if rest.is_empty() {
        entry.action
    } else {
        file_context_action_at_path(&entry.children, rest)
    }
}

fn sifs_identifiers_for_clipboard(details: &SifsObjectDetails) -> String {
    let mut lines = vec![
        format!("file_system_id: {}", details.file_system_id),
        format!("object_id: {}", details.object_id),
        format!("version: {}", details.version),
    ];
    if let Some(hash) = details
        .content_hash
        .as_deref()
        .filter(|value| !value.trim().is_empty())
    {
        lines.push(format!("content_hash: {hash}"));
    }
    lines.join("\n")
}

fn sifs_loading_rows(
    path: &str,
    details_open: bool,
    slow_after_secs: Option<u64>,
) -> Vec<(&'static str, String)> {
    let mut rows = vec![(
        "Status",
        if slow_after_secs.is_some() {
            "SIFS is still loading".to_string()
        } else {
            "Connecting to SIFS".to_string()
        },
    )];
    if let Some(seconds) = slow_after_secs {
        rows.push((
            "Wait",
            format!("Directory listing has been running for at least {seconds} seconds."),
        ));
    }
    if details_open {
        rows.push(("Path", path.to_string()));
        rows.push(("Authority", "SIFS through daemon".to_string()));
    }
    rows
}

fn sifs_unavailable_rows(error: &str, details_open: bool) -> Vec<(&'static str, String)> {
    let mut rows = vec![
        ("Status", sifs_unavailable_summary(error).to_string()),
        (
            "Available",
            "Local files, drives, UNC paths, and mounted paths still work.".to_string(),
        ),
        (
            "Next",
            "Retry SIFS, open Connection, or browse local files".to_string(),
        ),
    ];
    if details_open {
        rows.push(("Reason", error.to_string()));
        rows.push(("Authority", "SIFS through daemon".to_string()));
    }
    rows
}

fn inspector_detail_button_label(details_open: bool) -> &'static str {
    if details_open {
        "Hide advanced"
    } else {
        "Advanced details"
    }
}

// ---------------------------------------------------------------------------
// Composed inspector — stock controls own generic chrome, focus, and semantics.
// ---------------------------------------------------------------------------

/// The interactive Files inspector is rebuilt from a compact state signature. Generic cards,
/// fields, badges, and actions are composed from SUI widgets; only the file-list and placement
/// data remain app-owned.
struct InspectorView {
    child: WidgetPod,
}

impl InspectorView {
    fn new(shared: Shared) -> Self {
        let reader: ThemeReader = {
            let s = shared.clone();
            Rc::new(move || s.theme().with_size(ControlSize::Small))
        };
        let source = shared
            .signals()
            .files_structure
            .select_named("files inspector structure", |key| {
                (key.inspector.clone(), key.daemon_available)
            });
        let build_shared = shared.clone();
        let build_reader = Rc::clone(&reader);
        let child = RebuildOnChange::key_from(source, move |_key| {
            composed_inspector_content(&build_shared, &build_reader)
        });
        Self {
            child: WidgetPod::new(child),
        }
    }
}

impl Widget for InspectorView {
    fn event(&mut self, _ctx: &mut EventCtx, _event: &Event) {}

    fn measure(&mut self, ctx: &mut MeasureCtx, constraints: Constraints) -> Size {
        self.child.measure(ctx, constraints)
    }

    fn arrange(&mut self, ctx: &mut ArrangeCtx, bounds: Rect) {
        self.child.arrange(ctx, bounds);
    }

    fn paint(&self, ctx: &mut PaintCtx) {
        self.child.paint(ctx);
    }

    fn semantics(&self, ctx: &mut SemanticsCtx) {
        self.child.semantics(ctx);
    }

    fn visit_children(&self, visitor: &mut dyn WidgetPodVisitor) {
        visitor.visit(&self.child);
    }

    fn visit_children_mut(&mut self, visitor: &mut dyn WidgetPodMutVisitor) {
        visitor.visit(&mut self.child);
    }
}

#[cfg(test)]
fn inspector_summary(shared: &Shared) -> String {
    let files = shared.files();
    if files.loading {
        return format!(
            "loading|{:?}|{}|{}|{:?}",
            files.source, files.path, files.inspector_details_open, files.list_slow_after_secs
        );
    }
    if let Some(error) = &files.error {
        return format!(
            "error|{:?}|{}|{}|{}",
            files.source, files.path, error, files.inspector_details_open
        );
    }
    if let Some(selection) = marked_selection_summary(&files) {
        return format!(
            "selection|{:?}|{}|{}|{}|{}|{}|{}",
            files.source,
            files.path,
            selection.count,
            selection.file_count,
            selection.folder_count,
            selection.link_count,
            files.inspector_details_open
        );
    }
    match files.selected_entry() {
        Some(entry) => format!(
            "{:?}|{}|{}|{}|{}|{}|{}|{}|{}|{}|{}|{}|{}",
            files.source,
            entry.path,
            entry.is_dir,
            entry.is_link,
            files.clustered,
            files.details_loading,
            files.details_error.as_deref().unwrap_or(""),
            files.preview_loading,
            files.preview_error.as_deref().unwrap_or(""),
            files.inspector_details_open,
            sifs_details_signature(files.selected_details.as_ref()),
            local_details_signature(files.selected_local_details.as_ref()),
            files_preview_signature(files.selected_preview.as_ref())
        ),
        None => format!(
            "unselected|{:?}|{}|{}|{}|{}|{}",
            files.source,
            files.path,
            files.clustered,
            files.entries.len(),
            files.inspector_details_open,
            unselected_inspector_health_summary(&files).unwrap_or_default()
        ),
    }
}

fn detail_rows_widget(
    rows: impl IntoIterator<Item = (&'static str, String)>,
    reader: &ThemeReader,
) -> Stack {
    let mut body = Stack::vertical().alignment(Alignment::Stretch).gap(4.0);
    for (label, value) in rows {
        body = body.with_child(
            DetailRow::new(label, value)
                .theme_when(clone_reader(reader))
                .max_value_lines(6),
        );
    }
    body
}

fn inspector_card<W>(
    title: impl Into<String>,
    child: W,
    reader: &ThemeReader,
    header_action: Option<sui::Button>,
    prominent_title: bool,
) -> Surface
where
    W: Widget + 'static,
{
    let theme = reader();
    let mut section = PanelSection::new(title, child)
        .theme_when(clone_reader(reader))
        .gap(10.0);
    if prominent_title {
        let mut title_style = theme.text_style(theme.palette.text);
        title_style.font_size = theme.text.xl.size;
        title_style.line_height = theme.text.xl.line_height;
        title_style.weight = FontWeight::SEMIBOLD;
        section = section.title_style(title_style);
    }
    if let Some(action) = header_action {
        section = section.header_action(action);
    }
    Surface::panel(section)
        .theme_when(clone_reader(reader))
        .padding(Insets {
            left: 12.0,
            top: 10.0,
            right: 12.0,
            bottom: 12.0,
        })
        .fill_width(true)
}

fn inspector_details_button(
    shared: &Shared,
    reader: &ThemeReader,
    details_open: bool,
) -> sui::Button {
    let label = inspector_detail_button_label(details_open);
    let s = shared.clone();
    sui::Button::new(label)
        .semantic_name(label)
        .description("Technical file, version, storage, and authority details")
        .icon(if details_open {
            IconGlyph::ChevronUp
        } else {
            IconGlyph::ChevronDown
        })
        .appearance(ButtonAppearance::Ghost)
        .tone(SemanticTone::Accent)
        .min_height(24.0)
        .theme_when(clone_reader(reader))
        .on_press_with_ctx(move |ctx| {
            let open = s.files().inspector_details_open;
            s.files_mut().inspector_details_open = !open;
            request_files_overlay_rebuild(ctx);
        })
}

fn activate_file_context_action(shared: &Shared, action: FileContextAction, ctx: &mut EventCtx) {
    match action {
        FileContextAction::OpenInNewTab => {
            let selected = shared.files().selected_entry().cloned();
            if let Some(entry) = selected {
                let source = shared.files().source;
                if entry.is_dir {
                    shared.open_files_tab(source, entry.path);
                } else {
                    shared.open_document_tab(source, entry.path, entry.name);
                }
                request_files_overlay_rebuild(ctx);
            }
        }
        FileContextAction::Open => {
            let selected = shared.files().selected;
            if let Some(index) = selected {
                shared.files_mut().activate_row(index);
            }
        }
        FileContextAction::AttachToChat => {
            let waker = { shared.borrow().waker.clone() };
            shared.files_mut().start_attach_selected(waker);
        }
        FileContextAction::Copy => shared
            .files_mut()
            .open_action_prompt(FileActionPromptKind::Copy),
        FileContextAction::CopySelected => shared
            .files_mut()
            .open_action_prompt(FileActionPromptKind::CopySelected),
        FileContextAction::CopyPath => {
            let value = shared
                .files()
                .selected_entry()
                .map(|entry| entry.path.clone());
            if let Some(value) = value {
                ctx.set_clipboard_text(value);
            }
        }
        FileContextAction::CopyPaths => {
            let value = shared
                .files()
                .marked_targets()
                .into_iter()
                .map(|target| target.path)
                .collect::<Vec<_>>()
                .join("\n");
            if !value.is_empty() {
                ctx.set_clipboard_text(value);
            }
        }
        FileContextAction::Transfer => {
            let kind = match shared.files().source {
                FilesSourceKind::Local => FileActionPromptKind::CopyToSifs,
                FilesSourceKind::Sifs => FileActionPromptKind::CopyToLocal,
            };
            shared.files_mut().open_action_prompt(kind);
        }
        FileContextAction::TransferSelected => shared
            .files_mut()
            .open_action_prompt(FileActionPromptKind::TransferSelected),
        FileContextAction::Move => shared
            .files_mut()
            .open_action_prompt(FileActionPromptKind::Move),
        FileContextAction::MoveSelected => shared
            .files_mut()
            .open_action_prompt(FileActionPromptKind::MoveSelected),
        FileContextAction::Rename => shared
            .files_mut()
            .open_action_prompt(FileActionPromptKind::Rename),
        FileContextAction::Delete => shared
            .files_mut()
            .open_action_prompt(FileActionPromptKind::Delete),
        FileContextAction::DeleteSelected => shared
            .files_mut()
            .open_action_prompt(FileActionPromptKind::DeleteSelected),
        FileContextAction::EditPlacement => {
            shared
                .files_mut()
                .open_action_prompt(FileActionPromptKind::Placement);
            let waker = { shared.borrow().waker.clone() };
            shared.files_mut().start_placement_preview(waker);
        }
        FileContextAction::RefreshPlacement => {
            let waker = { shared.borrow().waker.clone() };
            shared.files_mut().start_placement_refresh(waker);
        }
        FileContextAction::RepairReplicas => {
            let waker = { shared.borrow().waker.clone() };
            shared.files_mut().start_replica_repair(waker);
        }
        FileContextAction::MakeMetadataPrimary => {
            let waker = { shared.borrow().waker.clone() };
            shared.files_mut().start_make_metadata_primary(waker);
        }
        FileContextAction::PinMetadata => {
            let waker = { shared.borrow().waker.clone() };
            shared.files_mut().start_pin_metadata(waker);
        }
        FileContextAction::UnpinMetadata => {
            let waker = { shared.borrow().waker.clone() };
            shared.files_mut().start_unpin_metadata(waker);
        }
        FileContextAction::PinContent => {
            let waker = { shared.borrow().waker.clone() };
            shared.files_mut().start_pin_content(waker);
        }
        FileContextAction::UnpinContent => {
            let waker = { shared.borrow().waker.clone() };
            shared.files_mut().start_unpin_content(waker);
        }
        FileContextAction::ConnectionSettings => {
            open_settings_section(shared, SettingsSection::System);
        }
        FileContextAction::CopyIdentifiers => {
            let value = shared
                .files()
                .selected_details
                .as_ref()
                .map(sifs_identifiers_for_clipboard);
            if let Some(value) = value {
                ctx.set_clipboard_text(value);
            }
        }
        FileContextAction::HistoryIssues => {
            let waker = { shared.borrow().waker.clone() };
            shared.files_mut().open_history(waker);
        }
        FileContextAction::FolderHistory => {
            let waker = { shared.borrow().waker.clone() };
            shared.files_mut().open_folder_history(waker);
        }
        FileContextAction::NewFile => shared
            .files_mut()
            .open_action_prompt(FileActionPromptKind::NewFile),
        FileContextAction::NewFolder => shared
            .files_mut()
            .open_action_prompt(FileActionPromptKind::NewFolder),
        FileContextAction::ImportFiles | FileContextAction::ImportFolder => {
            let picker_action = if action == FileContextAction::ImportFiles {
                FilesPickerAction::ImportFiles
            } else {
                FilesPickerAction::ImportFolder
            };
            let waker = { shared.borrow().waker.clone() };
            shared
                .files_mut()
                .request_native_picker(picker_action, waker);
        }
        FileContextAction::GoToPath => shared
            .files_mut()
            .open_action_prompt(FileActionPromptKind::GoTo),
        FileContextAction::OpenLocalFile | FileContextAction::OpenLocalFolder => {
            let picker_action = if action == FileContextAction::OpenLocalFile {
                FilesPickerAction::OpenFile
            } else {
                FilesPickerAction::OpenFolder
            };
            let waker = { shared.borrow().waker.clone() };
            shared
                .files_mut()
                .request_native_picker(picker_action, waker);
        }
        FileContextAction::RefreshFolder => shared.files_mut().reload(),
        FileContextAction::OpenStorageCenter => {
            let waker = { shared.borrow().waker.clone() };
            shared.files_mut().open_storage_center(waker);
        }
        FileContextAction::OpenPlacementActivity => {
            let waker = { shared.borrow().waker.clone() };
            shared.files_mut().open_placement_activity(waker);
        }
        FileContextAction::RepairCurrentLocation => {
            let waker = { shared.borrow().waker.clone() };
            shared
                .files_mut()
                .start_current_location_replica_repair(waker);
        }
        FileContextAction::OpenCluster => open_cluster_tab(shared),
    }
    request_files_overlay_rebuild(ctx);
}

fn preview_card(
    source: FilesSourceKind,
    loading: bool,
    error: Option<&str>,
    preview: Option<&FilesPreview>,
    custom_preview: Option<&CustomFilesPreview>,
    reader: &ThemeReader,
) -> Surface {
    let theme = reader();
    let mut body = Stack::vertical().alignment(Alignment::Stretch).gap(8.0);
    if !loading
        && error.is_none()
        && let Some(custom) = custom_preview
    {
        body = body
            .with_child(
                StatusBadge::new(format!("Custom preview · {}", custom.label))
                    .tone(SemanticTone::Accent)
                    .theme_when(clone_reader(reader)),
            )
            .with_child(
                SizedBox::new()
                    .height(custom.sizing.preferred_height.clamp(160, 420) as f32)
                    .child(ModuleWidget::new(
                        custom.session.clone(),
                        custom.sizing,
                        reader.clone(),
                    )),
            );
        return inspector_card("Preview", body, reader, None, false);
    }
    let (badge, badge_tone, text, muted) = if loading {
        (
            "Reading preview",
            SemanticTone::Accent,
            "Reading a bounded preview from the selected source".to_string(),
            None,
        )
    } else if let Some(error) = error {
        (
            "Preview unavailable",
            SemanticTone::Warning,
            file_preview_error_display(source, error),
            None,
        )
    } else if let Some(preview) = preview {
        let text = if preview.binary {
            preview.lines.join(" ")
        } else {
            preview
                .lines
                .iter()
                .take(FILE_PREVIEW_MAX_LINES)
                .cloned()
                .collect::<Vec<_>>()
                .join("\n")
        };
        (
            if preview.binary {
                "Binary preview"
            } else {
                "Text preview"
            },
            SemanticTone::Neutral,
            text,
            preview
                .truncated
                .then(|| format!("Preview truncated to {} KB.", FILE_PREVIEW_MAX_BYTES / 1024)),
        )
    } else {
        (
            "Preview pending",
            SemanticTone::Neutral,
            "Preview has not loaded yet".to_string(),
            None,
        )
    };
    body = body.with_child(
        StatusBadge::new(badge)
            .tone(badge_tone)
            .theme_when(clone_reader(reader)),
    );
    let mut body_style = theme.text_style(theme.palette.text);
    body_style.font_size = theme.text.sm.size;
    body_style.line_height = theme.text.sm.line_height;
    body = body.with_child(RichText::from_plain_text(text, body_style));
    if let Some(muted) = muted {
        let mut muted_style = theme.text_style(theme.palette.text_muted);
        muted_style.font_size = theme.text.xs.size;
        muted_style.line_height = theme.text.xs.line_height;
        body = body.with_child(RichText::from_plain_text(muted, muted_style));
    }
    inspector_card("Preview", body, reader, None, false)
}

fn selected_item_actions(
    shared: &Shared,
    reader: &ThemeReader,
    entry: &SifsEntry,
) -> impl Widget + use<> {
    let source = shared.files().source;
    let open = file_action_button(
        shared,
        reader,
        FileContextAction::Open,
        if entry.is_dir { "Open folder" } else { "Open" },
        if entry.is_dir {
            IconGlyph::Folder
        } else {
            IconGlyph::FileText
        },
        ButtonAppearance::Tonal,
    );
    let transfer = (!entry.is_dir).then(|| {
        file_action_button(
            shared,
            reader,
            FileContextAction::Transfer,
            match source {
                FilesSourceKind::Sifs => "Download",
                FilesSourceKind::Local => "Copy to Sinomo",
            },
            if source == FilesSourceKind::Sifs {
                IconGlyph::Download
            } else {
                IconGlyph::Storage
            },
            ButtonAppearance::Ghost,
        )
    });
    let attach = (!entry.is_dir).then(|| {
        file_action_button(
            shared,
            reader,
            FileContextAction::AttachToChat,
            "Attach to chat",
            IconGlyph::Attach,
            ButtonAppearance::Ghost,
        )
    });
    let more = files_primary_menu(
        "inspector-selection-actions",
        shared,
        reader,
        FileContextMenuTarget::Selection,
        sui::Button::new("More")
            .icon(IconGlyph::MoreHorizontal)
            .min_height(32.0)
            .appearance(ButtonAppearance::Ghost)
            .theme_when(clone_reader(reader)),
    );

    let mut primary = Flex::horizontal()
        .wrap(FlexWrap::Wrap)
        .gap(6.0)
        .align_items(Alignment::Center)
        .with_child(open);
    if let Some(attach) = attach {
        primary = primary.with_child(attach);
    }
    let mut secondary = Flex::horizontal()
        .wrap(FlexWrap::Wrap)
        .gap(6.0)
        .align_items(Alignment::Center);
    if let Some(transfer) = transfer {
        secondary = secondary.with_child(transfer);
    }
    if source == FilesSourceKind::Sifs {
        secondary = secondary.with_child(file_action_button(
            shared,
            reader,
            FileContextAction::HistoryIssues,
            "History & issues",
            IconGlyph::History,
            ButtonAppearance::Ghost,
        ));
    }
    secondary = secondary.with_child(more);
    let mut actions = Stack::vertical()
        .alignment(Alignment::Stretch)
        .gap(4.0)
        .with_child(primary)
        .with_child(secondary);
    if source == FilesSourceKind::Sifs {
        actions = actions.with_child(availability_actions(shared, reader));
    }
    actions
}

fn availability_actions(shared: &Shared, reader: &ThemeReader) -> ContextMenu {
    files_primary_menu(
        "inspector-availability-actions",
        shared,
        reader,
        FileContextMenuTarget::Availability,
        sui::Button::new("Manage availability")
            .icon(IconGlyph::Storage)
            .min_height(32.0)
            .appearance(ButtonAppearance::Tonal)
            .tone(SemanticTone::Accent)
            .theme_when(clone_reader(reader)),
    )
}

fn current_location_overview(shared: &Shared, reader: &ThemeReader) -> impl Widget + use<> {
    let files = shared.files();
    let (status, tone) = match files.source {
        FilesSourceKind::Local => ("On this device".to_string(), SemanticTone::Neutral),
        FilesSourceKind::Sifs => match files.sifs_health.as_ref() {
            Some(health) if sifs_health_has_attention(health) => {
                ("Needs attention".to_string(), SemanticTone::Warning)
            }
            Some(health) if sifs_health_has_activity(health) => {
                ("Syncing changes".to_string(), SemanticTone::Accent)
            }
            Some(_) => ("Available".to_string(), SemanticTone::Success),
            None if files.sifs_health_error.is_some() => {
                ("Health unavailable".to_string(), SemanticTone::Warning)
            }
            None => ("Ready".to_string(), SemanticTone::Neutral),
        },
    };
    let hint = match files.source {
        FilesSourceKind::Sifs => {
            "Select an item to open it, share it, or choose where copies stay available."
        }
        FilesSourceKind::Local => {
            "Select an item to open it or copy it into Sinomo for access across devices."
        }
    };
    let rows = vec![
        ("Location", files.path.clone()),
        ("Contents", files_entry_count_status(&files)),
    ];
    let mut advanced_rows = Vec::new();
    if files.source == FilesSourceKind::Sifs && files.inspector_details_open {
        if let Some(detail) = files_sifs_connection_detail(&files) {
            advanced_rows.push(("Daemon", detail));
        }
        if let Some(detail) = unselected_inspector_health_detail(&files) {
            advanced_rows.push(("DFS detail", detail));
        }
    }
    drop(files);

    let theme = reader();
    let mut hint_style = theme.text_style(theme.palette.text_muted);
    hint_style.font_size = theme.text.sm.size;
    hint_style.line_height = theme.text.sm.line_height;
    let mut content = Stack::vertical()
        .alignment(Alignment::Stretch)
        .gap(10.0)
        .with_child(
            StatusBadge::new(status)
                .icon(IconGlyph::Storage)
                .tone(tone)
                .theme_when(clone_reader(reader)),
        )
        .with_child(detail_rows_widget(rows, reader))
        .with_child(Label::new(hint).text_style(hint_style));

    if shared.files().source == FilesSourceKind::Sifs {
        let storage = file_action_button(
            shared,
            reader,
            FileContextAction::OpenStorageCenter,
            "Storage health",
            IconGlyph::Storage,
            ButtonAppearance::Tonal,
        );
        let activity = file_action_button(
            shared,
            reader,
            FileContextAction::OpenPlacementActivity,
            "View activity",
            IconGlyph::History,
            ButtonAppearance::Ghost,
        );
        let versions = file_action_button(
            shared,
            reader,
            FileContextAction::FolderHistory,
            "Saved versions",
            IconGlyph::History,
            ButtonAppearance::Ghost,
        );
        let settings_shared = shared.clone();
        let mount = sui::Button::new("Mount & sync")
            .icon(IconGlyph::Folder)
            .min_height(32.0)
            .appearance(ButtonAppearance::Ghost)
            .theme_when(clone_reader(reader))
            .on_press(move || open_settings_section(&settings_shared, SettingsSection::Storage));
        content = content
            .with_child(Separator::horizontal().theme_when(clone_reader(reader)))
            .with_child(
                Flex::horizontal()
                    .wrap(FlexWrap::Wrap)
                    .gap(6.0)
                    .align_items(Alignment::Center)
                    .with_child(storage)
                    .with_child(versions)
                    .with_child(activity)
                    .with_child(mount),
            );
    }
    if !advanced_rows.is_empty() {
        content = content
            .with_child(Separator::horizontal().theme_when(clone_reader(reader)))
            .with_child(detail_rows_widget(advanced_rows, reader));
    }
    content
}

fn composed_inspector_content(shared: &Shared, reader: &ThemeReader) -> WidgetPod {
    let files = shared.files();
    let details_button = || inspector_details_button(shared, reader, files.inspector_details_open);

    if files.loading {
        let rows = sifs_loading_rows(
            &files.path,
            files.inspector_details_open,
            files.list_slow_after_secs,
        );
        return WidgetPod::new(inspector_card(
            "Loading SIFS",
            detail_rows_widget(rows, reader),
            reader,
            Some(details_button()),
            false,
        ));
    }

    if sifs_daemon_offline(shared) {
        // The listing already explains the offline daemon; keep the inspector quiet instead of
        // repeating it.
        let theme = reader();
        let mut note_style = theme.text_style(theme.palette.text_muted);
        note_style.font_size = theme.text.sm.size;
        note_style.line_height = theme.text.sm.line_height;
        return WidgetPod::new(inspector_card(
            unselected_inspector_title(files.source),
            Label::new(SIFS_OFFLINE_INSPECTOR_NOTE).text_style(note_style),
            reader,
            None,
            false,
        ));
    }

    if let Some(error) = &files.error {
        let rows = sifs_unavailable_rows(error, files.inspector_details_open);
        return WidgetPod::new(inspector_card(
            "SIFS unavailable",
            detail_rows_widget(rows, reader),
            reader,
            Some(details_button()),
            false,
        ));
    }

    if let Some(selection) = marked_selection_summary(&files) {
        let theme = reader();
        let mut summary_style = theme.text_style(theme.palette.text_muted);
        summary_style.font_size = theme.text.sm.size;
        summary_style.line_height = theme.text.sm.line_height;
        let summary_line = marked_selection_composition(&selection);
        let overview_rows = vec![
            ("Total size", marked_selection_size(&selection)),
            ("Location", files.path.clone()),
            ("Source", files.source.label().to_string()),
        ];
        let selected_body = Stack::vertical()
            .alignment(Alignment::Stretch)
            .gap(10.0)
            .with_child(Label::new(summary_line).text_style(summary_style))
            .with_child(detail_rows_widget(overview_rows, reader));
        let mut content = Stack::vertical()
            .alignment(Alignment::Stretch)
            .gap(12.0)
            .with_child(inspector_card(
                marked_entries_label(selection.count),
                selected_body,
                reader,
                Some(details_button()),
                true,
            ));

        if files.source == FilesSourceKind::Sifs {
            let (status, tone) = if selection.placement_attention_count > 0 {
                (
                    format!(
                        "{} {}",
                        selection.placement_attention_count,
                        if selection.placement_attention_count == 1 {
                            "needs attention"
                        } else {
                            "need attention"
                        }
                    ),
                    SemanticTone::Warning,
                )
            } else if selection.placement_syncing_count > 0 {
                (
                    format!("{} syncing", selection.placement_syncing_count),
                    SemanticTone::Accent,
                )
            } else if selection.placement_known_count == selection.count {
                ("Selection available".to_string(), SemanticTone::Success)
            } else {
                (
                    "Availability partly known".to_string(),
                    SemanticTone::Neutral,
                )
            };
            let rows = vec![
                ("Placement", marked_selection_placement(&selection)),
                (
                    "Metadata",
                    format!(
                        "{} of {} items loaded",
                        selection.placement_known_count, selection.count
                    ),
                ),
                (
                    "This device",
                    format!(
                        "{} of {} items available here",
                        selection.local_available_count, selection.count
                    ),
                ),
            ];
            let body = Stack::vertical()
                .alignment(Alignment::Stretch)
                .gap(8.0)
                .with_child(
                    StatusBadge::new(status)
                        .tone(tone)
                        .theme_when(clone_reader(reader)),
                )
                .with_child(detail_rows_widget(rows, reader));
            content = content.with_child(inspector_card("Availability", body, reader, None, false));
        }

        if files.inspector_details_open {
            content = content.with_child(inspector_card(
                "Selected items",
                detail_rows_widget(vec![("Paths", marked_selection_paths(&selection))], reader),
                reader,
                None,
                false,
            ));
        }
        return WidgetPod::new(content);
    }

    let Some(entry) = files.selected_entry().cloned() else {
        let body = current_location_overview(shared, reader);
        let header_action = (files.source == FilesSourceKind::Sifs).then(details_button);
        return WidgetPod::new(inspector_card(
            unselected_inspector_title(files.source),
            body,
            reader,
            header_action,
            false,
        ));
    };

    let details = files.selected_details.as_ref();
    let kind = details
        .map(|details| details.kind.as_str())
        .unwrap_or_else(|| {
            if entry.is_dir {
                "directory"
            } else if entry.is_link {
                "symlink"
            } else {
                "file"
            }
        });
    let kind_line = if files.source == FilesSourceKind::Sifs {
        sifs_compact_header_line(
            &entry,
            details,
            files.clustered,
            files.details_loading,
            files.details_error.as_deref(),
        )
    } else {
        format!("{kind} · {}", details_size(&entry, details))
    };
    let theme = reader();
    let mut kind_style = theme.text_style(theme.palette.text_muted);
    kind_style.font_size = theme.text.sm.size;
    kind_style.line_height = theme.text.sm.line_height;
    let mut selected_body = Stack::vertical()
        .alignment(Alignment::Stretch)
        .gap(10.0)
        .with_child(Label::new(kind_line).text_style(kind_style))
        .with_child(
            DetailRow::new("Path", entry.path.clone())
                .theme_when(clone_reader(reader))
                .max_value_lines(6),
        );
    let modified = match files.source {
        FilesSourceKind::Sifs => {
            details.map(|details| unix_nanos_label(details.modified_at_unix_nanos))
        }
        FilesSourceKind::Local => files
            .selected_local_details
            .as_ref()
            .and_then(|details| details.modified_at_unix_nanos)
            .map(unix_nanos_label),
    };
    if let Some(modified) = modified {
        selected_body = selected_body.with_child(
            DetailRow::new("Modified", modified)
                .theme_when(clone_reader(reader))
                .max_value_lines(2),
        );
    }
    selected_body = selected_body
        .with_child(Separator::horizontal().theme_when(clone_reader(reader)))
        .with_child(selected_item_actions(shared, reader, &entry));
    if files.attachment_loading {
        selected_body = selected_body.with_child(
            StatusBadge::new("Preparing chat attachment")
                .tone(SemanticTone::Accent)
                .theme_when(clone_reader(reader)),
        );
    } else if let Some(error) = files.attachment_error.as_deref() {
        selected_body = selected_body.with_child(
            Label::new(error.to_string()).text_style(theme.text_style(theme.palette.danger)),
        );
    }
    let selected_card = inspector_card(
        entry.name.clone(),
        selected_body,
        reader,
        Some(details_button()),
        true,
    );

    let mut content = Stack::vertical()
        .alignment(Alignment::Stretch)
        .gap(12.0)
        .with_child(selected_card);

    if !entry.is_dir {
        content = content.with_child(preview_card(
            files.source,
            files.preview_loading,
            files.preview_error.as_deref(),
            files.selected_preview.as_ref(),
            files.custom_preview.as_ref(),
            reader,
        ));
    }

    if files.source == FilesSourceKind::Local {
        let local = files.selected_local_details.as_ref();
        let status_label = local_metadata_status_label(
            files.details_loading,
            files.details_error.as_deref(),
            local,
        );
        let status_tone = local_metadata_status_tone(
            files.details_loading,
            files.details_error.as_deref(),
            local,
        );
        let mut rows = vec![("Source", "Host filesystem".to_string())];
        if let Some(local) = local {
            rows.push((
                "Permissions",
                if local.readonly {
                    "read-only".to_string()
                } else {
                    "writable".to_string()
                },
            ));
            if let Some(canonical) = &local.canonical_path
                && canonical != &local.path
            {
                rows.push(("Canonical", canonical.clone()));
            }
        } else if let Some(error) = &files.details_error {
            rows.push(("Reason", error.clone()));
        } else if files.details_loading {
            rows.push(("Status", "Reading metadata".to_string()));
        }
        let body = Stack::vertical()
            .alignment(Alignment::Stretch)
            .gap(8.0)
            .with_child(
                StatusBadge::new(status_label)
                    .tone(status_tone)
                    .theme_when(clone_reader(reader)),
            )
            .with_child(detail_rows_widget(rows, reader));
        content = content.with_child(inspector_card("Local file", body, reader, None, false));

        if files.inspector_details_open {
            let mut rows = Vec::new();
            if let Some(local) = local {
                rows.push(("Kind", local.kind.clone()));
                rows.push(("Accessed", local_time_label(local.accessed_at_unix_nanos)));
                rows.push(("Modified", local_time_label(local.modified_at_unix_nanos)));
                rows.push(("Created", local_time_label(local.created_at_unix_nanos)));
            }
            if !rows.is_empty() {
                content = content.with_child(inspector_card(
                    "Technical details",
                    detail_rows_widget(rows, reader),
                    reader,
                    None,
                    false,
                ));
            }
        }
    } else {
        let status_label = sifs_metadata_status_label(
            files.details_loading,
            files.details_error.as_deref(),
            details,
        );
        let status_tone = sifs_metadata_status_tone(
            files.details_loading,
            files.details_error.as_deref(),
            details,
        );
        let placement_rows = vec![
            (
                "Content copies",
                sifs_replication_summary(details, files.clustered),
            ),
            ("Metadata home", sifs_metadata_shard_summary(details)),
            ("Object health", sifs_health_summary(details)),
            ("This device", sifs_pin_summary(details)),
            (
                "Recommended",
                sifs_inspector_next_step(
                    details,
                    files.clustered,
                    files.details_loading,
                    files.details_error.as_deref(),
                ),
            ),
        ];
        let (live_label, live_tone) = if files.live_updates_connected {
            ("Live changes on", SemanticTone::Success)
        } else if files.live_updates_error.is_some() {
            ("Live changes reconnecting", SemanticTone::Warning)
        } else {
            ("Snapshot view", SemanticTone::Neutral)
        };
        let placement_body = Stack::vertical()
            .alignment(Alignment::Stretch)
            .gap(8.0)
            .with_child(
                StatusBadge::new(short_node_label(&files.node_id))
                    .icon(IconGlyph::Storage)
                    .tone(SemanticTone::Accent)
                    .theme_when(clone_reader(reader)),
            )
            .with_child(
                StatusBadge::new(status_label)
                    .tone(status_tone)
                    .theme_when(clone_reader(reader)),
            )
            .with_child(
                StatusBadge::new(live_label)
                    .tone(live_tone)
                    .theme_when(clone_reader(reader)),
            )
            .with_child(detail_rows_widget(placement_rows, reader));
        content = content.with_child(inspector_card(
            "Availability",
            placement_body,
            reader,
            None,
            false,
        ));

        if files.inspector_details_open {
            let mut status_rows = Vec::new();
            if let Some(error) = &files.live_updates_error {
                status_rows.push(("Live updates", error.clone()));
            }
            if let Some(error) = &files.details_error {
                status_rows.push(("Reason", error.clone()));
                status_rows.push(("Source", "SIFS through daemon".to_string()));
            } else if files.details_loading {
                status_rows.push(("Status", "Reading DFS metadata".to_string()));
            } else if details.is_none() {
                status_rows.push((
                    "Status",
                    "Metadata has not returned for this object yet".to_string(),
                ));
                status_rows.push(("Source", "SIFS through daemon".to_string()));
            }
            if !status_rows.is_empty() {
                content = content.with_child(inspector_card(
                    "DFS details",
                    detail_rows_widget(status_rows, reader),
                    reader,
                    None,
                    false,
                ));
            }

            if let Some(details) = details {
                let metadata_rows = vec![
                    ("Type", details.kind.clone()),
                    ("Size", details_size(&entry, Some(details))),
                    ("Modified", unix_nanos_label(details.modified_at_unix_nanos)),
                    ("Created", unix_nanos_label(details.created_at_unix_nanos)),
                    ("Accessed", unix_nanos_label(details.accessed_at_unix_nanos)),
                    (
                        "Permissions",
                        format!("{:04o} · {} links", details.mode, details.link_count),
                    ),
                    (
                        "Owner",
                        format!("uid {} · gid {}", details.uid, details.gid),
                    ),
                ];
                content = content.with_child(inspector_card(
                    "File metadata",
                    detail_rows_widget(metadata_rows, reader),
                    reader,
                    None,
                    false,
                ));

                let mut identity_rows = vec![
                    ("File system", details.file_system_id.clone()),
                    ("Object ID", details.object_id.clone()),
                    ("Version", details.version.clone()),
                ];
                if let Some(hash) = &details.content_hash {
                    identity_rows.push(("Content hash", hash.clone()));
                }
                content = content.with_child(inspector_card(
                    "DFS identity",
                    detail_rows_widget(identity_rows, reader),
                    reader,
                    None,
                    false,
                ));

                let mut placement_detail_rows = vec![
                    ("Policy", details.policy.clone()),
                    (
                        "Durable nodes",
                        details_locations_friendly(details, &files.node_id),
                    ),
                    ("Local pins", sifs_pin_detail_summary(details)),
                ];
                if let Some(placement) = details.placement.as_ref() {
                    placement_detail_rows.push((
                        "Managed placement",
                        format!(
                            "W={} · N={} · zones≥{}",
                            placement.policy.min_commit_replicas,
                            placement.policy.desired_replicas,
                            placement.policy.min_distinct_zones
                        ),
                    ));
                    placement_detail_rows.push(("Inheritance", placement.explanation.clone()));
                    if !placement.policy.required_node_ids.is_empty() {
                        placement_detail_rows.push((
                            "Required nodes",
                            placement
                                .policy
                                .required_node_ids
                                .iter()
                                .map(ToString::to_string)
                                .collect::<Vec<_>>()
                                .join(", "),
                        ));
                    }
                    if !placement.policy.forbidden_node_ids.is_empty() {
                        placement_detail_rows.push((
                            "Forbidden nodes",
                            placement
                                .policy
                                .forbidden_node_ids
                                .iter()
                                .map(ToString::to_string)
                                .collect::<Vec<_>>()
                                .join(", "),
                        ));
                    }
                }
                if let Some(shard) = details.metadata_shard.as_ref() {
                    placement_detail_rows
                        .push(("Metadata shard", sifs_metadata_shard_detail_summary(shard)));
                }
                if let Some(health) = details.health.as_ref() {
                    placement_detail_rows.push(("Agent state", health.agent_state.clone()));
                    placement_detail_rows.push((
                        "DFS records",
                        format!(
                            "{} · {} · {}",
                            plural(health.version_count, "version"),
                            plural(health.receipt_count, "receipt"),
                            plural(health.intent_count, "intent")
                        ),
                    ));
                    placement_detail_rows.push((
                        "Repair backlog",
                        plural(health.pending_repair_count, "missing replica"),
                    ));
                    placement_detail_rows
                        .push(("Missing nodes", sifs_missing_replica_summary(health)));
                }
                content = content.with_child(inspector_card(
                    "Placement internals",
                    detail_rows_widget(placement_detail_rows, reader),
                    reader,
                    None,
                    false,
                ));
            }
        }

        if !files.clustered {
            let mut note_style = theme.text_style(theme.palette.text_muted);
            note_style.font_size = theme.text.xs.size;
            note_style.line_height = theme.text.xs.line_height;
            content = content.with_child(
                Surface::panel(RichText::from_plain_text(
                    "Join a cluster to spread this object across nodes and tune replication.",
                    note_style,
                ))
                .appearance(sui::SurfaceAppearance::Soft)
                .tone(SemanticTone::Neutral)
                .theme_when(clone_reader(reader))
                .padding(Insets {
                    left: 12.0,
                    top: 10.0,
                    right: 12.0,
                    bottom: 10.0,
                })
                .fill_width(true),
            );
        }
    }

    WidgetPod::new(content)
}

/// Assemble the wide inspector and the compact sheet body from the same stock SUI controls.
fn inspector(
    shared: &Shared,
    reader: &ThemeReader,
    scroll_state: &ScrollState,
) -> impl Widget + use<> {
    let header = WidgetPadding::horizontal(
        CONTENT_PAD,
        SizedBox::new().height(18.0).child(
            SectionLabel::new("Selection info")
                .semantic_name("Selection info")
                .theme_when(clone_reader(reader)),
        ),
    )
    .fill_child_height(true);
    let body = WidgetPadding::new(
        sui::Insets {
            left: 0.0,
            right: 0.0,
            top: CONTENT_PAD + 4.0,
            bottom: 0.0,
        },
        Stack::vertical()
            .alignment(Alignment::Stretch)
            .gap(12.0)
            .with_child(header)
            .with_child(InspectorView::new(shared.clone())),
    )
    .fill_child_width(true);
    Surface::new(
        SurfaceRole::Sidebar,
        ScrollView::vertical(body)
            .state(scroll_state.clone())
            .name("Selection info")
            .theme_when(clone_gray_scrollbar_reader(reader))
            .viewport_width_hint(true),
    )
    .border(SurfaceBorder::Left)
    .theme_when(clone_reader(reader))
    .fill()
}

// ---------------------------------------------------------------------------
// Composed pods (wide split / narrow list-only) + responsive host.
// ---------------------------------------------------------------------------

/// The header bar wrapped so it rebuilds (breadcrumb segments and history affordances) whenever
/// navigation state changes. A fixed-height titlebar surface over a hairline separator.
fn header_bar(shared: &Shared, reader: &ThemeReader) -> impl Widget + use<> {
    let source = shared
        .signals()
        .files_structure
        .select_named("files header structure", |key| key.header.clone());
    let s = shared.clone();
    let r = Rc::clone(reader);
    let rebuilt = RebuildOnChange::key_from(source, move |_key| WidgetPod::new(header(&s, &r)));
    Surface::window(
        WidgetPadding::horizontal(CONTENT_PAD, rebuilt)
            .fill_child_width(true)
            .fill_child_height(true),
    )
    .theme_when(clone_reader(reader))
    .fill_width(true)
}

fn picker_first_header_bar(shared: &Shared, reader: &ThemeReader) -> impl Widget + use<> {
    let source = shared
        .signals()
        .files_structure
        .select_named("files picker header structure", |key| key.header.clone());
    let s = shared.clone();
    let r = Rc::clone(reader);
    let rebuilt = RebuildOnChange::key_from(source, move |_key| {
        WidgetPod::new(picker_first_header(&s, &r))
    });
    Surface::window(
        WidgetPadding::horizontal(CONTENT_PAD, rebuilt)
            .fill_child_width(true)
            .fill_child_height(true),
    )
    .theme_when(clone_reader(reader))
    .fill_width(true)
}

/// Chooses only the desktop command-row density; the surrounding wide Files body and inspector
/// stay mounted. SUI retains and focus-scopes both header variants independently of the wider
/// 640px inspector breakpoint.
fn desktop_header(shared: &Shared, reader: &ThemeReader) -> impl Widget + use<> {
    ConstraintView::new(picker_first_header_bar(shared, reader)).when(
        ConstraintQuery::new().min_width(FULL_HEADER_INNER_MIN_W + CONTENT_PAD * 2.0),
        header_bar(shared, reader),
    )
}

fn compact_header_bar(shared: &Shared, reader: &ThemeReader) -> impl Widget + use<> {
    let source = shared
        .signals()
        .files_structure
        .select_named("files compact header structure", |key| key.header.clone());
    let s = shared.clone();
    let r = Rc::clone(reader);
    let rebuilt =
        RebuildOnChange::key_from(source, move |_key| WidgetPod::new(compact_header(&s, &r)));
    Surface::window(
        WidgetPadding::new(
            Insets {
                left: 8.0,
                top: 6.0,
                right: 8.0,
                bottom: 6.0,
            },
            rebuilt,
        )
        .fill_child_width(true)
        .fill_child_height(true),
    )
    .theme_when(clone_reader(reader))
    .fill_width(true)
}

/// The file-list column switches between loading, error, empty, and populated presentations. A shared
/// `scroll_state` is threaded so the position is consistent across the wide/narrow swap.
fn list_column(
    shared: &Shared,
    reader: &ThemeReader,
    scroll_state: &ScrollState,
    contextual_selection: bool,
) -> impl Widget + use<> {
    let source = shared
        .signals()
        .files_structure
        .select_named("files column structure", |key| {
            // The populated body observes its own listing changes and retains thumbnail geometry
            // across pagination. Rebuilding it here too would discard that retained state.
            (
                key.list.theme,
                key.list.source,
                key.list.loading,
                key.list.error.clone(),
                key.list.entries.is_empty(),
                key.daemon_available,
            )
        });
    let s = shared.clone();
    let r = Rc::clone(reader);
    let ss = scroll_state.clone();
    let listing = RebuildOnChange::key_from(source, move |_key| listing(&s, &r, &ss));
    let dock = Dock::new(listing);
    if contextual_selection {
        dock.top(FILE_ACTION_BAR_H, files_action_bar(shared, reader, true))
    } else {
        dock
    }
}

/// Wide split: header docked on top, with independently resizable Locations and Inspector
/// sidebars around the file list. The native splitters retain their ratios in [`FilesState`] so a
/// theme/scale rebuild does not discard the operator's preferred widths.
fn wide_pod(
    shared: &Shared,
    reader: &ThemeReader,
    scroll_state: &ScrollState,
    places_scroll_state: &ScrollState,
    inspector_scroll_state: &ScrollState,
) -> impl Widget + use<> {
    let places_scroll = ScrollView::vertical(files_places_rail(shared, reader))
        .state(places_scroll_state.clone())
        .theme_when(clone_gray_scrollbar_reader(reader));
    let places = Background::new(Color::TRANSPARENT, places_scroll).brush_when({
        let s = shared.clone();
        move || palette(&s).sidebar
    });
    let places_ratio = shared.files().places_sidebar_ratio;
    let places_ratio_shared = shared.clone();
    let list_with_places =
        SplitView::horizontal(places, list_column(shared, reader, scroll_state, false))
            .name("File locations sidebar")
            .ratio(places_ratio)
            .min_first(PLACES_SIDEBAR_MIN_W)
            .min_second(FILE_LIST_MIN_W)
            .theme_when(clone_reader(reader))
            .on_change(move |ratio| {
                places_ratio_shared
                    .files_mut()
                    .set_places_sidebar_ratio(ratio)
            });
    let inspector_ratio = shared.files().inspector_sidebar_ratio;
    let inspector_ratio_shared = shared.clone();
    let body = SplitView::horizontal(
        list_with_places,
        inspector(shared, reader, inspector_scroll_state),
    )
    .name("Selection info sidebar")
    .ratio(1.0 - inspector_ratio)
    .min_first(PLACES_SIDEBAR_MIN_W + FILE_LIST_MIN_W)
    .min_second(INSPECTOR_SIDEBAR_MIN_W)
    .theme_when(clone_reader(reader))
    .on_change(move |ratio| {
        inspector_ratio_shared
            .files_mut()
            .set_inspector_sidebar_ratio(1.0 - ratio)
    });
    let header = Stack::vertical()
        .alignment(Alignment::Stretch)
        .with_child(
            SizedBox::new()
                .height(HEADER_H)
                .child(desktop_header(shared, reader)),
        )
        .with_child(Separator::horizontal().theme_when(clone_reader(reader)));
    Dock::new(body)
        .top(HEADER_H + 1.0, header)
        .bottom(FILES_STATUS_H, files_status_bar(shared, reader))
}

/// Narrow: compact header + list body. Commands and the inspector remain
/// reachable through overlays owned by `FilesDialogHost`.
fn narrow_pod(
    shared: &Shared,
    reader: &ThemeReader,
    scroll_state: &ScrollState,
) -> impl Widget + use<> {
    let header = Stack::vertical()
        .alignment(Alignment::Stretch)
        .with_child(
            SizedBox::new()
                .height(HEADER_H)
                .child(compact_header_bar(shared, reader)),
        )
        .with_child(Separator::horizontal().theme_when(clone_reader(reader)));
    Dock::new(list_column(shared, reader, scroll_state, true))
        .top(HEADER_H + 1.0, header)
        .bottom(FILES_STATUS_H, files_status_bar(shared, reader))
}

fn compact_command_button<E, F>(
    label: impl Into<String>,
    reader: &ThemeReader,
    enabled: E,
    on_press: F,
) -> sui::Button
where
    E: Fn() -> bool + 'static,
    F: FnMut(&mut EventCtx) + 'static,
{
    sui::Button::new(label)
        .min_height(32.0)
        .theme_when(clone_reader(reader))
        .enabled_when(enabled)
        .on_press_with_ctx(on_press)
}

fn compact_files_commands(shared: &Shared, reader: &ThemeReader) -> impl Widget + use<> {
    let forward = {
        let enabled = shared.clone();
        let action = shared.clone();
        compact_command_button(
            "Forward",
            reader,
            move || enabled.files().can_go_forward(),
            move |ctx| {
                let waker = { action.borrow().waker.clone() };
                let mut files = action.files_mut();
                files.close_compact_overlay();
                files.go_forward(waker);
                drop(files);
                request_files_overlay_rebuild(ctx);
            },
        )
    };
    let refresh = {
        let enabled = shared.clone();
        let action = shared.clone();
        compact_command_button(
            "Refresh current folder",
            reader,
            move || !enabled.files().loading,
            move |ctx| {
                let waker = { action.borrow().waker.clone() };
                let mut files = action.files_mut();
                files.close_compact_overlay();
                files.refresh(waker);
                drop(files);
                request_files_overlay_rebuild(ctx);
            },
        )
    };
    let browse_sifs = {
        let enabled = shared.clone();
        let action = shared.clone();
        compact_command_button(
            "Browse SIFS",
            reader,
            move || {
                let files = enabled.files();
                files.source != FilesSourceKind::Sifs && !files.loading
            },
            move |ctx| {
                let waker = { action.borrow().waker.clone() };
                let mut files = action.files_mut();
                files.close_compact_overlay();
                files.switch_source(FilesSourceKind::Sifs, waker);
                drop(files);
                request_files_overlay_rebuild(ctx);
            },
        )
    };
    let browse_local = {
        let enabled = shared.clone();
        let action = shared.clone();
        compact_command_button(
            "Browse local files",
            reader,
            move || {
                let files = enabled.files();
                files.source != FilesSourceKind::Local && !files.loading
            },
            move |ctx| {
                let waker = { action.borrow().waker.clone() };
                let mut files = action.files_mut();
                files.close_compact_overlay();
                files.switch_source(FilesSourceKind::Local, waker);
                drop(files);
                request_files_overlay_rebuild(ctx);
            },
        )
    };
    let open_local_file = {
        let enabled = shared.clone();
        let action = shared.clone();
        compact_command_button(
            "Open local file...",
            reader,
            move || !enabled.files().picker_lane.is_pending(),
            move |ctx| {
                let waker = { action.borrow().waker.clone() };
                let mut files = action.files_mut();
                files.close_compact_overlay();
                files.request_native_picker(FilesPickerAction::OpenFile, waker);
                drop(files);
                request_files_overlay_rebuild(ctx);
            },
        )
    };
    let open_local_folder = {
        let enabled = shared.clone();
        let action = shared.clone();
        compact_command_button(
            "Choose local folder...",
            reader,
            move || !enabled.files().picker_lane.is_pending(),
            move |ctx| {
                let waker = { action.borrow().waker.clone() };
                let mut files = action.files_mut();
                files.close_compact_overlay();
                files.request_native_picker(FilesPickerAction::OpenFolder, waker);
                drop(files);
                request_files_overlay_rebuild(ctx);
            },
        )
    };
    let import_files = {
        let enabled = shared.clone();
        let action = shared.clone();
        compact_command_button(
            "Import files...",
            reader,
            move || {
                let files = enabled.files();
                files.can_modify_current_location() && !files.picker_lane.is_pending()
            },
            move |ctx| {
                let waker = { action.borrow().waker.clone() };
                let mut files = action.files_mut();
                files.close_compact_overlay();
                files.request_native_picker(FilesPickerAction::ImportFiles, waker);
                drop(files);
                request_files_overlay_rebuild(ctx);
            },
        )
    };
    let import_folder = {
        let enabled = shared.clone();
        let action = shared.clone();
        compact_command_button(
            "Import folder...",
            reader,
            move || {
                let files = enabled.files();
                files.can_modify_current_location() && !files.picker_lane.is_pending()
            },
            move |ctx| {
                let waker = { action.borrow().waker.clone() };
                let mut files = action.files_mut();
                files.close_compact_overlay();
                files.request_native_picker(FilesPickerAction::ImportFolder, waker);
                drop(files);
                request_files_overlay_rebuild(ctx);
            },
        )
    };
    let go_to = {
        let enabled = shared.clone();
        let action = shared.clone();
        compact_command_button(
            "Go to path",
            reader,
            move || !enabled.files().loading,
            move |ctx| {
                action
                    .files_mut()
                    .open_action_prompt(FileActionPromptKind::GoTo);
                request_files_overlay_rebuild(ctx);
            },
        )
    };
    let new_file = {
        let enabled = shared.clone();
        let action = shared.clone();
        compact_command_button(
            "New file",
            reader,
            move || enabled.files().can_modify_current_location(),
            move |ctx| {
                action
                    .files_mut()
                    .open_action_prompt(FileActionPromptKind::NewFile);
                request_files_overlay_rebuild(ctx);
            },
        )
    };
    let new_folder = {
        let enabled = shared.clone();
        let action = shared.clone();
        compact_command_button(
            "New folder",
            reader,
            move || enabled.files().can_modify_current_location(),
            move |ctx| {
                action
                    .files_mut()
                    .open_action_prompt(FileActionPromptKind::NewFolder);
                request_files_overlay_rebuild(ctx);
            },
        )
    };
    let content = Stack::vertical()
        .alignment(Alignment::Stretch)
        .gap(6.0)
        .with_child(forward)
        .with_child(refresh)
        .with_child(browse_sifs)
        .with_child(browse_local)
        .with_child(open_local_file)
        .with_child(open_local_folder)
        .with_child(import_files)
        .with_child(import_folder)
        .with_child(go_to)
        .with_child(new_file)
        .with_child(new_folder);
    ScrollView::vertical(WidgetPadding::new(
        Insets {
            left: 2.0,
            top: 2.0,
            right: 8.0,
            bottom: 2.0,
        },
        content,
    ))
    .name("Compact file command overflow")
    .theme_when(clone_gray_scrollbar_reader(reader))
    .viewport_width_hint(true)
}

#[cfg(test)]
fn files_action_dialog_signature(shared: &Shared) -> String {
    let files = shared.files();
    match &files.action_prompt {
        Some(prompt) => format!(
            "{:?}|{}|{}|{}|{}|{}|{}|{}|{}|{}|{}",
            prompt.kind,
            prompt.target_path.as_deref().unwrap_or(""),
            prompt.targets.len(),
            prompt.error.as_deref().unwrap_or(""),
            files.placement_edit_revision,
            files.placement_preview_revision.unwrap_or_default(),
            files.placement_loading,
            files.placement_applying,
            files
                .placement_reconciliation
                .as_ref()
                .map_or(0, |job| job.revision),
            files.placement_preview.is_some(),
            files.placement_error.as_deref().unwrap_or(""),
        ),
        None => "closed".to_string(),
    }
}

fn go_to_path_description(source: FilesSourceKind) -> &'static str {
    match source {
        FilesSourceKind::Sifs => {
            "Open a SIFS path, e.g. /services, /users, or /sinomo/nodes/<node>/files"
        }
        FilesSourceKind::Local => {
            "Open drive, UNC, or mounted path, e.g. C:\\Users or \\\\server\\share"
        }
    }
}

fn go_to_path_placeholder(source: FilesSourceKind) -> &'static str {
    match source {
        FilesSourceKind::Sifs => "/services",
        FilesSourceKind::Local => "C:\\Users or \\\\server\\share",
    }
}

fn prompt_destination_source(
    kind: FileActionPromptKind,
    source: FilesSourceKind,
) -> Option<FilesSourceKind> {
    match kind {
        FileActionPromptKind::Copy
        | FileActionPromptKind::CopySelected
        | FileActionPromptKind::Move
        | FileActionPromptKind::MoveSelected => Some(source),
        FileActionPromptKind::CopyToSifs => Some(FilesSourceKind::Sifs),
        FileActionPromptKind::CopyToLocal => Some(FilesSourceKind::Local),
        FileActionPromptKind::TransferSelected => Some(match source {
            FilesSourceKind::Sifs => FilesSourceKind::Local,
            FilesSourceKind::Local => FilesSourceKind::Sifs,
        }),
        _ => None,
    }
}

fn destination_chooser_controls(
    shared: &Shared,
    reader: &ThemeReader,
    kind: FileActionPromptKind,
    source: FilesSourceKind,
) -> Option<Stack> {
    let destination = prompt_destination_source(kind, source)?;
    let theme = reader();
    let mut hint_style = theme.text_style(theme.palette.text_muted);
    hint_style.font_size = theme.text.sm.size;
    hint_style.line_height = theme.text.sm.line_height;
    let mut content = Stack::vertical()
        .alignment(Alignment::Stretch)
        .gap(7.0)
        .with_child(
            Label::new("Choose a destination").text_style(theme.text_style(theme.palette.text)),
        );
    if destination == FilesSourceKind::Local {
        let enabled = shared.clone();
        let action = shared.clone();
        content = content
            .with_child(
                sui::Button::new("Choose folder...")
                    .icon(IconGlyph::Folder)
                    .min_height(34.0)
                    .appearance(ButtonAppearance::Tonal)
                    .tone(SemanticTone::Accent)
                    .theme_when(clone_reader(reader))
                    .enabled_when(move || !enabled.files().picker_lane.is_pending())
                    .on_press_with_ctx(move |ctx| {
                        let waker = { action.borrow().waker.clone() };
                        action
                            .files_mut()
                            .request_native_picker(FilesPickerAction::ChooseDestination, waker);
                        request_files_overlay_rebuild(ctx);
                    }),
            )
            .with_child(
                Label::new(
                    "The selected folder is combined with the original name. You can edit the exact path below before starting.",
                )
                .text_style(hint_style),
            );
    } else {
        let choice = |label: &'static str, path: &'static str| {
            let action = shared.clone();
            sui::Button::new(label)
                .icon(IconGlyph::Folder)
                .min_height(34.0)
                .appearance(ButtonAppearance::Ghost)
                .theme_when(clone_reader(reader))
                .on_press_with_ctx(move |ctx| {
                    action.files_mut().choose_sifs_destination(path);
                    request_files_overlay_rebuild(ctx);
                })
        };
        content = content
            .with_child(
                Flex::horizontal()
                    .wrap(FlexWrap::Wrap)
                    .gap(6.0)
                    .align_items(Alignment::Center)
                    .with_child(choice("Sinomo root", "/"))
                    .with_child(choice("Services", "/services"))
                    .with_child(choice("Users", "/users")),
            )
            .with_child(
                Label::new(
                    "Choose a common Sinomo space, then edit the exact folder or name below if needed.",
                )
                .text_style(hint_style),
            );
    }
    Some(content)
}

fn placement_preview_rows(preview: &SifsPlacementPreview) -> Vec<(&'static str, String)> {
    let policy = &preview.resolved.policy;
    let consistency = match &policy.consistency {
        sinomo_runtime::core::DfsObjectPolicy::ReplicatedConfirmed => "replicated-confirmed",
        sinomo_runtime::core::DfsObjectPolicy::ReplicatedEventual => "replicated-eventual",
        sinomo_runtime::core::DfsObjectPolicy::LocalOwned => "local-owned",
        sinomo_runtime::core::DfsObjectPolicy::EphemeralLocal => "ephemeral-local",
        sinomo_runtime::core::DfsObjectPolicy::AppendOnly => "append-only",
    };
    vec![
        (
            "Resolved",
            format!(
                "{consistency} · W={} · N={} · zones≥{}",
                policy.min_commit_replicas, policy.desired_replicas, policy.min_distinct_zones
            ),
        ),
        ("Inheritance", preview.resolved.explanation.clone()),
    ]
}

fn placement_draft_rows(draft: &PlacementEditorDraft) -> Vec<(&'static str, String)> {
    let scope = match draft.scope {
        SifsPlacementScope::SelfOnly => "This object",
        SifsPlacementScope::Subtree => "This folder and descendants",
    };
    let Some(policy) = draft.active_policy() else {
        return vec![
            ("Selected scope", scope.to_string()),
            (
                "Draft",
                "Exact values unavailable from the connected daemon".to_string(),
            ),
        ];
    };
    let action = if policy.inherit && draft.active_has_exact_rule() {
        "Remove the exact rule and inherit"
    } else if policy.inherit {
        "No exact rule; inherits effective values"
    } else if draft.has_actionable_change() {
        "Create or update the exact rule"
    } else {
        "Existing exact rule; no changes yet"
    };
    vec![
        ("Selected scope", scope.to_string()),
        (
            "Draft policy",
            format!(
                "{} · W={} · N={} · zones≥{}",
                policy.consistency.label(),
                policy.min_commit_replicas,
                policy.desired_replicas,
                policy.min_distinct_zones
            ),
        ),
        ("On Apply", action.to_string()),
    ]
}

fn placement_reconciliation_rows(
    job: &SifsPlacementReconciliationJob,
) -> Vec<(&'static str, String)> {
    let (completed, total) = job.progress_fraction();
    let percent = completed
        .saturating_mul(100)
        .checked_div(total)
        .unwrap_or(0);
    let mut rows = vec![
        ("Reconciliation", format!("{:?} · {percent}%", job.state)),
        (
            "Objects",
            format!(
                "{} scanned · {} matched · {} updated",
                job.scanned_object_count, job.matched_object_count, job.updated_object_count
            ),
        ),
        (
            "Repairs",
            format!(
                "{} completed · {} pending",
                job.completed_repair_count, job.pending_repair_count
            ),
        ),
    ];
    if let Some(error) = job.last_error.as_ref() {
        rows.push((
            if job.state.is_terminal() {
                "Result"
            } else {
                "Retrying"
            },
            error.clone(),
        ));
    }
    rows
}

/// Retained checkbox whose model can also be changed by its mutually-exclusive sibling.
struct PlacementSyncedCheckbox {
    inner: Checkbox,
    checked_reader: Box<dyn Fn() -> bool>,
    semantic_name: String,
}

impl PlacementSyncedCheckbox {
    fn new(
        inner: Checkbox,
        checked_reader: impl Fn() -> bool + 'static,
        semantic_name: impl Into<String>,
    ) -> Self {
        Self {
            inner,
            checked_reader: Box::new(checked_reader),
            semantic_name: semantic_name.into(),
        }
    }

    fn sync_checked(&mut self) {
        let checked = (self.checked_reader)();
        if self.inner.is_checked() != checked {
            self.inner.set_checked(checked);
        }
    }
}

impl Widget for PlacementSyncedCheckbox {
    fn event(&mut self, ctx: &mut EventCtx, event: &Event) {
        self.sync_checked();
        self.inner.event(ctx, event);
    }

    fn measure(&mut self, ctx: &mut MeasureCtx, constraints: Constraints) -> Size {
        self.sync_checked();
        self.inner.measure(ctx, constraints)
    }

    fn paint(&self, ctx: &mut PaintCtx) {
        self.inner.paint(ctx);
    }

    fn semantics(&self, ctx: &mut SemanticsCtx) {
        let mut node = SemanticsNode::new(ctx.widget_id(), SemanticsRole::CheckBox, ctx.bounds());
        node.name = Some(self.semantic_name.clone());
        node.state.focused = ctx.is_focused();
        node.state.checked = Some(if self.inner.is_checked() {
            ToggleState::Checked
        } else {
            ToggleState::Unchecked
        });
        node.actions = vec![SemanticsAction::Focus, SemanticsAction::Activate];
        ctx.push(node);
    }

    fn accepts_focus(&self) -> bool {
        self.inner.accepts_focus()
    }

    fn focus_changed(&mut self, ctx: &mut EventCtx, focused: bool) {
        self.inner.focus_changed(ctx, focused);
    }
}

fn placement_impact_widget(preview: &SifsPlacementPreview, reader: &ThemeReader) -> Stack {
    if !preview.supports_safe_apply() {
        return Stack::vertical().with_child(
            StatusBadge::new(
                "Impact totals are unavailable because the connected daemon returned a legacy placement preview",
            )
            .icon(IconGlyph::Alert)
            .tone(SemanticTone::Danger)
            .theme_when(clone_reader(reader)),
        );
    }
    let impact = &preview.impact;
    let byte_value = if impact.unknown_size_object_count == 0 {
        human_size(Some(impact.affected_bytes))
    } else {
        format!(
            "{} + {} unknown",
            human_size(Some(impact.affected_bytes)),
            impact.unknown_size_object_count
        )
    };
    let cards = [
        ("Affected objects", impact.affected_object_count.to_string()),
        ("Affected bytes", byte_value),
        ("Copies added", impact.copies_added.to_string()),
        ("Copies removed", impact.copies_removed.to_string()),
    ]
    .into_iter()
    .fold(
        Flex::horizontal()
            .wrap(FlexWrap::Wrap)
            .gap(10.0)
            .align_items(Alignment::Stretch),
        |row, (label, value)| {
            row.with_item(
                Surface::panel(
                    DetailRow::new(label, value)
                        .theme_when(clone_reader(reader))
                        .max_value_lines(2),
                )
                .padding(Insets::all(10.0))
                .theme_when(clone_reader(reader))
                .fill_width(true),
                FlexItem::flex(1.0)
                    .basis_gap_aware_fraction(0.5)
                    .min_width(150.0),
            )
        },
    );
    let mut content = Stack::vertical()
        .alignment(Alignment::Stretch)
        .gap(8.0)
        .with_child(cards);
    if !impact.complete {
        content = content.with_child(
            StatusBadge::new(
                "Impact totals are partial because at least one policy cannot currently be satisfied",
            )
            .icon(IconGlyph::Alert)
            .tone(SemanticTone::Warning)
            .theme_when(clone_reader(reader)),
        );
    }
    content
}

fn placement_node_status(
    node: &sinomo_runtime::dfs::DfsPlacementNodePreview,
) -> (&'static str, SemanticTone) {
    match (node.current_replica, node.desired_replica) {
        (true, true) => ("Keep", SemanticTone::Success),
        (false, true) => ("Add", SemanticTone::Accent),
        (true, false) => ("Remove", SemanticTone::Warning),
        (false, false) => ("Standby", SemanticTone::Neutral),
    }
}

fn placement_current_status(
    node: &sinomo_runtime::dfs::DfsPlacementNodePreview,
) -> (&'static str, SemanticTone) {
    if node.current_replica {
        ("Stored", SemanticTone::Success)
    } else {
        ("Not stored", SemanticTone::Neutral)
    }
}

fn placement_reachability(
    reachability: sinomo_runtime::dfs::DfsPlacementNodeReachability,
) -> (&'static str, SemanticTone) {
    match reachability {
        sinomo_runtime::dfs::DfsPlacementNodeReachability::Local => {
            ("This node", SemanticTone::Success)
        }
        sinomo_runtime::dfs::DfsPlacementNodeReachability::Reachable => {
            ("Reachable", SemanticTone::Success)
        }
        sinomo_runtime::dfs::DfsPlacementNodeReachability::Unreachable => {
            ("Unavailable", SemanticTone::Danger)
        }
        sinomo_runtime::dfs::DfsPlacementNodeReachability::Unknown => {
            ("Unknown", SemanticTone::Neutral)
        }
    }
}

fn placement_node_row(
    shared: &Shared,
    reader: &ThemeReader,
    node: &sinomo_runtime::dfs::DfsPlacementNodePreview,
) -> SemanticRegion {
    let node_id_text = node.node_id.to_string();
    let constraints_locked = {
        let files = shared.files();
        files.placement_editor_locked()
            || !files
                .placement_draft
                .as_ref()
                .and_then(PlacementEditorDraft::active_policy)
                .is_some_and(|policy| policy.consistency.is_editable())
    };
    let required_action_id = node.node_id.clone();
    let required_reader_id = node.node_id.clone();
    let required = {
        let checked = shared.clone();
        let changed = shared.clone();
        let checkbox = Checkbox::new("Required")
            .checked(node.required)
            .theme_when(clone_reader(reader))
            .on_change(move |on| {
                let waker = { changed.borrow().waker.clone() };
                changed
                    .files_mut()
                    .set_placement_node_required(required_action_id.clone(), on);
                if let Some(waker) = waker {
                    waker.wake();
                }
            });
        PlacementSyncedCheckbox::new(
            checkbox,
            move || {
                checked
                    .files()
                    .placement_draft
                    .as_ref()
                    .and_then(PlacementEditorDraft::active_policy)
                    .is_some_and(|draft| draft.required_node_ids.contains(&required_reader_id))
            },
            format!("Require node {node_id_text}"),
        )
    };
    let forbidden_action_id = node.node_id.clone();
    let forbidden_reader_id = node.node_id.clone();
    let forbidden = {
        let checked = shared.clone();
        let changed = shared.clone();
        let checkbox = Checkbox::new("Forbidden")
            .checked(node.forbidden)
            .theme_when(clone_reader(reader))
            .on_change(move |on| {
                let waker = { changed.borrow().waker.clone() };
                changed
                    .files_mut()
                    .set_placement_node_forbidden(forbidden_action_id.clone(), on);
                if let Some(waker) = waker {
                    waker.wake();
                }
            });
        PlacementSyncedCheckbox::new(
            checkbox,
            move || {
                checked
                    .files()
                    .placement_draft
                    .as_ref()
                    .and_then(PlacementEditorDraft::active_policy)
                    .is_some_and(|draft| draft.forbidden_node_ids.contains(&forbidden_reader_id))
            },
            format!("Forbid node {node_id_text}"),
        )
    };
    let (reachability, reachability_tone) = placement_reachability(node.reachability);
    let (current, current_tone) = placement_current_status(node);
    let (desired, desired_tone) = placement_node_status(node);
    let capacity = if node.capacity_weight == 0 {
        "—".to_string()
    } else {
        format!("{}× weight", node.capacity_weight)
    };
    let theme = reader();
    let mut explanation_style = theme.text_style(theme.palette.text_muted);
    explanation_style.font_size = theme.text.xs.size;
    explanation_style.line_height = theme.text.xs.line_height;
    let mut row = Flex::horizontal()
        .gap(8.0)
        .align_items(Alignment::Center)
        .with_item(
            Stack::vertical()
                .gap(2.0)
                .with_child(Label::new(short_node_label(&node_id_text)).theme(reader()))
                .with_child(
                    Label::new(if node.accepts_content {
                        "Content eligible"
                    } else {
                        "Not content eligible"
                    })
                    .theme(reader()),
                ),
            FlexItem::fixed(140.0),
        )
        .with_item(
            Label::new(
                node.zone
                    .clone()
                    .unwrap_or_else(|| "Unassigned".to_string()),
            )
            .theme(reader()),
            FlexItem::fixed(80.0),
        )
        .with_item(
            StatusBadge::new(reachability)
                .tone(reachability_tone)
                .theme_when(clone_reader(reader)),
            FlexItem::fixed(104.0),
        )
        .with_item(
            Label::new(capacity.clone()).theme(reader()),
            FlexItem::fixed(78.0),
        )
        .with_item(
            StatusBadge::new(current)
                .tone(current_tone)
                .theme_when(clone_reader(reader)),
            FlexItem::fixed(88.0),
        )
        .with_item(
            StatusBadge::new(desired)
                .tone(desired_tone)
                .theme_when(clone_reader(reader)),
            FlexItem::fixed(84.0),
        );
    if constraints_locked {
        row = row
            .with_item(
                Label::new(if node.required { "Required" } else { "—" }).theme(reader()),
                FlexItem::fixed(92.0),
            )
            .with_item(
                Label::new(if node.forbidden { "Forbidden" } else { "—" }).theme(reader()),
                FlexItem::fixed(98.0),
            );
    } else {
        row = row
            .with_item(required, FlexItem::fixed(92.0))
            .with_item(forbidden, FlexItem::fixed(98.0));
    }
    row = row.with_item(
        RichText::from_plain_text(node.explanation.clone(), explanation_style),
        FlexItem::flex(1.0).basis(190.0).min_width(150.0),
    );
    let description = format!(
        "Node {node_id_text}; zone {}; {reachability}; capacity {capacity}; current {current}; desired {desired}; required {}; forbidden {}; {}",
        node.zone.as_deref().unwrap_or("unassigned"),
        node.required,
        node.forbidden,
        node.explanation
    );
    SemanticRegion::new(
        format!("Placement node {node_id_text}"),
        Surface::panel(WidgetPadding::new(Insets::all(8.0), row))
            .theme_when(clone_reader(reader))
            .fill_width(true),
    )
    .role(SemanticsRole::ListItem)
    .description(description)
}

fn placement_node_table(
    shared: &Shared,
    reader: &ThemeReader,
    preview: &SifsPlacementPreview,
) -> SemanticRegion {
    let editor_nodes = placement_editor_nodes(shared, preview);
    let header = WidgetPadding::new(
        Insets {
            left: 8.0,
            right: 8.0,
            top: 2.0,
            bottom: 2.0,
        },
        Flex::horizontal()
            .gap(8.0)
            .align_items(Alignment::Center)
            .with_item(
                SectionLabel::new("Node").theme_when(clone_reader(reader)),
                FlexItem::fixed(140.0),
            )
            .with_item(
                SectionLabel::new("Zone").theme_when(clone_reader(reader)),
                FlexItem::fixed(80.0),
            )
            .with_item(
                SectionLabel::new("Reachability").theme_when(clone_reader(reader)),
                FlexItem::fixed(104.0),
            )
            .with_item(
                SectionLabel::new("Capacity").theme_when(clone_reader(reader)),
                FlexItem::fixed(78.0),
            )
            .with_item(
                SectionLabel::new("Current").theme_when(clone_reader(reader)),
                FlexItem::fixed(88.0),
            )
            .with_item(
                SectionLabel::new("Desired").theme_when(clone_reader(reader)),
                FlexItem::fixed(84.0),
            )
            .with_item(
                SectionLabel::new("Required").theme_when(clone_reader(reader)),
                FlexItem::fixed(92.0),
            )
            .with_item(
                SectionLabel::new("Forbidden").theme_when(clone_reader(reader)),
                FlexItem::fixed(98.0),
            )
            .with_item(
                SectionLabel::new("Explanation").theme_when(clone_reader(reader)),
                FlexItem::flex(1.0).basis(190.0).min_width(150.0),
            ),
    );
    let mut rows = Stack::vertical()
        .alignment(Alignment::Stretch)
        .gap(4.0)
        .with_child(header);
    for node in &editor_nodes {
        rows = rows.with_child(placement_node_row(shared, reader, node));
    }
    SemanticRegion::new("Placement nodes", rows)
        .role(SemanticsRole::List)
        .description(format!("{} placement candidate nodes", editor_nodes.len()))
}

fn placement_editor_nodes(
    shared: &Shared,
    preview: &SifsPlacementPreview,
) -> Vec<sinomo_runtime::dfs::DfsPlacementNodePreview> {
    let active_constraints = {
        let files = shared.files();
        files
            .placement_draft
            .as_ref()
            .and_then(PlacementEditorDraft::active_policy)
            .map(|policy| {
                (
                    policy.required_node_ids.clone(),
                    policy.forbidden_node_ids.clone(),
                )
            })
    };
    let mut nodes = preview.nodes.clone();
    let Some((required_node_ids, forbidden_node_ids)) = active_constraints else {
        return nodes;
    };

    let mut visible_node_ids = BTreeSet::new();
    for node in &mut nodes {
        visible_node_ids.insert(node.node_id.clone());
        // Current/desired columns describe the selected path object, while the
        // constraint columns always describe the scope being edited.
        node.required = required_node_ids.contains(&node.node_id);
        node.forbidden = forbidden_node_ids.contains(&node.node_id);
    }
    let referenced_node_ids = required_node_ids
        .union(&forbidden_node_ids)
        .cloned()
        .collect::<BTreeSet<_>>();
    for node_id in referenced_node_ids {
        if !visible_node_ids.insert(node_id.clone()) {
            continue;
        }
        let required = required_node_ids.contains(&node_id);
        let forbidden = forbidden_node_ids.contains(&node_id);
        let constraint = if required { "required" } else { "forbidden" };
        nodes.push(sinomo_runtime::dfs::DfsPlacementNodePreview {
            node_id,
            zone: None,
            capacity_weight: 0,
            accepts_content: false,
            reachability: sinomo_runtime::dfs::DfsPlacementNodeReachability::Unknown,
            current_replica: false,
            desired_replica: false,
            preferred_for_commit: false,
            required,
            forbidden,
            storage_health: None,
            storage_freshness: None,
            usable_capacity_bytes: None,
            reserved_free_bytes: None,
            path_state: None,
            path_latency_micros: None,
            path_throughput_bytes_per_second: None,
            path_metering: None,
            observation_freshness: None,
            explanation: format!(
                "{constraint} by the selected scope; this preview has no content advertisement or replica metadata for the node"
            ),
        });
    }
    nodes.sort_by(|left, right| left.node_id.cmp(&right.node_id));
    nodes
}

fn placement_diagnostics_widget(
    preview: &SifsPlacementPreview,
    preview_is_current: bool,
    reader: &ThemeReader,
) -> Option<SemanticRegion> {
    let legacy_preview = !preview.supports_safe_apply();
    if !legacy_preview && preview.blocking_diagnostics.is_empty() && preview.warnings.is_empty() {
        return None;
    }
    let mut rows = Stack::vertical().alignment(Alignment::Stretch).gap(6.0);
    if legacy_preview {
        let message = "This daemon returned a legacy preview without reachability, policy-diagnostic, and impact safety data. Upgrade or restart the daemon before applying placement.";
        rows = rows.with_child(
            StatusBadge::new(if preview_is_current {
                message.to_string()
            } else {
                format!("Previous preview (stale): {message}")
            })
            .icon(IconGlyph::Alert)
            .tone(if preview_is_current {
                SemanticTone::Danger
            } else {
                SemanticTone::Warning
            })
            .theme_when(clone_reader(reader)),
        );
    }
    for diagnostic in &preview.blocking_diagnostics {
        let message = diagnostic.message();
        rows = rows.with_child(
            StatusBadge::new(if preview_is_current {
                message
            } else {
                format!("Previous preview (stale): {message}")
            })
            .icon(IconGlyph::Alert)
            .tone(if preview_is_current {
                SemanticTone::Danger
            } else {
                SemanticTone::Warning
            })
            .theme_when(clone_reader(reader)),
        );
    }
    for warning in &preview.warnings {
        rows = rows.with_child(
            StatusBadge::new(if preview_is_current {
                warning.clone()
            } else {
                format!("Previous preview (stale): {warning}")
            })
            .icon(IconGlyph::Alert)
            .tone(if preview_is_current {
                SemanticTone::Warning
            } else {
                SemanticTone::Neutral
            })
            .theme_when(clone_reader(reader)),
        );
    }
    Some(
        SemanticRegion::new(
            if preview_is_current {
                "Placement policy warnings"
            } else {
                "Previous placement policy warnings"
            },
            rows,
        )
        .role(SemanticsRole::Text)
        .description(if preview_is_current {
            "Resolve blocking placement policy warnings before applying"
        } else {
            "Warnings from a stale placement preview; preview the current draft before applying"
        }),
    )
}

fn placement_scope_control(
    shared: &Shared,
    reader: &ThemeReader,
    target_is_dir: bool,
) -> SegmentedControl {
    let selected = shared.clone();
    let changed = shared.clone();
    let (self_known, subtree_known) =
        shared
            .files()
            .placement_draft
            .as_ref()
            .map_or((false, false), |draft| {
                (
                    draft.scope_is_known(SifsPlacementScope::SelfOnly),
                    draft.scope_is_known(SifsPlacementScope::Subtree),
                )
            });
    let mut self_item = SegmentedControlItem::new("This object")
        .semantic_name("Self placement scope")
        .description("Inspect or edit the rule applying only to the selected object");
    if !self_known {
        self_item = self_item
            .description(
                "Exact self-only values were not returned by this daemon; refresh after upgrading the daemon",
            )
            .enabled(false);
    }
    let subtree = if target_is_dir && subtree_known {
        SegmentedControlItem::new("This folder + descendants")
            .semantic_name("Subtree placement scope")
            .description("Inspect or edit the rule applying to this folder and descendants")
    } else if target_is_dir {
        SegmentedControlItem::new("This folder + descendants")
            .semantic_name("Subtree placement scope")
            .description(
                "Exact subtree values were not returned by this daemon; refresh after upgrading the daemon",
            )
            .enabled(false)
    } else {
        SegmentedControlItem::new("This folder + descendants")
            .semantic_name("Subtree placement scope")
            .description("Subtree scope is available only for folders")
            .enabled(false)
    };
    SegmentedControl::new("Placement scope")
        .items([self_item, subtree])
        .selected_when(move || {
            Some(
                selected
                    .files()
                    .placement_draft
                    .as_ref()
                    .map_or(0, |draft| {
                        usize::from(draft.scope == SifsPlacementScope::Subtree)
                    }),
            )
        })
        .theme_when(clone_reader(reader))
        .on_change_with_ctx(move |ctx, index, _label| {
            changed.files_mut().set_placement_scope(if index == 1 {
                SifsPlacementScope::Subtree
            } else {
                SifsPlacementScope::SelfOnly
            });
            request_files_overlay_rebuild(ctx);
        })
}

fn placement_user_preview_rows(preview: &SifsPlacementPreview) -> Vec<(&'static str, String)> {
    let policy = &preview.resolved.policy;
    let mode = match &policy.consistency {
        sinomo_runtime::core::DfsObjectPolicy::ReplicatedConfirmed => {
            "Confirmed copies before publishing"
        }
        sinomo_runtime::core::DfsObjectPolicy::ReplicatedEventual => {
            "Available while remaining copies finish"
        }
        sinomo_runtime::core::DfsObjectPolicy::LocalOwned => "Only on its owning device",
        sinomo_runtime::core::DfsObjectPolicy::EphemeralLocal => "Temporary on this device",
        sinomo_runtime::core::DfsObjectPolicy::AppendOnly => "Append-only storage",
    };
    let publish = if matches!(
        policy.consistency,
        sinomo_runtime::core::DfsObjectPolicy::ReplicatedConfirmed
    ) {
        format!("After all {} copies are durable", policy.desired_replicas)
    } else {
        format!(
            "After {} of {} copies are durable",
            policy.min_commit_replicas, policy.desired_replicas
        )
    };
    vec![
        ("Availability", mode.to_string()),
        ("Publishing", publish),
        (
            "Device spread",
            if policy.min_distinct_zones == 0 {
                "No zone minimum".to_string()
            } else {
                format!("At least {} zones", policy.min_distinct_zones)
            },
        ),
    ]
}

fn placement_goal_control(shared: &Shared, reader: &ThemeReader) -> Stack {
    let editable = shared
        .files()
        .placement_draft
        .as_ref()
        .and_then(PlacementEditorDraft::active_policy)
        .is_some_and(|policy| policy.consistency.is_editable());
    let item = |label: &'static str, name: &'static str, description: &'static str| {
        let item = SegmentedControlItem::new(label)
            .semantic_name(name)
            .description(description);
        if editable { item } else { item.enabled(false) }
    };
    let selected = shared.clone();
    let changed = shared.clone();
    let control = SegmentedControl::new("Availability goal")
        .items([
            item(
                "Use folder default",
                "Use inherited availability",
                "Follow the nearest folder availability rule",
            ),
            item(
                "Across devices",
                "Available across devices",
                "Publish after the required copies are durable, then continue toward the desired copy count",
            ),
            item(
                "Confirmed copies",
                "Confirmed availability",
                "Publish only after every desired copy is durable",
            ),
        ])
        .selected_when(move || {
            Some(
                selected
                    .files()
                    .placement_draft
                    .as_ref()
                    .and_then(PlacementEditorDraft::active_policy)
                    .map_or(0, |policy| {
                        if policy.inherit {
                            0
                        } else if policy.consistency == PlacementEditorConsistency::Confirmed {
                            2
                        } else {
                            1
                        }
                    }),
            )
        })
        .theme_when(clone_reader(reader))
        .on_change_with_ctx(move |ctx, index, _label| {
            changed.files_mut().set_placement_goal(index);
            request_files_overlay_rebuild(ctx);
        });
    let theme = reader();
    let mut hint_style = theme.text_style(theme.palette.text_muted);
    hint_style.font_size = theme.text.sm.size;
    hint_style.line_height = theme.text.sm.line_height;
    Stack::vertical()
        .alignment(Alignment::Stretch)
        .gap(7.0)
        .with_child(control)
        .with_child(
            Label::new(
                "Across devices favors responsiveness; Confirmed copies waits for the complete copy set before publishing a write.",
            )
            .text_style(hint_style),
        )
}

fn placement_policy_controls(shared: &Shared, reader: &ThemeReader, _target_is_dir: bool) -> Stack {
    if shared.files().placement_editor_locked() {
        let applying = shared.files().placement_applying;
        let rows = shared
            .files()
            .placement_draft
            .as_ref()
            .and_then(|draft| draft.active_policy().map(|policy| (draft, policy)))
            .map(|(draft, policy)| {
                vec![
                    ("Consistency", policy.consistency.label().to_string()),
                    (
                        "W / N / zones",
                        format!(
                            "{} / {} / {}",
                            policy.min_commit_replicas,
                            policy.desired_replicas,
                            policy.min_distinct_zones
                        ),
                    ),
                    (
                        "Scope",
                        match draft.scope {
                            SifsPlacementScope::SelfOnly => "This object".to_string(),
                            SifsPlacementScope::Subtree => {
                                "This folder and descendants".to_string()
                            }
                        },
                    ),
                ]
            })
            .unwrap_or_default();
        return Stack::vertical()
            .alignment(Alignment::Stretch)
            .gap(8.0)
            .with_child(
                StatusBadge::new(if applying {
                    "Policy controls are locked until Apply finishes"
                } else {
                    "Policy controls are locked while SIFS reconciles existing objects"
                })
                .tone(SemanticTone::Info)
                .theme_when(clone_reader(reader)),
            )
            .with_child(detail_rows_widget(rows, reader));
    }

    if let Some(reason) = shared
        .files()
        .placement_draft
        .as_ref()
        .and_then(PlacementEditorDraft::active_policy)
        .and_then(|draft| draft.consistency.policy().err())
    {
        return Stack::vertical()
            .alignment(Alignment::Stretch)
            .gap(8.0)
            .with_child(
                StatusBadge::new(reason)
                    .icon(IconGlyph::Alert)
                    .tone(SemanticTone::Warning)
                    .theme_when(clone_reader(reader)),
            )
            .with_child(
                Label::new(
                    "The current non-replicated policy is shown read-only. Use the DFS administration surface for an explicit data migration.",
                )
                .theme(reader()),
            );
    }

    let consistency = {
        let selected = shared.clone();
        let changed = shared.clone();
        SegmentedControl::new("Placement consistency")
            .items([
                SegmentedControlItem::new("Eventual")
                    .semantic_name("Eventual placement")
                    .description(
                        "A write is visible after W durable copies; repair continues toward N",
                    ),
                SegmentedControlItem::new("Confirmed")
                    .semantic_name("Confirmed placement")
                    .description("A write is visible only after all N desired copies are durable"),
            ])
            .selected_when(move || {
                Some(
                    selected
                        .files()
                        .placement_draft
                        .as_ref()
                        .and_then(PlacementEditorDraft::active_policy)
                        .map_or(0, |draft| {
                            usize::from(draft.consistency == PlacementEditorConsistency::Confirmed)
                        }),
                )
            })
            .theme_when(clone_reader(reader))
            .on_change_with_ctx(move |ctx, index, _label| {
                changed
                    .files_mut()
                    .set_placement_consistency(if index == 1 {
                        PlacementEditorConsistency::Confirmed
                    } else {
                        PlacementEditorConsistency::Eventual
                    });
                request_files_overlay_rebuild(ctx);
            })
    };

    let candidate_limit = shared.files().placement_candidate_limit();
    let (confirmed, desired_limit, desired_minimum) = shared
        .files()
        .placement_draft
        .as_ref()
        .and_then(PlacementEditorDraft::active_policy)
        .map_or((false, 1, 1), |draft| {
            (
                draft.consistency == PlacementEditorConsistency::Confirmed,
                draft.desired_replicas.max(1),
                1_usize
                    .max(draft.required_node_ids.len())
                    .max(draft.min_distinct_zones),
            )
        });
    let min_commit = {
        let value = shared.clone();
        let changed = shared.clone();
        NumberInput::new("Minimum write replicas W")
            .range(1.0, desired_limit as f64)
            .step(1.0)
            .precision(0)
            .value_when(move || {
                value
                    .files()
                    .placement_draft
                    .as_ref()
                    .and_then(PlacementEditorDraft::active_policy)
                    .map_or(1.0, |draft| draft.min_commit_replicas as f64)
            })
            .theme_when(clone_reader(reader))
            .on_change(move |value| {
                let waker = { changed.borrow().waker.clone() };
                changed
                    .files_mut()
                    .set_placement_min_commit_replicas(value.round().max(1.0) as usize);
                if let Some(waker) = waker {
                    waker.wake();
                }
            })
    };
    let desired = {
        let value = shared.clone();
        let changed = shared.clone();
        NumberInput::new("Desired replicas N")
            .range(
                desired_minimum as f64,
                candidate_limit.max(desired_minimum) as f64,
            )
            .step(1.0)
            .precision(0)
            .value_when(move || {
                value
                    .files()
                    .placement_draft
                    .as_ref()
                    .and_then(PlacementEditorDraft::active_policy)
                    .map_or(1.0, |draft| draft.desired_replicas as f64)
            })
            .theme_when(clone_reader(reader))
            .on_change(move |value| {
                let waker = { changed.borrow().waker.clone() };
                changed.files_mut().set_placement_desired_replicas(
                    value.round().max(desired_minimum as f64) as usize,
                );
                if let Some(waker) = waker {
                    waker.wake();
                }
            })
    };
    let zones = {
        let value = shared.clone();
        let changed = shared.clone();
        NumberInput::new("Minimum distinct zones")
            .range(0.0, desired_limit as f64)
            .step(1.0)
            .precision(0)
            .value_when(move || {
                value
                    .files()
                    .placement_draft
                    .as_ref()
                    .and_then(PlacementEditorDraft::active_policy)
                    .map_or(0.0, |draft| draft.min_distinct_zones as f64)
            })
            .theme_when(clone_reader(reader))
            .on_change(move |value| {
                let waker = { changed.borrow().waker.clone() };
                changed
                    .files_mut()
                    .set_placement_min_distinct_zones(value.round().max(0.0) as usize);
                if let Some(waker) = waker {
                    waker.wake();
                }
            })
    };
    let write_threshold = if confirmed {
        Stack::vertical()
            .gap(4.0)
            .with_child(Label::new("Write threshold (W)").theme(reader()))
            .with_child(
                SizedBox::new().width(152.0).child(
                    StatusBadge::new(format!("W = {desired_limit}"))
                        .tone(SemanticTone::Accent)
                        .theme_when(clone_reader(reader)),
                ),
            )
            .with_child(Label::new("Confirmed keeps W equal to N").theme(reader()))
    } else {
        Stack::vertical()
            .gap(4.0)
            .with_child(Label::new("Write threshold (W)").theme(reader()))
            .with_child(SizedBox::new().width(152.0).child(min_commit))
            .with_child(Label::new("Copies required before visibility").theme(reader()))
    };
    let counts = Flex::horizontal()
        .wrap(FlexWrap::Wrap)
        .gap(12.0)
        .align_items(Alignment::Start)
        .with_item(write_threshold, FlexItem::fixed(230.0))
        .with_item(
            Stack::vertical()
                .gap(4.0)
                .with_child(Label::new("Desired copies (N)").theme(reader()))
                .with_child(SizedBox::new().width(152.0).child(desired))
                .with_child(Label::new("Durable target after repair").theme(reader())),
            FlexItem::fixed(230.0),
        )
        .with_item(
            Stack::vertical()
                .gap(4.0)
                .with_child(Label::new("Zone diversity").theme(reader()))
                .with_child(SizedBox::new().width(152.0).child(zones))
                .with_child(Label::new("0 disables the zone constraint").theme(reader())),
            FlexItem::fixed(230.0),
        );

    let inheritance = StatusBadge::new("Explicit override")
        .label_when({
            let shared = shared.clone();
            move || {
                let files = shared.files();
                let Some(draft) = files.placement_draft.as_ref() else {
                    return "Placement policy unavailable".to_string();
                };
                let Some(policy) = draft.active_policy() else {
                    return "Exact policy unavailable from this daemon".to_string();
                };
                if policy.inherit && draft.active_has_exact_rule() {
                    "Will remove this scope's explicit rule".to_string()
                } else if policy.inherit {
                    "No explicit rule for this scope · showing inherited values".to_string()
                } else if draft.has_actionable_change() {
                    "Edited explicit override".to_string()
                } else {
                    "Existing explicit rule · change a field or choose inheritance".to_string()
                }
            }
        })
        .tone_when({
            let shared = shared.clone();
            move || {
                if shared
                    .files()
                    .placement_draft
                    .as_ref()
                    .is_some_and(|draft| draft.active_policy().is_some_and(|policy| policy.inherit))
                {
                    SemanticTone::Neutral
                } else {
                    SemanticTone::Accent
                }
            }
        })
        .theme_when(clone_reader(reader));

    Stack::vertical()
        .alignment(Alignment::Stretch)
        .gap(10.0)
        .with_child(consistency)
        .with_child(counts)
        .with_child(inheritance)
}

fn placement_preview_status(shared: &Shared, reader: &ThemeReader) -> StatusBadge {
    StatusBadge::new("Preview required")
        .label_when({
            let shared = shared.clone();
            move || {
                let files = shared.files();
                if files.placement_applying {
                    "Applying policy".to_string()
                } else if files.placement_loading {
                    if files.placement_reconciliation_in_flight() {
                        "Checking replacement policy".to_string()
                    } else {
                        "Checking policy".to_string()
                    }
                } else if files.placement_reconciliation_in_flight()
                    && files
                        .placement_draft
                        .as_ref()
                        .is_some_and(PlacementEditorDraft::has_actionable_change)
                {
                    if files.placement_preview_is_current()
                        && files
                            .placement_preview
                            .as_ref()
                            .is_some_and(|preview| !preview.supports_safe_apply())
                    {
                        "Replacement preview requires a newer daemon".to_string()
                    } else if files.placement_preview_is_current()
                        && files
                            .placement_preview
                            .as_ref()
                            .is_some_and(|preview| !preview.is_satisfiable())
                    {
                        "Replacement policy cannot be satisfied".to_string()
                    } else if files.placement_preview_is_current() {
                        "Replacement preview is current".to_string()
                    } else {
                        "Preview the replacement policy".to_string()
                    }
                } else if files.placement_reconciliation_in_flight() {
                    "Reconciling existing objects · edit to replace this plan".to_string()
                } else if files.placement_preview_is_current()
                    && files
                        .placement_preview
                        .as_ref()
                        .is_some_and(|preview| !preview.supports_safe_apply())
                {
                    "Preview requires a newer daemon".to_string()
                } else if files.placement_preview_is_current()
                    && files
                        .placement_preview
                        .as_ref()
                        .is_some_and(|preview| !preview.is_satisfiable())
                {
                    "Policy cannot be satisfied".to_string()
                } else if files.placement_preview_is_current() {
                    "Preview is current".to_string()
                } else if files.placement_preview.is_some() {
                    "Preview out of date".to_string()
                } else {
                    "Preview required".to_string()
                }
            }
        })
        .tone_when({
            let shared = shared.clone();
            move || {
                let files = shared.files();
                if files.placement_applying || files.placement_loading {
                    SemanticTone::Info
                } else if files.placement_preview_is_current()
                    && files.placement_preview.as_ref().is_some_and(|preview| {
                        !preview.supports_safe_apply() || !preview.is_satisfiable()
                    })
                {
                    SemanticTone::Danger
                } else if files.placement_reconciliation_in_flight() {
                    SemanticTone::Info
                } else if files.placement_preview_is_current() {
                    SemanticTone::Success
                } else {
                    SemanticTone::Warning
                }
            }
        })
        .theme_when(clone_reader(reader))
}

fn files_placement_dialog(
    shared: &Shared,
    reader: &ThemeReader,
    prompt: &FileActionPrompt,
) -> WidgetPod {
    let target = prompt
        .target_path
        .as_deref()
        .unwrap_or("selected SIFS object");
    let draft_rows = shared
        .files()
        .placement_draft
        .as_ref()
        .map(placement_draft_rows)
        .unwrap_or_default();
    let advanced_open = shared.files().placement_advanced_open;
    let advanced = {
        let shared = shared.clone();
        sui::Button::new(if advanced_open {
            "Hide advanced settings"
        } else {
            "Advanced settings"
        })
        .icon(if advanced_open {
            IconGlyph::ChevronUp
        } else {
            IconGlyph::ChevronDown
        })
        .appearance(ButtonAppearance::Ghost)
        .tone(SemanticTone::Neutral)
        .theme_when(clone_reader(reader))
        .on_press_with_ctx(move |ctx| {
            shared.files_mut().toggle_placement_advanced();
            request_files_overlay_rebuild(ctx);
        })
    };
    let mut content = Stack::vertical()
        .alignment(Alignment::Stretch)
        .gap(12.0)
        .with_child(
            Label::new(format!(
                "Choose how {target} stays available. Nothing changes until you preview the plan and apply it."
            ))
            .theme(reader()),
        )
        .with_child(
            PanelSection::new(
                "Availability",
                placement_goal_control(shared, reader),
            )
            .theme_when(clone_reader(reader)),
        )
        .with_child(
            PanelSection::new(
                "Apply to",
                placement_scope_control(shared, reader, prompt.target_is_dir),
            )
            .theme_when(clone_reader(reader)),
        )
        .with_child(advanced)
        .with_child(placement_preview_status(shared, reader));

    if advanced_open {
        content = content
            .with_child(
                PanelSection::new(
                    "Copy policy",
                    placement_policy_controls(shared, reader, prompt.target_is_dir),
                )
                .theme_when(clone_reader(reader)),
            )
            .with_child(
                PanelSection::new("Policy details", detail_rows_widget(draft_rows, reader))
                    .theme_when(clone_reader(reader)),
            );
    }

    if let Some(error) = prompt.error.as_ref() {
        content = content.with_child(
            StatusBadge::new(error.clone())
                .tone(SemanticTone::Warning)
                .theme_when(clone_reader(reader)),
        );
    }
    {
        let files = shared.files();
        if let Some(preview) = files.placement_preview.as_ref() {
            let preview_is_current = files.placement_preview_is_current();
            if !preview_is_current {
                content = content.with_child(
                    StatusBadge::new(
                        "Previous preview — its warnings, impact totals, and desired node states are out of date. Preview changes to refresh them.",
                    )
                    .icon(IconGlyph::Alert)
                    .tone(SemanticTone::Warning)
                    .theme_when(clone_reader(reader)),
                );
            }
            if let Some(diagnostics) =
                placement_diagnostics_widget(preview, preview_is_current, reader)
            {
                content = content.with_child(diagnostics);
            }
            let draft_has_actionable_change = files
                .placement_draft
                .as_ref()
                .is_some_and(PlacementEditorDraft::has_actionable_change);
            content = content.with_child(
                PanelSection::new(
                    if preview_is_current {
                        "Preview"
                    } else {
                        "Previous preview"
                    },
                    detail_rows_widget(placement_user_preview_rows(preview), reader),
                )
                .theme_when(clone_reader(reader)),
            );
            if advanced_open {
                content = content
                    .with_child(
                        PanelSection::new(
                            if preview_is_current {
                                "Resolved policy"
                            } else {
                                "Previous resolved policy"
                            },
                            detail_rows_widget(placement_preview_rows(preview), reader),
                        )
                        .theme_when(clone_reader(reader)),
                    )
                    .with_child(
                        PanelSection::new(
                            if preview_is_current {
                                if draft_has_actionable_change {
                                    "Before you apply"
                                } else {
                                    "Current placement impact"
                                }
                            } else {
                                "Previous impact estimate"
                            },
                            placement_impact_widget(preview, reader),
                        )
                        .theme_when(clone_reader(reader)),
                    );
            }
            if advanced_open && preview.supports_safe_apply() {
                content = content.with_child(
                    PanelSection::new(
                        if preview_is_current {
                            "Selected path object's node placement"
                        } else {
                            "Previous path-object node placement"
                        },
                        Stack::vertical()
                            .alignment(Alignment::Stretch)
                            .gap(6.0)
                            .with_child(
                                Label::new(if files
                                    .placement_draft
                                    .as_ref()
                                    .is_some_and(|draft| {
                                        draft.scope == SifsPlacementScope::Subtree
                                    }) {
                                    "This table is the selected folder object's plan. Descendants are evaluated individually during the subtree scan."
                                } else {
                                    "This table is the selected object's current and desired plan."
                                })
                                .theme(reader()),
                            )
                            .with_child(
                                ScrollView::horizontal(placement_node_table(
                                    shared, reader, preview,
                                ))
                                .name("Placement node table")
                                .theme_when(clone_gray_scrollbar_reader(reader)),
                            ),
                    )
                    .theme_when(clone_reader(reader)),
                );
            }
        }
        if let Some(job) = files.placement_reconciliation.as_ref() {
            if !job.state.is_terminal() {
                content = content.with_child(
                    StatusBadge::new(
                        "The accepted plan remains authoritative while this job runs. If a desired node stays unavailable, edit the policy and preview it; Apply replacement will atomically supersede this job.",
                    )
                    .icon(IconGlyph::Hourglass)
                    .tone(SemanticTone::Info)
                    .theme_when(clone_reader(reader)),
                );
            }
            content = content.with_child(
                PanelSection::new(
                    "Reconciliation",
                    detail_rows_widget(placement_reconciliation_rows(job), reader),
                )
                .theme_when(clone_reader(reader)),
            );
        }
        if let Some(error) = files.placement_error.as_ref() {
            content = content.with_child(
                StatusBadge::new(error.clone())
                    .tone(SemanticTone::Danger)
                    .theme_when(clone_reader(reader)),
            );
        }
    }

    let preview = {
        let enabled = shared.clone();
        let shared = shared.clone();
        sui::Button::new("Preview changes")
            .appearance(ButtonAppearance::Outline)
            .tone(SemanticTone::Accent)
            .theme_when(clone_reader(reader))
            .enabled_when(move || {
                let files = enabled.files();
                !files.placement_loading
                    && !files.placement_editor_locked()
                    && files
                        .placement_draft
                        .as_ref()
                        .and_then(PlacementEditorDraft::active_policy)
                        .is_some_and(|policy| policy.consistency.is_editable())
            })
            .on_press_with_ctx(move |ctx| {
                let waker = { shared.borrow().waker.clone() };
                shared.files_mut().start_placement_preview(waker);
                request_files_overlay_rebuild(ctx);
            })
    };
    let apply = {
        let label = if shared.files().placement_reconciliation_in_flight()
            && shared
                .files()
                .placement_draft
                .as_ref()
                .is_some_and(PlacementEditorDraft::has_actionable_change)
        {
            "Apply replacement"
        } else {
            "Apply availability"
        };
        let enabled = shared.clone();
        let apply = shared.clone();
        sui::Button::new(label)
            .min_width(132.0)
            .theme_when(clone_reader(reader))
            .enabled_when(move || enabled.files().placement_apply_allowed())
            .on_press_with_ctx(move |ctx| {
                let waker = { apply.borrow().waker.clone() };
                apply.files_mut().submit_action_prompt(waker);
                request_files_overlay_rebuild(ctx);
            })
    };
    let cancel = {
        let label = if shared.files().placement_reconciliation.is_some() {
            "Close"
        } else {
            "Cancel"
        };
        let enabled = shared.clone();
        let shared = shared.clone();
        sui::Button::new(label)
            .min_width(112.0)
            .appearance(ButtonAppearance::Tonal)
            .tone(SemanticTone::Neutral)
            .theme_when(clone_reader(reader))
            .enabled_when(move || !enabled.files().placement_applying)
            .on_press_with_ctx(move |ctx| {
                shared.files_mut().close_action_prompt();
                request_files_overlay_rebuild(ctx);
            })
    };
    let actions = Flex::horizontal()
        .wrap(FlexWrap::Wrap)
        .gap(8.0)
        .align_items(Alignment::End)
        .with_child(preview)
        .with_child(apply)
        .with_child(cancel);

    let body = Stack::vertical()
        .alignment(Alignment::Stretch)
        .gap(12.0)
        .with_child(
            SizedBox::new().height(480.0).child(
                ScrollView::vertical(WidgetPadding::new(
                    Insets {
                        left: 2.0,
                        top: 2.0,
                        right: 10.0,
                        bottom: 8.0,
                    },
                    content,
                ))
                .name("Placement editor")
                .theme_when(clone_gray_scrollbar_reader(reader))
                .viewport_width_hint(true),
            ),
        )
        .with_child(actions);
    let dismiss = {
        let shared = shared.clone();
        move || shared.files_mut().close_action_prompt()
    };
    WidgetPod::new(
        sui::Dialog::new("Manage availability", body)
            .theme(shared.theme())
            .description("Choose where copies stay available, preview the plan, and apply it")
            .max_width(1040.0)
            .dismiss_on_scrim(true)
            .on_dismiss(dismiss),
    )
}

fn files_action_dialog(shared: &Shared, reader: &ThemeReader) -> Option<WidgetPod> {
    let prompt = shared.files().action_prompt.clone()?;
    if prompt.kind == FileActionPromptKind::Placement {
        return Some(files_placement_dialog(shared, reader, &prompt));
    }
    let source = shared.files().source;
    let title = prompt.kind.title();
    let description = match prompt.kind {
        FileActionPromptKind::GoTo => go_to_path_description(source).to_string(),
        FileActionPromptKind::NewFile => format!("Create a file in {}", shared.files().path),
        FileActionPromptKind::NewFolder => format!("Create a folder in {}", shared.files().path),
        FileActionPromptKind::Copy => prompt
            .target_path
            .as_deref()
            .map(|path| format!("Copy {path} to another {} path", source.operation_scope()))
            .unwrap_or_else(|| "Select a file to copy".to_string()),
        FileActionPromptKind::CopySelected => {
            let label = marked_entries_label(prompt.targets.len());
            format!(
                "Copy {label} into a destination folder in {}",
                source.operation_scope()
            )
        }
        FileActionPromptKind::CopyToSifs => prompt
            .target_path
            .as_deref()
            .map(|path| format!("Copy local {path} into SIFS"))
            .unwrap_or_else(|| "Select a local file or folder to copy into SIFS".to_string()),
        FileActionPromptKind::CopyToLocal => prompt
            .target_path
            .as_deref()
            .map(|path| format!("Download SIFS {path} to a local path"))
            .unwrap_or_else(|| "Select a SIFS file or folder to download".to_string()),
        FileActionPromptKind::TransferSelected => {
            let label = marked_entries_label(prompt.targets.len());
            match source {
                FilesSourceKind::Sifs => format!("Download {label} into a local folder"),
                FilesSourceKind::Local => format!("Copy {label} into a SIFS folder"),
            }
        }
        FileActionPromptKind::Move => prompt
            .target_path
            .as_deref()
            .map(|path| format!("Move {path} to another {} path", source.operation_scope()))
            .unwrap_or_else(|| "Select an item to move".to_string()),
        FileActionPromptKind::MoveSelected => {
            let label = marked_entries_label(prompt.targets.len());
            format!(
                "Move {label} into a destination folder in {}",
                source.operation_scope()
            )
        }
        FileActionPromptKind::Rename => prompt
            .target_path
            .as_deref()
            .map(|path| format!("Rename {path}"))
            .unwrap_or_else(|| "Select an item to rename".to_string()),
        FileActionPromptKind::Delete => prompt
            .target_path
            .as_deref()
            .map(|path| format!("Delete {path}? This action cannot be undone."))
            .unwrap_or_else(|| "Select an item to delete".to_string()),
        FileActionPromptKind::DeleteSelected => {
            let label = marked_entries_label(prompt.targets.len());
            format!(
                "Delete {label} from {}? This action cannot be undone.",
                shared.files().path
            )
        }
        FileActionPromptKind::Placement => prompt
            .target_path
            .as_deref()
            .map(|path| {
                format!(
                    "Configure {path}. Use eventual or confirmed, W/N, zones, scope=self|subtree, and comma-separated required/forbidden node IDs. Use inherit scope=... to remove this override."
                )
            })
            .unwrap_or_else(|| "Select a SIFS file or folder first".to_string()),
    };
    let input_label = match prompt.kind {
        FileActionPromptKind::GoTo => "Path",
        FileActionPromptKind::Copy
        | FileActionPromptKind::CopySelected
        | FileActionPromptKind::CopyToSifs
        | FileActionPromptKind::CopyToLocal
        | FileActionPromptKind::TransferSelected
        | FileActionPromptKind::MoveSelected
        | FileActionPromptKind::Move => "Destination",
        FileActionPromptKind::Placement => "Placement policy",
        _ => "Name",
    };
    let input = (!matches!(
        prompt.kind,
        FileActionPromptKind::Delete | FileActionPromptKind::DeleteSelected
    ))
    .then(|| {
        let s = shared.clone();
        let placeholder = match prompt.kind {
            FileActionPromptKind::GoTo => go_to_path_placeholder(source),
            FileActionPromptKind::CopyToSifs => "/services/artifact",
            FileActionPromptKind::CopyToLocal => "C:\\Users\\you\\Downloads\\artifact",
            FileActionPromptKind::CopySelected | FileActionPromptKind::MoveSelected => match source
            {
                FilesSourceKind::Sifs => "/services/archive",
                FilesSourceKind::Local => "archive",
            },
            FileActionPromptKind::TransferSelected => match source {
                FilesSourceKind::Sifs => "C:\\Users\\you\\Downloads",
                FilesSourceKind::Local => "/services/imports",
            },
            FileActionPromptKind::Placement => {
                "eventual W=1 N=3 zones=2 scope=subtree required=node-a forbidden=node-b"
            }
            _ => input_label,
        };
        sui::TextInput::new(format!("files-action-input-{title}"))
            .value(prompt.input.clone())
            .placeholder(placeholder)
            .min_width(320.0)
            .theme_when(clone_reader(reader))
            .on_change(move |value| {
                s.files_mut().set_action_prompt_input(value);
            })
    });
    let primary_label = prompt.kind.primary_label();
    let submit = {
        let s = shared.clone();
        sui::Button::new(primary_label)
            .min_width(112.0)
            .tone(file_action_submit_tone(prompt.kind))
            .theme_when(clone_reader(reader))
            .on_press_with_ctx(move |ctx| {
                let waker = { s.borrow().waker.clone() };
                s.files_mut().submit_action_prompt(waker);
                request_files_overlay_rebuild(ctx);
            })
    };
    let cancel = {
        let s = shared.clone();
        sui::Button::new("Cancel")
            .min_width(112.0)
            .theme_when(clone_reader(reader))
            .appearance(sui::ButtonAppearance::Tonal)
            .tone(SemanticTone::Neutral)
            .on_press_with_ctx(move |ctx| {
                s.files_mut().close_action_prompt();
                request_files_overlay_rebuild(ctx);
            })
    };
    let mut actions = Flex::horizontal()
        .wrap(FlexWrap::Wrap)
        .gap(8.0)
        .align_items(Alignment::End);
    if prompt.kind == FileActionPromptKind::Placement {
        let preview_shared = shared.clone();
        actions = actions.with_child(
            sui::Button::new("Preview")
                .appearance(ButtonAppearance::Outline)
                .tone(SemanticTone::Accent)
                .theme_when(clone_reader(reader))
                .on_press_with_ctx(move |ctx| {
                    let waker = { preview_shared.borrow().waker.clone() };
                    preview_shared.files_mut().start_placement_preview(waker);
                    request_files_overlay_rebuild(ctx);
                }),
        );
    }
    actions = actions.with_child(submit).with_child(cancel);

    let dialog_theme = shared.theme();
    let mut body = Stack::vertical()
        .gap(10.0)
        .alignment(Alignment::Stretch)
        .with_child(sui::Label::new(description).theme(dialog_theme));
    if let Some(chooser) = destination_chooser_controls(shared, reader, prompt.kind, source) {
        body = body.with_child(
            Surface::panel(chooser)
                .appearance(sui::SurfaceAppearance::Soft)
                .padding(Insets::all(10.0))
                .theme_when(clone_reader(reader))
                .fill_width(true),
        );
    }
    if let Some(input) = input {
        body = body.with_child(input);
    }
    if let Some(error) = prompt.error {
        body = body.with_child(sui::Label::new(error).theme(dialog_theme));
    }
    if prompt.kind == FileActionPromptKind::Placement {
        let files = shared.files();
        if files.placement_loading {
            body = body.with_child(
                StatusBadge::new("Checking placement")
                    .tone(SemanticTone::Info)
                    .theme_when(clone_reader(reader)),
            );
        }
        if let Some(preview) = files.placement_preview.as_ref() {
            body = body.with_child(detail_rows_widget(placement_preview_rows(preview), reader));
        }
        if let Some(job) = files.placement_reconciliation.as_ref() {
            body = body.with_child(detail_rows_widget(
                placement_reconciliation_rows(job),
                reader,
            ));
        }
        if let Some(error) = files.placement_error.as_ref() {
            body = body.with_child(
                StatusBadge::new(error.clone())
                    .tone(SemanticTone::Warning)
                    .theme_when(clone_reader(reader)),
            );
        }
    }
    body = body.with_child(actions);

    let dismiss = {
        let s = shared.clone();
        move || {
            s.files_mut().close_action_prompt();
        }
    };

    Some(WidgetPod::new(
        sui::Dialog::new(title, body)
            .theme(dialog_theme)
            .description(input_label)
            .max_width(460.0)
            .dismiss_on_scrim(true)
            .on_dismiss(dismiss),
    ))
}

fn file_action_submit_tone(kind: FileActionPromptKind) -> SemanticTone {
    if matches!(
        kind,
        FileActionPromptKind::Delete | FileActionPromptKind::DeleteSelected
    ) {
        SemanticTone::Danger
    } else {
        SemanticTone::Accent
    }
}

fn document_status_text(shared: &Shared) -> String {
    let files = shared.files();
    let Some(document) = files.document.as_ref() else {
        return "Document closed".to_string();
    };
    if document.loading {
        return "Reading a verified snapshot...".to_string();
    }
    if document.load_error.is_some() {
        return "Document unavailable".to_string();
    }
    if document.saving {
        return "Saving safely...".to_string();
    }
    if document.save_error.is_some() {
        return "Save needs attention; your edits are still open".to_string();
    }
    if document.save_warning.is_some() {
        return match document.source {
            FilesSourceKind::Sifs => "Saved; SIFS maintenance needs attention".to_string(),
            FilesSourceKind::Local => {
                "Saved; host filesystem follow-up needs attention".to_string()
            }
        };
    }
    if document.dirty() {
        return "Unsaved changes".to_string();
    }
    if document.read_only_reason.is_some() {
        return "Read-only verified snapshot".to_string();
    }
    match document.source {
        FilesSourceKind::Sifs => "Saved to SIFS with version protection".to_string(),
        FilesSourceKind::Local => "Saved".to_string(),
    }
}

fn document_detail_text(shared: &Shared) -> String {
    let files = shared.files();
    let Some(document) = files.document.as_ref() else {
        return String::new();
    };
    if let Some(error) = &document.load_error {
        return error.clone();
    }
    if let Some(error) = &document.save_error {
        return error.clone();
    }
    if let Some(warning) = &document.save_warning {
        return match document.source {
            FilesSourceKind::Sifs => format!(
                "The new SIFS version is visible, but follow-up maintenance warned: {warning}"
            ),
            FilesSourceKind::Local => format!(
                "The local content was committed, but host filesystem follow-up warned: {warning}"
            ),
        };
    }
    if let Some(reason) = &document.read_only_reason {
        return reason.clone();
    }
    if document.dirty() {
        return format!(
            "{} - Attach sends this unsaved editor buffer and labels it as unpersisted; Ctrl+S saves with conflict protection.",
            document.path
        );
    }
    match document.source {
        FilesSourceKind::Local => format!(
            "{} - Ctrl+S saves by atomic same-folder replacement after checking path, size, and modified time.",
            document.path
        ),
        FilesSourceKind::Sifs => format!(
            "{} - Ctrl+S uses an expected object ID and version, so a concurrent SIFS update cannot be overwritten.",
            document.path
        ),
    }
}

fn files_document_sheet(shared: &Shared, reader: &ThemeReader) -> Option<WidgetPod> {
    let document = shared.files().document.clone()?;
    let theme = reader();
    let mut text_style = theme.mono_text_style(theme.palette.text);
    text_style.font_size = theme.text.sm.size;
    text_style.line_height = theme.text.sm.line_height;
    let editor_shared = shared.clone();
    let mut editor = TextSurface::new(format!("files-document:{}", document.path))
        .theme(theme)
        .text_style(text_style)
        .padding(Insets::all(12.0))
        .min_width(0.0)
        .min_height(420.0)
        .wrap(TextWrap::NoWrap)
        .value(document.text.clone())
        .on_change(move |value| editor_shared.files_mut().set_document_text(value));
    if !document.editable() {
        editor = editor.read_only(true);
    }
    let status_shared = shared.clone();
    let detail_shared = shared.clone();
    let status = Surface::panel(
        Stack::vertical()
            .alignment(Alignment::Stretch)
            .gap(3.0)
            .with_child(
                Label::new("Document")
                    .text_when(move || document_status_text(&status_shared))
                    .text_style(theme.text_style(theme.palette.text)),
            )
            .with_child(
                Label::new("Document path")
                    .text_when(move || document_detail_text(&detail_shared))
                    .text_style(theme.text_style(theme.palette.text_muted)),
            ),
    )
    .theme_when(clone_reader(reader))
    .padding(Insets {
        left: 12.0,
        top: 8.0,
        right: 12.0,
        bottom: 8.0,
    })
    .fill_width(true);
    let editor_body = Dock::new(
        Surface::field(editor)
            .theme_when(clone_reader(reader))
            .fill_width(true),
    )
    .bottom(
        74.0,
        ScrollView::vertical(status)
            .name("Document status")
            .viewport_width_hint(true),
    )
    .fallback_width(780.0)
    .fallback_body_height(520.0);
    let body = SwitchView::new()
        .selected(if document.loading {
            0
        } else if document.load_error.is_some() {
            1
        } else {
            2
        })
        .with_child(centered_note(
            reader,
            IconGlyph::Hourglass,
            "Opening document",
            "Reading the complete selected version on the Files background worker",
        ))
        .with_child(centered_note(
            reader,
            IconGlyph::Alert,
            "Document unavailable",
            document
                .load_error
                .clone()
                .unwrap_or_else(|| "The document could not be opened".to_string()),
        ))
        .with_child(editor_body);

    let close_shared = shared.clone();
    let close = sui::Button::new("Close")
        .appearance(ButtonAppearance::Outline)
        .tone(SemanticTone::Neutral)
        .theme_when(clone_reader(reader))
        .on_press_with_ctx(move |ctx| {
            close_shared.files_mut().request_close_document();
            request_files_overlay_rebuild(ctx);
        });
    let attach_shared = shared.clone();
    let attach_enabled = shared.clone();
    let in_tab = shared.workspace_kind() == Some(crate::state::WorkspaceTabKind::Document);
    let attach = sui::Button::new(if in_tab {
        "Attach"
    } else {
        "Attach to current chat"
    })
    .description("Attach this document to the current chat")
    .icon(IconGlyph::Attach)
    .appearance(ButtonAppearance::Tonal)
    .tone(SemanticTone::Accent)
    .theme_when(clone_reader(reader))
    .enabled_when(move || {
        let files = attach_enabled.files();
        files
            .document
            .as_ref()
            .is_some_and(|document| !document.loading && document.load_error.is_none())
            && !files.attachment_loading
    })
    .on_press_with_ctx(move |ctx| {
        let waker = { attach_shared.borrow().waker.clone() };
        attach_shared.files_mut().start_attach_document(waker);
        request_files_overlay_rebuild(ctx);
    });
    let mut actions = Flex::horizontal().gap(8.0).with_child(attach);
    if document.load_error.is_some() {
        let retry_shared = shared.clone();
        actions = actions.with_child(
            sui::Button::new("Retry")
                .appearance(ButtonAppearance::Tonal)
                .tone(SemanticTone::Accent)
                .theme_when(clone_reader(reader))
                .on_press_with_ctx(move |ctx| {
                    let waker = { retry_shared.borrow().waker.clone() };
                    retry_shared.files_mut().retry_document(waker);
                    request_files_overlay_rebuild(ctx);
                }),
        );
    } else if !document.loading {
        let save_shared = shared.clone();
        let save_enabled = shared.clone();
        actions = actions.with_child(
            sui::Button::new("Save")
                .icon(IconGlyph::Check)
                .appearance(ButtonAppearance::Filled)
                .tone(SemanticTone::Accent)
                .theme_when(clone_reader(reader))
                .enabled_when(move || {
                    save_enabled
                        .files()
                        .document
                        .as_ref()
                        .is_some_and(|document| {
                            document.editable() && document.dirty() && !document.saving
                        })
                })
                .on_press_with_ctx(move |ctx| {
                    let waker = { save_shared.borrow().waker.clone() };
                    save_shared.files_mut().save_document(waker);
                    request_files_overlay_rebuild(ctx);
                }),
        );
    }
    if shared.workspace_kind() == Some(crate::state::WorkspaceTabKind::Document) {
        let header = TrailingSlotRow::new(Label::new(document.title).theme(theme), actions)
            .trailing_width(200.0)
            .trailing_height(36.0)
            .gap(8.0);
        return Some(WidgetPod::new(
            Surface::panel(Dock::new(body).top(52.0, WidgetPadding::all(8.0, header)))
                .theme_when(clone_reader(reader))
                .fill(),
        ));
    }
    let dismiss_shared = shared.clone();
    Some(WidgetPod::new(
        SideSheet::new(document.title.clone(), body)
            .theme_when(clone_reader(reader))
            .description(format!(
                "Complete {} text document - {}",
                document.source.label(),
                document.path
            ))
            .placement(SideSheetPlacement::Right)
            .width(920.0)
            .modal(true)
            .dismiss_on_scrim(true)
            .action(actions.with_child(close))
            .on_dismiss(move || dismiss_shared.files_mut().request_close_document()),
    ))
}

fn files_document_close_dialog(shared: &Shared, reader: &ThemeReader) -> Option<WidgetPod> {
    if !shared.files().document_close_confirmation {
        return None;
    }
    let title = shared
        .files()
        .document
        .as_ref()
        .map(|document| document.title.clone())
        .unwrap_or_else(|| "document".to_string());
    let discard_shared = shared.clone();
    let keep_shared = shared.clone();
    let actions = Flex::horizontal()
        .wrap(FlexWrap::Wrap)
        .gap(8.0)
        .align_items(Alignment::End)
        .with_child(
            sui::Button::new("Discard changes")
                .appearance(ButtonAppearance::Tonal)
                .tone(SemanticTone::Danger)
                .theme_when(clone_reader(reader))
                .on_press_with_ctx(move |ctx| {
                    let waker = { discard_shared.borrow().waker.clone() };
                    discard_shared
                        .files_mut()
                        .discard_document_and_continue(waker);
                    request_files_overlay_rebuild(ctx);
                }),
        )
        .with_child(
            sui::Button::new("Keep editing")
                .appearance(ButtonAppearance::Filled)
                .tone(SemanticTone::Accent)
                .theme_when(clone_reader(reader))
                .on_press_with_ctx(move |ctx| {
                    keep_shared.files_mut().cancel_document_close();
                    request_files_overlay_rebuild(ctx);
                }),
        );
    let body = Stack::vertical()
        .alignment(Alignment::Stretch)
        .gap(12.0)
        .with_child(
            Label::new(format!(
                "{title} has unsaved changes. Discarding closes the current snapshot without writing it."
            ))
            .theme(reader()),
        )
        .with_child(actions);
    Some(WidgetPod::new(
        sui::Dialog::new("Unsaved changes", body)
            .theme(reader())
            .description("Choose whether to keep editing or discard the document changes")
            .max_width(480.0)
            .dismiss_on_scrim(false),
    ))
}

fn placement_activity_status_label(
    status: sinomo_runtime::dfs::DfsPlacementReconciliationActivityStatus,
) -> &'static str {
    use sinomo_runtime::dfs::DfsPlacementReconciliationActivityStatus as Status;
    match status {
        Status::Running => "Running",
        Status::Retrying => "Retrying",
        Status::Failed => "Failed",
        Status::Completed => "Completed",
        Status::Superseded => "Superseded",
    }
}

fn placement_activity_status_tone(
    status: sinomo_runtime::dfs::DfsPlacementReconciliationActivityStatus,
) -> SemanticTone {
    use sinomo_runtime::dfs::DfsPlacementReconciliationActivityStatus as Status;
    match status {
        Status::Running => SemanticTone::Info,
        Status::Retrying => SemanticTone::Warning,
        Status::Failed => SemanticTone::Danger,
        Status::Completed => SemanticTone::Success,
        Status::Superseded => SemanticTone::Neutral,
    }
}

fn placement_activity_phase_label(
    phase: sinomo_runtime::dfs::DfsPlacementReconciliationState,
) -> &'static str {
    use sinomo_runtime::dfs::DfsPlacementReconciliationState as Phase;
    match phase {
        Phase::Pending => "Queued",
        Phase::Scanning => "Scanning objects",
        Phase::Repairing => "Repairing copies",
        Phase::Completed => "Finished",
        Phase::Failed => "Stopped",
    }
}

fn placement_activity_relative_time(unix_nanos: u64) -> String {
    let now = time::OffsetDateTime::now_utc().unix_timestamp_nanos();
    let elapsed_nanos = now.saturating_sub(unix_nanos as i128);
    let elapsed_secs = u64::try_from(elapsed_nanos / 1_000_000_000).unwrap_or(u64::MAX);
    match elapsed_secs {
        0..=4 => "just now".to_string(),
        5..=59 => format!("{elapsed_secs}s ago"),
        60..=3_599 => format!("{}m ago", elapsed_secs / 60),
        3_600..=86_399 => format!("{}h ago", elapsed_secs / 3_600),
        86_400..=604_799 => format!("{}d ago", elapsed_secs / 86_400),
        _ => unix_nanos_label(unix_nanos),
    }
}

fn placement_activity_row_description(
    activity: &sinomo_runtime::dfs::DfsPlacementReconciliationActivitySummary,
) -> String {
    let phase = if activity.status
        == sinomo_runtime::dfs::DfsPlacementReconciliationActivityStatus::Superseded
    {
        "Replaced"
    } else {
        placement_activity_phase_label(activity.phase)
    };
    let mut description = format!(
        "{}; {}; {}; {} of {} progress units; {} of {} objects scanned; {} repairs completed; last cluster update {}",
        placement_activity_status_label(activity.status),
        phase,
        activity.path,
        activity.progress_completed,
        activity.progress_total,
        activity.scanned_object_count,
        activity.total_object_count,
        activity.completed_repair_count,
        placement_activity_relative_time(activity.updated_at_unix_nanos),
    );
    if let Some(error) = activity.last_error.as_deref() {
        description.push_str("; ");
        description.push_str(error);
    }
    description
}

fn placement_activity_row(
    shared: &Shared,
    reader: &ThemeReader,
    activity: &sinomo_runtime::dfs::DfsPlacementReconciliationActivitySummary,
) -> WidgetPod {
    let theme = reader();
    let pal = Palette::from_theme(&theme, widgets::theme_is_dark(shared));
    let title_style = pal.text_style(&theme, 14.0, FontWeight::SEMIBOLD, pal.text);
    let detail_style = pal.text_style(&theme, 11.0, FontWeight::NORMAL, pal.text_muted);
    let status = StatusBadge::new(placement_activity_status_label(activity.status))
        .tone(placement_activity_status_tone(activity.status))
        .theme_when(clone_reader(reader));
    let phase_label = if activity.status
        == sinomo_runtime::dfs::DfsPlacementReconciliationActivityStatus::Superseded
    {
        "Replaced"
    } else {
        placement_activity_phase_label(activity.phase)
    };
    let phase = StatusBadge::new(phase_label)
        .tone(SemanticTone::Neutral)
        .theme_when(clone_reader(reader));
    let path = activity.path.clone();
    let reveal = {
        let shared = shared.clone();
        sui::Button::new("Show path")
            .icon(IconGlyph::Folder)
            .min_width(104.0)
            .appearance(ButtonAppearance::Tonal)
            .tone(SemanticTone::Neutral)
            .theme_when(clone_reader(reader))
            .on_press_with_ctx(move |ctx| {
                let waker = { shared.borrow().waker.clone() };
                shared
                    .files_mut()
                    .reveal_placement_activity_path(path.clone(), waker);
                request_files_overlay_rebuild(ctx);
            })
    };
    let progress = if activity.progress_total == 0 {
        0.0
    } else {
        (activity.progress_completed as f64 / activity.progress_total as f64).clamp(0.0, 1.0)
    };
    let percent = (progress * 100.0).round() as u64;
    let header = TrailingSlotRow::new(
        Stack::vertical()
            .alignment(Alignment::Stretch)
            .gap(5.0)
            .with_child(
                Flex::horizontal()
                    .wrap(FlexWrap::Wrap)
                    .gap(6.0)
                    .align_items(Alignment::Center)
                    .with_child(status)
                    .with_child(phase),
            )
            .with_child(Label::new(activity.path.clone()).text_style(title_style)),
        reveal,
    )
    .trailing_width(108.0)
    .trailing_height(32.0)
    .gap(12.0);
    let mut content = Stack::vertical()
        .alignment(Alignment::Stretch)
        .gap(7.0)
        .with_child(header)
        .with_child(
            Label::new(format!(
                "{percent}% · {}/{} scanned · {} matched · {} updated",
                activity.scanned_object_count,
                activity.total_object_count,
                activity.matched_object_count,
                activity.updated_object_count,
            ))
            .text_style(detail_style.clone()),
        )
        .with_child(
            SizedBox::new().height(5.0).child(
                sui::ProgressBar::new(format!("Reconciliation progress for {}", activity.path))
                    .value(progress)
                    .tone(placement_activity_status_tone(activity.status))
                    .height(5.0)
                    .theme_when(clone_reader(reader)),
            ),
        )
        .with_child(
            Label::new(format!(
                "Copies: {} scheduled · {} completed · {} pending",
                activity.scheduled_repair_count,
                activity.completed_repair_count,
                activity.pending_repair_count,
            ))
            .text_style(detail_style.clone()),
        );
    if let Some(error) = activity.last_error.as_deref() {
        let superseded = activity.status
            == sinomo_runtime::dfs::DfsPlacementReconciliationActivityStatus::Superseded;
        let tone = if superseded {
            SemanticTone::Neutral
        } else if activity.status
            == sinomo_runtime::dfs::DfsPlacementReconciliationActivityStatus::Failed
        {
            SemanticTone::Danger
        } else {
            SemanticTone::Warning
        };
        content = content.with_child(
            Surface::panel(
                Stack::vertical()
                    .alignment(Alignment::Stretch)
                    .gap(5.0)
                    .with_child(
                        StatusBadge::new(if superseded {
                            "Replacement"
                        } else {
                            "Last issue"
                        })
                        .icon(if superseded {
                            IconGlyph::History
                        } else {
                            IconGlyph::Alert
                        })
                        .tone(tone)
                        .theme_when(clone_reader(reader)),
                    )
                    .with_child(Label::new(error.to_string()).text_style(detail_style.clone())),
            )
            .appearance(sui::SurfaceAppearance::Soft)
            .padding(Insets::all(9.0))
            .theme_when(clone_reader(reader)),
        );
    }
    content = content.with_child({
        let scope = match activity.scope {
            SifsPlacementScope::SelfOnly => "This object",
            SifsPlacementScope::Subtree => "Folder subtree",
        };
        Label::new(format!(
            "{} scope · updated {} · job {}",
            scope,
            placement_activity_relative_time(activity.updated_at_unix_nanos),
            middle_short(&activity.job_id, 28),
        ))
        .text_style(detail_style)
    });
    WidgetPod::new(
        Surface::panel(content)
            .appearance(sui::SurfaceAppearance::Soft)
            .padding(Insets {
                left: 14.0,
                top: 12.0,
                right: 14.0,
                bottom: 12.0,
            })
            .theme_when(clone_reader(reader))
            .fill_width(true),
    )
}

fn placement_activity_virtual_list(shared: &Shared, reader: &ThemeReader) -> impl Widget + use<> {
    let source = shared.signals().files_structure.select_named(
        "placement reconciliation activity rows",
        |key| {
            let items = key
                .placement_activity
                .activities
                .iter()
                .filter(|activity| key.placement_activity.filter.includes(activity.status))
                .cloned()
                .map(|activity| (activity.job_id.clone(), activity))
                .collect();
            VirtualCollectionSnapshot::new(items, None)
        },
    );
    let row_shared = shared.clone();
    let row_reader = Rc::clone(reader);
    VirtualCollectionHost::new(
        "Placement reconciliation activity collection",
        source,
        move |model, state| {
            let shared = row_shared.clone();
            let reader = Rc::clone(&row_reader);
            VirtualList::new(
                "Reconciliation activity",
                model,
                move |_job_id, activity| {
                    let shared = shared.clone();
                    let reader = Rc::clone(&reader);
                    RebuildOnChange::key_from(activity, move |activity| {
                        placement_activity_row(&shared, &reader, activity)
                    })
                },
            )
            .state(state)
            .estimated_row_height(154.0)
            .gap(10.0)
            .padding(Insets {
                left: 2.0,
                top: 2.0,
                right: 10.0,
                bottom: 10.0,
            })
            .selection_mode(VirtualListSelectionMode::None)
            .chrome(VirtualListChrome::Transparent)
            .theme_when(clone_reader(&row_reader))
            .row_name(|_job_id, activity| format!("Reconciliation {}", activity.path))
            .row_description(|_job_id, activity| placement_activity_row_description(activity))
        },
    )
}

