fn scroll_placement_activity_summary(
    state: &ScrollState,
    viewport: sui::WidgetId,
    delta: f32,
    ctx: &mut EventCtx,
) {
    let current = state.current_offset();
    let max = state.max_offset();
    let next = sui::Vector::new(current.x, (current.y + delta).clamp(0.0, max.y));
    if state.set_offset(next) {
        // The arrow is a sibling of the retained viewport. Invalidating only the
        // arrow leaves the viewport's cached layout and content transform unchanged.
        use sui::{InvalidationKind, InvalidationRequest, InvalidationTarget};
        let target = InvalidationTarget::Widget(viewport);
        for kind in [
            InvalidationKind::Measure,
            InvalidationKind::Arrange,
            InvalidationKind::Paint,
            InvalidationKind::HitTest,
            InvalidationKind::Semantics,
        ] {
            ctx.request(InvalidationRequest::new(target, kind));
        }
    }
}

fn files_placement_activity_sheet(shared: &Shared, reader: &ThemeReader) -> WidgetPod {
    use sinomo_runtime::dfs::DfsPlacementReconciliationActivityStatus as Status;

    let counts = Flex::horizontal()
        .wrap(FlexWrap::Wrap)
        .gap(8.0)
        .align_items(Alignment::Center)
        .with_child(placement_activity_count_badge(
            shared,
            reader,
            Status::Running,
        ))
        .with_child(placement_activity_count_badge(
            shared,
            reader,
            Status::Retrying,
        ))
        .with_child(placement_activity_count_badge(
            shared,
            reader,
            Status::Failed,
        ))
        .with_child(placement_activity_count_badge(
            shared,
            reader,
            Status::Completed,
        ))
        .with_child(placement_activity_count_badge(
            shared,
            reader,
            Status::Superseded,
        ));
    let filter = placement_activity_filter_control(shared, reader);
    let connection = {
        let label_shared = shared.clone();
        let tone_shared = shared.clone();
        StatusBadge::new("Reading cluster activity")
            .label_when(move || {
                let files = label_shared.files();
                if files.placement_activity_loading {
                    "Refreshing cluster activity".to_string()
                } else if let Some(error) = files.placement_activity_error.as_deref() {
                    format!("Last cluster read failed · {}", middle_short(error, 48))
                } else if files.live_updates_error.is_some() {
                    "Polling snapshots · live updates disconnected".to_string()
                } else if files.placement_activity_history_truncated {
                    "Monitoring available cluster activity".to_string()
                } else if files.placement_activity_partial {
                    "Monitoring active jobs and retained history".to_string()
                } else if files.placement_activity_has_active_jobs() {
                    "Monitoring active reconciliation jobs".to_string()
                } else {
                    "Latest retained activity loaded".to_string()
                }
            })
            .icon(IconGlyph::Storage)
            .tone_when(move || {
                let files = tone_shared.files();
                if files.placement_activity_error.is_some()
                    || files.live_updates_error.is_some()
                    || files.placement_activity_history_truncated
                {
                    SemanticTone::Warning
                } else if files.placement_activity_loading
                    || files.placement_activity_partial
                    || files.placement_activity_has_active_jobs()
                {
                    SemanticTone::Info
                } else {
                    SemanticTone::Success
                }
            })
            .theme_when(clone_reader(reader))
    };
    let refreshed = {
        let shared = shared.clone();
        Label::new("Waiting for the first cluster snapshot")
            .text_when(move || {
                let files = shared.files();
                files
                    .placement_activity_refreshed_at_unix_nanos
                    .map(|time| {
                        let history = if files.placement_activity_next_cursor.is_some() {
                            "older matching activity is available"
                        } else if files.placement_activity_history_truncated {
                            "older terminal history is truncated"
                        } else if files.placement_activity_partial {
                            "retained operational history is loaded"
                        } else {
                            "all available matching activity is loaded"
                        };
                        format!(
                            "Last snapshot {} · {} loaded {} jobs · {history}",
                            placement_activity_relative_time(time),
                            files.placement_activity.len(),
                            files.placement_activity_filter.label(),
                        )
                    })
                    .unwrap_or_else(|| "Waiting for the first cluster snapshot".to_string())
            })
            .theme(reader())
    };
    let header = Stack::vertical()
        .alignment(Alignment::Stretch)
        .gap(8.0)
        .with_child(placement_activity_error_notice(shared, reader))
        .with_child(placement_activity_stream_notice(shared, reader))
        .with_child(placement_activity_completeness_notice(shared, reader))
        .with_child(counts)
        .with_child(connection)
        .with_child(refreshed);

    let body_shared = shared.clone();
    let content = SwitchView::new()
        .selected_when(move || placement_activity_body_index(&body_shared.files()))
        .with_child(centered_note(
            reader,
            IconGlyph::Hourglass,
            "Loading reconciliation activity",
            "Reading recent durable placement jobs from the cluster control plane.",
        ))
        .with_child(centered_note(
            reader,
            IconGlyph::Alert,
            "Activity temporarily unavailable",
            "The full cluster error is shown above. Retry after the daemon or cluster connection recovers.",
        ))
        .with_child(centered_note(
            reader,
            IconGlyph::History,
            "No matching jobs in loaded activity",
            "Load older activity to search earlier jobs, or change the status filter.",
        ))
        .with_child(centered_note(
            reader,
            IconGlyph::Alert,
            "Available activity history is incomplete",
            "The cluster cannot prove that no matching job exists. See the retained-history notice above.",
        ))
        .with_child(centered_note(
            reader,
            IconGlyph::History,
            "No matching jobs in retained operational history",
            "Active jobs are queried separately. Older-daemon terminal activity may not appear in retained history.",
        ))
        .with_child(centered_note(
            reader,
            IconGlyph::Check,
            "No matching reconciliation jobs",
            "Change the filter or apply a placement policy to create a durable reconciliation job.",
        ))
        .with_child(placement_activity_virtual_list(shared, reader));

    let load_older = {
        let enabled = shared.clone();
        let action = shared.clone();
        sui::Button::new("Load older activity")
            .appearance(ButtonAppearance::Tonal)
            .tone(SemanticTone::Neutral)
            .theme_when(clone_reader(reader))
            .enabled_when(move || {
                let files = enabled.files();
                files.placement_activity_next_cursor.is_some() && !files.placement_activity_loading
            })
            .on_press(move || action.files_mut().load_older_placement_activity())
    };
    let summary_scroll_state = ScrollState::new();
    let summary_scroll = WidgetPadding::new(
        Insets::ZERO,
        ScrollView::vertical(
            WidgetPadding::new(
                Insets {
                    left: 2.0,
                    top: 2.0,
                    right: 10.0,
                    bottom: 12.0,
                },
                header,
            )
            .fill_child_width(true),
        )
        .state(summary_scroll_state.clone())
        .theme_when(clone_gray_scrollbar_reader(reader))
        .name("Reconciliation activity summary"),
    );
    let summary_viewport = summary_scroll.child_pod().id();
    let previous_summary = {
        let enabled = summary_scroll_state.clone();
        let action = summary_scroll_state.clone();
        IconButton::new(IconGlyph::ChevronUp, "Previous activity summary")
            .size(30.0)
            .theme_when(clone_reader(reader))
            .enabled_when(move || enabled.current_offset().y > 0.5)
            .on_press_with_ctx(move |ctx| {
                scroll_placement_activity_summary(&action, summary_viewport, -140.0, ctx)
            })
    };
    let next_summary = {
        let enabled = summary_scroll_state.clone();
        let action = summary_scroll_state.clone();
        IconButton::new(IconGlyph::ChevronDown, "Next activity summary")
            .size(30.0)
            .theme_when(clone_reader(reader))
            .enabled_when(move || enabled.current_offset().y + 0.5 < enabled.max_offset().y)
            .on_press_with_ctx(move |ctx| {
                scroll_placement_activity_summary(&action, summary_viewport, 140.0, ctx)
            })
    };
    let summary = Flex::horizontal()
        .align_items(Alignment::Stretch)
        .with_item(summary_scroll, FlexItem::fill().min_width(0.0))
        .with_item(
            Stack::vertical()
                .alignment(Alignment::Center)
                .gap(6.0)
                .with_child(previous_summary)
                .with_child(next_summary),
            FlexItem::new().no_shrink(),
        );
    let header_with_filter = Dock::new(summary).bottom(
        44.0,
        WidgetPadding::new(
            Insets {
                left: 2.0,
                top: 4.0,
                right: 2.0,
                bottom: 4.0,
            },
            filter,
        )
        .fill_child_width(true),
    );
    let body = Dock::new(content)
        .top(204.0, header_with_filter)
        .bottom(
            44.0,
            Flex::horizontal()
                .align_items(Alignment::Center)
                .with_item(load_older, FlexItem::new().no_shrink()),
        )
        .fallback_width(720.0)
        .fallback_body_height(650.0);
    let refresh = {
        let shared = shared.clone();
        sui::Button::new("Refresh")
            .icon(IconGlyph::Redo)
            .appearance(ButtonAppearance::Tonal)
            .tone(SemanticTone::Accent)
            .theme_when(clone_reader(reader))
            .enabled_when({
                let shared = shared.clone();
                move || !shared.files().placement_activity_loading
            })
            .on_press(move || {
                let waker = { shared.borrow().waker.clone() };
                if let Some(waker) = waker {
                    shared.files_mut().ensure_worker(waker);
                }
                shared.files_mut().refresh_placement_activity();
            })
    };
    let close = {
        let shared = shared.clone();
        sui::Button::new("Close")
            .appearance(ButtonAppearance::Outline)
            .tone(SemanticTone::Neutral)
            .theme_when(clone_reader(reader))
            .on_press_with_ctx(move |ctx| {
                shared.files_mut().close_placement_activity();
                request_files_overlay_rebuild(ctx);
            })
    };
    let dismiss = shared.clone();
    WidgetPod::new(
        SideSheet::new("Reconciliation activity", body)
            .theme_when(clone_reader(reader))
            .description("Cluster DFS placement jobs and repair progress")
            .placement(SideSheetPlacement::Right)
            .width(780.0)
            .modal(true)
            .dismiss_on_scrim(true)
            .action(refresh)
            .action(close)
            .on_dismiss(move || dismiss.files_mut().close_placement_activity()),
    )
}

fn storage_repair_row(reader: &ThemeReader, repair: &DfsOperatorRepairView) -> Surface {
    let rows = vec![
        (
            "Missing from",
            short_node_label(repair.missing_replica_node_id.as_str()),
        ),
        ("Version", middle_short(repair.version.as_str(), 24)),
        ("Object", middle_short(repair.object_id.as_str(), 24)),
    ];
    Surface::panel(detail_rows_widget(rows, reader))
        .appearance(sui::SurfaceAppearance::Soft)
        .tone(SemanticTone::Warning)
        .padding(Insets::all(10.0))
        .theme_when(clone_reader(reader))
        .fill_width(true)
}

fn files_storage_center_sheet(shared: &Shared, reader: &ThemeReader) -> Option<WidgetPod> {
    if !shared.files().storage_center_open {
        return None;
    }
    let files = shared.files();
    let loading = files.storage_center_loading;
    let error = files.storage_center_error.clone();
    let overview = files.storage_overview.clone();
    drop(files);

    let mut content = Stack::vertical().alignment(Alignment::Stretch).gap(12.0);
    if let Some(overview) = overview.as_ref() {
        let status = &overview.status;
        let attention = status.pending_repair_count > 0
            || status.pending_write_count > 0
            || status.failed_namespace_job_count > 0;
        content = content.with_child(inspector_card(
            "Overview",
            Stack::vertical()
                .alignment(Alignment::Stretch)
                .gap(9.0)
                .with_child(
                    StatusBadge::new(if attention {
                        "Storage needs attention"
                    } else {
                        "Storage is healthy"
                    })
                    .icon(if attention {
                        IconGlyph::Alert
                    } else {
                        IconGlyph::Check
                    })
                    .tone(if attention {
                        SemanticTone::Warning
                    } else {
                        SemanticTone::Success
                    })
                    .theme_when(clone_reader(reader)),
                )
                .with_child(detail_rows_widget(
                    vec![
                        ("Objects", status.object_count.to_string()),
                        ("Versions", status.version_count.to_string()),
                        ("Pending writes", status.pending_write_count.to_string()),
                        ("Missing copies", status.pending_repair_count.to_string()),
                        ("Metadata shards", status.metadata_shards.len().to_string()),
                    ],
                    reader,
                )),
            reader,
            None,
            false,
        ));
        for reason in status.blocking_incomplete_reasons() {
            content = content.with_child(
                StatusBadge::new(format!("Incomplete storage view: {reason}"))
                    .icon(IconGlyph::Alert)
                    .tone(SemanticTone::Warning)
                    .theme_when(clone_reader(reader)),
            );
        }

        let mut repair_rows = Stack::vertical().alignment(Alignment::Stretch).gap(8.0);
        for repair in overview.repairs.iter().take(20) {
            repair_rows = repair_rows.with_child(storage_repair_row(reader, repair));
        }
        if overview.repairs.is_empty() {
            repair_rows = repair_rows
                .with_child(Label::new("No missing-copy records were returned.").theme(reader()));
        } else if overview.repairs.len() > 20 || overview.repairs_have_more {
            repair_rows = repair_rows.with_child(
                StatusBadge::new(
                    "More missing-copy records exist. The Cluster view and bounded DFS operator command expose the wider queue.",
                )
                .tone(SemanticTone::Info)
                .theme_when(clone_reader(reader)),
            );
        }
        content = content.with_child(
            PanelSection::new("Missing copies", repair_rows)
                .theme_when(clone_reader(reader))
                .gap(8.0),
        );

        let cluster = shared.clone();
        let mount = shared.clone();
        let activity = shared.clone();
        content = content.with_child(
            PanelSection::new(
                "Storage tools",
                Flex::horizontal()
                    .wrap(FlexWrap::Wrap)
                    .gap(8.0)
                    .align_items(Alignment::Center)
                    .with_child(
                        sui::Button::new("Open Cluster")
                            .icon(IconGlyph::Storage)
                            .appearance(ButtonAppearance::Ghost)
                            .theme_when(clone_reader(reader))
                            .on_press(move || {
                                cluster.files_mut().close_storage_center();
                                open_cluster_tab(&cluster);
                            }),
                    )
                    .with_child(
                        sui::Button::new("Mount & sync")
                            .icon(IconGlyph::Folder)
                            .appearance(ButtonAppearance::Ghost)
                            .theme_when(clone_reader(reader))
                            .on_press(move || {
                                mount.files_mut().close_storage_center();
                                open_settings_section(&mount, SettingsSection::Storage)
                            }),
                    )
                    .with_child(
                        sui::Button::new("Reconciliation activity")
                            .icon(IconGlyph::History)
                            .appearance(ButtonAppearance::Ghost)
                            .theme_when(clone_reader(reader))
                            .on_press_with_ctx(move |ctx| {
                                activity.files_mut().close_storage_center();
                                let waker = { activity.borrow().waker.clone() };
                                activity.files_mut().open_placement_activity(waker);
                                request_files_overlay_rebuild(ctx);
                            }),
                    ),
            )
            .theme_when(clone_reader(reader)),
        );
    }
    if loading && overview.is_some() {
        content = content.with_child(
            StatusBadge::new("Refreshing storage health...")
                .icon(IconGlyph::Hourglass)
                .tone(SemanticTone::Info)
                .theme_when(clone_reader(reader)),
        );
    }
    if let Some(error) = error.clone().filter(|_| overview.is_some()) {
        content = content.with_child(
            StatusBadge::new(error)
                .icon(IconGlyph::Alert)
                .tone(SemanticTone::Danger)
                .theme_when(clone_reader(reader)),
        );
    }

    let loaded = ScrollView::vertical(
        WidgetPadding::new(
            Insets {
                left: 2.0,
                top: 2.0,
                right: 10.0,
                bottom: 16.0,
            },
            content,
        )
        .fill_child_width(true),
    )
    .name("Storage health overview")
    .theme_when(clone_gray_scrollbar_reader(reader))
    .viewport_width_hint(true);
    let selected = if overview.is_some() {
        2
    } else if loading {
        0
    } else {
        1
    };
    let body = SwitchView::new()
        .selected(selected)
        .with_child(centered_note(
            reader,
            IconGlyph::Hourglass,
            "Checking storage",
            "Reading DFS status and missing-copy pages.",
        ))
        .with_child(centered_note(
            reader,
            IconGlyph::Alert,
            "Storage health unavailable",
            error.unwrap_or_else(|| "The daemon did not return storage health.".to_string()),
        ))
        .with_child(loaded);

    let refresh_shared = shared.clone();
    let refresh_enabled = shared.clone();
    let refresh = sui::Button::new("Refresh")
        .icon(IconGlyph::Redo)
        .appearance(ButtonAppearance::Tonal)
        .tone(SemanticTone::Accent)
        .theme_when(clone_reader(reader))
        .enabled_when(move || !refresh_enabled.files().storage_center_loading)
        .on_press_with_ctx(move |ctx| {
            let waker = { refresh_shared.borrow().waker.clone() };
            refresh_shared.files_mut().request_storage_overview(waker);
            request_files_overlay_rebuild(ctx);
        });
    let close_shared = shared.clone();
    let close = sui::Button::new("Close")
        .appearance(ButtonAppearance::Outline)
        .tone(SemanticTone::Neutral)
        .theme_when(clone_reader(reader))
        .on_press_with_ctx(move |ctx| {
            close_shared.files_mut().close_storage_center();
            request_files_overlay_rebuild(ctx);
        });
    let dismiss = shared.clone();
    Some(WidgetPod::new(
        SideSheet::new("Storage health", body)
            .theme_when(clone_reader(reader))
            .description("DFS objects, pending work, and missing copies")
            .placement(SideSheetPlacement::Right)
            .width(780.0)
            .modal(true)
            .dismiss_on_scrim(true)
            .action(refresh)
            .action(close)
            .on_dismiss(move || dismiss.files_mut().close_storage_center()),
    ))
}

fn history_note(reader: &ThemeReader, text: impl Into<String>) -> Label {
    let theme = reader();
    let mut style = theme.text_style(theme.palette.text_muted);
    style.font_size = theme.text.sm.size;
    style.line_height = theme.text.sm.line_height;
    Label::new(text).text_style(style)
}

fn history_saved_label(nanos: u64) -> String {
    let relative = placement_activity_relative_time(nanos);
    let absolute = unix_nanos_label(nanos);
    if relative == absolute {
        absolute
    } else {
        format!("{relative} · {absolute}")
    }
}

fn history_source_label(entry: &DfsFileHistoryEntry) -> &'static str {
    match entry.captured.source {
        DfsFileVersionSource::Checkpoint { .. } => "Saved manually",
        DfsFileVersionSource::RetentionRule => "Automatic",
        DfsFileVersionSource::LocalOperation { .. } => "Preserved local edit",
    }
}

fn history_kept_by(entry: &DfsFileHistoryEntry) -> String {
    let names = entry
        .pins
        .iter()
        .map(|pin| format!("\u{201c}{pin}\u{201d}"))
        .collect::<Vec<_>>();
    match (names.is_empty(), entry.captured.policy_capture.is_some()) {
        (false, false) => names.join(", "),
        (false, true) => format!("{} and the automatic rule", names.join(", ")),
        (true, _) => "the automatic rule until its retention window passes".to_string(),
    }
}

fn history_card_button(
    reader: &ThemeReader,
    label: impl Into<String>,
    icon: IconGlyph,
    appearance: ButtonAppearance,
    tone: SemanticTone,
    enabled: bool,
) -> sui::Button {
    sui::Button::new(label)
        .icon(icon)
        .min_height(30.0)
        .appearance(appearance)
        .tone(tone)
        .theme_when(clone_reader(reader))
        .enabled(enabled)
}

fn history_preview_panel(reader: &ThemeReader, preview: &FilesHistoryPreview) -> Surface {
    let theme = reader();
    let mut body = Stack::vertical().alignment(Alignment::Stretch).gap(6.0);
    let (badge, tone, text, note) = match preview.result.as_ref() {
        None => (
            "Reading version",
            SemanticTone::Accent,
            "Reading a bounded prefix of this saved version.".to_string(),
            None,
        ),
        Some(Err(error)) => (
            "Preview unavailable",
            SemanticTone::Warning,
            error.clone(),
            None,
        ),
        Some(Ok(preview)) => (
            if preview.binary {
                "Binary content"
            } else {
                "Text preview"
            },
            SemanticTone::Neutral,
            if preview.binary {
                preview.lines.join(" ")
            } else {
                preview.lines.join("\n")
            },
            preview.truncated.then(|| {
                format!(
                    "Showing the first {} KB or {} lines.",
                    FILE_PREVIEW_MAX_BYTES / 1024,
                    HISTORY_PREVIEW_MAX_LINES
                )
            }),
        ),
    };
    body = body.with_child(
        StatusBadge::new(badge)
            .icon(IconGlyph::FileText)
            .tone(tone)
            .theme_when(clone_reader(reader)),
    );
    let mut text_style = theme.text_style(theme.palette.text);
    text_style.font_size = theme.text.sm.size;
    text_style.line_height = theme.text.sm.line_height;
    body = body.with_child(RichText::from_plain_text(text, text_style));
    if let Some(note) = note {
        body = body.with_child(history_note(reader, note));
    }
    Surface::panel(body)
        .appearance(sui::SurfaceAppearance::Soft)
        .padding(Insets::all(10.0))
        .theme_when(clone_reader(reader))
        .fill_width(true)
}

fn history_entry_card(
    shared: &Shared,
    reader: &ThemeReader,
    entry: &DfsFileHistoryEntry,
    folder_mode: bool,
    loading: bool,
    preview: Option<&FilesHistoryPreview>,
) -> Surface {
    let mut badges = Flex::horizontal()
        .wrap(FlexWrap::Wrap)
        .gap(6.0)
        .align_items(Alignment::Center);
    if entry.is_current {
        badges = badges.with_child(
            StatusBadge::new("Current content")
                .icon(IconGlyph::Check)
                .tone(SemanticTone::Success)
                .theme_when(clone_reader(reader)),
        );
    }
    if entry.deleted {
        badges = badges.with_child(
            StatusBadge::new("Deleted file")
                .icon(IconGlyph::Trash)
                .tone(SemanticTone::Warning)
                .theme_when(clone_reader(reader)),
        );
    }
    badges = badges.with_child(
        StatusBadge::new(history_source_label(entry))
            .icon(IconGlyph::History)
            .tone(SemanticTone::Neutral)
            .theme_when(clone_reader(reader)),
    );

    let theme = reader();
    let mut meta_style = theme.text_style(theme.palette.text);
    meta_style.font_size = theme.text.sm.size;
    meta_style.line_height = theme.text.sm.line_height;
    let saved_path = normalize_path(&entry.captured.object.path);
    let mut body = Stack::vertical()
        .alignment(Alignment::Stretch)
        .gap(6.0)
        .with_child(badges)
        .with_child(
            Label::new(format!(
                "Saved {} · {}",
                history_saved_label(entry.captured.captured_at_unix_nanos),
                human_size(Some(entry.size_bytes))
            ))
            .text_style(meta_style),
        )
        .with_child(history_note(
            reader,
            format!("Kept by {}", history_kept_by(entry)),
        ));
    if folder_mode || saved_path != entry.current_path {
        body = body.with_child(history_note(reader, format!("Saved from {saved_path}")));
    }
    if saved_path != entry.current_path {
        body = body.with_child(history_note(
            reader,
            format!(
                "{} {}",
                if entry.deleted {
                    "Deleted at"
                } else {
                    "Now at"
                },
                entry.current_path
            ),
        ));
    }

    let identity = entry.identity.clone();
    let previewing = preview.is_some_and(|preview| preview.identity == identity);
    let mut actions = Flex::horizontal()
        .wrap(FlexWrap::Wrap)
        .gap(6.0)
        .align_items(Alignment::Center);
    if !folder_mode && !entry.is_current && !entry.deleted {
        let action = shared.clone();
        let selected = identity.clone();
        actions = actions.with_child(
            history_card_button(
                reader,
                "Restore",
                IconGlyph::Undo,
                ButtonAppearance::Tonal,
                SemanticTone::Accent,
                !loading,
            )
            .on_press_with_ctx(move |ctx| {
                action.files_mut().stage_history_restore(selected.clone());
                request_files_overlay_rebuild(ctx);
            }),
        );
    }
    {
        let action = shared.clone();
        let selected = identity.clone();
        let (label, appearance, tone) = if entry.deleted {
            ("Recover", ButtonAppearance::Tonal, SemanticTone::Accent)
        } else {
            (
                "Save as new file",
                ButtonAppearance::Ghost,
                SemanticTone::Neutral,
            )
        };
        actions = actions.with_child(
            history_card_button(reader, label, IconGlyph::File, appearance, tone, !loading)
                .on_press_with_ctx(move |ctx| {
                    action.files_mut().stage_history_recover(selected.clone());
                    request_files_overlay_rebuild(ctx);
                }),
        );
    }
    {
        let action = shared.clone();
        let selected = identity.clone();
        actions = actions.with_child(
            history_card_button(
                reader,
                if previewing {
                    "Hide preview"
                } else {
                    "Preview"
                },
                IconGlyph::FileText,
                ButtonAppearance::Ghost,
                SemanticTone::Neutral,
                true,
            )
            .on_press_with_ctx(move |ctx| {
                let waker = { action.borrow().waker.clone() };
                action
                    .files_mut()
                    .toggle_history_preview(selected.clone(), waker);
                request_files_overlay_rebuild(ctx);
            }),
        );
    }
    {
        let action = shared.clone();
        let selected = identity.clone();
        actions = actions.with_child(
            history_card_button(
                reader,
                "Add name",
                IconGlyph::Lock,
                ButtonAppearance::Ghost,
                SemanticTone::Neutral,
                !loading,
            )
            .on_press_with_ctx(move |ctx| {
                action.files_mut().stage_history_add_pin(selected.clone());
                request_files_overlay_rebuild(ctx);
            }),
        );
    }
    if folder_mode && !entry.deleted {
        let action = shared.clone();
        let path = entry.current_path.clone();
        actions = actions.with_child(
            history_card_button(
                reader,
                "Show file",
                IconGlyph::Folder,
                ButtonAppearance::Ghost,
                SemanticTone::Neutral,
                !loading,
            )
            .on_press_with_ctx(move |ctx| {
                let waker = { action.borrow().waker.clone() };
                action.files_mut().reveal_history_path(path.clone(), waker);
                request_files_overlay_rebuild(ctx);
            }),
        );
    }
    body = body.with_child(actions);

    if !entry.pins.is_empty() {
        let mut pins = Flex::horizontal()
            .wrap(FlexWrap::Wrap)
            .gap(6.0)
            .align_items(Alignment::Center);
        for pin in &entry.pins {
            let action = shared.clone();
            let selected = identity.clone();
            let pin_id = pin.clone();
            pins = pins.with_child(
                history_card_button(
                    reader,
                    format!("Release \u{201c}{}\u{201d}", middle_short(pin, 36)),
                    IconGlyph::Unlock,
                    ButtonAppearance::Outline,
                    SemanticTone::Warning,
                    !loading,
                )
                .on_press_with_ctx(move |ctx| {
                    action
                        .files_mut()
                        .stage_history_unpin(selected.clone(), pin_id.clone());
                    request_files_overlay_rebuild(ctx);
                }),
            );
        }
        body = body.with_child(pins);
    }
    if let Some(preview) = preview.filter(|_| previewing) {
        body = body.with_child(history_preview_panel(reader, preview));
    }

    let label = history_entry_label(entry);
    let title = if folder_mode {
        format!(
            "{} · {}",
            middle_short(&history_entry_file_name(entry), 40),
            middle_short(&label, 40)
        )
    } else {
        middle_short(&label, 64)
    };
    inspector_card(title, body, reader, None, false)
}

fn history_capture_card(
    shared: &Shared,
    reader: &ThemeReader,
    object: &DfsOperatorObjectView,
    retention: Option<&DfsFileHistoryRetention>,
    loading: bool,
) -> Surface {
    let mut body = Stack::vertical()
        .alignment(Alignment::Stretch)
        .gap(8.0)
        .with_child(history_note(
            reader,
            "Keep the current content so you can restore or recover it later. The name says why you saved it.",
        ));
    if history_object_can_capture(&object.object) {
        let input_shared = shared.clone();
        let input = sui::TextInput::new("files-history-capture-name")
            .value(shared.files().history_capture_name.clone())
            .placeholder("Name, for example before-edit")
            .min_width(220.0)
            .theme_when(clone_reader(reader))
            .on_change(move |value| {
                input_shared.files_mut().set_history_capture_name(value);
            });
        let save_shared = shared.clone();
        let save = sui::Button::new("Save version")
            .icon(IconGlyph::Add)
            .min_height(32.0)
            .appearance(ButtonAppearance::Filled)
            .tone(SemanticTone::Accent)
            .theme_when(clone_reader(reader))
            .enabled(!loading)
            .on_press_with_ctx(move |ctx| {
                let waker = { save_shared.borrow().waker.clone() };
                save_shared.files_mut().capture_history_version(waker);
                request_files_overlay_rebuild(ctx);
            });
        body = body.with_child(input).with_child(
            Flex::horizontal()
                .wrap(FlexWrap::Wrap)
                .gap(8.0)
                .align_items(Alignment::Center)
                .with_child(save)
                .with_child(history_note(
                    reader,
                    "Leave the name empty to use the current date and time.",
                )),
        );
    } else {
        body = body.with_child(history_note(
            reader,
            "Only file content can be saved as a version.",
        ));
    }
    body = body.with_child(history_note(reader, history_retention_summary(retention)));
    inspector_card("Save a version", body, reader, None, false)
}

fn history_decision_panel(
    shared: &Shared,
    reader: &ThemeReader,
    decision: &HistoryDecision,
    loading: bool,
) -> Surface {
    let (title, summary, confirm_label, tone) = match decision {
        HistoryDecision::Restore(_) => (
            "Restore this version?".to_string(),
            "The file gets a new current version with the saved content, but only if it has not changed since this view loaded. The content it replaces is kept only if you saved it or an automatic rule covers it.",
            "Restore version",
            SemanticTone::Warning,
        ),
        HistoryDecision::Recover(draft) => (
            format!(
                "Recover \u{201c}{}\u{201d}",
                middle_short(&draft.source_label, 48)
            ),
            "Create a new file with this version's content. Recovery never replaces an existing file, so choose a path that is not in use.",
            "Recover file",
            SemanticTone::Accent,
        ),
        HistoryDecision::AddPin(draft) => (
            format!(
                "Add a name to \u{201c}{}\u{201d}",
                middle_short(&draft.source_label, 48)
            ),
            "Each name keeps this version on its own until that name is released.",
            "Add name",
            SemanticTone::Accent,
        ),
        HistoryDecision::Unpin(request) => {
            let pin = match &request.operation {
                DfsFileHistoryPinOperation::Unpin { pin_id }
                | DfsFileHistoryPinOperation::Pin { pin_id }
                | DfsFileHistoryPinOperation::Capture { pin_id } => pin_id.clone(),
            };
            (
                format!("Release \u{201c}{}\u{201d}?", middle_short(&pin, 48)),
                "If no other name or automatic rule keeps this version, it leaves the history and its content can be permanently removed.",
                "Release name",
                SemanticTone::Danger,
            )
        }
    };
    let mut panel = Stack::vertical()
        .alignment(Alignment::Stretch)
        .gap(8.0)
        .with_child(
            StatusBadge::new(title)
                .icon(IconGlyph::Alert)
                .tone(tone)
                .theme_when(clone_reader(reader)),
        )
        .with_child(Label::new(summary).theme(reader()));
    match decision {
        HistoryDecision::Restore(request) => {
            let source = shared
                .files()
                .history_entry(&request.source)
                .map(|entry| {
                    format!(
                        "{} · {}",
                        history_entry_label(entry),
                        history_saved_label(entry.captured.captured_at_unix_nanos)
                    )
                })
                .unwrap_or_else(|| request.source.version.to_string());
            panel = panel
                .with_child(
                    DetailRow::new("Saved version", source).theme_when(clone_reader(reader)),
                )
                .with_child(
                    DetailRow::new("File", request.destination_path.clone())
                        .theme_when(clone_reader(reader)),
                );
        }
        HistoryDecision::Recover(draft) => {
            let input_shared = shared.clone();
            panel = panel.with_child(
                sui::TextInput::new("files-history-recover-destination")
                    .value(draft.destination.clone())
                    .placeholder("/folder/recovered-file.txt")
                    .min_width(260.0)
                    .theme_when(clone_reader(reader))
                    .on_change(move |value| {
                        input_shared.files_mut().set_history_decision_input(value);
                    }),
            );
            if draft.confirmed.is_some() {
                panel = panel.with_child(history_note(
                    reader,
                    "Confirming the same path again retries the same recovery.",
                ));
            }
        }
        HistoryDecision::AddPin(draft) => {
            let input_shared = shared.clone();
            panel = panel.with_child(
                sui::TextInput::new("files-history-pin-name")
                    .value(draft.name.clone())
                    .placeholder("Name, for example audit")
                    .min_width(220.0)
                    .theme_when(clone_reader(reader))
                    .on_change(move |value| {
                        input_shared.files_mut().set_history_decision_input(value);
                    }),
            );
        }

        HistoryDecision::Unpin(_) => {}
    }
    let back = shared.clone();
    let confirm = shared.clone();
    panel = panel.with_child(
        Flex::horizontal()
            .wrap(FlexWrap::Wrap)
            .gap(8.0)
            .align_items(Alignment::Center)
            .with_child(
                sui::Button::new("Back")
                    .enabled(!loading)
                    .appearance(ButtonAppearance::Ghost)
                    .tone(SemanticTone::Neutral)
                    .theme_when(clone_reader(reader))
                    .on_press_with_ctx(move |ctx| {
                        back.files_mut().cancel_history_decision();
                        request_files_overlay_rebuild(ctx);
                    }),
            )
            .with_child(
                sui::Button::new(confirm_label)
                    .enabled(!loading)
                    .icon(IconGlyph::Check)
                    .appearance(ButtonAppearance::Filled)
                    .tone(tone)
                    .theme_when(clone_reader(reader))
                    .on_press_with_ctx(move |ctx| {
                        let waker = { confirm.borrow().waker.clone() };
                        confirm.files_mut().confirm_history_decision(waker);
                        request_files_overlay_rebuild(ctx);
                    }),
            ),
    );
    Surface::panel(panel)
        .appearance(sui::SurfaceAppearance::Soft)
        .tone(tone)
        .padding(Insets::all(12.0))
        .theme_when(clone_reader(reader))
        .fill_width(true)
}

fn history_issues_card(
    _shared: &Shared,
    reader: &ThemeReader,
    object: &DfsOperatorObjectView,
) -> Surface {
    let count = object.repairs.len();
    let tone = if count == 0 {
        SemanticTone::Success
    } else {
        SemanticTone::Warning
    };
    let mut body = Stack::vertical()
        .alignment(Alignment::Stretch)
        .gap(9.0)
        .with_child(
            StatusBadge::new(if count == 0 {
                "No missing copies".into()
            } else {
                plural(count, "missing copy")
            })
            .icon(if count == 0 {
                IconGlyph::Check
            } else {
                IconGlyph::Alert
            })
            .tone(tone)
            .theme_when(clone_reader(reader)),
        );
    for repair in object.repairs.iter().take(4) {
        body = body.with_child(history_note(
            reader,
            format!(
                "Version {} is missing from {}",
                middle_short(repair.version.as_str(), 18),
                short_node_label(repair.missing_replica_node_id.as_str()),
            ),
        ));
    }
    Surface::panel(body)
        .appearance(sui::SurfaceAppearance::Soft)
        .tone(tone)
        .padding(Insets::all(12.0))
        .theme_when(clone_reader(reader))
        .fill_width(true)
}

fn files_history_sheet(
    shared: &Shared,
    reader: &ThemeReader,
    scroll_state: &ScrollState,
) -> Option<WidgetPod> {
    if !shared.files().history_open {
        return None;
    }
    let files = shared.files();
    let loading = files.history_loading;
    let loaded = files.history_loaded;
    let more_loading = files.history_more_loading();
    let error = files.history_error.clone();
    let notice = files.history_notice.clone();
    let decision = files.history_decision.clone();
    let object = files.history_object.clone();
    let target = files.history_target.clone();
    let entries = files.history_entries.clone();
    let has_more = files.history_next_cursor.is_some();
    let list_error = files.history_list_error.clone();
    let retention = files.history_retention.clone();
    let preview = files.history_preview.clone();
    let folder_mode = target.as_ref().is_some_and(HistoryTarget::is_folder);
    let title = match target.as_ref() {
        Some(target) if target.path() == "/" => "SIFS".to_string(),
        Some(target) => history_path_file_name(target.path()),
        None => files
            .selected_entry()
            .map(|entry| entry.name.clone())
            .unwrap_or_else(|| "History & issues".to_string()),
    };
    drop(files);

    let mut content = Stack::vertical()
        .alignment(Alignment::Stretch)
        .gap(12.0)
        .with_child(history_note(
            reader,
            if folder_mode {
                "Versions saved from files in this folder, including files that were deleted. Recover a version to bring its content back as a new file."
            } else {
                "Save versions of this file, then restore or recover them later. DFS authority applies every change and this view refreshes afterward."
            },
        ));
    if loading && loaded {
        content = content.with_child(
            StatusBadge::new(
                notice
                    .clone()
                    .unwrap_or_else(|| "Refreshing history...".to_string()),
            )
            .icon(IconGlyph::Hourglass)
            .tone(SemanticTone::Info)
            .theme_when(clone_reader(reader)),
        );
    } else if let Some(notice) = notice.clone() {
        content = content.with_child(
            StatusBadge::new(notice)
                .icon(IconGlyph::Check)
                .tone(SemanticTone::Success)
                .theme_when(clone_reader(reader)),
        );
    }
    if let Some(error) = error.clone().filter(|_| loaded) {
        content = content.with_child(
            StatusBadge::new(error)
                .icon(IconGlyph::Alert)
                .tone(SemanticTone::Danger)
                .theme_when(clone_reader(reader)),
        );
    }
    if let Some(decision) = decision.as_ref() {
        content = content.with_child(history_decision_panel(shared, reader, decision, loading));
    }
    if !folder_mode && let Some(object) = object.as_ref() {
        content = content.with_child(history_capture_card(
            shared,
            reader,
            object,
            retention.as_ref(),
            loading,
        ));
    }

    let mut version_stack = Stack::vertical().alignment(Alignment::Stretch).gap(10.0);
    if folder_mode {
        version_stack = version_stack.with_child(history_note(
            reader,
            history_retention_summary(retention.as_ref()),
        ));
    }
    for entry in &entries {
        version_stack = version_stack.with_child(history_entry_card(
            shared,
            reader,
            entry,
            folder_mode,
            loading,
            preview.as_ref(),
        ));
    }
    if entries.is_empty() && list_error.is_none() {
        version_stack = version_stack.with_child(history_note(
            reader,
            match (folder_mode, has_more) {
                (_, true) => "No saved versions found yet. Older history has not been searched.",
                (true, false) => "No saved versions were found in this folder.",
                (false, false) => {
                    "No saved versions yet. Save a version before changes you may want to undo."
                }
            },
        ));
    }
    if let Some(list_error) = list_error {
        version_stack = version_stack.with_child(
            StatusBadge::new(list_error)
                .icon(IconGlyph::Alert)
                .tone(SemanticTone::Warning)
                .theme_when(clone_reader(reader)),
        );
    }
    if has_more {
        let more_shared = shared.clone();
        version_stack = version_stack.with_child(
            sui::Button::new(if more_loading {
                "Searching older versions..."
            } else {
                "Search older versions"
            })
            .icon(IconGlyph::Search)
            .min_height(32.0)
            .appearance(ButtonAppearance::Outline)
            .tone(SemanticTone::Neutral)
            .theme_when(clone_reader(reader))
            .enabled(!loading && !more_loading)
            .on_press_with_ctx(move |ctx| {
                let waker = { more_shared.borrow().waker.clone() };
                more_shared.files_mut().request_more_history(waker);
                request_files_overlay_rebuild(ctx);
            }),
        );
    }
    let versions_title = match (folder_mode, entries.len()) {
        (true, 0) => "Saved versions in this folder".to_string(),
        (true, count) => format!("Saved versions in this folder ({count})"),
        (false, 0) => "Saved versions".to_string(),
        (false, count) => format!("Saved versions ({count})"),
    };
    content = content.with_child(
        PanelSection::new(versions_title, version_stack)
            .theme_when(clone_reader(reader))
            .gap(10.0),
    );
    if let Some(object) = object.as_ref() {
        let has_issues = !object.repairs.is_empty();
        if !folder_mode || has_issues {
            content = content.with_child(history_issues_card(shared, reader, object));
        }
    }

    let body_content = ScrollView::vertical(
        WidgetPadding::new(
            Insets {
                left: 2.0,
                top: 2.0,
                right: 10.0,
                bottom: 16.0,
            },
            content,
        )
        .fill_child_width(true),
    )
    .state(scroll_state.clone())
    .name("File history and issues")
    .theme_when(clone_gray_scrollbar_reader(reader))
    .viewport_width_hint(true);
    let selected = if loaded {
        2
    } else if loading {
        0
    } else {
        1
    };
    let body = SwitchView::new()
        .selected(selected)
        .with_child(centered_note(
            reader,
            IconGlyph::Hourglass,
            "Loading history",
            "Reading saved versions and the authoritative DFS object view.",
        ))
        .with_child(centered_note(
            reader,
            IconGlyph::Alert,
            "History unavailable",
            error.unwrap_or_else(|| "No DFS object history was returned.".to_string()),
        ))
        .with_child(body_content);

    let refresh_shared = shared.clone();
    let refresh_enabled = shared.clone();
    let refresh = sui::Button::new("Refresh")
        .icon(IconGlyph::Redo)
        .appearance(ButtonAppearance::Tonal)
        .tone(SemanticTone::Accent)
        .theme_when(clone_reader(reader))
        .enabled_when(move || !refresh_enabled.files().history_loading)
        .on_press_with_ctx(move |ctx| {
            let waker = { refresh_shared.borrow().waker.clone() };
            refresh_shared.files_mut().request_history(waker);
            request_files_overlay_rebuild(ctx);
        });
    let close_shared = shared.clone();
    let close = sui::Button::new("Close")
        .appearance(ButtonAppearance::Outline)
        .tone(SemanticTone::Neutral)
        .theme_when(clone_reader(reader))
        .on_press_with_ctx(move |ctx| {
            close_shared.files_mut().close_history();
            request_files_overlay_rebuild(ctx);
        });
    let dismiss = shared.clone();
    Some(WidgetPod::new(
        SideSheet::new(title, body)
            .theme_when(clone_reader(reader))
            .description(if folder_mode {
                "Saved versions in this folder, including deleted files"
            } else {
                "Saved versions and missing copies"
            })
            .placement(SideSheetPlacement::Right)
            .width(720.0)
            .modal(true)
            .dismiss_on_scrim(true)
            .action(refresh)
            .action(close)
            .on_dismiss(move || dismiss.files_mut().close_history()),
    ))
}

fn compact_file_selection_actions(shared: &Shared, reader: &ThemeReader) -> impl Widget + use<> {
    let source = shared.files().source;
    let actions_for_selection = selection_context_actions(&shared.files());
    let mut previous_group = None;
    let mut actions = Stack::vertical().alignment(Alignment::Stretch).gap(6.0);

    for action in actions_for_selection {
        let group = action.group();
        if previous_group.is_some_and(|previous| previous != group) {
            actions = actions.with_child(Separator::horizontal().theme_when(clone_reader(reader)));
        }
        previous_group = Some(group);

        let enabled = action.enabled(&shared.files());
        let destructive = action.destructive();
        let action_shared = shared.clone();
        let mut button = sui::Button::new(action.label(source))
            .min_height(36.0)
            .theme_when(clone_reader(reader))
            .enabled(enabled)
            .on_press_with_ctx(move |ctx| {
                action_shared.files_mut().close_compact_overlay();
                activate_file_context_action(&action_shared, action, ctx);
                request_files_overlay_rebuild(ctx);
            });
        if destructive {
            button = button
                .appearance(ButtonAppearance::Outline)
                .tone(SemanticTone::Warning);
        }
        actions = actions.with_child(button);
    }

    ScrollView::vertical(WidgetPadding::new(
        Insets {
            left: 2.0,
            top: 2.0,
            right: 10.0,
            bottom: 12.0,
        },
        actions,
    ))
    .name("Selected item actions")
    .theme_when(clone_gray_scrollbar_reader(reader))
    .viewport_width_hint(true)
}

fn compact_files_dialog(shared: &Shared, reader: &ThemeReader) -> Option<WidgetPod> {
    let overlay = shared.files().compact_overlay?;
    let (title, description, selected) = match overlay {
        CompactFilesOverlay::Commands => (
            "File commands",
            "Commands hidden from the compact file toolbar",
            0,
        ),
        CompactFilesOverlay::SelectionActions => (
            "Selected item actions",
            "Actions for the selected file, folder, or marked items",
            1,
        ),
        CompactFilesOverlay::Inspector => (
            "Selection info",
            "Preview, placement, metadata, identity, and selection summaries",
            2,
        ),
    };
    let inspector_scroll_state = ScrollState::new();
    let body = SwitchView::new()
        .selected(selected)
        .with_child(compact_files_commands(shared, reader))
        .with_child(compact_file_selection_actions(shared, reader))
        .with_child(inspector(shared, reader, &inspector_scroll_state));
    let dismiss_shared = shared.clone();
    Some(WidgetPod::new(
        SideSheet::new(title, body)
            .theme_when(clone_reader(reader))
            .description(description)
            .placement(SideSheetPlacement::Right)
            .width(420.0)
            .modal(true)
            .dismiss_on_scrim(true)
            .on_dismiss(move || dismiss_shared.files_mut().close_compact_overlay()),
    ))
}

fn files_dialog(
    shared: &Shared,
    reader: &ThemeReader,
    history_scroll: &ScrollState,
) -> Option<WidgetPod> {
    if shared.workspace_kind() == Some(crate::state::WorkspaceTabKind::Document) {
        return files_document_close_dialog(shared, reader);
    }
    if shared.files().document_close_confirmation {
        files_document_close_dialog(shared, reader)
    } else if shared.files().document.is_some() {
        files_document_sheet(shared, reader)
    } else if shared.files().action_prompt.is_some() {
        files_action_dialog(shared, reader)
    } else if shared.files().history_open {
        files_history_sheet(shared, reader, history_scroll)
    } else if shared.files().storage_center_open {
        files_storage_center_sheet(shared, reader)
    } else if shared.files().placement_activity_open {
        Some(files_placement_activity_sheet(shared, reader))
    } else {
        compact_files_dialog(shared, reader)
    }
}

struct FilesDialogHost {
    shared: Shared,
    reader: ThemeReader,
    body: WidgetPod,
    dialog: Option<WidgetPod>,
    dialog_key: FilesDialogStructure,
    /// Keeps the history sheet's position across rebuilds after each action.
    history_scroll: ScrollState,
}

impl FilesDialogHost {
    fn new<W>(body: W, shared: Shared, reader: ThemeReader) -> Self
    where
        W: Widget + 'static,
    {
        let dialog_key = shared.signals().files_structure.get().dialog;
        let history_scroll = ScrollState::new();
        let dialog = files_dialog(&shared, &reader, &history_scroll);
        Self {
            shared,
            reader,
            body: WidgetPod::new(body),
            dialog,
            dialog_key,
            history_scroll,
        }
    }

    fn sync_dialog(&mut self, key: FilesDialogStructure) {
        if key == self.dialog_key {
            return;
        }
        if !matches!(self.dialog_key, FilesDialogStructure::History { .. })
            && matches!(key, FilesDialogStructure::History { .. })
        {
            self.history_scroll = ScrollState::new();
        }
        self.dialog_key = key;
        self.dialog = files_dialog(&self.shared, &self.reader, &self.history_scroll);
    }
}

impl Widget for FilesDialogHost {
    fn event(&mut self, ctx: &mut EventCtx, event: &Event) {
        if ctx.phase() == EventPhase::Capture
            && let Event::Keyboard(key) = event
            && key.state == KeyState::Pressed
            && (key.modifiers.control || key.modifiers.meta)
            && key.key.eq_ignore_ascii_case("s")
            && self.shared.files().document.is_some()
        {
            let waker = { self.shared.borrow().waker.clone() };
            self.shared.files_mut().save_document(waker);
            ctx.set_handled();
            request_files_overlay_rebuild(ctx);
        }
    }

    fn measure(&mut self, ctx: &mut MeasureCtx, constraints: Constraints) -> Size {
        let source = self
            .shared
            .signals()
            .files_structure
            .select_named("files dialog structure", |key| key.dialog.clone());
        let key = ctx.observe(&source);
        self.sync_dialog(key);
        let size = constraints.clamp(Size::new(
            if constraints.max.width.is_finite() {
                constraints.max.width
            } else {
                920.0
            },
            if constraints.max.height.is_finite() {
                constraints.max.height
            } else {
                640.0
            },
        ));
        let tight = Constraints::tight(size);
        self.body.measure(ctx, tight);
        if let Some(dialog) = &mut self.dialog {
            dialog.measure(ctx, tight);
        }
        size
    }

    fn arrange(&mut self, ctx: &mut ArrangeCtx, bounds: Rect) {
        self.body.arrange(ctx, bounds);
        if let Some(dialog) = &mut self.dialog {
            dialog.arrange(ctx, bounds);
        }
    }

    fn paint(&self, ctx: &mut PaintCtx) {
        self.body.paint(ctx);
        if let Some(dialog) = &self.dialog {
            dialog.paint(ctx);
        }
    }

    fn semantics(&self, ctx: &mut SemanticsCtx) {
        self.body.semantics(ctx);
        if let Some(dialog) = &self.dialog {
            dialog.semantics(ctx);
        }
    }

    fn stack_host_options(&self) -> Option<StackHostOptions> {
        Some(StackHostOptions::default())
    }

    fn visit_children(&self, visitor: &mut dyn WidgetPodVisitor) {
        visitor.visit(&self.body);
        if let Some(dialog) = &self.dialog {
            visitor.visit(dialog);
        }
    }

    fn visit_children_mut(&mut self, visitor: &mut dyn WidgetPodMutVisitor) {
        visitor.visit(&mut self.body);
        if let Some(dialog) = &mut self.dialog {
            visitor.visit(dialog);
        }
    }
}

/// The files tab's lazy-load boundary. SUI's retained [`ConstraintView`] owns the responsive
/// wide/narrow branch selection; this wrapper only keeps the important rule that opening SIFS is
/// deferred until the Files tab is actually measured.
pub struct FilesView {
    shared: Shared,
    child: WidgetPod,
}

impl FilesView {
    pub fn new(shared: Shared) -> Self {
        let theme_reader: ThemeReader = {
            let s = shared.clone();
            Rc::new(move || s.theme())
        };
        // One shared list scroll state keeps the file position consistent across the wide/narrow
        // swap. The inspector owns a separate scroll state because expanded technical details are
        // independent of the directory listing.
        let scroll_state = ScrollState::new();
        let places_scroll_state = ScrollState::new();
        let inspector_scroll_state = ScrollState::new();
        let narrow = narrow_pod(&shared, &theme_reader, &scroll_state);
        let wide = wide_pod(
            &shared,
            &theme_reader,
            &scroll_state,
            &places_scroll_state,
            &inspector_scroll_state,
        );
        Self {
            shared,
            child: WidgetPod::new(
                ConstraintView::new(narrow)
                    .when(ConstraintQuery::new().min_width(WIDE_THRESHOLD), wide),
            ),
        }
    }
}

impl Widget for FilesView {
    fn event(&mut self, _ctx: &mut EventCtx, _event: &Event) {}

    fn measure(&mut self, ctx: &mut MeasureCtx, constraints: Constraints) -> Size {
        let waker = { self.shared.borrow().waker.clone() };
        let changed = self.shared.files_mut_unpublished().ensure_loaded(waker);
        if changed {
            self.shared.publish_files_signals();
        }
        self.child.measure(ctx, constraints)
    }

    fn arrange(&mut self, ctx: &mut ArrangeCtx, bounds: Rect) {
        self.child.arrange(ctx, bounds);
    }

    fn paint(&self, ctx: &mut PaintCtx) {
        self.child.paint(ctx);
    }

    fn semantics(&self, ctx: &mut SemanticsCtx) {
        self.child.semantics(ctx);
    }

    fn visit_children(&self, visitor: &mut dyn WidgetPodVisitor) {
        visitor.visit(&self.child);
    }

    fn visit_children_mut(&mut self, visitor: &mut dyn WidgetPodMutVisitor) {
        visitor.visit(&mut self.child);
    }
}

/// Build the files tab content.
pub fn view(shared: Shared) -> impl Widget {
    let reader: ThemeReader = {
        let s = shared.clone();
        Rc::new(move || s.theme().with_size(ControlSize::Small))
    };
    FilesDialogHost::new(FilesView::new(shared.clone()), shared, reader)
}

/// A document occupies the tab body; only unsaved-close confirmation is modal.
pub(crate) fn document_view(shared: Shared) -> impl Widget {
    let theme_shared = shared.clone();
    let reader: ThemeReader = Rc::new(move || theme_shared.theme().with_size(ControlSize::Small));
    let content_shared = shared.clone();
    let content_reader = reader.clone();
    let source = shared
        .signals()
        .files_structure
        .select_named("document contents", |key| {
            // The revision changes on load/reload, not on typing or close confirmation.
            match &key.dialog {
                FilesDialogStructure::Document { theme, revision }
                | FilesDialogStructure::DocumentConfirmation { theme, revision } => {
                    Some((*theme, *revision))
                }
                _ => None,
            }
        });
    let body = RebuildOnChange::key_from(source, move |_| {
        files_document_sheet(&content_shared, &content_reader)
            .unwrap_or_else(|| WidgetPod::new(SizedBox::new()))
    });
    FilesDialogHost::new(body, shared, reader)
}

