    fn pending_placement_job() -> SifsPlacementReconciliationJob {
        SifsPlacementReconciliationJob {
            schema_version: sinomo_runtime::dfs::DFS_PLACEMENT_RECONCILIATION_SCHEMA_VERSION,
            job_id: "placement-job".to_string(),
            file_system_id: sinomo_runtime::dfs::DfsFileSystemId::from_legacy_named("sifs")
                .expect("filesystem"),
            path: "/folder".to_string(),
            scope: SifsPlacementScope::Subtree,
            state: sinomo_runtime::dfs::DfsPlacementReconciliationState::Scanning,
            cursor: None,
            total_object_count: 3,
            scanned_object_count: 1,
            matched_object_count: 1,
            updated_object_count: 1,
            scheduled_repair_count: 1,
            completed_repair_count: 0,
            pending_repair_count: 1,
            unavailable_node_ids: BTreeSet::new(),
            candidate_snapshot: Vec::new(),
            placement_snapshot: None,
            adaptive: false,
            adaptive_budget: None,
            processed_content_bytes: 0,
            accepted_config: sinomo_runtime::dfs::DfsFileSystemConfig {
                file_system_id: sinomo_runtime::dfs::DfsFileSystemId::from_legacy_named("sifs")
                    .expect("filesystem"),
                display_name: "SIFS".to_string(),
                owner_node_id: sinomo_runtime::node::NodeId::from_legacy_named("node-a")
                    .expect("node"),
                subtree_policies: Vec::new(),
                retention_policies: Default::default(),
                module_metadata: Default::default(),
            },
            revision: 2,
            created_at_unix_nanos: 1,
            updated_at_unix_nanos: 2,
            last_error: None,
        }
    }

    fn placement_activity_summary(
        job_id: &str,
        status: sinomo_runtime::dfs::DfsPlacementReconciliationActivityStatus,
        created_at_unix_nanos: u64,
    ) -> sinomo_runtime::dfs::DfsPlacementReconciliationActivitySummary {
        use sinomo_runtime::dfs::{
            DfsPlacementReconciliationActivityStatus as Status,
            DfsPlacementReconciliationState as Phase,
        };
        let mut job = pending_placement_job();
        job.job_id = job_id.to_string();
        job.path = format!("/datasets/{job_id}");
        job.created_at_unix_nanos = created_at_unix_nanos;
        job.updated_at_unix_nanos = created_at_unix_nanos.saturating_add(1);
        match status {
            Status::Running => {
                job.state = Phase::Scanning;
                job.last_error = None;
            }
            Status::Retrying => {
                job.state = Phase::Repairing;
                job.last_error = Some("node-b is temporarily unreachable".to_string());
            }
            Status::Failed => {
                job.state = Phase::Failed;
                job.last_error = Some("placement policy became invalid".to_string());
            }
            Status::Completed => {
                job.state = Phase::Completed;
                job.scanned_object_count = job.total_object_count;
                job.completed_repair_count = job.scheduled_repair_count;
                job.pending_repair_count = 0;
                job.last_error = None;
            }
            Status::Superseded => {
                job.state = Phase::Failed;
                job.last_error = Some("superseded by a newer placement policy".to_string());
            }
        }
        let mut summary =
            sinomo_runtime::dfs::DfsPlacementReconciliationActivitySummary::from(&job);
        summary.status = status;
        summary
    }

    #[test]
    fn reconciliation_activity_uses_an_independent_request_lane_and_preserves_history() {
        use sinomo_runtime::dfs::DfsPlacementReconciliationActivityStatus as Status;

        let fixture = sinomo_testdir::TestDir::new(
            "app-ui-reconciliation-activity-uses-an-independent-request-lane-and-preserves-history",
        );
        let backend = Backend::local_fallback_for_data_dir(
            sinomo_runtime::local::SinomoDataDir::new(fixture.path()),
        );
        let mut state = FilesState::new(&backend);
        let (tx, rx) = mpsc::channel();
        state.worker_tx = Some(tx);
        state.pending_placement_request_id = Some(91);

        state.open_placement_activity(None);
        let command = rx.recv().expect("activity request");
        let request_id = match command {
            FilesWorkerCommand::PlacementActivity {
                request_id,
                filter,
                cursor,
                append,
            } => {
                assert_eq!(filter, PlacementActivityFilter::All);
                assert!(cursor.is_none());
                assert!(!append);
                request_id
            }
            _ => panic!("expected placement activity request"),
        };
        assert_eq!(state.pending_placement_request_id, Some(91));

        let completed = placement_activity_summary("completed-job", Status::Completed, 20);
        assert!(
            state.apply_worker_result(FilesWorkerResult::PlacementActivity {
                request_id,
                filter: PlacementActivityFilter::All,
                append: false,
                result: Ok(
                    sinomo_runtime::dfs::DfsPlacementReconciliationActivityPage {
                        activities: vec![completed.clone()],
                        next_cursor: None,
                        ..Default::default()
                    }
                ),
            })
        );
        assert_eq!(state.placement_activity, vec![completed]);
        assert!(state.placement_activity_error.is_none());
        assert_eq!(state.pending_placement_request_id, Some(91));

        state.pending_placement_activity_request_id = Some(72);
        let newer = placement_activity_summary("newer-job", Status::Completed, 30);
        assert!(
            state.apply_worker_result(FilesWorkerResult::PlacementActivity {
                request_id: 72,
                filter: PlacementActivityFilter::All,
                append: false,
                result: Ok(
                    sinomo_runtime::dfs::DfsPlacementReconciliationActivityPage {
                        activities: vec![newer.clone()],
                        next_cursor: None,
                        ..Default::default()
                    }
                ),
            })
        );
        assert_eq!(state.placement_activity[0], newer);
        assert_eq!(state.placement_activity.len(), 1);

        state.close_placement_activity();
        assert!(!state.placement_activity_open);
        assert_eq!(state.placement_activity.len(), 1);
    }

    #[test]
    fn reconciliation_activity_append_deduplicates_by_job_revision() {
        use sinomo_runtime::dfs::DfsPlacementReconciliationActivityStatus as Status;

        let fixture = sinomo_testdir::TestDir::new(
            "app-ui-reconciliation-activity-append-deduplicates-by-job-revision",
        );
        let backend = Backend::local_fallback_for_data_dir(
            sinomo_runtime::local::SinomoDataDir::new(fixture.path()),
        );
        let mut state = FilesState::new(&backend);
        let mut current = placement_activity_summary("same-job", Status::Completed, 10);
        current.revision = 8;
        state.placement_activity = vec![current.clone()];
        state.placement_activity_open = true;
        state.pending_placement_activity_request_id = Some(44);
        state.pending_placement_activity_append = true;

        let mut stale = current.clone();
        stale.revision = 7;
        stale.updated_object_count = 999;
        let older = placement_activity_summary("older-job", Status::Failed, 5);
        assert!(
            state.apply_worker_result(FilesWorkerResult::PlacementActivity {
                request_id: 44,
                filter: PlacementActivityFilter::All,
                append: true,
                result: Ok(
                    sinomo_runtime::dfs::DfsPlacementReconciliationActivityPage {
                        activities: vec![stale, older.clone()],
                        next_cursor: None,
                        ..Default::default()
                    }
                ),
            })
        );

        assert_eq!(state.placement_activity.len(), 2);
        assert_eq!(state.placement_activity[0], current);
        assert_eq!(state.placement_activity[1], older);
        assert_eq!(state.placement_activity[0].updated_object_count, 1);
    }

    #[test]
    fn placement_activity_radios_follow_domain_across_retained_frames() -> sui::Result<()> {
        use sui::{Event, PointerButton, PointerButtons, PointerEvent, PointerEventKind};

        let fixture = sinomo_testdir::TestDir::new("app-ui-placement-activity-radios-follow-domain-across-retained-frames");
        let backend = Backend::local_fallback_for_data_dir(
            sinomo_runtime::local::SinomoDataDir::new(fixture.path()),
        );
        let shared = Shared::new(AppState::ready(backend));
        let (tx, rx) = mpsc::channel();
        shared.files_mut().worker_tx = Some(tx);
        let reader: ThemeReader = {
            let shared = shared.clone();
            Rc::new(move || shared.theme())
        };
        let initial_filter = shared.files().placement_activity_filter;
        let choices = [
            (PlacementActivityFilter::All, "All"),
            (PlacementActivityFilter::Active, "Active"),
            (PlacementActivityFilter::Failed, "Failed"),
            (PlacementActivityFilter::Completed, "Done"),
        ];
        // Retain the production radios so parent rebuilding cannot repair stale selection.
        let radios =
            choices
                .into_iter()
                .fold(Flex::horizontal().gap(6.0), |row, (filter, label)| {
                    row.with_child(placement_activity_filter_radio(
                        &shared,
                        &reader,
                        initial_filter,
                        filter,
                        label,
                    ))
                });
        let runtime = sui::Application::new()
            .window(
                sui::WindowBuilder::new()
                    .root(SizedBox::new().width(520.0).height(120.0).child(radios)),
            )
            .build()?;
        let app = sui_testing::TestApp::from_runtime(runtime)?;
        let window = app.main_window()?;
        let initial = window.snapshot()?;
        let initial_ids: Vec<_> = initial
            .accessibility
            .nodes
            .iter()
            .filter(|node| node.role == sui::SemanticsRole::RadioButton)
            .map(|node| node.id)
            .collect();
        assert_eq!(initial_ids.len(), 4);
        let point = |name: &str| {
            let bounds = initial
                .accessibility
                .nodes
                .iter()
                .find(|node| {
                    node.role == sui::SemanticsRole::RadioButton
                        && node.name.as_deref() == Some(name)
                })
                .expect("visible filter radio")
                .bounds;
            sui::Point::new(
                bounds.x() + bounds.width() * 0.5,
                bounds.y() + bounds.height() * 0.5,
            )
        };
        let activate_now = |point: sui::Point| -> sui::Result<()> {
            window.dispatch_event_now(Event::Pointer(PointerEvent::new(
                PointerEventKind::Move,
                point,
            )))?;
            let mut down = PointerEvent::new(PointerEventKind::Down, point);
            down.button = Some(PointerButton::Primary);
            down.buttons = PointerButtons::new(1);
            window.dispatch_event_now(Event::Pointer(down))?;
            let mut up = PointerEvent::new(PointerEventKind::Up, point);
            up.button = Some(PointerButton::Primary);
            window.dispatch_event_now(Event::Pointer(up))
        };
        let expect_request = |expected| match rx.try_recv().expect("one filter query") {
            FilesWorkerCommand::PlacementActivity {
                filter,
                cursor,
                append,
                ..
            } => {
                assert_eq!(filter, expected);
                assert!(cursor.is_none());
                assert!(!append);
            }
            _ => panic!("expected placement activity query"),
        };
        let assert_visible = |expected: &str| -> sui::Result<()> {
            window.run_until_idle()?;
            let snapshot = window.snapshot_now()?;
            let radios: Vec<_> = snapshot
                .accessibility
                .nodes
                .iter()
                .filter(|node| node.role == sui::SemanticsRole::RadioButton)
                .collect();
            assert_eq!(
                radios.iter().map(|node| node.id).collect::<Vec<_>>(),
                initial_ids
            );
            assert!(radios.iter().all(|node| !node.state.disabled));
            let checked: Vec<_> = radios
                .iter()
                .filter(|node| node.state.selected)
                .map(|node| node.name.clone().expect("radio name"))
                .collect();
            assert_eq!(checked, vec![expected.to_string()]);
            Ok(())
        };
        assert_eq!(initial_filter, PlacementActivityFilter::All);
        assert_visible("All")?;

        // X then the previously selected Y, with no frame or parent rebuild between inputs.
        activate_now(point("Active"))?;
        activate_now(point("All"))?;
        // dispatch_event_now queues input; pumping delivers both activations before redraw.
        window.run_until_idle()?;
        assert_eq!(
            shared.files().placement_activity_filter,
            PlacementActivityFilter::All
        );
        expect_request(PlacementActivityFilter::Active);
        expect_request(PlacementActivityFilter::All);
        assert!(matches!(rx.try_recv(), Err(TryRecvError::Empty)));
        assert_visible("All")?;

        // The same retained controls also switch correctly across rendered frames.
        activate_now(point("Active"))?;
        window.run_until_idle()?;
        assert_eq!(
            shared.files().placement_activity_filter,
            PlacementActivityFilter::Active
        );
        expect_request(PlacementActivityFilter::Active);
        assert!(matches!(rx.try_recv(), Err(TryRecvError::Empty)));
        assert_visible("Active")?;
        activate_now(point("All"))?;
        window.run_until_idle()?;
        assert_eq!(
            shared.files().placement_activity_filter,
            PlacementActivityFilter::All
        );
        expect_request(PlacementActivityFilter::All);
        assert!(matches!(rx.try_recv(), Err(TryRecvError::Empty)));
        assert_visible("All")?;

        // A repeated selection must preserve the query/poll state.
        let generation = shared
            .files()
            .placement_activity_poll_generation
            .load(Ordering::Acquire);
        activate_now(point("All"))?;
        window.run_until_idle()?;
        assert!(matches!(rx.try_recv(), Err(TryRecvError::Empty)));
        assert_eq!(
            shared
                .files()
                .placement_activity_poll_generation
                .load(Ordering::Acquire),
            generation
        );
        assert_visible("All")?;

        // An external domain change must reach retained check states and remain selectable.
        assert!(
            shared
                .files_mut()
                .set_placement_activity_filter(PlacementActivityFilter::Failed)
        );
        window.dispatch_event_now(Event::Pointer(PointerEvent::new(
            PointerEventKind::Move,
            point("Failed"),
        )))?;
        window.pump_frames(1)?;
        assert!(matches!(rx.try_recv(), Err(TryRecvError::Empty)));
        assert_visible("Failed")?;
        activate_now(point("All"))?;
        window.run_until_idle()?;
        assert_eq!(
            shared.files().placement_activity_filter,
            PlacementActivityFilter::All
        );
        expect_request(PlacementActivityFilter::All);
        assert!(matches!(rx.try_recv(), Err(TryRecvError::Empty)));
        assert_visible("All")?;
        Ok(())
    }

    #[test]
    fn reconciliation_activity_filter_groups_running_and_retrying_as_active() {
        use sinomo_runtime::dfs::DfsPlacementReconciliationActivityStatus as Status;

        assert!(PlacementActivityFilter::Active.includes(Status::Running));
        assert!(PlacementActivityFilter::Active.includes(Status::Retrying));
        assert!(!PlacementActivityFilter::Active.includes(Status::Failed));
        assert!(!PlacementActivityFilter::Active.includes(Status::Completed));
        assert!(!PlacementActivityFilter::Active.includes(Status::Superseded));
        assert!(PlacementActivityFilter::Failed.includes(Status::Failed));
        assert!(!PlacementActivityFilter::Failed.includes(Status::Superseded));
        assert!(PlacementActivityFilter::Completed.includes(Status::Completed));
        assert!(PlacementActivityFilter::All.includes(Status::Superseded));
    }

    #[test]
    fn reconciliation_activity_filter_queries_the_server_and_evicts_finished_active_jobs() {
        use sinomo_runtime::dfs::DfsPlacementReconciliationActivityStatus as Status;

        let fixture = sinomo_testdir::TestDir::new(
            "app-ui-reconciliation-activity-filter-queries-the-server-and-evicts-finished-active-jobs",
        );
        let backend = Backend::local_fallback_for_data_dir(
            sinomo_runtime::local::SinomoDataDir::new(fixture.path()),
        );
        let mut state = FilesState::new(&backend);
        let (tx, rx) = mpsc::channel();
        state.worker_tx = Some(tx);
        state.placement_activity_open = true;

        assert!(state.set_placement_activity_filter(PlacementActivityFilter::Active));
        state.refresh_placement_activity();
        let (first_request_id, first_filter) = match rx.recv().expect("active activity request") {
            FilesWorkerCommand::PlacementActivity {
                request_id,
                filter,
                cursor,
                append,
            } => {
                assert!(cursor.is_none());
                assert!(!append);
                (request_id, filter)
            }
            _ => panic!("expected placement activity request"),
        };
        assert_eq!(first_filter, PlacementActivityFilter::Active);
        assert_eq!(
            first_filter.request_statuses(),
            vec![Status::Running, Status::Retrying]
        );

        let running = placement_activity_summary("active-job", Status::Running, 20);
        assert!(
            state.apply_worker_result(FilesWorkerResult::PlacementActivity {
                request_id: first_request_id,
                filter: first_filter,
                append: false,
                result: Ok(
                    sinomo_runtime::dfs::DfsPlacementReconciliationActivityPage {
                        activities: vec![running.clone()],
                        ..Default::default()
                    },
                ),
            })
        );
        assert_eq!(state.placement_activity, vec![running]);

        // A later successful Active head is authoritative: once the job completes, the daemon
        // omits it from this server-side query and the UI must evict the stale running row.
        state.refresh_placement_activity();
        let second_request_id = match rx.recv().expect("authoritative activity refresh") {
            FilesWorkerCommand::PlacementActivity {
                request_id,
                filter,
                cursor,
                append,
            } => {
                assert_eq!(filter, PlacementActivityFilter::Active);
                assert!(cursor.is_none());
                assert!(!append);
                request_id
            }
            _ => panic!("expected placement activity request"),
        };
        assert!(
            state.apply_worker_result(FilesWorkerResult::PlacementActivity {
                request_id: second_request_id,
                filter: PlacementActivityFilter::Active,
                append: false,
                result: Ok(Default::default()),
            })
        );
        assert!(state.placement_activity.is_empty());
        state.close_placement_activity();
    }

