    #[test]
    fn reconciliation_activity_sheet_exposes_cluster_statuses_and_virtual_filtering()
    -> sui::Result<()> {
        use sinomo_runtime::dfs::DfsPlacementReconciliationActivityStatus as Status;

        let fixture = sinomo_testdir::TestDir::new(
            "app-ui-reconciliation-activity-sheet-exposes-cluster-statuses-and-virtual-filtering",
        );
        let backend = Backend::local_fallback_for_data_dir(
            sinomo_runtime::local::SinomoDataDir::new(fixture.path()),
        );
        let shared = Shared::new(AppState::ready(backend));
        {
            let mut files = shared.files_mut();
            files.clustered = true;
            files.placement_activity_open = true;
            files.placement_activity = vec![
                placement_activity_summary("running-job", Status::Running, 40),
                placement_activity_summary("retrying-job", Status::Retrying, 30),
                placement_activity_summary("failed-job", Status::Failed, 20),
                placement_activity_summary("completed-job", Status::Completed, 10),
            ];
            files.placement_activity_refreshed_at_unix_nanos = Some(40);
        }
        let reader: ThemeReader = {
            let shared = shared.clone();
            Rc::new(move || shared.theme())
        };
        let runtime = sui::Application::new()
            .window(
                sui::WindowBuilder::new()
                    .title("Reconciliation activity")
                    .root(FilesDialogHost::new(
                        SizedBox::new().width(1200.0).height(860.0),
                        shared.clone(),
                        Rc::clone(&reader),
                    )),
            )
            .build()?;
        let app = sui_testing::TestApp::from_runtime(runtime)?;
        let window = app.main_window()?;
        app.run_until_idle()?;
        window.advance_time(1.0)?;
        app.run_until_idle()?;

        assert!(window.get_by_text("Reconciliation activity").count()? >= 1);
        for label in [
            "1 Running loaded",
            "1 Retrying loaded",
            "1 Failed loaded",
            "1 Completed loaded",
            "0 Superseded loaded",
        ] {
            assert_eq!(window.get_by_text(label).count()?, 1, "missing {label}");
        }
        let realized_rows = window.get_by_role(SemanticsRole::ProgressBar).count()?;
        assert!((2..=4).contains(&realized_rows));
        assert_eq!(
            window
                .get_by_role(SemanticsRole::Button)
                .with_name("Show path")
                .count()?,
            realized_rows
        );

        let failed_filter = window
            .get_by_role(SemanticsRole::RadioButton)
            .with_name("Failed");
        failed_filter.expect().to_be_visible()?;
        failed_filter.click()?;
        app.run_until_idle()?;
        assert_eq!(
            shared.files().placement_activity_filter,
            PlacementActivityFilter::Failed
        );
        assert_eq!(
            window.get_by_role(SemanticsRole::ProgressBar).count()?,
            1,
            "the keyed virtual collection should retain only the failed row after filtering"
        );
        assert_eq!(
            window
                .get_by_role(SemanticsRole::ProgressBar)
                .with_name("Reconciliation progress for /datasets/failed-job")
                .count()?,
            1
        );
        Ok(())
    }

    #[test]
    fn reconciliation_activity_compact_extra_large_keeps_offline_error_and_history_reachable()
    -> sui::Result<()> {
        use sinomo_runtime::dfs::DfsPlacementReconciliationActivityStatus as Status;

        let full_error = "The cluster control plane rejected this activity read because the retained projection is temporarily unavailable on node oracle-eu-west-very-long-name.";
        let live_error =
            "The daemon event stream disconnected while waiting for DFS placement updates.";
        let fixture = sinomo_testdir::TestDir::new(
            "app-ui-reconciliation-activity-compact-extra-large-keeps-offline-error-and-history-reachable",
        );
        let backend = Backend::local_fallback_for_data_dir(
            sinomo_runtime::local::SinomoDataDir::new(fixture.path()),
        );
        let mut app_state = AppState::ready(backend);
        app_state.text_scale = AppTextScale::ExtraLarge;
        let shared = Shared::new(app_state);
        {
            let mut files = shared.files_mut();
            files.clustered = false;
            files.loaded = true;
            files.loading = false;
            files.placement_activity_filter = PlacementActivityFilter::All;
            files.placement_activity_loaded_filter = PlacementActivityFilter::All;
            files.placement_activity = vec![
                placement_activity_summary("failed-job", Status::Failed, 20),
                placement_activity_summary("superseded-job", Status::Superseded, 10),
            ];
            files.placement_activity_error = Some(full_error.to_string());
            files.live_updates_error = Some(live_error.to_string());
            files.placement_activity_partial = true;
            files.placement_activity_history_truncated = false;
            files.placement_activity_refreshed_at_unix_nanos = Some(20);
        }

        let runtime = sui::Application::new()
            .window(
                sui::WindowBuilder::new()
                    .title("Compact reconciliation activity")
                    .root(view(shared.clone())),
            )
            .build()?;
        let app = sui_testing::TestApp::from_runtime(runtime)?;
        let window = app.main_window()?;
        window
            .root()
            .dispatch_event(Event::Window(WindowEvent::Resized(Size::new(360.0, 640.0))))?;
        app.run_until_idle()?;

        let closed_snapshot = window.snapshot()?;
        let activity_entrypoint = closed_snapshot
            .accessibility
            .nodes
            .iter()
            .find(|node| {
                node.role == SemanticsRole::Button
                    && node.name.as_deref() == Some("Reconciliation activity")
            })
            .expect("offline files toolbar keeps the activity center reachable");
        assert!(!activity_entrypoint.state.disabled);

        shared.files_mut().placement_activity_open = true;
        app.run_until_idle()?;
        window.advance_time(1.0)?;
        app.run_until_idle()?;
        let snapshot = window.snapshot()?;
        let dialog = snapshot
            .accessibility
            .nodes
            .iter()
            .find(|node| {
                node.role == SemanticsRole::Dialog
                    && node.name.as_deref() == Some("Reconciliation activity")
            })
            .expect("activity side sheet");
        assert!(dialog.bounds.x() >= 0.0 && dialog.bounds.y() >= 0.0);
        assert!(dialog.bounds.max_x() <= 360.0 && dialog.bounds.max_y() <= 640.0);

        let header_bounds = snapshot
            .accessibility
            .nodes
            .iter()
            .find(|node| {
                node.role == SemanticsRole::ScrollView
                    && node.name.as_deref() == Some("Reconciliation activity summary")
            })
            .expect("scrollable activity summary")
            .bounds;
        let error_status = snapshot
            .accessibility
            .nodes
            .iter()
            .find(|node| {
                node.role == SemanticsRole::Status
                    && node.name.as_deref() == Some("Reconciliation activity read failed")
            })
            .expect("persistent activity error status");
        assert_eq!(error_status.description.as_deref(), Some(full_error));
        assert!(error_status.bounds.y() < header_bounds.max_y());

        for button_name in ["Retry activity read", "Refresh", "Close"] {
            let button = snapshot
                .accessibility
                .nodes
                .iter()
                .find(|node| {
                    node.role == SemanticsRole::Button && node.name.as_deref() == Some(button_name)
                })
                .unwrap_or_else(|| panic!("missing {button_name} button"));
            assert!(!button.state.disabled || button_name == "Refresh");
            assert!(button.bounds.x() >= 0.0 && button.bounds.y() >= 0.0);
            assert!(button.bounds.max_x() <= 360.0 && button.bounds.max_y() <= 640.0);
        }

        let next_summary = window
            .get_by_role(SemanticsRole::Button)
            .with_name("Next activity summary");
        next_summary.expect().to_be_visible()?;
        // Native font metrics change wrapping and the number of scroll steps needed.
        // Verify reachability through the production controls instead of a fixed click count.
        let reveal_summary_status = |button: &str, status: &str| -> sui::Result<()> {
            for _ in 0..12 {
                let snapshot = window.snapshot()?;
                let bounds = snapshot
                    .accessibility
                    .nodes
                    .iter()
                    .find(|node| {
                        node.role == SemanticsRole::Status && node.name.as_deref() == Some(status)
                    })
                    .expect("activity summary status")
                    .bounds;
                if bounds.y() < header_bounds.max_y() && bounds.max_y() > header_bounds.y() {
                    return Ok(());
                }
                window
                    .get_by_role(SemanticsRole::Button)
                    .with_name(button)
                    .click()?;
                app.run_until_idle()?;
            }
            panic!("{status} was not reachable through {button} within 12 scroll steps");
        };
        reveal_summary_status(
            "Next activity summary",
            "Live reconciliation updates disconnected",
        )?;
        let live_snapshot = window.snapshot()?;
        let live_status = live_snapshot
            .accessibility
            .nodes
            .iter()
            .find(|node| {
                node.role == SemanticsRole::Status
                    && node.name.as_deref() == Some("Live reconciliation updates disconnected")
            })
            .expect("live-update fallback status");
        assert_eq!(live_status.description.as_deref(), Some(live_error));
        assert!(
            live_status.bounds.y() < header_bounds.max_y()
                && live_status.bounds.max_y() > header_bounds.y(),
            "live status {:?} must intersect header viewport {:?}",
            live_status.bounds,
            header_bounds
        );

        reveal_summary_status("Next activity summary", "Retained operational history")?;
        let retained_snapshot = window.snapshot()?;
        let retained_status = retained_snapshot
            .accessibility
            .nodes
            .iter()
            .find(|node| {
                node.role == SemanticsRole::Status
                    && node.name.as_deref() == Some("Retained operational history")
            })
            .expect("neutral retained-history status");
        assert!(
            retained_status.bounds.y() < header_bounds.max_y()
                && retained_status.bounds.max_y() > header_bounds.y()
        );
        assert_eq!(window.get_by_text("Retained history truncated").count()?, 0);

        let filter_snapshot = window.snapshot()?;
        let done_filter = filter_snapshot
            .accessibility
            .nodes
            .iter()
            .find(|node| {
                node.role == SemanticsRole::RadioButton && node.name.as_deref() == Some("Done")
            })
            .expect("compact Done filter");
        assert!(
            done_filter.bounds.x() >= dialog.bounds.x()
                && done_filter.bounds.max_x() <= dialog.bounds.max_x()
                && done_filter.bounds.y() >= dialog.bounds.y()
                && done_filter.bounds.max_y() <= dialog.bounds.max_y()
        );

        // Navigating the summary never dismisses or clears the durable read error.
        reveal_summary_status("Previous activity summary", "Reconciliation activity read failed")?;
        let restored_snapshot = window.snapshot()?;
        let restored_error = restored_snapshot
            .accessibility
            .nodes
            .iter()
            .find(|node| {
                node.role == SemanticsRole::Status
                    && node.name.as_deref() == Some("Reconciliation activity read failed")
            })
            .expect("activity error remains after scrolling");
        assert_eq!(restored_error.description.as_deref(), Some(full_error));
        assert!(restored_error.bounds.y() < header_bounds.max_y());

        let realized_rows = restored_snapshot
            .accessibility
            .nodes
            .iter()
            .filter(|node| node.role == SemanticsRole::ProgressBar)
            .count();
        let list_items = restored_snapshot
            .accessibility
            .nodes
            .iter()
            .filter(|node| node.role == SemanticsRole::ListItem)
            .count();
        assert!(realized_rows > 0);
        assert_eq!(
            list_items, realized_rows,
            "each virtual row owns one list-item semantic node"
        );
        // Native font metrics can make the first card fill the virtual viewport.
        // Reach the second row through its own scroll control, independently of
        // the summary, rather than assuming both rows are initially realized.
        let activity_list = window
            .get_by_role(SemanticsRole::List)
            .with_name("Reconciliation activity");
        let list_bounds = restored_snapshot
            .accessibility
            .nodes
            .iter()
            .find(|node| {
                node.role == SemanticsRole::List
                    && node.name.as_deref() == Some("Reconciliation activity")
            })
            .expect("virtual activity list")
            .bounds;
        let mut replaced_reachable = false;
        for _ in 0..12 {
            let snapshot = window.snapshot()?;
            replaced_reachable = snapshot.accessibility.nodes.iter().any(|node| {
                (node.name.as_deref() == Some("Replaced")
                    || node
                        .description
                        .as_deref()
                        .is_some_and(|text| text.contains("Replaced")))
                    && node.bounds.y() < list_bounds.max_y()
                    && node.bounds.max_y() > list_bounds.y()
            });
            if replaced_reachable {
                break;
            }
            activity_list.scroll_pixels(Vector::new(0.0, -140.0))?;
            app.run_until_idle()?;
        }
        assert!(
            replaced_reachable,
            "Replaced row must be reachable through the virtual list"
        );
        assert_eq!(
            shared.files().placement_activity_error.as_deref(),
            Some(full_error),
            "scrolling the job list preserves the durable activity read error"
        );
        Ok(())
    }

    #[test]
    fn placement_number_input_ranges_follow_desired_replica_changes() -> sui::Result<()> {
        let backend = Backend::local_fallback();
        let shared = Shared::new(AppState::ready(backend));
        {
            let mut preview = unsatisfiable_placement_preview();
            preview.blocking_diagnostics.clear();
            for node in &mut preview.nodes {
                node.accepts_content = true;
            }
            let mut files = shared.files_mut();
            files.action_prompt = Some(placement_prompt("/folder", true));
            files.placement_draft = Some(PlacementEditorDraft::for_details(None, true));
            files.placement_advanced_open = true;
            files.placement_preview = Some(preview);
        }
        let reader: ThemeReader = {
            let shared = shared.clone();
            Rc::new(move || shared.theme())
        };
        let runtime = sui::Application::new()
            .window(
                sui::WindowBuilder::new()
                    .title("Placement count bounds")
                    .root(FilesDialogHost::new(
                        SizedBox::new().width(1200.0).height(840.0),
                        shared.clone(),
                        Rc::clone(&reader),
                    )),
            )
            .build()?;
        let app = sui_testing::TestApp::from_runtime(runtime)?;
        let window = app.main_window()?;
        app.run_until_idle()?;

        let range_for = |name: &str| -> (f64, f64, f64) {
            let snapshot = window.snapshot().expect("placement editor snapshot");
            let node = snapshot
                .accessibility
                .nodes
                .iter()
                .find(|node| {
                    node.role == sui::SemanticsRole::SpinBox && node.name.as_deref() == Some(name)
                })
                .unwrap_or_else(|| panic!("missing {name} spinbox"));
            let Some(sui::SemanticsValue::Range { value, min, max }) = node.value.as_ref() else {
                panic!("{name} must expose numeric range semantics");
            };
            (*value, *min, *max)
        };

        assert_eq!(range_for("Desired replicas N"), (2.0, 1.0, 3.0));
        assert_eq!(range_for("Minimum write replicas W"), (1.0, 1.0, 2.0));
        assert_eq!(range_for("Minimum distinct zones"), (0.0, 0.0, 2.0));

        window
            .get_by_role(sui::SemanticsRole::SpinBox)
            .with_name("Desired replicas N")
            .press("ArrowUp")?;
        app.run_until_idle()?;

        assert_eq!(
            shared
                .files()
                .placement_draft
                .as_ref()
                .and_then(PlacementEditorDraft::active_policy)
                .map(|policy| policy.desired_replicas),
            Some(3)
        );
        assert_eq!(range_for("Minimum write replicas W"), (1.0, 1.0, 3.0));
        assert_eq!(range_for("Minimum distinct zones"), (0.0, 0.0, 3.0));
        Ok(())
    }

    #[test]
    fn placement_editor_exposes_controls_impact_nodes_and_blocking_warnings() -> sui::Result<()> {
        let backend = Backend::local_fallback();
        let shared = Shared::new(AppState::ready(backend));
        let preview = unsatisfiable_placement_preview();
        let zone_warning = preview
            .blocking_diagnostics
            .iter()
            .find(|diagnostic| {
                matches!(
                    diagnostic,
                    sinomo_runtime::dfs::DfsPlacementBlockingDiagnostic::InsufficientZones { .. }
                )
            })
            .expect("zone warning")
            .message();
        let required =
            sinomo_runtime::node::NodeId::from_legacy_named("node-required").expect("node");
        {
            let mut files = shared.files_mut();
            let mut draft = PlacementEditorDraft::for_details(None, true);
            draft.scope = SifsPlacementScope::Subtree;
            let policy = draft.active_policy_mut().expect("active policy");
            policy.desired_replicas = 3;
            policy.min_distinct_zones = 2;
            policy.required_node_ids.insert(required);
            draft.normalize();
            files.action_prompt = Some(FileActionPrompt {
                kind: FileActionPromptKind::Placement,
                input: String::new(),
                target_name: "folder".to_string(),
                target_path: Some("/folder".to_string()),
                target_is_dir: true,
                targets: Vec::new(),
                error: None,
            });
            files.placement_draft = Some(draft);
            files.placement_advanced_open = true;
            files.placement_edit_revision = 11;
            files.placement_preview_revision = Some(11);
            files.placement_preview = Some(preview);
        }
        let reader: ThemeReader = {
            let shared = shared.clone();
            Rc::new(move || shared.theme())
        };
        let runtime =
            sui::Application::new()
                .window(sui::WindowBuilder::new().title("Placement editor").root(
                    FilesDialogHost::new(
                        SizedBox::new().width(1200.0).height(840.0),
                        shared,
                        Rc::clone(&reader),
                    ),
                ))
                .build()?;
        let app = sui_testing::TestApp::from_runtime(runtime)?;
        let window = app.main_window()?;
        app.run_until_idle()?;
        let snapshot = window.snapshot()?;

        for name in [
            "Eventual placement",
            "Confirmed placement",
            "Self placement scope",
            "Subtree placement scope",
        ] {
            assert!(snapshot.accessibility.nodes.iter().any(|node| {
                node.role == sui::SemanticsRole::RadioButton && node.name.as_deref() == Some(name)
            }));
        }
        for name in [
            "Minimum write replicas W",
            "Desired replicas N",
            "Minimum distinct zones",
        ] {
            assert!(snapshot.accessibility.nodes.iter().any(|node| {
                node.role == sui::SemanticsRole::SpinBox && node.name.as_deref() == Some(name)
            }));
        }
        assert_eq!(
            snapshot
                .accessibility
                .nodes
                .iter()
                .filter(|node| {
                    node.role == sui::SemanticsRole::CheckBox
                        && node
                            .name
                            .as_deref()
                            .is_some_and(|name| name.starts_with("Require node "))
                })
                .count(),
            3
        );
        assert_eq!(
            snapshot
                .accessibility
                .nodes
                .iter()
                .filter(|node| {
                    node.role == sui::SemanticsRole::CheckBox
                        && node
                            .name
                            .as_deref()
                            .is_some_and(|name| name.starts_with("Forbid node "))
                })
                .count(),
            3
        );
        for label in [
            "Affected objects",
            "Affected bytes",
            "Copies added",
            "Copies removed",
        ] {
            assert!(window.get_by_text(label).count()? >= 1, "missing {label}");
        }
        assert!(window.get_by_text(zone_warning).count()? >= 1);
        assert!(snapshot.accessibility.nodes.iter().any(|node| {
            node.role == sui::SemanticsRole::Button
                && node.name.as_deref() == Some("Apply availability")
                && node.state.disabled
        }));
        Ok(())
    }

