    #[test]
    fn files_header_keeps_navigation_usable_for_long_paths() -> sui::Result<()> {
        let backend = Backend::local_fallback();
        let shared = Shared::new(AppState::ready(backend));
        let long_path =
            "C:\\Program Files\\WindowsApps\\OpenAI.Codex_26.623.5546.0_x64__2p2nqsd0c76g0\\app";
        {
            let mut files = shared.files_mut();
            files.source = FilesSourceKind::Local;
            files.loaded = true;
            files.loading = false;
            files.path = long_path.to_string();
            files.entries = vec![SifsEntry {
                name: "chrome.dll".to_string(),
                path: Path::new(long_path)
                    .join("chrome.dll")
                    .to_string_lossy()
                    .into_owned(),
                is_dir: false,
                is_link: false,
                size: Some(294_300_000),
            }];
            files.selected = Some(0);
        }

        let runtime = sui::Application::new()
            .window(
                sui::WindowBuilder::new().title("Files long header").root(
                    SizedBox::new()
                        .width(1280.0)
                        .height(720.0)
                        .child(view(shared.clone())),
                ),
            )
            .build()?;
        let app = sui_testing::TestApp::from_runtime(runtime)?;
        let window = app.main_window()?;
        let snapshot = window.snapshot()?;

        for (label, name) in [
            ("Back", "Back"),
            ("Up", "Up"),
            ("Refresh", "Refresh Local files"),
        ] {
            let node = snapshot
                .accessibility
                .nodes
                .iter()
                .find(|node| {
                    node.role == sui::SemanticsRole::Button && node.name.as_deref() == Some(name)
                })
                .unwrap_or_else(|| panic!("{label} command should be present"));
            assert!(
                node.bounds.width() >= 28.0 && node.bounds.height() >= 28.0,
                "{label} command should keep a usable hit target, got {:?}",
                node.bounds
            );
            assert!(
                node.bounds.max_x() <= 1280.0 && node.bounds.max_y() <= HEADER_H,
                "{label} command should stay inside the header, got {:?}",
                node.bounds
            );
        }
        for item_action in [
            "Open local file",
            "New folder",
            "Rename",
            "Delete selected item",
            "Run maintenance and refresh",
        ] {
            assert_eq!(
                window
                    .get_by_role(sui::SemanticsRole::Button)
                    .with_name(item_action)
                    .count()?,
                0,
                "{item_action} belongs in the item context menu, not the header"
            );
        }

        Ok(())
    }

    #[test]
    fn compact_file_table_keeps_unselected_placement_visible() -> sui::Result<()> {
        let backend = Backend::local_fallback();
        let shared = Shared::new(AppState::ready(backend));
        {
            let mut files = shared.files_mut();
            files.source = FilesSourceKind::Sifs;
            files.loaded = true;
            files.loading = false;
            files.error = None;
            files.clustered = true;
            files.path = "/".to_string();
            files.entries = vec![SifsEntry {
                name: "artifact.txt".to_string(),
                path: "/artifact.txt".to_string(),
                is_dir: false,
                is_link: false,
                size: Some(5),
            }];
            files.entry_metadata.insert(
                "/artifact.txt".to_string(),
                SifsEntryMetadata {
                    path: "/artifact.txt".to_string(),
                    object_id: "object-artifact".to_string(),
                    version: "version-1".to_string(),
                    modified_at_unix_nanos: 0,
                    policy: "replicated-eventual".to_string(),
                    current_locations: vec!["node-a".to_string(), "node-b".to_string()],
                    placement: Some(SifsEntryPlacement {
                        agent_state: "current".to_string(),
                        desired_replicas: 2,
                    }),
                },
            );
            files.selected = None;
        }
        shared.publish_files_signals();

        let runtime = sui::Application::new()
            .window(
                sui::WindowBuilder::new()
                    .title("Files compact placement")
                    .root(view(shared.clone())),
            )
            .build()?;
        let app = sui_testing::TestApp::from_runtime(runtime)?;
        let window = app.main_window()?;
        window
            .root()
            .dispatch_event(Event::Window(WindowEvent::Resized(Size::new(360.0, 640.0))))?;
        app.run_until_idle()?;

        let snapshot = window.snapshot()?;
        let table = snapshot
            .accessibility
            .nodes
            .iter()
            .find(|node| {
                node.role == sui::SemanticsRole::Table
                    && node.name.as_deref() == Some("files-listing")
            })
            .expect("compact files table semantics");
        assert!(
            table
                .description
                .as_deref()
                .is_some_and(|description| description.contains("Columns: Name, Availability;")),
            "compact table should retain Availability, got {:?}",
            table.description
        );
        assert!(
            !table
                .description
                .as_deref()
                .is_some_and(|description| description.contains("Details")),
            "Details should yield before Placement in the compact table, got {:?}",
            table.description
        );

        let row = snapshot
            .accessibility
            .nodes
            .iter()
            .find(|node| {
                node.role == sui::SemanticsRole::ListItem
                    && node.name.as_deref() == Some("artifact.txt")
            })
            .expect("unselected artifact row semantics");
        assert!(
            row.description
                .as_deref()
                .is_some_and(|description| description.contains("Placement: synced; 2/2 replicas")),
            "unselected row should expose placement metadata, got {:?}",
            row.description
        );
        let unselected_description = row.description.clone();

        window
            .get_by_role(sui::SemanticsRole::ListItem)
            .with_name("artifact.txt")
            .click()?;
        app.run_until_idle()?;
        let selected_description = window
            .snapshot()?
            .accessibility
            .nodes
            .into_iter()
            .find(|node| {
                node.role == sui::SemanticsRole::ListItem
                    && node.name.as_deref() == Some("artifact.txt")
            })
            .expect("selected artifact row semantics")
            .description;
        assert_eq!(
            selected_description, unselected_description,
            "selection should not change placement presentation in the file list"
        );

        Ok(())
    }

