    #[test]
    fn files_task_queue_reorder_preserves_virtual_row_widget_ids() -> sui::Result<()> {
        let backend = Backend::local_fallback();
        let shared = Shared::new(AppState::ready(backend));
        {
            let mut files = shared.files_mut();
            files.loaded = true;
            files.loading = false;
            files.tasks = vec![
                FilesTask {
                    id: 41,
                    source: FilesSourceKind::Sifs,
                    title: "Copy alpha".to_string(),
                    detail: "/alpha -> /archive/alpha".to_string(),
                    state: FilesTaskState::Running,
                    progress: Some(0.2),
                },
                FilesTask {
                    id: 73,
                    source: FilesSourceKind::Sifs,
                    title: "Copy beta".to_string(),
                    detail: "/beta -> /archive/beta".to_string(),
                    state: FilesTaskState::Running,
                    progress: Some(0.6),
                },
            ];
        }
        let reader: ThemeReader = Rc::new(DefaultTheme::light);
        let runtime = sui::Application::new()
            .window(
                sui::WindowBuilder::new()
                    .title("Files keyed task rows")
                    .root(
                        SizedBox::new()
                            .width(FILES_TASK_POPOVER_W)
                            .height(240.0)
                            .child(FilesTaskQueue::new(shared.clone(), &reader)),
                    ),
            )
            .build()?;
        let app = sui_testing::TestApp::from_runtime(runtime)?;
        let window = app.main_window()?;

        let row_ids = |snapshot: &sui_testing::WindowSnapshot| {
            snapshot
                .accessibility
                .nodes
                .iter()
                .filter(|node| node.role == SemanticsRole::ListItem)
                .filter_map(|node| {
                    node.name
                        .as_ref()
                        .filter(|name| {
                            name.as_str() == "Copy alpha" || name.as_str() == "Copy beta"
                        })
                        .map(|name| (name.clone(), node.id))
                })
                .collect::<std::collections::BTreeMap<_, _>>()
        };
        let before = row_ids(&window.snapshot()?);
        assert_eq!(before.len(), 2);

        shared.files_mut().tasks.swap(0, 1);
        app.run_until_idle()?;
        let after = row_ids(&window.snapshot()?);
        assert_eq!(
            after, before,
            "same-key task rows should move without replacing their retained widget pods"
        );

        Ok(())
    }

